//! SCCP payload, proof, and counterparty submission helpers for Iroha bridge flows.
//!
//! The crate targets the Rust standard library. The historical `std` feature is
//! kept as a compatibility alias for workspace consumers that still enable it.
#![allow(missing_docs)]
#![allow(missing_copy_implementations)]
// SCCP transcript helpers intentionally mirror wire/public-input layouts, so
// several functions keep long argument lists and verifier-sized bodies instead
// of hiding consensus fields behind lossy builder abstractions.
#![allow(
    clippy::assigning_clones,
    clippy::collapsible_if,
    clippy::derivable_impls,
    clippy::doc_markdown,
    clippy::if_not_else,
    clippy::manual_is_multiple_of,
    clippy::manual_range_patterns,
    clippy::match_same_arms,
    clippy::needless_pass_by_value,
    clippy::needless_question_mark,
    clippy::nonminimal_bool,
    clippy::option_if_let_else,
    clippy::question_mark,
    clippy::range_plus_one,
    clippy::struct_excessive_bools,
    clippy::too_many_arguments,
    clippy::too_many_lines,
    clippy::type_complexity,
    clippy::unnecessary_lazy_evaluations,
    clippy::unnecessary_wraps,
    clippy::useless_let_if_seq
)]

