pub fn sccp_profiled_destination_rollout_v1(
    domain: u32,
    verifier_identity: String,
    verifier_code_hash: String,
) -> Option<SccpDestinationRolloutV1> {
    sccp_profiled_destination_rollout_with_key_hash_v1(
        domain,
        verifier_identity,
        verifier_code_hash,
        None,
    )
}

fn sccp_profiled_destination_rollout_unchecked_v1(
    domain: u32,
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: Option<String>,
) -> Option<SccpDestinationRolloutV1> {
    let mut rollout = sccp_destination_rollout_for_domain(domain)?;
    rollout.immutable_verifier_ready = true;
    rollout.anchors_ready = true;
    rollout.verifier_identity = Some(verifier_identity);
    rollout.verifier_code_hash = Some(verifier_code_hash);
    rollout.verifier_key_hash = verifier_key_hash;
    rollout.anchor_id = Some(sccp_destination_anchor_id_for_domain(domain)?.to_owned());
    rollout.blockers.clear();
    Some(rollout)
}

fn sccp_domain_uses_static_destination_binding(domain: u32) -> bool {
    matches!(
        domain,
        SCCP_DOMAIN_SOL
            | SCCP_DOMAIN_TON
            | SCCP_DOMAIN_SORA_KUSAMA
            | SCCP_DOMAIN_SORA_POLKADOT
            | SCCP_DOMAIN_SORA2
    )
}

fn sccp_apply_static_destination_binding(rollout: &mut SccpDestinationRolloutV1) -> Option<()> {
    if !sccp_domain_uses_static_destination_binding(rollout.domain) {
        return Some(());
    }

    let binding = sccp_destination_binding_for_domain(rollout.domain)?;
    rollout.destination_binding_key = Some(binding.key);
    rollout.destination_binding_hash = Some(encode_0x_lower_hex(&binding.binding_hash));
    Some(())
}

fn sccp_profiled_destination_rollout_with_key_hash_v1(
    domain: u32,
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: Option<String>,
) -> Option<SccpDestinationRolloutV1> {
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        domain,
        verifier_identity,
        verifier_code_hash,
        verifier_key_hash,
    )?;
    sccp_apply_static_destination_binding(&mut rollout)?;
    sccp_destination_rollout_is_production_ready(domain, &rollout).then_some(rollout)
}

/// Build a Substrate-family destination rollout bound to a finalized runtime snapshot.
pub fn sccp_substrate_runtime_destination_rollout_with_finalized_runtime_v1(
    domain: u32,
    verifier_identity: String,
    finalized_head: H256,
    runtime_spec_version: u32,
    runtime_transaction_version: u32,
    runtime_code: Vec<u8>,
) -> Option<SccpDestinationRolloutV1> {
    if !matches!(
        domain,
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2
    ) || !h256_is_nonzero(&finalized_head)
    {
        return None;
    }
    let runtime_code_hash = sccp_substrate_runtime_code_hash_v1(&runtime_code)?;
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        domain,
        verifier_identity,
        encode_0x_lower_hex(&runtime_code_hash),
        None,
    )?;
    sccp_apply_static_destination_binding(&mut rollout)?;
    rollout.substrate_finalized_head = Some(encode_0x_lower_hex(&finalized_head));
    rollout.substrate_runtime_spec_name = Some(sccp_chain_key_for_domain(domain)?.to_owned());
    rollout.substrate_runtime_spec_version = Some(runtime_spec_version.to_string());
    rollout.substrate_runtime_transaction_version = Some(runtime_transaction_version.to_string());
    rollout.substrate_runtime_code_hash = Some(encode_0x_lower_hex(&runtime_code_hash));
    rollout.substrate_runtime_code_base64 = Some(encode_standard_base64(&runtime_code));
    sccp_destination_rollout_is_production_ready(domain, &rollout).then_some(rollout)
}

/// Return the legacy EVM-family destination rollout profile without deployment binding evidence.
///
/// Production readiness now requires the network id, bridge wrapper address,
/// canonical deployment binding key, and canonical deployment binding hash, so
/// this helper returns `None` for ETH/BSC mainnet lanes. Use
/// [`sccp_evm_mainnet_destination_rollout_with_binding_v1`] when deployment
/// material is available.
pub fn sccp_evm_mainnet_destination_rollout_v1(
    domain: u32,
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: String,
) -> Option<SccpDestinationRolloutV1> {
    if !matches!(domain, SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC) {
        return None;
    }
    sccp_profiled_destination_rollout_with_key_hash_v1(
        domain,
        verifier_identity,
        verifier_code_hash,
        Some(verifier_key_hash),
    )
}

/// Build a production-ready EVM-family destination rollout with deployment binding evidence.
pub fn sccp_evm_mainnet_destination_rollout_with_binding_v1(
    domain: u32,
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: String,
    destination_network_id: String,
    destination_bridge_address: String,
) -> Option<SccpDestinationRolloutV1> {
    if !matches!(domain, SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC) {
        return None;
    }
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        domain,
        verifier_identity,
        verifier_code_hash,
        Some(verifier_key_hash),
    )?;
    let network_id = decode_fixed_hex_bytes::<32>(&destination_network_id)?;
    if sccp_evm_mainnet_network_id_word_for_domain(domain).as_ref() != Some(&network_id) {
        return None;
    }
    let bridge_address = decode_fixed_hex_bytes::<20>(&destination_bridge_address)?;
    let verifier_address =
        decode_evm_hex_address(rollout.verifier_identity.as_deref()?.as_bytes())?;
    let verifier_code_hash = decode_fixed_hex_bytes::<32>(rollout.verifier_code_hash.as_deref()?)?;
    let verifier_key_hash = decode_fixed_hex_bytes::<32>(rollout.verifier_key_hash.as_deref()?)?;
    let binding = sccp_evm_destination_binding_from_deployment_material(
        domain,
        network_id,
        verifier_address,
        bridge_address,
        verifier_code_hash,
        verifier_key_hash,
    )?;
    rollout.destination_network_id = Some(encode_0x_lower_hex(&network_id));
    rollout.destination_bridge_address = Some(encode_0x_lower_hex(&bridge_address));
    rollout.destination_binding_key = Some(binding.key);
    rollout.destination_binding_hash = Some(encode_0x_lower_hex(&binding.binding_hash));
    sccp_destination_rollout_is_production_ready(domain, &rollout).then_some(rollout)
}

/// Return the legacy Solana destination rollout profile without live ProgramData evidence.
///
/// Production readiness requires immutable upgradeable ProgramData metadata plus
/// replayable verifier executable bytes. Use
/// [`sccp_solana_mainnet_destination_rollout_with_live_evidence_v1`] when live
/// deployment evidence is available.
pub fn sccp_solana_mainnet_destination_rollout_v1(
    verifier_identity: String,
    verifier_code_hash: String,
) -> Option<SccpDestinationRolloutV1> {
    sccp_profiled_destination_rollout_v1(SCCP_DOMAIN_SOL, verifier_identity, verifier_code_hash)
}

/// Build a production-ready Solana destination rollout with immutable ProgramData evidence.
pub fn sccp_solana_mainnet_destination_rollout_with_live_evidence_v1(
    verifier_identity: String,
    verifier_code_hash: String,
    programdata_address: String,
    programdata_slot: String,
    program_account_context_slot: String,
    programdata_account_context_slot: String,
    programdata_executable_base64: String,
) -> Option<SccpDestinationRolloutV1> {
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        SCCP_DOMAIN_SOL,
        verifier_identity,
        verifier_code_hash,
        None,
    )?;
    sccp_apply_static_destination_binding(&mut rollout)?;

    let programdata_raw = decode_sol_base58_address(programdata_address.as_bytes())?;
    let slot = sccp_canonical_positive_u64(&programdata_slot)?;
    let program_account_context = sccp_canonical_positive_u64(&program_account_context_slot)?;
    let programdata_account_context =
        sccp_canonical_positive_u64(&programdata_account_context_slot)?;
    if program_account_context < slot || programdata_account_context < slot {
        return None;
    }

    let executable = decode_standard_base64(&programdata_executable_base64)?;
    let executable_hash = sccp_solana_verifier_program_code_hash_v1(&executable)?;
    if required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref()).as_ref()
        != Some(&executable_hash)
    {
        return None;
    }

    let program_account_data = solana_upgradeable_program_account_data(programdata_raw);
    let programdata_metadata = solana_immutable_programdata_metadata(slot);
    let metadata_hash = blake2b256_bytes(&programdata_metadata);
    rollout.solana_rpc_commitment = Some("finalized".to_owned());
    rollout.solana_program_owner = Some(SCCP_SOLANA_UPGRADEABLE_LOADER_ID.to_owned());
    rollout.solana_programdata_owner = Some(SCCP_SOLANA_UPGRADEABLE_LOADER_ID.to_owned());
    rollout.solana_program_immutable = Some(true);
    rollout.solana_program_account_data_base64 =
        Some(encode_standard_base64(&program_account_data));
    rollout.solana_programdata_address = Some(programdata_address);
    rollout.solana_programdata_slot = Some(programdata_slot.clone());
    rollout.solana_expected_programdata_slot = Some(programdata_slot);
    rollout.solana_program_account_context_slot = Some(program_account_context_slot);
    rollout.solana_programdata_account_context_slot = Some(programdata_account_context_slot);
    rollout.solana_programdata_metadata_blake2b256 = Some(encode_0x_lower_hex(&metadata_hash));
    rollout.solana_programdata_metadata_base64 =
        Some(encode_standard_base64(&programdata_metadata));
    rollout.solana_programdata_executable_blake2b256 = Some(encode_0x_lower_hex(&executable_hash));
    rollout.solana_programdata_executable_base64 = Some(programdata_executable_base64);
    sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_SOL, &rollout).then_some(rollout)
}

/// Return the legacy TON destination rollout profile without live account evidence.
///
/// Production readiness now requires live account state pins plus the verifier
/// code BoC so the runtime can recompute the TON code root. Use
/// [`sccp_ton_mainnet_destination_rollout_with_live_evidence_v1`] when live
/// deployment evidence is available.
pub fn sccp_ton_mainnet_destination_rollout_v1(
    verifier_identity: String,
    verifier_code_hash: String,
) -> Option<SccpDestinationRolloutV1> {
    sccp_profiled_destination_rollout_v1(SCCP_DOMAIN_TON, verifier_identity, verifier_code_hash)
}

/// Build a production-ready TON mainnet destination rollout with live account evidence.
pub fn sccp_ton_mainnet_destination_rollout_with_live_evidence_v1(
    verifier_identity: String,
    verifier_code_hash: String,
    ton_account_state_hash: String,
    ton_last_transaction_lt: String,
    ton_last_transaction_hash: String,
    ton_verifier_code_boc: String,
) -> Option<SccpDestinationRolloutV1> {
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        SCCP_DOMAIN_TON,
        verifier_identity,
        verifier_code_hash,
        None,
    )?;
    sccp_apply_static_destination_binding(&mut rollout)?;

    let expected_code_hash =
        required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref())?;
    let code_boc = decode_hex_bytes(&ton_verifier_code_boc)?;
    let code_boc_root_hash = sccp_ton_boc_single_root_hash(&code_boc)?;
    if code_boc_root_hash != expected_code_hash {
        return None;
    }

    rollout.ton_account_status = Some("active".to_owned());
    rollout.ton_account_state_hash = Some(ton_account_state_hash);
    rollout.ton_last_transaction_lt = Some(ton_last_transaction_lt);
    rollout.ton_last_transaction_hash = Some(ton_last_transaction_hash);
    rollout.ton_verifier_code_boc_root_hash = Some(encode_0x_lower_hex(&code_boc_root_hash));
    rollout.ton_verifier_code_boc = Some(encode_0x_lower_hex(&code_boc));
    sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_TON, &rollout).then_some(rollout)
}

/// Return the legacy TRON destination rollout profile without deployment binding evidence.
///
/// Production readiness now requires the TRON network id plus the canonical
/// deployment binding key/hash, so this helper returns `None`. Use
/// [`sccp_tron_mainnet_destination_rollout_with_binding_v1`] when deployment
/// material is available.
pub fn sccp_tron_mainnet_destination_rollout_v1(
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: String,
) -> Option<SccpDestinationRolloutV1> {
    sccp_profiled_destination_rollout_with_key_hash_v1(
        SCCP_DOMAIN_TRON,
        verifier_identity,
        verifier_code_hash,
        Some(verifier_key_hash),
    )
}

/// Build a production-ready TRON destination rollout with deployment binding evidence.
pub fn sccp_tron_mainnet_destination_rollout_with_binding_v1(
    verifier_identity: String,
    verifier_code_hash: String,
    verifier_key_hash: String,
    destination_network_id: String,
) -> Option<SccpDestinationRolloutV1> {
    let mut rollout = sccp_profiled_destination_rollout_unchecked_v1(
        SCCP_DOMAIN_TRON,
        verifier_identity,
        verifier_code_hash,
        Some(verifier_key_hash),
    )?;
    let network_id = decode_fixed_hex_bytes::<32>(&destination_network_id)?;
    let verifier_code_hash = decode_fixed_hex_bytes::<32>(rollout.verifier_code_hash.as_deref()?)?;
    let verifier_key_hash = decode_fixed_hex_bytes::<32>(rollout.verifier_key_hash.as_deref()?)?;
    let binding = sccp_tron_destination_binding_from_deployment_material(
        network_id,
        rollout.verifier_identity.as_deref()?,
        verifier_code_hash,
        verifier_key_hash,
    )?;
    rollout.destination_network_id = Some(encode_0x_lower_hex(&network_id));
    rollout.destination_binding_key = Some(binding.key);
    rollout.destination_binding_hash = Some(encode_0x_lower_hex(&binding.binding_hash));
    sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_TRON, &rollout).then_some(rollout)
}

fn hex32_string_is_nonzero(value: &str) -> bool {
    let raw = value
        .strip_prefix("0x")
        .or_else(|| value.strip_prefix("0X"))
        .unwrap_or(value)
        .as_bytes();
    if raw.len() != 64 {
        return false;
    }

    let mut has_nonzero = false;
    for byte in raw {
        let Some(value) = (match byte {
            b'0'..=b'9' => Some(byte - b'0'),
            b'a'..=b'f' => Some(byte - b'a' + 10),
            b'A'..=b'F' => Some(byte - b'A' + 10),
            _ => None,
        }) else {
            return false;
        };
        has_nonzero |= value != 0;
    }
    has_nonzero
}

fn non_empty_metadata(value: Option<&str>) -> bool {
    value.is_some_and(|value| !value.trim().is_empty())
}

fn solana_verifier_program_id_is_valid(value: &str) -> bool {
    if value != value.trim() {
        return false;
    }
    let Some(program_id) = decode_sol_base58_address(value.as_bytes()) else {
        return false;
    };
    program_id.iter().copied().any(|byte| byte != 0)
}

fn evm_verifier_contract_address_is_valid(value: &str) -> bool {
    if value != value.trim() {
        return false;
    }
    let Some(address) = decode_evm_hex_address(value.as_bytes()) else {
        return false;
    };
    address.iter().copied().any(|byte| byte != 0)
}

fn ton_verifier_contract_address_is_valid(value: &str) -> bool {
    if value != value.trim() {
        return false;
    }
    let Some((workchain, account)) = decode_ton_raw_address(value.as_bytes()) else {
        return false;
    };
    workchain == SCCP_TON_BASECHAIN_WORKCHAIN_ID && account.iter().copied().any(|byte| byte != 0)
}

fn tron_verifier_contract_address_is_valid(value: &str) -> bool {
    decode_tron_base58check_nonzero_address(value.as_bytes()).is_some()
}

/// Check whether a TRON verifier contract address is a non-zero Base58Check account address.
pub fn sccp_tron_verifier_contract_address_is_valid(value: &str) -> bool {
    tron_verifier_contract_address_is_valid(value)
}

fn substrate_runtime_verifier_identity_is_valid(value: &str) -> bool {
    value == SCCP_SUBSTRATE_RUNTIME_DESTINATION_VERIFIER_ID_V1
}

fn sccp_destination_rollout_matches_domain_profile(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    if rollout.anchor_id.as_deref() != sccp_destination_anchor_id_for_domain(domain) {
        return false;
    }

    let Some(verifier_identity) = rollout.verifier_identity.as_deref() else {
        return false;
    };

    match domain {
        SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC => {
            evm_verifier_contract_address_is_valid(verifier_identity)
        }
        SCCP_DOMAIN_SOL => solana_verifier_program_id_is_valid(verifier_identity),
        SCCP_DOMAIN_TON => ton_verifier_contract_address_is_valid(verifier_identity),
        SCCP_DOMAIN_TRON => tron_verifier_contract_address_is_valid(verifier_identity),
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2 => {
            substrate_runtime_verifier_identity_is_valid(verifier_identity)
        }
        _ => false,
    }
}

fn sccp_destination_rollout_requires_verifier_key_hash(domain: u32) -> bool {
    matches!(
        sccp_verifier_backend_family_for_domain(domain),
        Some(
            SccpVerifierBackendFamilyV1::EvmGroth16Bn254
                | SccpVerifierBackendFamilyV1::TronGroth16Bn254,
        )
    )
}

fn sccp_destination_rollout_verifier_key_hash_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    if sccp_destination_rollout_requires_verifier_key_hash(domain) {
        return rollout
            .verifier_key_hash
            .as_deref()
            .is_some_and(hex32_string_is_nonzero);
    }

    rollout.verifier_key_hash.is_none()
}

fn required_hex_string_is_nonzero<const N: usize>(value: Option<&str>) -> Option<[u8; N]> {
    let raw = decode_fixed_hex_bytes::<N>(value?)?;
    raw.iter().any(|byte| *byte != 0).then_some(raw)
}

fn sccp_destination_binding_hash_matches(
    rollout: &SccpDestinationRolloutV1,
    expected_hash: &H256,
) -> bool {
    required_hex_string_is_nonzero::<32>(rollout.destination_binding_hash.as_deref()).as_ref()
        == Some(expected_hash)
}

fn required_destination_binding_key_matches(
    rollout: &SccpDestinationRolloutV1,
    expected_key: &str,
) -> bool {
    rollout.destination_binding_key.as_deref() == Some(expected_key)
}

fn sccp_evm_destination_rollout_binding_metadata_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    let Some(network_id) =
        required_hex_string_is_nonzero::<32>(rollout.destination_network_id.as_deref())
    else {
        return false;
    };
    let Some(expected_network_id) = sccp_evm_mainnet_network_id_word_for_domain(domain) else {
        return false;
    };
    if network_id != expected_network_id {
        return false;
    }
    let Some(bridge_address) =
        required_hex_string_is_nonzero::<20>(rollout.destination_bridge_address.as_deref())
    else {
        return false;
    };
    let Some(verifier_identity) = rollout.verifier_identity.as_deref() else {
        return false;
    };
    let Some(verifier_address) = decode_evm_hex_address(verifier_identity.as_bytes()) else {
        return false;
    };
    let Some(verifier_code_hash) =
        required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref())
    else {
        return false;
    };
    let Some(verifier_key_hash) =
        required_hex_string_is_nonzero::<32>(rollout.verifier_key_hash.as_deref())
    else {
        return false;
    };
    let Some(binding) = sccp_evm_destination_binding_from_deployment_material(
        domain,
        network_id,
        verifier_address,
        bridge_address,
        verifier_code_hash,
        verifier_key_hash,
    ) else {
        return false;
    };

    sccp_destination_binding_hash_matches(rollout, &binding.binding_hash)
        && required_destination_binding_key_matches(rollout, &binding.key)
}

fn sccp_tron_destination_rollout_binding_metadata_is_ready(
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    let Some(network_id) =
        required_hex_string_is_nonzero::<32>(rollout.destination_network_id.as_deref())
    else {
        return false;
    };
    if rollout.destination_bridge_address.is_some() {
        return false;
    }
    let Some(verifier_code_hash) =
        required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref())
    else {
        return false;
    };
    let Some(verifier_key_hash) =
        required_hex_string_is_nonzero::<32>(rollout.verifier_key_hash.as_deref())
    else {
        return false;
    };
    let Some(verifier_identity) = rollout.verifier_identity.as_deref() else {
        return false;
    };
    let Some(binding) = sccp_tron_destination_binding_from_deployment_material(
        network_id,
        verifier_identity,
        verifier_code_hash,
        verifier_key_hash,
    ) else {
        return false;
    };

    sccp_destination_binding_hash_matches(rollout, &binding.binding_hash)
        && required_destination_binding_key_matches(rollout, &binding.key)
}

fn sccp_static_destination_rollout_binding_metadata_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    if rollout.destination_network_id.is_some() || rollout.destination_bridge_address.is_some() {
        return false;
    }
    let Some(binding) = sccp_destination_binding_for_domain(domain) else {
        return false;
    };

    sccp_destination_binding_hash_matches(rollout, &binding.binding_hash)
        && required_destination_binding_key_matches(rollout, &binding.key)
}

fn sccp_destination_rollout_binding_metadata_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    match domain {
        SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC => {
            sccp_evm_destination_rollout_binding_metadata_is_ready(domain, rollout)
        }
        SCCP_DOMAIN_TRON => sccp_tron_destination_rollout_binding_metadata_is_ready(rollout),
        SCCP_DOMAIN_SOL
        | SCCP_DOMAIN_TON
        | SCCP_DOMAIN_SORA_KUSAMA
        | SCCP_DOMAIN_SORA_POLKADOT
        | SCCP_DOMAIN_SORA2 => {
            sccp_static_destination_rollout_binding_metadata_is_ready(domain, rollout)
        }
        _ => false,
    }
}

fn sccp_ton_live_decimal_is_positive_canonical(value: &str) -> bool {
    let raw = value.as_bytes();
    if raw.is_empty() || raw[0] == b'0' {
        return false;
    }
    raw.iter().all(u8::is_ascii_digit)
}

fn sccp_canonical_positive_u64(value: &str) -> Option<u64> {
    if !sccp_ton_live_decimal_is_positive_canonical(value) {
        return None;
    }
    value.parse::<u64>().ok()
}

fn sccp_canonical_u32_decimal(value: &str) -> Option<u32> {
    let raw = value.as_bytes();
    if raw.is_empty()
        || value != value.trim()
        || raw.iter().any(|byte| !byte.is_ascii_digit())
        || (raw.len() > 1 && raw[0] == b'0')
    {
        return None;
    }
    value.parse::<u32>().ok()
}

fn base64_standard_value(byte: u8) -> Option<u8> {
    match byte {
        b'A'..=b'Z' => Some(byte - b'A'),
        b'a'..=b'z' => Some(byte - b'a' + 26),
        b'0'..=b'9' => Some(byte - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

fn decode_standard_base64(value: &str) -> Option<Vec<u8>> {
    if value.is_empty()
        || value != value.trim()
        || value.bytes().any(|byte| byte.is_ascii_whitespace())
    {
        return None;
    }
    let bytes = value.as_bytes();
    if !bytes.len().is_multiple_of(4) {
        return None;
    }

    let chunk_count = bytes.len() / 4;
    let mut out = Vec::with_capacity(chunk_count * 3);
    for (chunk_idx, chunk) in bytes.chunks_exact(4).enumerate() {
        let is_last = chunk_idx + 1 == chunk_count;
        let padding = match chunk {
            [_, _, b'=', b'='] => 2,
            [_, _, _, b'='] => 1,
            [_, _, _, _] => 0,
            _ => return None,
        };
        if padding > 0 && !is_last {
            return None;
        }
        if chunk[0] == b'=' || chunk[1] == b'=' {
            return None;
        }

        let v0 = base64_standard_value(chunk[0])?;
        let v1 = base64_standard_value(chunk[1])?;
        let v2 = if padding == 2 {
            0
        } else {
            base64_standard_value(chunk[2])?
        };
        let v3 = if padding == 0 {
            base64_standard_value(chunk[3])?
        } else {
            0
        };

        out.push((v0 << 2) | (v1 >> 4));
        if padding < 2 {
            out.push(((v1 & 0x0f) << 4) | (v2 >> 2));
        }
        if padding == 0 {
            out.push(((v2 & 0x03) << 6) | v3);
        }
    }
    Some(out)
}

fn encode_standard_base64(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let b0 = chunk[0];
        let b1 = chunk.get(1).copied().unwrap_or(0);
        let b2 = chunk.get(2).copied().unwrap_or(0);
        out.push(TABLE[(b0 >> 2) as usize] as char);
        out.push(TABLE[(((b0 & 0x03) << 4) | (b1 >> 4)) as usize] as char);
        if chunk.len() > 1 {
            out.push(TABLE[(((b1 & 0x0f) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(TABLE[(b2 & 0x3f) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

fn blake2b256_bytes(payload: &[u8]) -> H256 {
    let mut hasher = Blake2bVar::new(32).expect("fixed hash length");
    hasher.update(payload);
    let mut out = [0u8; 32];
    hasher
        .finalize_variable(&mut out)
        .expect("fixed hash length");
    out
}

/// Return the Solana deployed verifier program code hash used by SCCP evidence.
pub fn sccp_solana_verifier_program_code_hash_v1(program_bytes: &[u8]) -> Option<H256> {
    if program_bytes.is_empty()
        || !program_bytes.iter().copied().any(|byte| byte != 0)
        || !program_bytes.starts_with(SCCP_SOLANA_BPF_ELF_MAGIC)
    {
        return None;
    }
    Some(blake2b256_bytes(program_bytes))
}

/// Return the deployed Substrate runtime code hash used by SCCP evidence.
pub fn sccp_substrate_runtime_code_hash_v1(runtime_code: &[u8]) -> Option<H256> {
    if runtime_code.is_empty() || !runtime_code.iter().copied().any(|byte| byte != 0) {
        return None;
    }
    Some(blake2b256_bytes(runtime_code))
}

fn solana_upgradeable_program_account_data(programdata_address: [u8; 32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(SCCP_SOLANA_UPGRADEABLE_PROGRAM_ACCOUNT_LEN);
    out.extend_from_slice(&SCCP_SOLANA_UPGRADEABLE_LOADER_PROGRAM_TAG.to_le_bytes());
    out.extend_from_slice(&programdata_address);
    out
}

fn solana_immutable_programdata_metadata(programdata_slot: u64) -> Vec<u8> {
    let mut out = Vec::with_capacity(SCCP_SOLANA_PROGRAMDATA_METADATA_LEN);
    out.extend_from_slice(&SCCP_SOLANA_UPGRADEABLE_LOADER_PROGRAMDATA_TAG.to_le_bytes());
    out.extend_from_slice(&programdata_slot.to_le_bytes());
    out.push(0);
    out.extend_from_slice(&[0u8; 32]);
    out
}

fn solana_destination_rollout_programdata_evidence(
    rollout: &SccpDestinationRolloutV1,
) -> Option<(
    [u8; 32],
    [u8; 32],
    u64,
    u64,
    u64,
    u64,
    Vec<u8>,
    Vec<u8>,
    Vec<u8>,
)> {
    if rollout.solana_rpc_commitment.as_deref()? != "finalized"
        || rollout.solana_program_owner.as_deref()? != SCCP_SOLANA_UPGRADEABLE_LOADER_ID
        || rollout.solana_programdata_owner.as_deref()? != SCCP_SOLANA_UPGRADEABLE_LOADER_ID
        || rollout.solana_program_immutable != Some(true)
    {
        return None;
    }

    let verifier_program =
        decode_sol_base58_address(rollout.verifier_identity.as_deref()?.as_bytes())?;
    let programdata_address =
        decode_sol_base58_address(rollout.solana_programdata_address.as_deref()?.as_bytes())?;
    if verifier_program == programdata_address
        || !programdata_address.iter().copied().any(|byte| byte != 0)
    {
        return None;
    }

    let programdata_slot =
        sccp_canonical_positive_u64(rollout.solana_programdata_slot.as_deref()?)?;
    let expected_programdata_slot =
        sccp_canonical_positive_u64(rollout.solana_expected_programdata_slot.as_deref()?)?;
    if programdata_slot != expected_programdata_slot {
        return None;
    }
    let program_account_context_slot =
        sccp_canonical_positive_u64(rollout.solana_program_account_context_slot.as_deref()?)?;
    let programdata_account_context_slot =
        sccp_canonical_positive_u64(rollout.solana_programdata_account_context_slot.as_deref()?)?;
    if program_account_context_slot < programdata_slot
        || programdata_account_context_slot < programdata_slot
    {
        return None;
    }

    let program_account_data =
        decode_standard_base64(rollout.solana_program_account_data_base64.as_deref()?)?;
    if program_account_data != solana_upgradeable_program_account_data(programdata_address) {
        return None;
    }

    let programdata_metadata =
        decode_standard_base64(rollout.solana_programdata_metadata_base64.as_deref()?)?;
    let expected_metadata = solana_immutable_programdata_metadata(programdata_slot);
    if programdata_metadata != expected_metadata {
        return None;
    }
    let metadata_hash = blake2b256_bytes(&programdata_metadata);
    if required_hex_string_is_nonzero::<32>(
        rollout.solana_programdata_metadata_blake2b256.as_deref(),
    )
    .as_ref()
        != Some(&metadata_hash)
    {
        return None;
    }

    let programdata_executable =
        decode_standard_base64(rollout.solana_programdata_executable_base64.as_deref()?)?;
    let executable_hash = sccp_solana_verifier_program_code_hash_v1(&programdata_executable)?;
    if required_hex_string_is_nonzero::<32>(
        rollout.solana_programdata_executable_blake2b256.as_deref(),
    )
    .as_ref()
        != Some(&executable_hash)
        || required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref()).as_ref()
            != Some(&executable_hash)
    {
        return None;
    }

    Some((
        verifier_program,
        programdata_address,
        programdata_slot,
        expected_programdata_slot,
        program_account_context_slot,
        programdata_account_context_slot,
        program_account_data,
        programdata_metadata,
        programdata_executable,
    ))
}

fn sccp_destination_rollout_solana_live_fields_are_absent(
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    rollout.solana_rpc_commitment.is_none()
        && rollout.solana_program_owner.is_none()
        && rollout.solana_programdata_owner.is_none()
        && rollout.solana_program_immutable.is_none()
        && rollout.solana_program_account_data_base64.is_none()
        && rollout.solana_programdata_address.is_none()
        && rollout.solana_programdata_slot.is_none()
        && rollout.solana_expected_programdata_slot.is_none()
        && rollout.solana_program_account_context_slot.is_none()
        && rollout.solana_programdata_account_context_slot.is_none()
        && rollout.solana_programdata_metadata_blake2b256.is_none()
        && rollout.solana_programdata_metadata_base64.is_none()
        && rollout.solana_programdata_executable_blake2b256.is_none()
        && rollout.solana_programdata_executable_base64.is_none()
}

fn sccp_solana_destination_rollout_live_programdata_evidence_is_ready(
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    solana_destination_rollout_programdata_evidence(rollout).is_some()
}

fn sccp_destination_rollout_ton_live_fields_are_absent(rollout: &SccpDestinationRolloutV1) -> bool {
    rollout.ton_account_status.is_none()
        && rollout.ton_account_state_hash.is_none()
        && rollout.ton_last_transaction_lt.is_none()
        && rollout.ton_last_transaction_hash.is_none()
        && rollout.ton_verifier_code_boc_root_hash.is_none()
        && rollout.ton_verifier_code_boc.is_none()
}

fn sccp_ton_destination_rollout_live_account_evidence_is_ready(
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    if rollout.ton_account_status.as_deref() != Some("active") {
        return false;
    }
    if required_hex_string_is_nonzero::<32>(rollout.ton_account_state_hash.as_deref()).is_none() {
        return false;
    }
    if !rollout
        .ton_last_transaction_lt
        .as_deref()
        .is_some_and(sccp_ton_live_decimal_is_positive_canonical)
    {
        return false;
    }
    if required_hex_string_is_nonzero::<32>(rollout.ton_last_transaction_hash.as_deref()).is_none()
    {
        return false;
    }

    let Some(verifier_code_hash) =
        required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref())
    else {
        return false;
    };
    let Some(code_boc_root_hash) =
        required_hex_string_is_nonzero::<32>(rollout.ton_verifier_code_boc_root_hash.as_deref())
    else {
        return false;
    };
    if code_boc_root_hash != verifier_code_hash {
        return false;
    }
    let Some(code_boc) = rollout
        .ton_verifier_code_boc
        .as_deref()
        .and_then(decode_hex_bytes)
    else {
        return false;
    };
    if code_boc.is_empty() || code_boc.len() > SCCP_TON_MAX_BOC_BYTES {
        return false;
    }

    sccp_ton_boc_single_root_hash(&code_boc) == Some(code_boc_root_hash)
}

fn substrate_destination_rollout_finalized_runtime_evidence(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> Option<(H256, String, u32, u32, Vec<u8>)> {
    if !matches!(
        domain,
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2
    ) || rollout.domain != domain
        || !substrate_runtime_verifier_identity_is_valid(rollout.verifier_identity.as_deref()?)
    {
        return None;
    }
    let expected_chain = sccp_chain_key_for_domain(domain)?;
    if rollout.substrate_runtime_spec_name.as_deref()? != expected_chain {
        return None;
    }

    let verifier_code_hash =
        required_hex_string_is_nonzero::<32>(rollout.verifier_code_hash.as_deref())?;
    let finalized_head =
        required_hex_string_is_nonzero::<32>(rollout.substrate_finalized_head.as_deref())?;
    let runtime_spec_version =
        sccp_canonical_u32_decimal(rollout.substrate_runtime_spec_version.as_deref()?)?;
    let runtime_transaction_version =
        sccp_canonical_u32_decimal(rollout.substrate_runtime_transaction_version.as_deref()?)?;
    let runtime_code = decode_standard_base64(rollout.substrate_runtime_code_base64.as_deref()?)?;
    let runtime_code_hash = sccp_substrate_runtime_code_hash_v1(&runtime_code)?;
    if required_hex_string_is_nonzero::<32>(rollout.substrate_runtime_code_hash.as_deref()).as_ref()
        != Some(&runtime_code_hash)
        || runtime_code_hash != verifier_code_hash
    {
        return None;
    }

    Some((
        finalized_head,
        expected_chain.to_owned(),
        runtime_spec_version,
        runtime_transaction_version,
        runtime_code,
    ))
}

fn sccp_destination_rollout_substrate_live_fields_are_absent(
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    rollout.substrate_finalized_head.is_none()
        && rollout.substrate_runtime_spec_name.is_none()
        && rollout.substrate_runtime_spec_version.is_none()
        && rollout.substrate_runtime_transaction_version.is_none()
        && rollout.substrate_runtime_code_hash.is_none()
        && rollout.substrate_runtime_code_base64.is_none()
}

fn sccp_substrate_destination_rollout_finalized_runtime_evidence_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    substrate_destination_rollout_finalized_runtime_evidence(domain, rollout).is_some()
}

fn sccp_destination_rollout_live_chain_metadata_is_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    match domain {
        SCCP_DOMAIN_SOL => {
            sccp_destination_rollout_ton_live_fields_are_absent(rollout)
                && sccp_destination_rollout_substrate_live_fields_are_absent(rollout)
                && sccp_solana_destination_rollout_live_programdata_evidence_is_ready(rollout)
        }
        SCCP_DOMAIN_TON => {
            sccp_destination_rollout_solana_live_fields_are_absent(rollout)
                && sccp_destination_rollout_substrate_live_fields_are_absent(rollout)
                && sccp_ton_destination_rollout_live_account_evidence_is_ready(rollout)
        }
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2 => {
            sccp_destination_rollout_solana_live_fields_are_absent(rollout)
                && sccp_destination_rollout_ton_live_fields_are_absent(rollout)
                && sccp_substrate_destination_rollout_finalized_runtime_evidence_is_ready(
                    domain, rollout,
                )
        }
        _ => {
            sccp_destination_rollout_solana_live_fields_are_absent(rollout)
                && sccp_destination_rollout_ton_live_fields_are_absent(rollout)
                && sccp_destination_rollout_substrate_live_fields_are_absent(rollout)
        }
    }
}

/// Return whether destination verifier deployment material is sufficient for production.
pub fn sccp_destination_rollout_is_production_ready(
    domain: u32,
    rollout: &SccpDestinationRolloutV1,
) -> bool {
    let Some(expected_plan) = sccp_destination_verifier_plan_for_domain(domain) else {
        return false;
    };
    let Some(expected_chain) = sccp_chain_key_for_domain(domain) else {
        return false;
    };

    rollout.version == 1
        && rollout.domain == domain
        && rollout.chain == expected_chain
        && rollout.verifier_plan == expected_plan
        && rollout.immutable_verifier_ready
        && rollout.anchors_ready
        && rollout.blockers.is_empty()
        && non_empty_metadata(rollout.verifier_identity.as_deref())
        && rollout
            .verifier_code_hash
            .as_deref()
            .is_some_and(hex32_string_is_nonzero)
        && sccp_destination_rollout_verifier_key_hash_is_ready(domain, rollout)
        && sccp_destination_rollout_binding_metadata_is_ready(domain, rollout)
        && sccp_destination_rollout_live_chain_metadata_is_ready(domain, rollout)
        && non_empty_metadata(rollout.anchor_id.as_deref())
        && sccp_destination_rollout_matches_domain_profile(domain, rollout)
}

fn sccp_route_allowlist_id_for_domain(domain: u32) -> Option<&'static str> {
    match domain {
        SCCP_DOMAIN_ETH => Some(SCCP_ETH_MAINNET_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_BSC => Some(SCCP_BSC_MAINNET_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_SOL => Some(SCCP_SOLANA_MAINNET_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_TON => Some(SCCP_TON_MAINNET_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_TRON => Some(SCCP_TRON_MAINNET_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_SORA_KUSAMA => Some(SCCP_SORA_KUSAMA_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_SORA_POLKADOT => Some(SCCP_SORA_POLKADOT_ROUTE_ALLOWLIST_ID_V1),
        SCCP_DOMAIN_SORA2 => Some(SCCP_SORA2_ROUTE_ALLOWLIST_ID_V1),
        _ => None,
    }
}

fn sccp_route_allowlist_blockers_for_domain(domain: u32) -> Option<Vec<String>> {
    sccp_route_allowlist_id_for_domain(domain)?;
    Some(vec![
        "production route allowlist is not anchored for this SCCP lane".to_owned(),
        "governance has not activated this SCCP route profile".to_owned(),
    ])
}

