pub fn sccp_profiled_route_allowlist_v1(
    domain: u32,
    route_allowlist_hash: String,
) -> Option<SccpRouteAllowlistReadinessV1> {
    let mut allowlist = sccp_route_allowlist_for_domain(domain)?;
    allowlist.route_allowlist_id = Some(sccp_route_allowlist_id_for_domain(domain)?.to_owned());
    allowlist.route_allowlist_hash = Some(route_allowlist_hash);
    allowlist.routes_allowlisted = true;
    allowlist.blockers.clear();
    sccp_route_allowlist_is_production_ready(domain, &allowlist).then_some(allowlist)
}

/// Return canonical route-allowlist evidence bytes for a fully bound SCCP lane.
pub fn canonical_sccp_route_allowlist_evidence_bytes_v1(
    domain: u32,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_binding_hash: H256,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&source_verifier_material_hash)
        || !h256_is_nonzero(&source_adapter_engine_deployment_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !sccp_nonzero_h256_values_are_pairwise_distinct(&[
            source_verifier_material_hash,
            source_adapter_engine_deployment_hash,
            destination_binding_hash,
        ])
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, domain);
    push_vec(&mut out, sccp_chain_key_for_domain(domain)?.as_bytes());
    push_vec(
        &mut out,
        SccpRouteActivationPolicyV1::GovernanceAllowlist
            .as_str()
            .as_bytes(),
    );
    push_vec(
        &mut out,
        sccp_route_allowlist_id_for_domain(domain)?.as_bytes(),
    );
    out.extend_from_slice(&source_verifier_material_hash);
    out.extend_from_slice(&source_adapter_engine_deployment_hash);
    out.extend_from_slice(&destination_binding_hash);
    Some(out)
}

/// Return the canonical route-allowlist hash for a fully bound SCCP lane.
pub fn sccp_route_allowlist_hash_for_lane_evidence_v1(
    domain: u32,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_binding_hash: H256,
) -> Option<H256> {
    Some(prefixed_blake2b(
        b"sccp:route-allowlist:lane-evidence:v1",
        &canonical_sccp_route_allowlist_evidence_bytes_v1(
            domain,
            source_verifier_material_hash,
            source_adapter_engine_deployment_hash,
            destination_binding_hash,
        )?,
    ))
}

/// Return canonical EVM route-canary evidence bytes from a live MessageProofAccepted event.
pub fn canonical_sccp_evm_route_canary_evidence_bytes_v1(
    domain: u32,
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
    transaction_hash: H256,
    log_index: u32,
    receipt_block_number: u64,
    receipt_block_hash: H256,
    block_receipts_root: H256,
    call_data_sha256: H256,
    message_id: H256,
    payload_hash: H256,
    target_domain: u32,
    statement_hash: H256,
    commitment_root: H256,
    finality_height: H256,
    finality_block_hash: H256,
    proof_version: u32,
    proof_source_domain: u32,
    used_message_proof: bool,
) -> Option<Vec<u8>> {
    if !matches!(domain, SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC)
        || destination_rollout.domain != domain
        || target_domain != domain
        || receipt_block_number == 0
        || !h256_is_nonzero(&route_allowlist_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !h256_is_nonzero(&transaction_hash)
        || !h256_is_nonzero(&receipt_block_hash)
        || !h256_is_nonzero(&block_receipts_root)
        || !h256_is_nonzero(&call_data_sha256)
        || !h256_is_nonzero(&message_id)
        || !h256_is_nonzero(&payload_hash)
        || !h256_is_nonzero(&statement_hash)
        || !h256_is_nonzero(&commitment_root)
        || !h256_is_nonzero(&finality_height)
        || !h256_is_nonzero(&finality_block_hash)
        || proof_version != 1
        || proof_source_domain != SCCP_DOMAIN_SORA
        || !used_message_proof
        || !sccp_destination_rollout_is_production_ready(domain, destination_rollout)
    {
        return None;
    }
    if !sccp_nonzero_h256_values_are_pairwise_distinct(&[
        transaction_hash,
        receipt_block_hash,
        block_receipts_root,
        call_data_sha256,
        message_id,
        payload_hash,
        statement_hash,
        commitment_root,
        finality_height,
        finality_block_hash,
    ]) {
        return None;
    }
    if destination_binding_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.destination_binding_hash.as_deref(),
        )?
    {
        return None;
    }
    let bridge_address = required_hex_string_is_nonzero::<20>(
        destination_rollout.destination_bridge_address.as_deref(),
    )?;
    let network_id = required_hex_string_is_nonzero::<32>(
        destination_rollout.destination_network_id.as_deref(),
    )?;
    let verifier_backend = sccp_verifier_backend_for_domain(domain)?;
    if verifier_backend.family != SccpVerifierBackendFamilyV1::EvmGroth16Bn254
        || verifier_backend.key != SCCP_EVM_GROTH16_BN254_PROOF_BACKEND_V1
    {
        return None;
    }
    let verifier_backend_hash = keccak256_bytes(verifier_backend.key.as_bytes());
    let proof_family_hash = keccak256_bytes(SCCP_STARK_FRI_PROOF_FAMILY_V1.as_bytes());

    let mut out = Vec::new();
    push_u8(&mut out, 3);
    out.extend_from_slice(&route_allowlist_hash);
    out.extend_from_slice(&bridge_address);
    out.extend_from_slice(&transaction_hash);
    push_u32(&mut out, log_index);
    push_u64(&mut out, receipt_block_number);
    out.extend_from_slice(&receipt_block_hash);
    out.extend_from_slice(&block_receipts_root);
    out.extend_from_slice(&call_data_sha256);
    out.extend_from_slice(&message_id);
    push_u32(&mut out, SCCP_DOMAIN_SORA);
    push_u32(&mut out, target_domain);
    out.extend_from_slice(&payload_hash);
    out.extend_from_slice(&commitment_root);
    out.extend_from_slice(&finality_height);
    out.extend_from_slice(&finality_block_hash);
    out.extend_from_slice(&statement_hash);
    push_u32(&mut out, proof_version);
    push_u32(&mut out, proof_source_domain);
    out.extend_from_slice(&destination_binding_hash);
    out.extend_from_slice(&verifier_backend_hash);
    out.extend_from_slice(&proof_family_hash);
    out.extend_from_slice(&network_id);
    push_u8(&mut out, u8::from(used_message_proof));
    Some(out)
}

/// Return the canonical EVM route-canary evidence hash from a live event transcript.
pub fn sccp_evm_route_canary_evidence_hash_v1(
    domain: u32,
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
    transaction_hash: H256,
    log_index: u32,
    receipt_block_number: u64,
    receipt_block_hash: H256,
    block_receipts_root: H256,
    call_data_sha256: H256,
    message_id: H256,
    payload_hash: H256,
    target_domain: u32,
    statement_hash: H256,
    commitment_root: H256,
    finality_height: H256,
    finality_block_hash: H256,
    proof_version: u32,
    proof_source_domain: u32,
    used_message_proof: bool,
) -> Option<H256> {
    Some(prefixed_blake2b(
        b"iroha:sccp:evm-route-canary-evidence:v3",
        &canonical_sccp_evm_route_canary_evidence_bytes_v1(
            domain,
            route_allowlist_hash,
            destination_binding_hash,
            destination_rollout,
            transaction_hash,
            log_index,
            receipt_block_number,
            receipt_block_hash,
            block_receipts_root,
            call_data_sha256,
            message_id,
            payload_hash,
            target_domain,
            statement_hash,
            commitment_root,
            finality_height,
            finality_block_hash,
            proof_version,
            proof_source_domain,
            used_message_proof,
        )?,
    ))
}

/// Return canonical TRON route-canary evidence bytes from a live MessageProofAccepted event.
pub fn canonical_sccp_tron_route_canary_evidence_bytes_v1(
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
    transaction_id: H256,
    transaction_owner_address: [u8; 21],
    block_number: u64,
    block_timestamp: u64,
    log_index: u32,
    message_id: H256,
    call_data_sha256: H256,
    payload_hash: H256,
    target_domain: u32,
    statement_hash: H256,
    commitment_root: H256,
    finality_height: H256,
    finality_block_hash: H256,
    proof_version: u32,
    proof_source_domain: u32,
    used_message_proof: bool,
    raw_data_owner_matches_transaction: bool,
    signature_sha256: H256,
    signature_recovered_address: [u8; 21],
    signature_recovers_to_owner: bool,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&route_allowlist_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !h256_is_nonzero(&transaction_id)
        || transaction_owner_address[0] != 0x41
        || !transaction_owner_address[1..]
            .iter()
            .copied()
            .any(|byte| byte != 0)
        || block_number == 0
        || !h256_is_nonzero(&message_id)
        || !h256_is_nonzero(&call_data_sha256)
        || !h256_is_nonzero(&payload_hash)
        || target_domain != SCCP_DOMAIN_TRON
        || !h256_is_nonzero(&statement_hash)
        || !h256_is_nonzero(&commitment_root)
        || !h256_is_nonzero(&finality_height)
        || !h256_is_nonzero(&finality_block_hash)
        || proof_version != 1
        || proof_source_domain != SCCP_DOMAIN_SORA
        || !used_message_proof
        || !raw_data_owner_matches_transaction
        || !h256_is_nonzero(&signature_sha256)
        || signature_recovered_address[0] != 0x41
        || !signature_recovered_address[1..]
            .iter()
            .copied()
            .any(|byte| byte != 0)
        || !signature_recovers_to_owner
        || transaction_owner_address != signature_recovered_address
        || !sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_TRON, destination_rollout)
    {
        return None;
    }
    if !sccp_nonzero_h256_values_are_pairwise_distinct(&[
        transaction_id,
        call_data_sha256,
        message_id,
        payload_hash,
        statement_hash,
        commitment_root,
        finality_height,
        finality_block_hash,
        signature_sha256,
    ]) {
        return None;
    }
    if destination_binding_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.destination_binding_hash.as_deref(),
        )?
    {
        return None;
    }
    let network_id = required_hex_string_is_nonzero::<32>(
        destination_rollout.destination_network_id.as_deref(),
    )?;
    let verifier_identity = destination_rollout.verifier_identity.as_deref()?;
    let verifier_address_payload =
        decode_tron_base58check_nonzero_address(verifier_identity.as_bytes())?;
    let verifier_backend = sccp_verifier_backend_for_domain(SCCP_DOMAIN_TRON)?;
    if verifier_backend.family != SccpVerifierBackendFamilyV1::TronGroth16Bn254
        || verifier_backend.key != SCCP_TRON_GROTH16_BN254_PROOF_BACKEND_V1
    {
        return None;
    }
    let verifier_backend_hash = keccak256_bytes(verifier_backend.key.as_bytes());
    let proof_family_hash = keccak256_bytes(SCCP_STARK_FRI_PROOF_FAMILY_V1.as_bytes());

    let mut out = Vec::new();
    push_u8(&mut out, 3);
    out.extend_from_slice(&route_allowlist_hash);
    out.extend_from_slice(&verifier_address_payload);
    out.extend_from_slice(&transaction_id);
    out.extend_from_slice(&transaction_owner_address);
    push_u64(&mut out, block_number);
    push_u64(&mut out, block_timestamp);
    push_u32(&mut out, log_index);
    out.extend_from_slice(&call_data_sha256);
    out.extend_from_slice(&message_id);
    push_u32(&mut out, SCCP_DOMAIN_SORA);
    push_u32(&mut out, target_domain);
    out.extend_from_slice(&payload_hash);
    out.extend_from_slice(&commitment_root);
    out.extend_from_slice(&finality_height);
    out.extend_from_slice(&finality_block_hash);
    out.extend_from_slice(&statement_hash);
    push_u32(&mut out, proof_version);
    push_u32(&mut out, proof_source_domain);
    out.extend_from_slice(&destination_binding_hash);
    out.extend_from_slice(&verifier_backend_hash);
    out.extend_from_slice(&proof_family_hash);
    out.extend_from_slice(&network_id);
    push_u8(&mut out, u8::from(used_message_proof));
    push_u8(&mut out, u8::from(raw_data_owner_matches_transaction));
    out.extend_from_slice(&signature_sha256);
    out.extend_from_slice(&signature_recovered_address);
    push_u8(&mut out, u8::from(signature_recovers_to_owner));
    Some(out)
}

