/// Return canonical TON route-canary evidence bytes for a live account snapshot.
pub fn canonical_sccp_ton_route_canary_evidence_bytes_v1(
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
    account_state_hash: H256,
    last_transaction_lt: &str,
    last_transaction_hash: H256,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&route_allowlist_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !h256_is_nonzero(&source_verifier_material_hash)
        || !h256_is_nonzero(&source_adapter_engine_deployment_hash)
        || !h256_is_nonzero(&account_state_hash)
        || !h256_is_nonzero(&last_transaction_hash)
        || !sccp_ton_live_decimal_is_positive_canonical(last_transaction_lt)
        || !sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_TON, destination_rollout)
    {
        return None;
    }
    let verifier_identity = destination_rollout.verifier_identity.as_deref()?;
    if !ton_verifier_contract_address_is_valid(verifier_identity) {
        return None;
    }
    let account_status = destination_rollout.ton_account_status.as_deref()?;
    if account_status != "active" {
        return None;
    }
    if destination_binding_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.destination_binding_hash.as_deref(),
        )?
    {
        return None;
    }
    if account_state_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.ton_account_state_hash.as_deref(),
        )?
    {
        return None;
    }
    if destination_rollout.ton_last_transaction_lt.as_deref()? != last_transaction_lt {
        return None;
    }
    if last_transaction_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.ton_last_transaction_hash.as_deref(),
        )?
    {
        return None;
    }
    let verifier_code_hash =
        required_hex_string_is_nonzero::<32>(destination_rollout.verifier_code_hash.as_deref())?;
    let verifier_code_boc_root_hash = required_hex_string_is_nonzero::<32>(
        destination_rollout
            .ton_verifier_code_boc_root_hash
            .as_deref(),
    )?;
    if verifier_code_hash != verifier_code_boc_root_hash {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, SCCP_DOMAIN_SORA);
    push_u32(&mut out, SCCP_DOMAIN_TON);
    out.extend_from_slice(&route_allowlist_hash);
    out.extend_from_slice(&destination_binding_hash);
    out.extend_from_slice(&source_verifier_material_hash);
    out.extend_from_slice(&source_adapter_engine_deployment_hash);
    push_vec(&mut out, verifier_identity.as_bytes());
    out.extend_from_slice(&verifier_code_hash);
    push_vec(&mut out, account_status.as_bytes());
    out.extend_from_slice(&account_state_hash);
    push_vec(&mut out, last_transaction_lt.as_bytes());
    out.extend_from_slice(&last_transaction_hash);
    out.extend_from_slice(&verifier_code_boc_root_hash);
    Some(out)
}

/// Return the canonical TON route-canary evidence hash from a live account snapshot.
pub fn sccp_ton_route_canary_evidence_hash_v1(
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
    account_state_hash: H256,
    last_transaction_lt: &str,
    last_transaction_hash: H256,
) -> Option<H256> {
    Some(prefixed_blake2b(
        b"iroha:sccp:ton-route-canary-live-account:v1",
        &canonical_sccp_ton_route_canary_evidence_bytes_v1(
            route_allowlist_hash,
            destination_binding_hash,
            source_verifier_material_hash,
            source_adapter_engine_deployment_hash,
            destination_rollout,
            account_state_hash,
            last_transaction_lt,
            last_transaction_hash,
        )?,
    ))
}

/// Return canonical Solana route-canary evidence bytes for a live immutable ProgramData snapshot.
pub fn canonical_sccp_solana_route_canary_evidence_bytes_v1(
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&route_allowlist_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !h256_is_nonzero(&source_verifier_material_hash)
        || !h256_is_nonzero(&source_adapter_engine_deployment_hash)
        || !sccp_destination_rollout_is_production_ready(SCCP_DOMAIN_SOL, destination_rollout)
    {
        return None;
    }
    if destination_binding_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.destination_binding_hash.as_deref(),
        )?
    {
        return None;
    }
    let verifier_code_hash =
        required_hex_string_is_nonzero::<32>(destination_rollout.verifier_code_hash.as_deref())?;
    let (
        verifier_program,
        programdata_address,
        programdata_slot,
        expected_programdata_slot,
        program_account_context_slot,
        programdata_account_context_slot,
        program_account_data,
        programdata_metadata,
        programdata_executable,
    ) = solana_destination_rollout_programdata_evidence(destination_rollout)?;
    let rpc_commitment = destination_rollout.solana_rpc_commitment.as_deref()?;
    let program_owner = destination_rollout.solana_program_owner.as_deref()?;
    let programdata_owner = destination_rollout.solana_programdata_owner.as_deref()?;

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, SCCP_DOMAIN_SORA);
    push_u32(&mut out, SCCP_DOMAIN_SOL);
    out.extend_from_slice(&route_allowlist_hash);
    out.extend_from_slice(&destination_binding_hash);
    out.extend_from_slice(&source_verifier_material_hash);
    out.extend_from_slice(&source_adapter_engine_deployment_hash);
    out.extend_from_slice(&verifier_program);
    out.extend_from_slice(&verifier_code_hash);
    push_vec(&mut out, rpc_commitment.as_bytes());
    push_vec(&mut out, program_owner.as_bytes());
    push_vec(&mut out, programdata_owner.as_bytes());
    push_u8(&mut out, 1);
    push_vec(&mut out, &program_account_data);
    out.extend_from_slice(&programdata_address);
    push_u64(&mut out, programdata_slot);
    push_u64(&mut out, expected_programdata_slot);
    push_u64(&mut out, program_account_context_slot);
    push_u64(&mut out, programdata_account_context_slot);
    push_vec(&mut out, &programdata_metadata);
    push_vec(&mut out, &programdata_executable);
    Some(out)
}

/// Return the canonical Solana route-canary evidence hash from live ProgramData metadata.
pub fn sccp_solana_route_canary_evidence_hash_v1(
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_SOLANA_ROUTE_CANARY_LIVE_PROGRAM_LABEL_V1,
        &canonical_sccp_solana_route_canary_evidence_bytes_v1(
            route_allowlist_hash,
            destination_binding_hash,
            source_verifier_material_hash,
            source_adapter_engine_deployment_hash,
            destination_rollout,
        )?,
    ))
}

/// Return canonical Substrate-family route-canary evidence bytes for a finalized runtime snapshot.
pub fn canonical_sccp_substrate_route_canary_evidence_bytes_v1(
    domain: u32,
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<Vec<u8>> {
    if !matches!(
        domain,
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2
    ) || !h256_is_nonzero(&route_allowlist_hash)
        || !h256_is_nonzero(&destination_binding_hash)
        || !h256_is_nonzero(&source_verifier_material_hash)
        || !h256_is_nonzero(&source_adapter_engine_deployment_hash)
        || !sccp_destination_rollout_is_production_ready(domain, destination_rollout)
    {
        return None;
    }
    if destination_binding_hash
        != required_hex_string_is_nonzero::<32>(
            destination_rollout.destination_binding_hash.as_deref(),
        )?
    {
        return None;
    }
    let verifier_entrypoint = destination_rollout.verifier_identity.as_deref()?;
    let verifier_code_hash =
        required_hex_string_is_nonzero::<32>(destination_rollout.verifier_code_hash.as_deref())?;
    let (
        finalized_head,
        runtime_spec_name,
        runtime_spec_version,
        runtime_transaction_version,
        runtime_code,
    ) = substrate_destination_rollout_finalized_runtime_evidence(domain, destination_rollout)?;

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, SCCP_DOMAIN_SORA);
    push_u32(&mut out, domain);
    out.extend_from_slice(&route_allowlist_hash);
    out.extend_from_slice(&destination_binding_hash);
    out.extend_from_slice(&source_verifier_material_hash);
    out.extend_from_slice(&source_adapter_engine_deployment_hash);
    push_vec(&mut out, sccp_chain_key_for_domain(domain)?.as_bytes());
    push_vec(&mut out, verifier_entrypoint.as_bytes());
    out.extend_from_slice(&verifier_code_hash);
    out.extend_from_slice(&finalized_head);
    push_vec(&mut out, runtime_spec_name.as_bytes());
    push_u32(&mut out, runtime_spec_version);
    push_u32(&mut out, runtime_transaction_version);
    push_vec(&mut out, &runtime_code);
    Some(out)
}

/// Return the canonical Substrate-family route-canary evidence hash.
pub fn sccp_substrate_route_canary_evidence_hash_v1(
    domain: u32,
    route_allowlist_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_SUBSTRATE_ROUTE_CANARY_FINALIZED_RUNTIME_LABEL_V1,
        &canonical_sccp_substrate_route_canary_evidence_bytes_v1(
            domain,
            route_allowlist_hash,
            destination_binding_hash,
            source_verifier_material_hash,
            source_adapter_engine_deployment_hash,
            destination_rollout,
        )?,
    ))
}

/// Return the canonical route-allowlist hash from concrete governed lane records.
pub fn sccp_route_allowlist_hash_from_deployment_materials_v1(
    domain: u32,
    source_verifier_material: &SccpSourceVerifierMaterialV1,
    source_adapter_deployment: &SccpSourceAdapterEngineDeploymentV1,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<H256> {
    if !sccp_route_allowlist_lane_evidence_components_are_ready(
        domain,
        source_verifier_material,
        source_adapter_deployment,
        destination_rollout,
    ) {
        return None;
    }

    let destination_binding_hash = required_hex_string_is_nonzero::<32>(
        destination_rollout.destination_binding_hash.as_deref(),
    )?;
    sccp_route_allowlist_hash_for_lane_evidence_v1(
        domain,
        sccp_source_verifier_material_hash(source_verifier_material),
        sccp_source_adapter_engine_deployment_hash(source_adapter_deployment),
        destination_binding_hash,
    )
}

/// Build a production-ready route allowlist bound to exact governed lane records.
pub fn sccp_profiled_route_allowlist_for_lane_evidence_v1(
    domain: u32,
    source_verifier_material: &SccpSourceVerifierMaterialV1,
    source_adapter_deployment: &SccpSourceAdapterEngineDeploymentV1,
    destination_rollout: &SccpDestinationRolloutV1,
) -> Option<SccpRouteAllowlistReadinessV1> {
    let route_allowlist_hash = sccp_route_allowlist_hash_from_deployment_materials_v1(
        domain,
        source_verifier_material,
        source_adapter_deployment,
        destination_rollout,
    )?;
    sccp_profiled_route_allowlist_v1(domain, encode_0x_lower_hex(&route_allowlist_hash))
}

pub fn sccp_route_allowlist_with_canary_evidence_v1(
    mut allowlist: SccpRouteAllowlistReadinessV1,
    route_canary_evidence_hash: H256,
    destination_binding_hash: H256,
) -> Option<SccpRouteAllowlistReadinessV1> {
    let route_allowlist_hash =
        required_hex_string_is_nonzero::<32>(allowlist.route_allowlist_hash.as_deref())?;
    if !h256_is_nonzero(&route_canary_evidence_hash)
        || route_canary_evidence_hash == route_allowlist_hash
        || route_canary_evidence_hash == destination_binding_hash
        || !h256_is_nonzero(&destination_binding_hash)
    {
        return None;
    }
    allowlist.route_canary_status = Some("passed".to_owned());
    allowlist.route_canary_evidence_hash = Some(encode_0x_lower_hex(&route_canary_evidence_hash));
    allowlist.route_canary_route_allowlist_hash = Some(encode_0x_lower_hex(&route_allowlist_hash));
    allowlist.route_canary_destination_binding_hash =
        Some(encode_0x_lower_hex(&destination_binding_hash));
    Some(allowlist)
}

/// Attach route canary evidence after checking all governed lane record hashes.
pub fn sccp_route_allowlist_with_lane_canary_evidence_v1(
    allowlist: SccpRouteAllowlistReadinessV1,
    route_canary_evidence_hash: H256,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
) -> Option<SccpRouteAllowlistReadinessV1> {
    if !h256_is_nonzero(&source_verifier_material_hash)
        || !h256_is_nonzero(&source_adapter_engine_deployment_hash)
        || route_canary_evidence_hash == source_verifier_material_hash
        || route_canary_evidence_hash == source_adapter_engine_deployment_hash
    {
        return None;
    }
    sccp_route_allowlist_with_canary_evidence_v1(
        allowlist,
        route_canary_evidence_hash,
        destination_binding_hash,
    )
}

/// Attach EVM route canary evidence derived from a live MessageProofAccepted event.
pub fn sccp_evm_route_allowlist_with_lane_canary_evidence_v1(
    allowlist: SccpRouteAllowlistReadinessV1,
    destination_rollout: &SccpDestinationRolloutV1,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    transaction_hash: H256,
    log_index: u32,
    receipt_block_number: u64,
    receipt_block_hash: H256,
    block_receipts_root: H256,
    call_data_sha256: H256,
    message_id: H256,
    payload_hash: H256,
    target_domain: u32,
    statement_hash: H256,
    commitment_root: H256,
    finality_height: H256,
    finality_block_hash: H256,
    proof_version: u32,
    proof_source_domain: u32,
    used_message_proof: bool,
) -> Option<SccpRouteAllowlistReadinessV1> {
    if !matches!(allowlist.domain, SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC)
        || destination_rollout.domain != allowlist.domain
        || target_domain != allowlist.domain
        || proof_version != 1
        || proof_source_domain != SCCP_DOMAIN_SORA
        || !used_message_proof
    {
        return None;
    }
    let route_allowlist_hash =
        required_hex_string_is_nonzero::<32>(allowlist.route_allowlist_hash.as_deref())?;
    let route_canary_evidence_hash = sccp_evm_route_canary_evidence_hash_v1(
        allowlist.domain,
        route_allowlist_hash,
        destination_binding_hash,
        destination_rollout,
        transaction_hash,
        log_index,
        receipt_block_number,
        receipt_block_hash,
        block_receipts_root,
        call_data_sha256,
        message_id,
        payload_hash,
        target_domain,
        statement_hash,
        commitment_root,
        finality_height,
        finality_block_hash,
        proof_version,
        proof_source_domain,
        used_message_proof,
    )?;
    let mut allowlist = sccp_route_allowlist_with_lane_canary_evidence_v1(
        allowlist,
        route_canary_evidence_hash,
        destination_binding_hash,
        source_verifier_material_hash,
        source_adapter_engine_deployment_hash,
    )?;
    allowlist.evm_route_canary_transaction_hash = Some(encode_0x_lower_hex(&transaction_hash));
    allowlist.evm_route_canary_log_index = Some(log_index);
    allowlist.evm_route_canary_receipt_block_number = Some(receipt_block_number);
    allowlist.evm_route_canary_receipt_block_hash = Some(encode_0x_lower_hex(&receipt_block_hash));
    allowlist.evm_route_canary_block_receipts_root =
        Some(encode_0x_lower_hex(&block_receipts_root));
    allowlist.evm_route_canary_call_data_sha256 = Some(encode_0x_lower_hex(&call_data_sha256));
    allowlist.evm_route_canary_message_id = Some(encode_0x_lower_hex(&message_id));
    allowlist.evm_route_canary_payload_hash = Some(encode_0x_lower_hex(&payload_hash));
    allowlist.evm_route_canary_target_domain = Some(target_domain);
    allowlist.evm_route_canary_statement_hash = Some(encode_0x_lower_hex(&statement_hash));
    allowlist.evm_route_canary_commitment_root = Some(encode_0x_lower_hex(&commitment_root));
    allowlist.evm_route_canary_finality_height = Some(encode_0x_lower_hex(&finality_height));
    allowlist.evm_route_canary_finality_block_hash =
        Some(encode_0x_lower_hex(&finality_block_hash));
    allowlist.evm_route_canary_proof_version = Some(proof_version);
    allowlist.evm_route_canary_proof_source_domain = Some(proof_source_domain);
    allowlist.evm_route_canary_used_message_proof = Some(true);
    Some(allowlist)
}

/// Attach TRON route canary evidence derived from a live MessageProofAccepted event.
pub fn sccp_tron_route_allowlist_with_lane_canary_evidence_v1(
    allowlist: SccpRouteAllowlistReadinessV1,
    destination_rollout: &SccpDestinationRolloutV1,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    transaction_id: H256,
    transaction_owner_address: [u8; 21],
    block_number: u64,
    block_timestamp: u64,
    log_index: u32,
    message_id: H256,
    call_data_sha256: H256,
    payload_hash: H256,
    target_domain: u32,
    statement_hash: H256,
    commitment_root: H256,
    finality_height: H256,
    finality_block_hash: H256,
    proof_version: u32,
    proof_source_domain: u32,
    used_message_proof: bool,
    raw_data_owner_matches_transaction: bool,
    signature_sha256: H256,
    signature_recovered_address: [u8; 21],
    signature_recovers_to_owner: bool,
) -> Option<SccpRouteAllowlistReadinessV1> {
    if allowlist.domain != SCCP_DOMAIN_TRON
        || destination_rollout.domain != SCCP_DOMAIN_TRON
        || !used_message_proof
        || !raw_data_owner_matches_transaction
        || !signature_recovers_to_owner
        || !h256_is_nonzero(&signature_sha256)
        || block_number == 0
        || transaction_owner_address[0] != 0x41
        || !transaction_owner_address[1..]
            .iter()
            .copied()
            .any(|byte| byte != 0)
        || signature_recovered_address[0] != 0x41
        || !signature_recovered_address[1..]
            .iter()
            .copied()
            .any(|byte| byte != 0)
        || transaction_owner_address != signature_recovered_address
    {
        return None;
    }
    let route_allowlist_hash =
        required_hex_string_is_nonzero::<32>(allowlist.route_allowlist_hash.as_deref())?;
    let route_canary_evidence_hash = sccp_tron_route_canary_evidence_hash_v1(
        route_allowlist_hash,
        destination_binding_hash,
        destination_rollout,
        transaction_id,
        transaction_owner_address,
        block_number,
        block_timestamp,
        log_index,
        message_id,
        call_data_sha256,
        payload_hash,
        target_domain,
        statement_hash,
        commitment_root,
        finality_height,
        finality_block_hash,
        proof_version,
        proof_source_domain,
        used_message_proof,
        raw_data_owner_matches_transaction,
        signature_sha256,
        signature_recovered_address,
        signature_recovers_to_owner,
    )?;
    let mut allowlist = sccp_route_allowlist_with_lane_canary_evidence_v1(
        allowlist,
        route_canary_evidence_hash,
        destination_binding_hash,
        source_verifier_material_hash,
        source_adapter_engine_deployment_hash,
    )?;
    allowlist.tron_route_canary_transaction_id = Some(encode_0x_lower_hex(&transaction_id));
    allowlist.tron_route_canary_transaction_owner_address =
        Some(encode_0x_lower_hex(&transaction_owner_address));
    allowlist.tron_route_canary_block_number = Some(block_number);
    allowlist.tron_route_canary_block_timestamp = Some(block_timestamp);
    allowlist.tron_route_canary_log_index = Some(log_index);
    allowlist.tron_route_canary_message_id = Some(encode_0x_lower_hex(&message_id));
    allowlist.tron_route_canary_call_data_sha256 = Some(encode_0x_lower_hex(&call_data_sha256));
    allowlist.tron_route_canary_payload_hash = Some(encode_0x_lower_hex(&payload_hash));
    allowlist.tron_route_canary_target_domain = Some(target_domain);
    allowlist.tron_route_canary_statement_hash = Some(encode_0x_lower_hex(&statement_hash));
    allowlist.tron_route_canary_commitment_root = Some(encode_0x_lower_hex(&commitment_root));
    allowlist.tron_route_canary_finality_height = Some(encode_0x_lower_hex(&finality_height));
    allowlist.tron_route_canary_finality_block_hash =
        Some(encode_0x_lower_hex(&finality_block_hash));
    allowlist.tron_route_canary_proof_version = Some(proof_version);
    allowlist.tron_route_canary_proof_source_domain = Some(proof_source_domain);
    allowlist.tron_route_canary_used_message_proof = Some(true);
    allowlist.tron_route_canary_raw_data_owner_matches_transaction = Some(true);
    allowlist.tron_route_canary_signature_sha256 = Some(encode_0x_lower_hex(&signature_sha256));
    allowlist.tron_route_canary_signature_recovered_address =
        Some(encode_0x_lower_hex(&signature_recovered_address));
    allowlist.tron_route_canary_signature_recovers_to_owner = Some(true);
    Some(allowlist)
}

/// Attach TON route canary evidence derived from the live verifier account snapshot.
pub fn sccp_ton_route_allowlist_with_lane_canary_evidence_v1(
    allowlist: SccpRouteAllowlistReadinessV1,
    destination_rollout: &SccpDestinationRolloutV1,
    destination_binding_hash: H256,
    source_verifier_material_hash: H256,
    source_adapter_engine_deployment_hash: H256,
    account_state_hash: H256,
    last_transaction_lt: String,
    last_transaction_hash: H256,
) -> Option<SccpRouteAllowlistReadinessV1> {
    if allowlist.domain != SCCP_DOMAIN_TON || destination_rollout.domain != SCCP_DOMAIN_TON {
        return None;
    }
    let route_allowlist_hash =
        required_hex_string_is_nonzero::<32>(allowlist.route_allowlist_hash.as_deref())?;
    let route_canary_evidence_hash = sccp_ton_route_canary_evidence_hash_v1(
        route_allowlist_hash,
        destination_binding_hash,
        source_verifier_material_hash,
        source_adapter_engine_deployment_hash,
        destination_rollout,
        account_state_hash,
        &last_transaction_lt,
        last_transaction_hash,
    )?;
    let mut allowlist = sccp_route_allowlist_with_lane_canary_evidence_v1(
        allowlist,
        route_canary_evidence_hash,
        destination_binding_hash,
        source_verifier_material_hash,
        source_adapter_engine_deployment_hash,
    )?;
    allowlist.ton_route_canary_account_state_hash = Some(encode_0x_lower_hex(&account_state_hash));
    allowlist.ton_route_canary_last_transaction_lt = Some(last_transaction_lt);
    allowlist.ton_route_canary_last_transaction_hash =
        Some(encode_0x_lower_hex(&last_transaction_hash));
    Some(allowlist)
}

