fn push_sccp_source_adapter_deployment_solana_full_light_client_audit_bytes(
    out: &mut Vec<u8>,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) {
    if sccp_source_adapter_deployment_solana_full_light_client_audit_nonzero_count(deployment) == 0
    {
        return;
    }

    push_u8(out, 1);
    let verifier_hashes = [
        (
            SCCP_SOLANA_MAINNET_TOWER_REPLAY_VERIFIER_ID_V1,
            deployment.solana_tower_replay_verifier_hash,
        ),
        (
            SCCP_SOLANA_MAINNET_FULL_ACCOUNTSDB_LATTICE_VERIFIER_ID_V1,
            deployment.solana_full_accountsdb_lattice_verifier_hash,
        ),
        (
            SCCP_SOLANA_MAINNET_BANK_FORK_CHOICE_VERIFIER_ID_V1,
            deployment.solana_bank_fork_choice_verifier_hash,
        ),
    ];
    for (verifier_id, verifier_hash) in verifier_hashes {
        push_vec(out, verifier_id.as_bytes());
        out.extend_from_slice(&verifier_hash);
    }
}

fn push_sccp_source_adapter_deployment_ton_full_light_client_audit_bytes(
    out: &mut Vec<u8>,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) {
    if sccp_source_adapter_deployment_ton_full_light_client_audit_nonzero_count(deployment) == 0 {
        return;
    }

    push_u8(out, 2);
    let verifier_hashes = [
        (
            SCCP_TON_MAINNET_MASTERCHAIN_CONFIG_VERIFIER_ID_V1,
            deployment.ton_masterchain_config_verifier_hash,
        ),
        (
            SCCP_TON_MAINNET_VALIDATOR_SET_TRANSITION_VERIFIER_ID_V1,
            deployment.ton_validator_set_transition_verifier_hash,
        ),
        (
            SCCP_TON_MAINNET_SHARD_ACCOUNTS_DICTIONARY_VERIFIER_ID_V1,
            deployment.ton_shard_accounts_dictionary_verifier_hash,
        ),
    ];
    for (verifier_id, verifier_hash) in verifier_hashes {
        push_vec(out, verifier_id.as_bytes());
        out.extend_from_slice(&verifier_hash);
    }
}

pub fn canonical_sccp_source_adapter_engine_deployment_bytes(
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Vec<u8> {
    let mut out = Vec::new();
    push_u8(&mut out, deployment.version);
    push_u32(&mut out, deployment.source_domain);
    push_u32(&mut out, deployment.target_domain);
    push_vec(&mut out, deployment.source_chain.as_bytes());
    push_u8(
        &mut out,
        sccp_source_proof_plan_code(deployment.source_proof_plan),
    );
    push_u8(
        &mut out,
        sccp_proof_finality_model_code(deployment.finality_model),
    );
    push_vec(&mut out, deployment.adapter_proof_family.as_bytes());
    push_vec(&mut out, deployment.adapter_circuit_id.as_bytes());
    out.extend_from_slice(&deployment.adapter_verifier_vk_hash);
    push_vec(&mut out, deployment.source_trust_anchor_id.as_bytes());
    out.extend_from_slice(&deployment.source_trust_anchor_hash);
    push_vec(&mut out, deployment.consensus_verifier_id.as_bytes());
    out.extend_from_slice(&deployment.consensus_verifier_hash);
    push_vec(
        &mut out,
        deployment.message_inclusion_verifier_id.as_bytes(),
    );
    out.extend_from_slice(&deployment.message_inclusion_verifier_hash);
    push_vec(&mut out, deployment.finality_policy_id.as_bytes());
    out.extend_from_slice(&deployment.finality_policy_hash);
    push_vec(&mut out, deployment.source_state_verifier_id.as_bytes());
    out.extend_from_slice(&deployment.source_state_verifier_hash);
    push_vec(&mut out, deployment.source_bridge_emitter_id.as_bytes());
    push_vec(&mut out, &deployment.source_bridge_emitter_address);
    out.extend_from_slice(&deployment.source_bridge_emitter_code_hash);
    out.extend_from_slice(&deployment.source_bridge_network_id);
    push_vec(&mut out, &deployment.source_bridge_owner_address);
    out.extend_from_slice(&deployment.source_bridge_config_hash);
    out.extend_from_slice(&deployment.deployment_receipt_hash);
    push_sccp_source_adapter_deployment_solana_full_light_client_audit_bytes(&mut out, deployment);
    push_sccp_source_adapter_deployment_ton_full_light_client_audit_bytes(&mut out, deployment);
    out
}

pub fn sccp_source_adapter_engine_deployment_hash(
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> H256 {
    prefixed_blake2b(
        b"sccp:source-adapter-engine-deployment:v1",
        &canonical_sccp_source_adapter_engine_deployment_bytes(deployment),
    )
}

/// Audit hash for the remaining Solana full light-client verifier deployment bundle.
///
/// This provides the canonical governed transcript for the Tower replay, full
/// AccountsDB lattice, and bank/fork-choice verifier hashes consumed by the
/// Solana source-adapter production gate.
pub fn sccp_solana_full_light_client_gate_hash_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
    tower_replay_verifier_hash: H256,
    full_accountsdb_lattice_verifier_hash: H256,
    bank_fork_choice_verifier_hash: H256,
) -> Option<H256> {
    if material.source_domain != SCCP_DOMAIN_SOL
        || deployment.source_domain != SCCP_DOMAIN_SOL
        || deployment.target_domain != SCCP_DOMAIN_SORA
        || !sccp_source_adapter_engine_deployment_matches_material(material, deployment)
        || material.source_state_verifier_id != SCCP_SOLANA_MAINNET_ACCOUNTS_DB_VERIFIER_ID_V1
        || !sccp_source_state_verifier_is_production_ready(material)
        || !h256_is_nonzero(&tower_replay_verifier_hash)
        || !h256_is_nonzero(&full_accountsdb_lattice_verifier_hash)
        || !h256_is_nonzero(&bank_fork_choice_verifier_hash)
    {
        return None;
    }

    let audit_hashes = [
        tower_replay_verifier_hash,
        full_accountsdb_lattice_verifier_hash,
        bank_fork_choice_verifier_hash,
    ];
    if !sccp_solana_full_light_client_audit_hashes_are_role_separated(deployment, &audit_hashes) {
        return None;
    }

    if sccp_source_adapter_deployment_has_solana_full_light_client_audit(deployment)
        && (deployment.solana_tower_replay_verifier_hash != tower_replay_verifier_hash
            || deployment.solana_full_accountsdb_lattice_verifier_hash
                != full_accountsdb_lattice_verifier_hash
            || deployment.solana_bank_fork_choice_verifier_hash != bank_fork_choice_verifier_hash)
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, material.source_domain);
    push_u32(&mut out, deployment.target_domain);
    push_vec(&mut out, material.source_chain.as_bytes());
    push_u8(
        &mut out,
        sccp_source_proof_plan_code(material.source_proof_plan),
    );
    push_u8(
        &mut out,
        sccp_proof_finality_model_code(material.finality_model),
    );
    push_vec(&mut out, SCCP_SOLANA_MAINNET_GENESIS_HASH.as_bytes());
    out.extend_from_slice(&sccp_source_verifier_material_hash(material));
    out.extend_from_slice(&sccp_source_adapter_engine_deployment_hash(deployment));
    let verifier_hashes = [
        (
            SCCP_SOLANA_MAINNET_TOWER_REPLAY_VERIFIER_ID_V1,
            audit_hashes[0],
        ),
        (
            SCCP_SOLANA_MAINNET_FULL_ACCOUNTSDB_LATTICE_VERIFIER_ID_V1,
            audit_hashes[1],
        ),
        (
            SCCP_SOLANA_MAINNET_BANK_FORK_CHOICE_VERIFIER_ID_V1,
            audit_hashes[2],
        ),
    ];
    for (verifier_id, verifier_hash) in verifier_hashes {
        push_vec(&mut out, verifier_id.as_bytes());
        out.extend_from_slice(&verifier_hash);
    }
    Some(prefixed_blake2b(
        SCCP_SOLANA_FULL_LIGHT_CLIENT_GATE_PREFIX_V1,
        &out,
    ))
}

pub fn sccp_solana_full_light_client_gate_hash_from_deployment_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    if !sccp_source_adapter_deployment_has_solana_full_light_client_audit(deployment) {
        return None;
    }

    sccp_solana_full_light_client_gate_hash_v1(
        material,
        deployment,
        deployment.solana_tower_replay_verifier_hash,
        deployment.solana_full_accountsdb_lattice_verifier_hash,
        deployment.solana_bank_fork_choice_verifier_hash,
    )
}

/// Audit hash for the remaining TON full light-client verifier deployment bundle.
///
/// This transcript binds the masterchain config-34 opening, validator-set
/// transition-chain, and shard-accounts dictionary verifier hashes consumed by
/// the TON source-adapter production gate.
pub fn sccp_ton_full_light_client_gate_hash_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
    masterchain_config_verifier_hash: H256,
    validator_set_transition_verifier_hash: H256,
    shard_accounts_dictionary_verifier_hash: H256,
) -> Option<H256> {
    if material.source_domain != SCCP_DOMAIN_TON
        || deployment.source_domain != SCCP_DOMAIN_TON
        || deployment.target_domain != SCCP_DOMAIN_SORA
        || !sccp_source_adapter_engine_deployment_matches_material(material, deployment)
        || material.source_state_verifier_id != SCCP_TON_MAINNET_SHARD_STATE_VERIFIER_ID_V1
        || !sccp_source_state_verifier_is_production_ready(material)
        || !h256_is_nonzero(&masterchain_config_verifier_hash)
        || !h256_is_nonzero(&validator_set_transition_verifier_hash)
        || !h256_is_nonzero(&shard_accounts_dictionary_verifier_hash)
    {
        return None;
    }

    let audit_hashes = [
        masterchain_config_verifier_hash,
        validator_set_transition_verifier_hash,
        shard_accounts_dictionary_verifier_hash,
    ];
    if !sccp_ton_full_light_client_audit_hashes_are_role_separated(deployment, &audit_hashes) {
        return None;
    }

    if sccp_source_adapter_deployment_has_ton_full_light_client_audit(deployment)
        && (deployment.ton_masterchain_config_verifier_hash != masterchain_config_verifier_hash
            || deployment.ton_validator_set_transition_verifier_hash
                != validator_set_transition_verifier_hash
            || deployment.ton_shard_accounts_dictionary_verifier_hash
                != shard_accounts_dictionary_verifier_hash)
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, material.source_domain);
    push_u32(&mut out, deployment.target_domain);
    push_vec(&mut out, material.source_chain.as_bytes());
    push_u8(
        &mut out,
        sccp_source_proof_plan_code(material.source_proof_plan),
    );
    push_u8(
        &mut out,
        sccp_proof_finality_model_code(material.finality_model),
    );
    push_i32(&mut out, SCCP_TON_MAINNET_GLOBAL_ID);
    push_vec(
        &mut out,
        SCCP_TON_SHARD_STATE_OPEN_VERIFY_CIRCUIT_ID_V1.as_bytes(),
    );
    push_vec(
        &mut out,
        SCCP_TON_SHARD_STATE_FASTPQ_PARAMETER_SET_V1.as_bytes(),
    );
    push_vec(&mut out, material.source_state_verifier_id.as_bytes());
    out.extend_from_slice(&material.source_state_verifier_hash);
    out.extend_from_slice(&sccp_source_verifier_material_hash(material));
    out.extend_from_slice(&sccp_source_adapter_engine_deployment_hash(deployment));
    let verifier_hashes = [
        (
            SCCP_TON_MAINNET_MASTERCHAIN_CONFIG_VERIFIER_ID_V1,
            audit_hashes[0],
        ),
        (
            SCCP_TON_MAINNET_VALIDATOR_SET_TRANSITION_VERIFIER_ID_V1,
            audit_hashes[1],
        ),
        (
            SCCP_TON_MAINNET_SHARD_ACCOUNTS_DICTIONARY_VERIFIER_ID_V1,
            audit_hashes[2],
        ),
    ];
    for (verifier_id, verifier_hash) in verifier_hashes {
        push_vec(&mut out, verifier_id.as_bytes());
        out.extend_from_slice(&verifier_hash);
    }
    Some(prefixed_blake2b(
        SCCP_TON_FULL_LIGHT_CLIENT_GATE_PREFIX_V1,
        &out,
    ))
}

pub fn sccp_ton_full_light_client_gate_hash_from_deployment_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    if !sccp_source_adapter_deployment_has_ton_full_light_client_audit(deployment) {
        return None;
    }

    sccp_ton_full_light_client_gate_hash_v1(
        material,
        deployment,
        deployment.ton_masterchain_config_verifier_hash,
        deployment.ton_validator_set_transition_verifier_hash,
        deployment.ton_shard_accounts_dictionary_verifier_hash,
    )
}

/// Audit hash for the TRON DPoS source adapter deployment bundle.
///
/// The transcript binds the governed source bridge, source-call verifier, solid
/// block verifier, active witness-schedule anchor, and witness-transition
/// policy consumed by the TRON source-adapter production gate.
pub fn sccp_tron_dpos_source_gate_hash_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    if material.source_domain != SCCP_DOMAIN_TRON
        || deployment.source_domain != SCCP_DOMAIN_TRON
        || deployment.target_domain != SCCP_DOMAIN_SORA
        || material.source_proof_plan != SccpSourceProofPlanV1::TronDposReceiptProof
        || material.finality_model != SccpProofFinalityModelV1::TronDpos
        || material.source_trust_anchor_id != SCCP_TRON_MAINNET_SOURCE_TRUST_ANCHOR_ID_V1
        || material.consensus_verifier_id != SCCP_TRON_MAINNET_CONSENSUS_VERIFIER_ID_V1
        || material.message_inclusion_verifier_id
            != SCCP_TRON_MAINNET_MESSAGE_INCLUSION_VERIFIER_ID_V1
        || material.finality_policy_id != SCCP_TRON_MAINNET_FINALITY_POLICY_ID_V1
        || material.source_bridge_emitter_id != SCCP_TRON_MAINNET_SOURCE_BRIDGE_EMITTER_ID_V1
        || !sccp_source_adapter_engine_deployment_matches_material(material, deployment)
        || !sccp_source_bridge_config_hash_is_production_ready(material)
    {
        return None;
    }

    let source_bridge_emitter_address = material
        .source_bridge_emitter_address
        .as_slice()
        .try_into()
        .ok()?;
    let source_bridge_owner_address = material
        .source_bridge_owner_address
        .as_slice()
        .try_into()
        .ok()?;
    if !address20_is_nonzero(&source_bridge_emitter_address)
        || !address20_is_nonzero(&source_bridge_owner_address)
        || !h256_is_nonzero(&material.source_bridge_emitter_code_hash)
        || !h256_is_nonzero(&material.source_bridge_network_id)
        || !h256_is_nonzero(&material.source_bridge_config_hash)
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, material.source_domain);
    push_u32(&mut out, deployment.target_domain);
    push_vec(&mut out, material.source_chain.as_bytes());
    push_u8(
        &mut out,
        sccp_source_proof_plan_code(material.source_proof_plan),
    );
    push_u8(
        &mut out,
        sccp_proof_finality_model_code(material.finality_model),
    );
    push_vec(
        &mut out,
        SCCP_SOURCE_ADAPTER_OPEN_VERIFY_CIRCUIT_ID_V1.as_bytes(),
    );
    push_vec(
        &mut out,
        SCCP_TRON_GROTH16_BN254_PROOF_BACKEND_V1.as_bytes(),
    );
    out.extend_from_slice(&sccp_source_verifier_material_hash(material));
    out.extend_from_slice(&sccp_source_adapter_engine_deployment_hash(deployment));
    out.extend_from_slice(&deployment.adapter_verifier_vk_hash);
    push_vec(&mut out, material.source_trust_anchor_id.as_bytes());
    out.extend_from_slice(&material.source_trust_anchor_hash);
    push_vec(&mut out, material.consensus_verifier_id.as_bytes());
    out.extend_from_slice(&material.consensus_verifier_hash);
    push_vec(&mut out, material.message_inclusion_verifier_id.as_bytes());
    out.extend_from_slice(&material.message_inclusion_verifier_hash);
    push_vec(&mut out, material.finality_policy_id.as_bytes());
    out.extend_from_slice(&material.finality_policy_hash);
    push_vec(&mut out, material.source_bridge_emitter_id.as_bytes());
    push_vec(&mut out, &material.source_bridge_emitter_address);
    out.extend_from_slice(&material.source_bridge_emitter_code_hash);
    out.extend_from_slice(&material.source_bridge_network_id);
    push_vec(&mut out, &material.source_bridge_owner_address);
    out.extend_from_slice(&material.source_bridge_config_hash);
    for prefix in [
        SCCP_TRON_RECEIPT_STATE_PROOF_PREFIX_V1,
        SCCP_TRON_TRANSACTION_SOURCE_PROOF_PREFIX_V1,
        SCCP_TRON_EVENT_LOG_SOURCE_POLICY_PREFIX_V1,
        SCCP_TRON_SOLID_BLOCK_HEADER_PREFIX_V1,
        SCCP_TRON_WITNESS_SCHEDULE_PREFIX_V1,
        SCCP_TRON_WITNESS_SCHEDULE_PAYLOAD_PREFIX_V1,
        SCCP_TRON_SOLID_BLOCK_MESSAGE_PREFIX_V1,
        SCCP_TRON_WITNESS_SEAL_PREFIX_V1,
        SCCP_TRON_WITNESS_SCHEDULE_TRANSITION_MESSAGE_PREFIX_V1,
        SCCP_TRON_WITNESS_SCHEDULE_TRANSITION_SEAL_PREFIX_V1,
        SCCP_TRON_TRIGGER_SMART_CONTRACT_TYPE_URL_V1,
        SCCP_TRON_SOURCE_MESSAGE_CALL_ABI_V1,
        SCCP_TRON_SOURCE_BRIDGE_CONFIG_PREFIX_V1,
    ] {
        push_vec(&mut out, prefix);
    }
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_SOURCE_CALL_SIGNATURES)
            .expect("TRON source-call signature count fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_TRANSACTION_BYTES)
            .expect("TRON transaction byte bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_TRANSACTION_MERKLE_BRANCH_NODES)
            .expect("TRON transaction Merkle branch bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_WITNESSES).expect("TRON witness bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_SOLID_BLOCK_ANCESTOR_HEADERS)
            .expect("TRON solid-block ancestor bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_SOLID_BLOCK_CONFIRMATION_HEADERS)
            .expect("TRON solid-block confirmation bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_WITNESS_SCHEDULE_TRANSITIONS)
            .expect("TRON witness schedule transition bound fits u32"),
    );
    push_u32(
        &mut out,
        u32::try_from(SCCP_TRON_MAX_WITNESS_SCHEDULE_PAYLOAD_BYTES)
            .expect("TRON witness schedule payload bound fits u32"),
    );
    Some(prefixed_blake2b(SCCP_TRON_DPOS_SOURCE_GATE_PREFIX_V1, &out))
}

pub fn sccp_tron_dpos_source_gate_hash_from_deployment_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    sccp_tron_dpos_source_gate_hash_v1(material, deployment)
}

pub fn sccp_substrate_runtime_storage_gate_hash_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    if !matches!(
        material.source_domain,
        SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2
    ) || deployment.source_domain != material.source_domain
        || deployment.target_domain != SCCP_DOMAIN_SORA
        || !sccp_source_adapter_engine_deployment_matches_material(material, deployment)
        || !sccp_source_state_verifier_id_for_domain(material.source_domain)
            .is_some_and(|expected_id| material.source_state_verifier_id == expected_id)
        || !sccp_source_state_verifier_is_production_ready(material)
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, material.source_domain);
    push_u32(&mut out, deployment.target_domain);
    push_vec(&mut out, material.source_chain.as_bytes());
    push_u8(
        &mut out,
        sccp_source_proof_plan_code(material.source_proof_plan),
    );
    push_u8(
        &mut out,
        sccp_proof_finality_model_code(material.finality_model),
    );
    push_vec(
        &mut out,
        SCCP_SUBSTRATE_RUNTIME_STORAGE_OPEN_VERIFY_CIRCUIT_ID_V1.as_bytes(),
    );
    push_vec(
        &mut out,
        SCCP_SUBSTRATE_RUNTIME_STORAGE_FASTPQ_PARAMETER_SET_V1.as_bytes(),
    );
    push_vec(&mut out, material.source_state_verifier_id.as_bytes());
    out.extend_from_slice(&material.source_state_verifier_hash);
    out.extend_from_slice(&sccp_source_verifier_material_hash(material));
    out.extend_from_slice(&sccp_source_adapter_engine_deployment_hash(deployment));
    Some(prefixed_blake2b(
        SCCP_SUBSTRATE_RUNTIME_STORAGE_GATE_PREFIX_V1,
        &out,
    ))
}

pub fn sccp_substrate_runtime_storage_gate_hash_from_deployment_v1(
    material: &SccpSourceVerifierMaterialV1,
    deployment: &SccpSourceAdapterEngineDeploymentV1,
) -> Option<H256> {
    sccp_substrate_runtime_storage_gate_hash_v1(material, deployment)
}

