pub fn canonical_sccp_payload_bytes(payload: &SccpPayloadV1) -> Vec<u8> {
    let mut out = Vec::new();
    match payload {
        SccpPayloadV1::AssetRegister(payload) => {
            push_u8(&mut out, SccpPayloadV1::ASSET_REGISTER_DISCRIMINANT);
            out.extend_from_slice(&canonical_asset_register_payload_bytes(payload));
        }
        SccpPayloadV1::RouteActivate(payload) => {
            push_u8(&mut out, SccpPayloadV1::ROUTE_ACTIVATE_DISCRIMINANT);
            out.extend_from_slice(&canonical_route_activate_payload_bytes(payload));
        }
        SccpPayloadV1::Transfer(payload) => {
            push_u8(&mut out, SccpPayloadV1::TRANSFER_DISCRIMINANT);
            out.extend_from_slice(&canonical_transfer_payload_bytes(payload));
        }
        SccpPayloadV1::TokenAdd(payload) => {
            push_u8(&mut out, SccpPayloadV1::TOKEN_ADD_DISCRIMINANT);
            out.extend_from_slice(&canonical_token_add_payload_bytes(payload));
        }
        SccpPayloadV1::TokenPause(payload) => {
            push_u8(&mut out, SccpPayloadV1::TOKEN_PAUSE_DISCRIMINANT);
            out.extend_from_slice(&canonical_token_control_payload_bytes(payload));
        }
        SccpPayloadV1::TokenResume(payload) => {
            push_u8(&mut out, SccpPayloadV1::TOKEN_RESUME_DISCRIMINANT);
            out.extend_from_slice(&canonical_token_control_payload_bytes(payload));
        }
    }
    out
}

struct PayloadCursor<'a> {
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> PayloadCursor<'a> {
    fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, offset: 0 }
    }

    fn take_exact(&mut self, len: usize) -> Option<&'a [u8]> {
        let end = self.offset.checked_add(len)?;
        let slice = self.bytes.get(self.offset..end)?;
        self.offset = end;
        Some(slice)
    }

    fn take_u8(&mut self) -> Option<u8> {
        self.take_exact(1).map(|bytes| bytes[0])
    }

    fn take_u32(&mut self) -> Option<u32> {
        let mut out = [0u8; 4];
        out.copy_from_slice(self.take_exact(4)?);
        Some(u32::from_le_bytes(out))
    }

    fn take_u64(&mut self) -> Option<u64> {
        let mut out = [0u8; 8];
        out.copy_from_slice(self.take_exact(8)?);
        Some(u64::from_le_bytes(out))
    }

    fn take_u128(&mut self) -> Option<u128> {
        let mut out = [0u8; 16];
        out.copy_from_slice(self.take_exact(16)?);
        Some(u128::from_le_bytes(out))
    }

    fn take_vec(&mut self) -> Option<Vec<u8>> {
        let len = usize::try_from(self.take_u32()?).ok()?;
        Some(self.take_exact(len)?.to_vec())
    }

    fn is_finished(&self) -> bool {
        self.offset == self.bytes.len()
    }
}

pub fn decode_canonical_sccp_payload_bytes(payload_bytes: &[u8]) -> Option<SccpPayloadV1> {
    let mut cursor = PayloadCursor::new(payload_bytes);
    let discriminant = cursor.take_u8()?;
    let payload = match discriminant {
        SccpPayloadV1::ASSET_REGISTER_DISCRIMINANT => {
            SccpPayloadV1::AssetRegister(AssetRegisterPayloadV1 {
                version: cursor.take_u8()?,
                target_domain: cursor.take_u32()?,
                home_domain: cursor.take_u32()?,
                nonce: cursor.take_u64()?,
                asset_id_codec: cursor.take_u8()?,
                asset_id: cursor.take_vec()?,
                decimals: cursor.take_u8()?,
            })
        }
        SccpPayloadV1::ROUTE_ACTIVATE_DISCRIMINANT => {
            SccpPayloadV1::RouteActivate(RouteActivatePayloadV1 {
                version: cursor.take_u8()?,
                source_domain: cursor.take_u32()?,
                target_domain: cursor.take_u32()?,
                nonce: cursor.take_u64()?,
                asset_id_codec: cursor.take_u8()?,
                asset_id: cursor.take_vec()?,
                route_id_codec: cursor.take_u8()?,
                route_id: cursor.take_vec()?,
            })
        }
        SccpPayloadV1::TRANSFER_DISCRIMINANT => SccpPayloadV1::Transfer(TransferPayloadV1 {
            version: cursor.take_u8()?,
            source_domain: cursor.take_u32()?,
            dest_domain: cursor.take_u32()?,
            nonce: cursor.take_u64()?,
            asset_home_domain: cursor.take_u32()?,
            asset_id_codec: cursor.take_u8()?,
            asset_id: cursor.take_vec()?,
            amount: cursor.take_u128()?,
            sender_codec: cursor.take_u8()?,
            sender: cursor.take_vec()?,
            recipient_codec: cursor.take_u8()?,
            recipient: cursor.take_vec()?,
            route_id_codec: cursor.take_u8()?,
            route_id: cursor.take_vec()?,
        }),
        SccpPayloadV1::TOKEN_ADD_DISCRIMINANT => SccpPayloadV1::TokenAdd(TokenAddPayloadV1 {
            version: cursor.take_u8()?,
            target_domain: cursor.take_u32()?,
            nonce: cursor.take_u64()?,
            sora_asset_id: {
                let mut out = [0u8; 32];
                out.copy_from_slice(cursor.take_exact(32)?);
                out
            },
            decimals: cursor.take_u8()?,
            name: {
                let mut out = [0u8; 32];
                out.copy_from_slice(cursor.take_exact(32)?);
                out
            },
            symbol: {
                let mut out = [0u8; 32];
                out.copy_from_slice(cursor.take_exact(32)?);
                out
            },
        }),
        SccpPayloadV1::TOKEN_PAUSE_DISCRIMINANT => {
            SccpPayloadV1::TokenPause(TokenControlPayloadV1 {
                version: cursor.take_u8()?,
                target_domain: cursor.take_u32()?,
                nonce: cursor.take_u64()?,
                sora_asset_id: {
                    let mut out = [0u8; 32];
                    out.copy_from_slice(cursor.take_exact(32)?);
                    out
                },
            })
        }
        SccpPayloadV1::TOKEN_RESUME_DISCRIMINANT => {
            SccpPayloadV1::TokenResume(TokenControlPayloadV1 {
                version: cursor.take_u8()?,
                target_domain: cursor.take_u32()?,
                nonce: cursor.take_u64()?,
                sora_asset_id: {
                    let mut out = [0u8; 32];
                    out.copy_from_slice(cursor.take_exact(32)?);
                    out
                },
            })
        }
        _ => return None,
    };
    cursor.is_finished().then_some(payload)
}

fn h256_is_nonzero(value: &H256) -> bool {
    value.iter().any(|byte| *byte != 0)
}

fn secp256k1_recoverable_signature_s_is_low(signature: &[u8; 65]) -> bool {
    let mut s = [0u8; 32];
    s.copy_from_slice(&signature[32..64]);
    h256_is_nonzero(&s) && s <= SECP256K1_SCALAR_HALF_ORDER_BE
}

fn secp256k1_recoverable_signature_r_is_valid(signature: &[u8; 65]) -> bool {
    let mut r = [0u8; 32];
    r.copy_from_slice(&signature[..32]);
    h256_is_nonzero(&r) && r < SECP256K1_SCALAR_ORDER_BE
}

fn secp256k1_recoverable_signature_has_low_s(signature: &[u8; 65]) -> bool {
    matches!(signature[64], 27 | 28) && secp256k1_recoverable_signature_s_is_low(signature)
}

fn tron_recoverable_signature_is_canonical(signature: &[u8; 65]) -> bool {
    matches!(signature[64], 0..=3 | 27..=30)
        && secp256k1_recoverable_signature_r_is_valid(signature)
        && secp256k1_recoverable_signature_s_is_low(signature)
}

fn tron_recoverable_signature_slice_is_canonical(signature: &[u8]) -> bool {
    let Ok(signature) = <[u8; 65]>::try_from(signature) else {
        return false;
    };
    tron_recoverable_signature_is_canonical(&signature)
}

fn tron_recoverable_signature_for_recovery(signature: &[u8; 65]) -> Option<[u8; 65]> {
    if !tron_recoverable_signature_is_canonical(signature) {
        return None;
    }
    let mut normalized = *signature;
    normalized[64] = match signature[64] {
        0..=3 => signature[64].checked_add(27)?,
        27..=30 => signature[64],
        _ => return None,
    };
    Some(normalized)
}

fn address20_is_nonzero(value: &[u8; 20]) -> bool {
    value.iter().any(|byte| *byte != 0)
}

fn fixed_ascii_field_is_non_empty(value: &[u8; 32]) -> bool {
    value
        .iter()
        .position(|byte| *byte == 0)
        .map_or(value.as_slice(), |end| &value[..end])
        .iter()
        .any(|byte| *byte != 0)
}

pub fn verify_sccp_payload_structure(payload: &SccpPayloadV1) -> bool {
    let target_domain = sccp_message_target_domain(payload);
    if !is_supported_domain(target_domain) {
        return false;
    }

    match payload {
        SccpPayloadV1::AssetRegister(payload) => {
            payload.version == 1
                && is_supported_domain(payload.home_domain)
                && validate_sccp_codec_bytes(payload.asset_id_codec, &payload.asset_id)
        }
        SccpPayloadV1::RouteActivate(payload) => {
            payload.version == 1
                && is_supported_domain(payload.source_domain)
                && payload.source_domain != payload.target_domain
                && validate_sccp_codec_bytes(payload.asset_id_codec, &payload.asset_id)
                && validate_sccp_codec_bytes(payload.route_id_codec, &payload.route_id)
        }
        SccpPayloadV1::Transfer(payload) => {
            let Some(expected_sender_codec) =
                sccp_counterparty_account_codec(payload.source_domain)
            else {
                return false;
            };
            let Some(expected_recipient_codec) =
                sccp_counterparty_account_codec(payload.dest_domain)
            else {
                return false;
            };
            payload.version == 1
                && is_supported_domain(payload.source_domain)
                && is_supported_domain(payload.asset_home_domain)
                && payload.source_domain != payload.dest_domain
                && validate_sccp_codec_bytes(payload.asset_id_codec, &payload.asset_id)
                && payload.amount != 0
                && payload.sender_codec == expected_sender_codec
                && validate_sccp_codec_bytes(payload.sender_codec, &payload.sender)
                && payload.recipient_codec == expected_recipient_codec
                && validate_sccp_codec_bytes(payload.recipient_codec, &payload.recipient)
                && validate_sccp_codec_bytes(payload.route_id_codec, &payload.route_id)
        }
        SccpPayloadV1::TokenAdd(payload) => {
            payload.version == 1
                && is_supported_domain(payload.target_domain)
                && h256_is_nonzero(&payload.sora_asset_id)
                && fixed_ascii_field_is_non_empty(&payload.name)
                && fixed_ascii_field_is_non_empty(&payload.symbol)
        }
        SccpPayloadV1::TokenPause(payload) | SccpPayloadV1::TokenResume(payload) => {
            payload.version == 1
                && is_supported_domain(payload.target_domain)
                && h256_is_nonzero(&payload.sora_asset_id)
        }
    }
}

pub fn hub_commitment_from_sccp_payload(payload: &SccpPayloadV1) -> SccpHubCommitmentV1 {
    SccpHubCommitmentV1 {
        version: 1,
        kind: sccp_message_kind(payload),
        target_domain: sccp_message_target_domain(payload),
        message_id: sccp_message_id(payload),
        payload_hash: payload_hash(&canonical_sccp_payload_bytes(payload)),
    }
}

pub fn canonical_commitment_bytes(commitment: &SccpHubCommitmentV1) -> Vec<u8> {
    let mut out = Vec::with_capacity(1 + 1 + 4 + 32 + 32);
    push_u8(&mut out, commitment.version);
    push_u8(
        &mut out,
        match commitment.kind {
            SccpHubMessageKind::Burn => 0,
            SccpHubMessageKind::TokenAdd => 1,
            SccpHubMessageKind::TokenPause => 2,
            SccpHubMessageKind::TokenResume => 3,
            SccpHubMessageKind::AssetRegister => 4,
            SccpHubMessageKind::RouteActivate => 5,
            SccpHubMessageKind::Transfer => 6,
        },
    );
    push_u32(&mut out, commitment.target_domain);
    out.extend_from_slice(&commitment.message_id);
    out.extend_from_slice(&commitment.payload_hash);
    out
}

pub fn burn_message_id(payload: &BurnPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_BURN_V1,
        &canonical_burn_payload_bytes(payload),
    )
}

pub fn token_add_message_id(payload: &TokenAddPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_TOKEN_ADD_V1,
        &canonical_token_add_payload_bytes(payload),
    )
}

pub fn token_pause_message_id(payload: &TokenControlPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_TOKEN_PAUSE_V1,
        &canonical_token_control_payload_bytes(payload),
    )
}

pub fn token_resume_message_id(payload: &TokenControlPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_TOKEN_RESUME_V1,
        &canonical_token_control_payload_bytes(payload),
    )
}

pub fn asset_register_message_id(payload: &AssetRegisterPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_ASSET_REGISTER_V1,
        &canonical_asset_register_payload_bytes(payload),
    )
}

pub fn route_activate_message_id(payload: &RouteActivatePayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_ROUTE_ACTIVATE_V1,
        &canonical_route_activate_payload_bytes(payload),
    )
}

pub fn transfer_message_id(payload: &TransferPayloadV1) -> H256 {
    prefixed_keccak(
        SCCP_MSG_PREFIX_TRANSFER_V1,
        &canonical_transfer_payload_bytes(payload),
    )
}

pub fn sccp_message_id(payload: &SccpPayloadV1) -> H256 {
    match payload {
        SccpPayloadV1::AssetRegister(payload) => asset_register_message_id(payload),
        SccpPayloadV1::RouteActivate(payload) => route_activate_message_id(payload),
        SccpPayloadV1::Transfer(payload) => transfer_message_id(payload),
        SccpPayloadV1::TokenAdd(payload) => token_add_message_id(payload),
        SccpPayloadV1::TokenPause(payload) => token_pause_message_id(payload),
        SccpPayloadV1::TokenResume(payload) => token_resume_message_id(payload),
    }
}

pub fn sccp_message_kind(payload: &SccpPayloadV1) -> SccpHubMessageKind {
    match payload {
        SccpPayloadV1::AssetRegister(_) => SccpHubMessageKind::AssetRegister,
        SccpPayloadV1::RouteActivate(_) => SccpHubMessageKind::RouteActivate,
        SccpPayloadV1::Transfer(_) => SccpHubMessageKind::Transfer,
        SccpPayloadV1::TokenAdd(_) => SccpHubMessageKind::TokenAdd,
        SccpPayloadV1::TokenPause(_) => SccpHubMessageKind::TokenPause,
        SccpPayloadV1::TokenResume(_) => SccpHubMessageKind::TokenResume,
    }
}

pub fn sccp_message_target_domain(payload: &SccpPayloadV1) -> u32 {
    match payload {
        SccpPayloadV1::AssetRegister(payload) => payload.target_domain,
        SccpPayloadV1::RouteActivate(payload) => payload.target_domain,
        SccpPayloadV1::Transfer(payload) => payload.dest_domain,
        SccpPayloadV1::TokenAdd(payload) => payload.target_domain,
        SccpPayloadV1::TokenPause(payload) | SccpPayloadV1::TokenResume(payload) => {
            payload.target_domain
        }
    }
}

pub fn sccp_message_source_domain(payload: &SccpPayloadV1) -> u32 {
    match payload {
        SccpPayloadV1::AssetRegister(payload) => payload.home_domain,
        SccpPayloadV1::RouteActivate(payload) => payload.source_domain,
        SccpPayloadV1::Transfer(payload) => payload.source_domain,
        SccpPayloadV1::TokenAdd(_)
        | SccpPayloadV1::TokenPause(_)
        | SccpPayloadV1::TokenResume(_) => SCCP_DOMAIN_SORA,
    }
}

pub fn payload_hash(payload: &[u8]) -> H256 {
    prefixed_blake2b(SCCP_PAYLOAD_HASH_PREFIX_V1, payload)
}

pub fn sccp_source_event_digest(
    source_domain: u32,
    target_domain: u32,
    message_id: H256,
    payload_hash: H256,
) -> H256 {
    let mut out = Vec::with_capacity(1 + 4 + 4 + 32 + 32);
    push_u8(&mut out, 1);
    push_u32(&mut out, source_domain);
    push_u32(&mut out, target_domain);
    out.extend_from_slice(&message_id);
    out.extend_from_slice(&payload_hash);
    prefixed_blake2b(SCCP_SOURCE_EVENT_DIGEST_PREFIX_V1, &out)
}

pub fn sccp_source_event_leaf_hash(source_event_digest: H256) -> H256 {
    prefixed_blake2b(SCCP_SOURCE_EVENT_LEAF_PREFIX_V1, &source_event_digest)
}

fn h256_merkle_branch_siblings_are_bounded(inclusion_branch: &[Vec<u8>]) -> bool {
    inclusion_branch.len() <= SCCP_MAX_SOURCE_MERKLE_BRANCH_NODES
        && inclusion_branch.iter().all(|sibling| sibling.len() == 32)
}

fn h256_merkle_branch_is_nonempty_and_bounded(inclusion_branch: &[Vec<u8>]) -> bool {
    !inclusion_branch.is_empty() && h256_merkle_branch_siblings_are_bounded(inclusion_branch)
}

fn push_h256_inclusion_branch(out: &mut Vec<u8>, inclusion_branch: &[Vec<u8>]) -> Option<()> {
    if !h256_merkle_branch_siblings_are_bounded(inclusion_branch) {
        return None;
    }
    push_u32(out, u32::try_from(inclusion_branch.len()).ok()?);
    for sibling in inclusion_branch {
        let sibling: H256 = sibling.as_slice().try_into().ok()?;
        out.extend_from_slice(&sibling);
    }
    Some(())
}

fn ssz_hash_node(left: &H256, right: &H256) -> H256 {
    let mut hasher = Sha256::new();
    Digest::update(&mut hasher, left);
    Digest::update(&mut hasher, right);
    hasher.finalize().into()
}

fn ssz_merkleize_chunks(mut chunks: Vec<H256>) -> Option<H256> {
    if chunks.is_empty() {
        return Some([0u8; 32]);
    }
    let padded_len = chunks.len().checked_next_power_of_two()?;
    chunks.resize(padded_len, [0u8; 32]);
    while chunks.len() > 1 {
        let mut next = Vec::with_capacity(chunks.len() / 2);
        for pair in chunks.chunks_exact(2) {
            next.push(ssz_hash_node(&pair[0], &pair[1]));
        }
        chunks = next;
    }
    chunks.pop()
}

fn ssz_merkle_root_from_branch(leaf: H256, leaf_index: u64, branch: &[Vec<u8>]) -> Option<H256> {
    if !h256_merkle_branch_siblings_are_bounded(branch) {
        return None;
    }
    let mut current = leaf;
    let mut index = leaf_index;
    for sibling in branch {
        let sibling: H256 = sibling.as_slice().try_into().ok()?;
        current = if index & 1 == 0 {
            ssz_hash_node(&current, &sibling)
        } else {
            ssz_hash_node(&sibling, &current)
        };
        index >>= 1;
    }
    Some(current)
}

fn ssz_uint64_chunk(value: u64) -> H256 {
    let mut out = [0u8; 32];
    out[..8].copy_from_slice(&value.to_le_bytes());
    out
}

fn ssz_uint64_chunk_from_rlp(bytes: &[u8]) -> Option<H256> {
    Some(ssz_uint64_chunk(read_be_u64_minimal(bytes)?))
}

fn ssz_uint256_chunk_from_rlp(bytes: &[u8]) -> Option<H256> {
    if bytes.len() > 32 || (bytes.len() > 1 && bytes.first() == Some(&0)) {
        return None;
    }
    let mut out = [0u8; 32];
    for (idx, byte) in bytes.iter().rev().enumerate() {
        out[idx] = *byte;
    }
    Some(out)
}

fn ssz_bytevector_root(bytes: &[u8], expected_len: usize) -> Option<H256> {
    if bytes.len() != expected_len {
        return None;
    }
    let mut chunks = Vec::with_capacity(expected_len.div_ceil(32).max(1));
    for chunk in bytes.chunks(32) {
        let mut ssz_chunk = [0u8; 32];
        ssz_chunk[..chunk.len()].copy_from_slice(chunk);
        chunks.push(ssz_chunk);
    }
    ssz_merkleize_chunks(chunks)
}

fn ssz_mix_in_length(root: H256, len: usize) -> Option<H256> {
    let mut length_chunk = [0u8; 32];
    length_chunk[..8].copy_from_slice(&u64::try_from(len).ok()?.to_le_bytes());
    Some(ssz_hash_node(&root, &length_chunk))
}

fn ssz_bytelist_root(bytes: &[u8], max_len: usize) -> Option<H256> {
    if bytes.len() > max_len {
        return None;
    }
    let limit_chunks = max_len.div_ceil(32).max(1);
    let mut chunks = Vec::with_capacity(limit_chunks);
    for chunk in bytes.chunks(32) {
        let mut ssz_chunk = [0u8; 32];
        ssz_chunk[..chunk.len()].copy_from_slice(chunk);
        chunks.push(ssz_chunk);
    }
    chunks.resize(limit_chunks, [0u8; 32]);
    let root = ssz_merkleize_chunks(chunks)?;
    ssz_mix_in_length(root, bytes.len())
}

pub fn sccp_eth_execution_payload_header_root_from_rlp(header_rlp: &[u8]) -> Option<H256> {
    let fields = eth_rlp_header_fields(header_rlp)?;
    if fields.len() < 19 {
        return None;
    }

    let parent_hash: H256 = fields[0].try_into().ok()?;
    let fee_recipient = ssz_bytevector_root(fields[2], 20)?;
    let state_root: H256 = fields[3].try_into().ok()?;
    let transactions_root: H256 = fields[4].try_into().ok()?;
    let receipts_root: H256 = fields[5].try_into().ok()?;
    let logs_bloom = ssz_bytevector_root(fields[6], 256)?;
    let block_number = ssz_uint64_chunk_from_rlp(fields[8])?;
    let gas_limit = ssz_uint64_chunk_from_rlp(fields[9])?;
    let gas_used = ssz_uint64_chunk_from_rlp(fields[10])?;
    let timestamp = ssz_uint64_chunk_from_rlp(fields[11])?;
    let extra_data = ssz_bytelist_root(fields[12], 32)?;
    let prev_randao: H256 = fields[13].try_into().ok()?;
    let base_fee_per_gas = ssz_uint256_chunk_from_rlp(fields[15])?;
    let withdrawals_root: H256 = fields[16].try_into().ok()?;
    let blob_gas_used = ssz_uint64_chunk_from_rlp(fields[17])?;
    let excess_blob_gas = ssz_uint64_chunk_from_rlp(fields[18])?;
    let block_hash = keccak256_bytes(header_rlp);

    ssz_merkleize_chunks(vec![
        parent_hash,
        fee_recipient,
        state_root,
        receipts_root,
        logs_bloom,
        prev_randao,
        block_number,
        gas_limit,
        gas_used,
        timestamp,
        extra_data,
        base_fee_per_gas,
        block_hash,
        transactions_root,
        withdrawals_root,
        blob_gas_used,
        excess_blob_gas,
    ])
}

pub fn sccp_eth_beacon_body_root_from_execution_payload_branch(
    execution_payload_header_root: H256,
    execution_payload_branch: &[Vec<u8>],
) -> Option<H256> {
    if execution_payload_branch.len() != SCCP_ETH_EXECUTION_PAYLOAD_BODY_BRANCH_DEPTH {
        return None;
    }
    ssz_merkle_root_from_branch(
        execution_payload_header_root,
        SCCP_ETH_EXECUTION_PAYLOAD_BODY_FIELD_INDEX,
        execution_payload_branch,
    )
}

pub fn sccp_eth_beacon_block_header_root(
    slot: u64,
    proposer_index: u64,
    parent_root: H256,
    state_root: H256,
    body_root: H256,
) -> H256 {
    ssz_merkleize_chunks(vec![
        ssz_uint64_chunk(slot),
        ssz_uint64_chunk(proposer_index),
        parent_root,
        state_root,
        body_root,
    ])
    .expect("beacon block header has non-empty SSZ fields")
}

pub fn canonical_sccp_eth_sync_committee_bytes(
    sync_committee_public_keys: &[Vec<u8>],
    sync_committee_weights: &[u64],
    sync_committee_pops: &[Vec<u8>],
) -> Option<Vec<u8>> {
    if sync_committee_public_keys.is_empty()
        || sync_committee_public_keys.len() > SCCP_ETH_MAX_SYNC_COMMITTEE_AUTHORITIES
        || sync_committee_public_keys.len() != sync_committee_weights.len()
        || sync_committee_public_keys.len() != sync_committee_pops.len()
    {
        return None;
    }

    let mut out = Vec::new();
    let mut seen_keys = Vec::with_capacity(sync_committee_public_keys.len());
    push_u8(&mut out, 1);
    push_u32(
        &mut out,
        u32::try_from(sync_committee_public_keys.len()).expect("ETH sync committee count fits u32"),
    );
    for ((public_key, weight), pop) in sync_committee_public_keys
        .iter()
        .zip(sync_committee_weights.iter())
        .zip(sync_committee_pops.iter())
    {
        if public_key.len() != SCCP_ETH_SYNC_COMMITTEE_PUBLIC_KEY_BYTES
            || public_key.iter().all(|byte| *byte == 0)
            || *weight == 0
            || pop.len() != SCCP_ETH_SYNC_COMMITTEE_POP_BYTES
            || pop.iter().all(|byte| *byte == 0)
            || seen_keys.iter().any(|known| known == public_key)
        {
            return None;
        }
        seen_keys.push(public_key.clone());
        push_vec(&mut out, public_key);
        push_u64(&mut out, *weight);
        push_vec(&mut out, pop);
    }
    Some(out)
}

pub fn canonical_sccp_eth_sync_committee_payload_bytes(
    sync_committee_public_keys: &[Vec<u8>],
    sync_committee_weights: &[u64],
    sync_committee_pops: &[Vec<u8>],
) -> Option<Vec<u8>> {
    canonical_sccp_eth_sync_committee_bytes(
        sync_committee_public_keys,
        sync_committee_weights,
        sync_committee_pops,
    )
}

pub fn decode_sccp_eth_sync_committee_payload(
    payload: &[u8],
) -> Option<(Vec<Vec<u8>>, Vec<u64>, Vec<Vec<u8>>)> {
    if payload.len() > SCCP_ETH_MAX_SYNC_COMMITTEE_PAYLOAD_BYTES {
        return None;
    }
    let mut cursor = 0usize;
    if *payload.get(cursor)? != 1 {
        return None;
    }
    cursor = cursor.checked_add(1)?;
    let committee_count = usize::try_from(read_le_u32_at(payload, &mut cursor)?).ok()?;
    if committee_count == 0 || committee_count > SCCP_ETH_MAX_SYNC_COMMITTEE_AUTHORITIES {
        return None;
    }

    let mut sync_committee_public_keys = Vec::with_capacity(committee_count);
    let mut sync_committee_weights = Vec::with_capacity(committee_count);
    let mut sync_committee_pops = Vec::with_capacity(committee_count);
    for _ in 0..committee_count {
        let public_key_len = usize::try_from(read_le_u32_at(payload, &mut cursor)?).ok()?;
        let public_key_end = cursor.checked_add(public_key_len)?;
        let public_key = payload.get(cursor..public_key_end)?.to_vec();
        cursor = public_key_end;
        if public_key.len() != SCCP_ETH_SYNC_COMMITTEE_PUBLIC_KEY_BYTES
            || public_key.iter().all(|byte| *byte == 0)
            || sync_committee_public_keys
                .iter()
                .any(|known_public_key| known_public_key == &public_key)
        {
            return None;
        }
        let weight = read_le_u64_at(payload, &mut cursor)?;
        if weight == 0 {
            return None;
        }
        let pop_len = usize::try_from(read_le_u32_at(payload, &mut cursor)?).ok()?;
        let pop_end = cursor.checked_add(pop_len)?;
        let pop = payload.get(cursor..pop_end)?.to_vec();
        cursor = pop_end;
        if pop.len() != SCCP_ETH_SYNC_COMMITTEE_POP_BYTES || pop.iter().all(|byte| *byte == 0) {
            return None;
        }
        sync_committee_public_keys.push(public_key);
        sync_committee_weights.push(weight);
        sync_committee_pops.push(pop);
    }

    (cursor == payload.len()).then_some((
        sync_committee_public_keys,
        sync_committee_weights,
        sync_committee_pops,
    ))
}

pub fn sccp_eth_sync_committee_hash_from_payload(payload: &[u8]) -> Option<H256> {
    decode_sccp_eth_sync_committee_payload(payload)?;
    Some(prefixed_blake2b(SCCP_ETH_SYNC_COMMITTEE_PREFIX_V1, payload))
}

pub fn sccp_eth_sync_committee_hash(
    sync_committee_public_keys: &[Vec<u8>],
    sync_committee_weights: &[u64],
    sync_committee_pops: &[Vec<u8>],
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_ETH_SYNC_COMMITTEE_PREFIX_V1,
        &canonical_sccp_eth_sync_committee_bytes(
            sync_committee_public_keys,
            sync_committee_weights,
            sync_committee_pops,
        )?,
    ))
}

pub fn sccp_eth_sync_committee_payload_hash(payload: &[u8]) -> H256 {
    prefixed_blake2b(SCCP_ETH_SYNC_COMMITTEE_PAYLOAD_PREFIX_V1, payload)
}

