    push_u64(&mut out, from_sync_period);
    push_u64(&mut out, to_sync_period);
    push_u64(&mut out, transition_slot);
    out.extend_from_slice(&finalized_beacon_root);
    out.extend_from_slice(&parent_sync_committee_hash);
    out.extend_from_slice(&next_sync_committee_hash);
    out.extend_from_slice(&next_sync_committee_payload_hash);
    out.extend_from_slice(&next_sync_committee_branch_hash);
