pub fn canonical_sccp_eth_sync_committee_transition_signature_bytes(
    proof: &SccpEthSyncCommitteeTransitionProofV1,
) -> Option<Vec<u8>> {
    if proof.version != 1 {
        return None;
    }
    canonical_sccp_eth_sync_committee_aggregate_bytes(&proof.sync_committee_proof)?;
    let parent_sync_committee_hash = sccp_eth_sync_committee_hash(
        &proof.sync_committee_proof.sync_committee_public_keys,
        &proof.sync_committee_proof.sync_committee_weights,
        &proof.sync_committee_proof.sync_committee_pops,
    )?;
    let mut out = Vec::new();
    push_u8(&mut out, proof.version);
    push_u32(&mut out, proof.source_domain);
    push_u64(&mut out, proof.from_sync_period);
    push_u64(&mut out, proof.to_sync_period);
    push_u64(&mut out, proof.transition_slot);
    out.extend_from_slice(&proof.finalized_beacon_root);
    out.extend_from_slice(&proof.parent_sync_committee_hash);
    out.extend_from_slice(&proof.next_sync_committee_hash);
    push_vec(&mut out, &proof.next_sync_committee_payload);
    out.extend_from_slice(&proof.next_sync_committee_payload_hash);
    out.extend_from_slice(&proof.next_sync_committee_branch_hash);
    out.extend_from_slice(&proof.transition_message_hash);
    out.extend_from_slice(&parent_sync_committee_hash);
    push_eth_beacon_sync_committee_proof(&mut out, &proof.sync_committee_proof);
    Some(out)
}

pub fn sccp_eth_sync_committee_transition_signature_hash(
    proof: &SccpEthSyncCommitteeTransitionProofV1,
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_ETH_SYNC_COMMITTEE_TRANSITION_SIGNATURE_PREFIX_V1,
        &canonical_sccp_eth_sync_committee_transition_signature_bytes(proof)?,
    ))
}

fn read_be_u64_minimal(bytes: &[u8]) -> Option<u64> {
    if bytes.is_empty() {
        return Some(0);
    }
    if bytes.len() > 8 || (bytes.len() > 1 && bytes.first() == Some(&0)) {
        return None;
    }
    let mut out = 0u64;
    for byte in bytes {
        out = (out << 8) | u64::from(*byte);
    }
    Some(out)
}

fn read_rlp_len(payload: &[u8], len_offset: usize, len_len: usize) -> Option<usize> {
    if len_len == 0 || len_len > 8 || payload.len() < len_offset.checked_add(len_len)? {
        return None;
    }
    let len_bytes = &payload[len_offset..len_offset + len_len];
    if len_bytes.first() == Some(&0) {
        return None;
    }
    let len = read_be_usize(&{
        let mut padded = [0u8; 8];
        padded[8 - len_len..].copy_from_slice(len_bytes);
        padded
    })?;
    Some(len)
}

fn eth_rlp_list_payload(payload: &[u8]) -> Option<&[u8]> {
    let first = *payload.first()?;
    match first {
        0xc0..=0xf7 => {
            let len = usize::from(first - 0xc0);
            let end = 1usize.checked_add(len)?;
            (payload.len() == end).then_some(&payload[1..end])
        }
        0xf8..=0xff => {
            let len_len = usize::from(first - 0xf7);
            let len = read_rlp_len(payload, 1, len_len)?;
            if len < 56 {
                return None;
            }
            let start = 1usize.checked_add(len_len)?;
            let end = start.checked_add(len)?;
            (payload.len() == end).then_some(&payload[start..end])
        }
        _ => None,
    }
}

fn eth_rlp_string_at<'a>(payload: &'a [u8], cursor: &mut usize) -> Option<&'a [u8]> {
    let first = *payload.get(*cursor)?;
    match first {
        0x00..=0x7f => {
            let start = *cursor;
            *cursor = cursor.checked_add(1)?;
            Some(&payload[start..start + 1])
        }
        0x80..=0xb7 => {
            let len = usize::from(first - 0x80);
            let start = (*cursor).checked_add(1)?;
            let end = start.checked_add(len)?;
            if end > payload.len() || (len == 1 && payload[start] < 0x80) {
                return None;
            }
            *cursor = end;
            Some(&payload[start..end])
        }
        0xb8..=0xbf => {
            let len_len = usize::from(first - 0xb7);
            let len = read_rlp_len(payload, (*cursor).checked_add(1)?, len_len)?;
            if len < 56 {
                return None;
            }
            let start = (*cursor).checked_add(1)?.checked_add(len_len)?;
            let end = start.checked_add(len)?;
            if end > payload.len() {
                return None;
            }
            *cursor = end;
            Some(&payload[start..end])
        }
        _ => None,
    }
}

#[derive(Clone, Copy)]
enum SccpRlpItem<'a> {
    Bytes { payload: &'a [u8] },
    List { payload: &'a [u8], raw: &'a [u8] },
}

fn rlp_item_at<'a>(payload: &'a [u8], cursor: &mut usize) -> Option<SccpRlpItem<'a>> {
    let first = *payload.get(*cursor)?;
    match first {
        0x00..=0x7f => {
            let start = *cursor;
            *cursor = cursor.checked_add(1)?;
            Some(SccpRlpItem::Bytes {
                payload: &payload[start..start + 1],
            })
        }
        0x80..=0xb7 => {
            let len = usize::from(first - 0x80);
            let raw_start = *cursor;
            let start = raw_start.checked_add(1)?;
            let end = start.checked_add(len)?;
            if end > payload.len() || (len == 1 && payload[start] < 0x80) {
                return None;
            }
            *cursor = end;
            Some(SccpRlpItem::Bytes {
                payload: &payload[start..end],
            })
        }
        0xb8..=0xbf => {
            let len_len = usize::from(first - 0xb7);
            let raw_start = *cursor;
            let len = read_rlp_len(payload, raw_start.checked_add(1)?, len_len)?;
            if len < 56 {
                return None;
            }
            let start = raw_start.checked_add(1)?.checked_add(len_len)?;
            let end = start.checked_add(len)?;
            if end > payload.len() {
                return None;
            }
            *cursor = end;
            Some(SccpRlpItem::Bytes {
                payload: &payload[start..end],
            })
        }
        0xc0..=0xf7 => {
            let len = usize::from(first - 0xc0);
            let raw_start = *cursor;
            let start = raw_start.checked_add(1)?;
            let end = start.checked_add(len)?;
            if end > payload.len() {
                return None;
            }
            *cursor = end;
            Some(SccpRlpItem::List {
                payload: &payload[start..end],
                raw: &payload[raw_start..end],
            })
        }
        0xf8..=0xff => {
            let len_len = usize::from(first - 0xf7);
            let raw_start = *cursor;
            let len = read_rlp_len(payload, raw_start.checked_add(1)?, len_len)?;
            if len < 56 {
                return None;
            }
            let start = raw_start.checked_add(1)?.checked_add(len_len)?;
            let end = start.checked_add(len)?;
            if end > payload.len() {
                return None;
            }
            *cursor = end;
            Some(SccpRlpItem::List {
                payload: &payload[start..end],
                raw: &payload[raw_start..end],
            })
        }
    }
}

fn rlp_list_items(payload: &[u8]) -> Option<Vec<SccpRlpItem<'_>>> {
    let mut outer_cursor = 0usize;
    let list_payload = match rlp_item_at(payload, &mut outer_cursor)? {
        SccpRlpItem::List { payload, .. } => payload,
        SccpRlpItem::Bytes { .. } => return None,
    };
    if outer_cursor != payload.len() {
        return None;
    }
    let mut cursor = 0usize;
    let mut items = Vec::new();
    while cursor < list_payload.len() {
        items.push(rlp_item_at(list_payload, &mut cursor)?);
    }
    (cursor == list_payload.len()).then_some(items)
}

fn rlp_single_item(payload: &[u8]) -> Option<SccpRlpItem<'_>> {
    let mut cursor = 0usize;
    let item = rlp_item_at(payload, &mut cursor)?;
    (cursor == payload.len()).then_some(item)
}

fn rlp_items_from_list_payload(payload: &[u8]) -> Option<Vec<SccpRlpItem<'_>>> {
    let mut cursor = 0usize;
    let mut items = Vec::new();
    while cursor < payload.len() {
        items.push(rlp_item_at(payload, &mut cursor)?);
    }
    (cursor == payload.len()).then_some(items)
}

fn rlp_item_bytes(item: SccpRlpItem<'_>) -> Option<&[u8]> {
    match item {
        SccpRlpItem::Bytes { payload, .. } => Some(payload),
        SccpRlpItem::List { .. } => None,
    }
}

enum SccpMptNodeRef {
    Hash(H256),
    Inline(Vec<u8>),
}

fn mpt_child_ref(item: SccpRlpItem<'_>) -> Option<SccpMptNodeRef> {
    match item {
        SccpRlpItem::Bytes { payload, .. } => {
            let hash = <[u8; 32]>::try_from(payload).ok()?;
            Some(SccpMptNodeRef::Hash(hash))
        }
        SccpRlpItem::List { raw, .. } => {
            if raw.is_empty() || raw.len() >= 32 {
                return None;
            }
            Some(SccpMptNodeRef::Inline(raw.to_vec()))
        }
    }
}

fn minimal_be_usize(value: usize) -> Vec<u8> {
    let bytes = value.to_be_bytes();
    bytes
        .iter()
        .skip_while(|byte| **byte == 0)
        .copied()
        .collect()
}

fn rlp_encode_length(length: usize, short_offset: u8, long_offset: u8) -> Option<Vec<u8>> {
    if length < 56 {
        return Some(vec![short_offset.checked_add(u8::try_from(length).ok()?)?]);
    }
    let len_bytes = minimal_be_usize(length);
    let len_len = u8::try_from(len_bytes.len()).ok()?;
    let mut out = Vec::with_capacity(1 + len_bytes.len());
    out.push(long_offset.checked_add(len_len)?);
    out.extend_from_slice(&len_bytes);
    Some(out)
}

fn rlp_encode_bytes(value: &[u8]) -> Option<Vec<u8>> {
    if value.len() == 1 && value[0] < 0x80 {
        return Some(vec![value[0]]);
    }
    let mut out = rlp_encode_length(value.len(), 0x80, 0xb7)?;
    out.extend_from_slice(value);
    Some(out)
}

fn rlp_encode_list(fields: &[Vec<u8>]) -> Option<Vec<u8>> {
    let payload_len = fields
        .iter()
        .try_fold(0usize, |sum, field| sum.checked_add(field.len()))?;
    let mut out = rlp_encode_length(payload_len, 0xc0, 0xf7)?;
    out.reserve(payload_len);
    for field in fields {
        out.extend_from_slice(field);
    }
    Some(out)
}

fn rlp_encode_u64(value: u64) -> Vec<u8> {
    if value == 0 {
        return vec![0x80];
    }
    let bytes = value.to_be_bytes();
    let first_nonzero = bytes
        .iter()
        .position(|byte| *byte != 0)
        .expect("non-zero u64 has a non-zero byte");
    let minimal = &bytes[first_nonzero..];
    if minimal.len() == 1 && minimal[0] < 0x80 {
        return vec![minimal[0]];
    }
    let mut out = Vec::with_capacity(1 + minimal.len());
    out.push(0x80 + u8::try_from(minimal.len()).expect("u64 RLP length fits u8"));
    out.extend_from_slice(minimal);
    out
}

fn evm_u256_from_u64(value: u64) -> H256 {
    let mut out = [0u8; 32];
    out[24..].copy_from_slice(&value.to_be_bytes());
    out
}

fn evm_u256_add_u64(mut value: H256, addend: u64) -> Option<H256> {
    let mut carry = u128::from(addend);
    for byte in value.iter_mut().rev() {
        if carry == 0 {
            break;
        }
        let sum = u128::from(*byte) + (carry & 0xff);
        *byte = u8::try_from(sum & 0xff).expect("masked EVM u256 byte fits u8");
        carry = (carry >> 8) + (sum >> 8);
    }
    (carry == 0).then_some(value)
}

fn evm_storage_trie_key(storage_slot: H256) -> H256 {
    keccak256_bytes(&storage_slot)
}

fn evm_storage_word_from_trie_value(value: &[u8]) -> Option<H256> {
    let bytes = rlp_item_bytes(rlp_single_item(value)?)?;
    if bytes.len() > 32 || (bytes.len() > 1 && bytes.first() == Some(&0)) {
        return None;
    }
    let mut out = [0u8; 32];
    out[32 - bytes.len()..].copy_from_slice(bytes);
    Some(out)
}

fn evm_storage_word_as_u64(value: H256) -> Option<u64> {
    if value[..24].iter().any(|byte| *byte != 0) {
        return None;
    }
    let mut out = [0u8; 8];
    out.copy_from_slice(&value[24..]);
    Some(u64::from_be_bytes(out))
}

fn evm_account_storage_root_from_trie_value(value: &[u8]) -> Option<H256> {
    let items = rlp_list_items(value)?;
    if items.len() != 4 {
        return None;
    }
    let storage_root = <[u8; 32]>::try_from(rlp_item_bytes(items[2])?).ok()?;
    let code_hash = <[u8; 32]>::try_from(rlp_item_bytes(items[3])?).ok()?;
    (h256_is_nonzero(&storage_root) && h256_is_nonzero(&code_hash)).then_some(storage_root)
}

fn sccp_bsc_validator_set_length_slot() -> H256 {
    evm_u256_from_u64(SCCP_BSC_VALIDATOR_SET_LENGTH_STORAGE_SLOT)
}

fn sccp_bsc_current_validator_set_base_slot() -> H256 {
    keccak256_bytes(&sccp_bsc_validator_set_length_slot())
}

fn sccp_bsc_current_validator_consensus_address_slot(index: u32) -> Option<H256> {
    let offset = u64::from(index).checked_mul(SCCP_BSC_VALIDATOR_STRUCT_STORAGE_SLOTS)?;
    evm_u256_add_u64(sccp_bsc_current_validator_set_base_slot(), offset)
}

fn mpt_nibbles_from_bytes(bytes: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(byte >> 4);
        out.push(byte & 0x0f);
    }
    out
}

fn mpt_decode_compact_path(encoded: &[u8]) -> Option<(bool, Vec<u8>)> {
    let nibbles = mpt_nibbles_from_bytes(encoded);
    let flag = *nibbles.first()?;
    if flag > 3 {
        return None;
    }
    let is_leaf = flag & 0x02 != 0;
    let is_odd = flag & 0x01 != 0;
    if is_odd {
        Some((is_leaf, nibbles[1..].to_vec()))
    } else {
        if nibbles.get(1).copied() != Some(0) {
            return None;
        }
        Some((is_leaf, nibbles[2..].to_vec()))
    }
}

fn mpt_proof_nodes_are_bounded(proof_nodes: &[Vec<u8>]) -> bool {
    !proof_nodes.is_empty()
        && proof_nodes.len() <= SCCP_TRON_MAX_MPT_PROOF_NODES
        && proof_nodes
            .iter()
            .all(|node| !node.is_empty() && node.len() <= SCCP_TRON_MAX_MPT_NODE_BYTES)
}

fn push_mpt_proof_nodes(out: &mut Vec<u8>, proof_nodes: &[Vec<u8>]) -> Option<()> {
    if !mpt_proof_nodes_are_bounded(proof_nodes) {
        return None;
    }
    push_u32(out, u32::try_from(proof_nodes.len()).ok()?);
    for node in proof_nodes {
        push_vec(out, node);
    }
    Some(())
}

fn sccp_eth_sync_committee_shape_is_bounded(proof: &SccpEthBeaconSyncCommitteeProofV1) -> bool {
    proof.sync_committee_public_keys.len() <= SCCP_ETH_MAX_SYNC_COMMITTEE_AUTHORITIES
        && proof.sync_committee_weights.len() <= SCCP_ETH_MAX_SYNC_COMMITTEE_AUTHORITIES
        && proof.sync_committee_pops.len() <= SCCP_ETH_MAX_SYNC_COMMITTEE_AUTHORITIES
        && proof.signers_bitmap.len() == proof.sync_committee_public_keys.len().div_ceil(8)
        && proof.aggregate_signature.len() == SCCP_ETH_SYNC_COMMITTEE_SIGNATURE_BYTES
        && proof.aggregate_signature.iter().any(|byte| *byte != 0)
        && proof.sync_committee_public_keys.iter().all(|public_key| {
            public_key.len() == SCCP_ETH_SYNC_COMMITTEE_PUBLIC_KEY_BYTES
                && public_key.iter().any(|byte| *byte != 0)
        })
        && proof.sync_committee_pops.iter().all(|pop| {
            pop.len() == SCCP_ETH_SYNC_COMMITTEE_POP_BYTES && pop.iter().any(|byte| *byte != 0)
        })
}

fn sccp_eth_sync_committee_transition_shape_is_bounded(
    transition: &SccpEthSyncCommitteeTransitionProofV1,
) -> bool {
    !transition.next_sync_committee_payload.is_empty()
        && transition.next_sync_committee_payload.len() <= SCCP_ETH_MAX_SYNC_COMMITTEE_PAYLOAD_BYTES
        && sccp_eth_sync_committee_shape_is_bounded(&transition.sync_committee_proof)
}

fn sccp_eth_source_adapter_shape_is_bounded(adapter: &SccpEvmBeaconSourceProofV1) -> bool {
    adapter.execution_header_rlp.len() <= SCCP_EVM_MAX_HEADER_RLP_BYTES
        && h256_merkle_branch_siblings_are_bounded(&adapter.execution_payload_branch)
        && mpt_proof_nodes_are_bounded(&adapter.receipt_trie_proof_nodes)
        && sccp_eth_sync_committee_shape_is_bounded(&adapter.sync_committee_proof)
        && adapter.sync_committee_transition_proofs.len() <= SCCP_ETH_MAX_SYNC_COMMITTEE_TRANSITIONS
        && adapter
            .sync_committee_transition_proofs
            .iter()
            .all(sccp_eth_sync_committee_transition_shape_is_bounded)
}

fn sccp_bsc_validator_set_seal_shape_is_bounded(seal: &SccpBscValidatorSetSealProofV1) -> bool {
    seal.validator_public_keys.len() <= SCCP_BSC_MAX_PARLIA_VALIDATORS
        && seal.validator_powers.len() <= SCCP_BSC_MAX_PARLIA_VALIDATORS
        && seal.signers_bitmap.len() <= SCCP_BSC_MAX_PARLIA_VALIDATORS.div_ceil(8)
        && seal.signatures.len() <= SCCP_BSC_MAX_PARLIA_VALIDATORS
        && seal.validator_public_keys.iter().all(|public_key| {
            !public_key.is_empty() && public_key.len() <= SCCP_BSC_MAX_VALIDATOR_PUBLIC_KEY_BYTES
        })
        && seal
            .signatures
            .iter()
            .all(|signature| signature.len() <= 65)
}

fn sccp_bsc_validator_storage_proof_shape_is_bounded(
    proof: &SccpBscValidatorStorageProofV1,
) -> bool {
    proof.storage_value.len() <= SCCP_EVM_MAX_RECEIPT_VALUE_BYTES
        && mpt_proof_nodes_are_bounded(&proof.storage_proof_nodes)
}

fn sccp_bsc_validator_set_metadata_shape_is_bounded(
    proof: &SccpBscValidatorSetMetadataProofV1,
) -> bool {
    proof.validator_contract_address.len() <= 20
        && mpt_proof_nodes_are_bounded(&proof.account_proof_nodes)
        && proof.validator_set_length_value.len() <= SCCP_EVM_MAX_RECEIPT_VALUE_BYTES
        && mpt_proof_nodes_are_bounded(&proof.validator_set_length_proof_nodes)
        && proof.validator_storage_proofs.len() <= SCCP_BSC_MAX_PARLIA_VALIDATORS
        && proof
            .validator_storage_proofs
            .iter()
            .all(sccp_bsc_validator_storage_proof_shape_is_bounded)
}

fn sccp_bsc_validator_set_transition_shape_is_bounded(
    transition: &SccpBscValidatorSetTransitionProofV1,
) -> bool {
    transition.transition_header_rlp.len() <= SCCP_EVM_MAX_HEADER_RLP_BYTES
        && !transition.next_validator_set_payload.is_empty()
        && transition.next_validator_set_payload.len() <= SCCP_BSC_MAX_VALIDATOR_SET_PAYLOAD_BYTES
        && sccp_bsc_validator_set_metadata_shape_is_bounded(
            &transition.validator_set_metadata_proof,
        )
        && sccp_bsc_validator_set_seal_shape_is_bounded(&transition.seal_proof)
}

fn sccp_bsc_source_adapter_shape_is_bounded(adapter: &SccpBscValidatorSetSourceProofV1) -> bool {
    mpt_proof_nodes_are_bounded(&adapter.receipt_trie_proof_nodes)
        && sccp_bsc_validator_set_seal_shape_is_bounded(&adapter.seal_proof)
        && adapter.validator_set_transition_proofs.len() <= SCCP_BSC_MAX_VALIDATOR_SET_TRANSITIONS
        && adapter
            .validator_set_transition_proofs
            .iter()
            .all(sccp_bsc_validator_set_transition_shape_is_bounded)
}

fn sccp_source_state_verification_proof_shape_is_bounded(
    proof: &SccpSourceStateVerificationProofV1,
) -> bool {
    if proof.proof_family.len() > SCCP_SOURCE_STATE_MAX_PROOF_LABEL_BYTES
        || proof.circuit_id.len() > SCCP_SOURCE_STATE_MAX_PROOF_LABEL_BYTES
        || proof.proof_bytes.len() > SCCP_SOURCE_STATE_MAX_PROOF_BYTES
    {
        return false;
    }
    if !sccp_source_state_verification_proof_is_present(proof) {
        return true;
    }
    proof.version == 1
        && proof.proof_family == SCCP_STARK_FRI_PROOF_FAMILY_V1
        && !proof.circuit_id.is_empty()
        && !proof.proof_bytes.is_empty()
        && proof.proof_bytes.iter().any(|byte| *byte != 0)
}

fn sccp_source_state_verification_proof_is_present(
    proof: &SccpSourceStateVerificationProofV1,
) -> bool {
    proof.version != 0
        || !proof.proof_family.is_empty()
        || !proof.circuit_id.is_empty()
        || !proof.proof_bytes.is_empty()
}

fn sccp_solana_fixed_width_vectors_are_bounded(fields: &[Vec<u8>], max_fields: usize) -> bool {
    fields.len() <= max_fields && fields.iter().all(|field| field.len() <= 32)
}

fn sccp_solana_account_opening_shape_is_bounded(opening: &SccpSolanaAccountOpeningV1) -> bool {
    opening.address.len() <= 32 && opening.owner.len() <= 32
}

fn sccp_solana_account_inclusion_branch_shape_is_bounded(
    branch: &SccpSolanaAccountInclusionBranchV1,
) -> bool {
    h256_merkle_branch_siblings_are_bounded(&branch.siblings)
}

fn sccp_solana_vote_account_data_shape_is_bounded(
    account_data: &SccpSolanaVoteAccountDataV1,
) -> bool {
    account_data.node_pubkey.len() <= 32
        && account_data.authorized_voter.len() <= 32
        && account_data.authorized_withdrawer.len() <= 32
        && account_data.inflation_rewards_collector.len() <= 32
        && account_data.block_revenue_collector.len() <= 32
        && account_data.bls_pubkey_compressed.len() <= SCCP_SOLANA_BLS_PUBLIC_KEY_COMPRESSED_LEN
        && account_data.tower_vote_slots.len() <= SCCP_SOLANA_TOWER_VOTE_STACK_DEPTH as usize
}

fn sccp_solana_stake_account_data_shape_is_bounded(
    account_data: &SccpSolanaStakeAccountDataV1,
) -> bool {
    account_data.staker.len() <= 32
        && account_data.withdrawer.len() <= 32
        && account_data.voter_pubkey.len() <= 32
        && account_data.warmup_cooldown_rate_bytes.len()
            <= SCCP_SOLANA_STAKE_STATE_V2_WARMUP_COOLDOWN_RATE_BYTES
}

fn sccp_solana_raw_account_data_shape_is_bounded(
    fields: &[Vec<u8>],
    max_field_bytes: usize,
) -> bool {
    fields.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && fields.iter().all(|field| field.len() <= max_field_bytes)
}

fn sccp_solana_signer_bitmap_shape_is_canonical(bitmap: &[u8], roster_len: usize) -> bool {
    if bitmap.len() != roster_len.div_ceil(8) {
        return false;
    }
    let padding_bits = roster_len % 8;
    if padding_bits == 0 {
        return true;
    }
    let allowed_mask = (1u8 << padding_bits) - 1;
    bitmap
        .last()
        .is_some_and(|last_byte| last_byte & !allowed_mask == 0)
}

fn sccp_solana_vote_proof_shape_is_bounded(proof: &SccpSolanaFinalizedVoteProofV1) -> bool {
    proof.validator_public_keys.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof.validator_stakes.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof.validator_delegated_stakes.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof.validator_activation_epochs.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof.validator_deactivation_epochs.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && sccp_solana_fixed_width_vectors_are_bounded(
            &proof.validator_public_keys,
            SCCP_SOLANA_MAX_VALIDATORS,
        )
        && sccp_solana_fixed_width_vectors_are_bounded(
            &proof.validator_vote_account_addresses,
            SCCP_SOLANA_MAX_VALIDATORS,
        )
        && sccp_solana_fixed_width_vectors_are_bounded(
            &proof.validator_stake_account_addresses,
            SCCP_SOLANA_MAX_VALIDATORS,
        )
        && sccp_solana_fixed_width_vectors_are_bounded(
            &proof.validator_vote_account_hashes,
            SCCP_SOLANA_MAX_VALIDATORS,
        )
        && sccp_solana_fixed_width_vectors_are_bounded(
            &proof.validator_stake_account_hashes,
            SCCP_SOLANA_MAX_VALIDATORS,
        )
        && proof.validator_vote_account_openings.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_vote_account_openings
            .iter()
            .all(sccp_solana_account_opening_shape_is_bounded)
        && proof.validator_stake_account_openings.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_stake_account_openings
            .iter()
            .all(sccp_solana_account_opening_shape_is_bounded)
        && proof.validator_vote_account_data.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_vote_account_data
            .iter()
            .all(sccp_solana_vote_account_data_shape_is_bounded)
        && proof.validator_stake_account_data.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_stake_account_data
            .iter()
            .all(sccp_solana_stake_account_data_shape_is_bounded)
        && sccp_solana_raw_account_data_shape_is_bounded(
            &proof.validator_vote_account_raw_data,
            SCCP_SOLANA_VOTE_STATE_ACCOUNT_DATA_LEN,
        )
        && sccp_solana_raw_account_data_shape_is_bounded(
            &proof.validator_stake_account_raw_data,
            SCCP_SOLANA_STAKE_STATE_V2_STAKE_ACCOUNT_DATA_LEN,
        )
        && proof.validator_vote_account_inclusion_branches.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_vote_account_inclusion_branches
            .iter()
            .all(sccp_solana_account_inclusion_branch_shape_is_bounded)
        && proof.validator_stake_account_inclusion_branches.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .validator_stake_account_inclusion_branches
            .iter()
            .all(sccp_solana_account_inclusion_branch_shape_is_bounded)
        && sccp_solana_account_opening_shape_is_bounded(&proof.stake_history_sysvar_opening)
        && proof.stake_history_sysvar_raw_data.len() <= SCCP_SOLANA_MAX_ACCOUNT_RAW_DATA_BYTES
        && sccp_solana_account_inclusion_branch_shape_is_bounded(
            &proof.stake_history_sysvar_inclusion_branch,
        )
        && proof.stake_history_entries.len() <= SCCP_SOLANA_MAX_STAKE_HISTORY_ENTRIES
        && proof.accounts_lt_hash.len() <= SCCP_SOLANA_ACCOUNTS_LT_HASH_BYTES
        && sccp_source_state_verification_proof_shape_is_bounded(&proof.accounts_lt_hash_proof)
        && sccp_source_state_verification_proof_shape_is_bounded(
            &proof.tower_replay_verification_proof,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &proof.full_accountsdb_lattice_verification_proof,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &proof.bank_fork_choice_verification_proof,
        )
        && sccp_solana_signer_bitmap_shape_is_canonical(
            &proof.signers_bitmap,
            proof.validator_public_keys.len(),
        )
        && proof.signatures.len() <= SCCP_SOLANA_MAX_VALIDATORS
        && proof
            .signatures
            .iter()
            .all(|signature| signature.len() <= 64)
}

fn sccp_solana_finality_context_shape_is_bounded(context: &SccpSolanaFinalityContextV1) -> bool {
    context.tower_vote_slots.len() <= SCCP_SOLANA_TOWER_VOTE_STACK_DEPTH as usize
        && context.bank_hash_hard_fork_data.len() <= SCCP_SOLANA_MAX_BANK_HARD_FORK_HASH_DATA_BYTES
}

fn sccp_solana_source_adapter_shape_is_bounded(adapter: &SccpSolanaFinalizedSourceProofV1) -> bool {
    adapter.transaction_signature.len() <= SCCP_SOLANA_TRANSACTION_SIGNATURE_BYTES
        && adapter.emitter_program_id.len() <= SCCP_SOLANA_PROGRAM_ID_BYTES
        && sccp_solana_finality_context_shape_is_bounded(&adapter.finality_context)
        && sccp_solana_vote_proof_shape_is_bounded(&adapter.vote_proof)
}

fn sccp_tron_witness_seal_shape_is_bounded(seal: &SccpTronDposWitnessSealProofV1) -> bool {
    let roster_len = seal.witness_addresses.len();
    let Some(signer_indices) = signer_indices_from_bitmap(&seal.signers_bitmap, roster_len) else {
        return false;
    };
    if seal.version != 1
        || seal.total_weight == 0
        || seal.signed_weight == 0
        || roster_len == 0
        || roster_len > SCCP_TRON_MAX_WITNESSES
        || roster_len != seal.witness_weights.len()
        || signer_indices.is_empty()
        || seal.signatures.len() != signer_indices.len()
    {
        return false;
    }

    let mut seen_addresses = Vec::<[u8; 21]>::with_capacity(roster_len);
    for address in &seal.witness_addresses {
        let Ok(address) = <[u8; 21]>::try_from(address.as_slice()) else {
            return false;
        };
        if !sccp_tron_address21_is_nonzero(&address) || seen_addresses.contains(&address) {
            return false;
        }
        seen_addresses.push(address);
    }

    let Some(total_weight) = seal
        .witness_weights
        .iter()
        .try_fold(0u128, |total, weight| {
            (*weight != 0).then_some(total.saturating_add(u128::from(*weight)))
        })
    else {
        return false;
    };
    let Some(signed_weight) = signer_indices.iter().try_fold(0u128, |total, index| {
        seal.witness_weights
            .get(*index)
            .map(|weight| total.saturating_add(u128::from(*weight)))
    }) else {
        return false;
    };

    total_weight == u128::from(seal.total_weight)
        && signed_weight == u128::from(seal.signed_weight)
        && signed_weight.saturating_mul(3) > total_weight.saturating_mul(2)
        && seal
            .signatures
            .iter()
            .all(|signature| tron_recoverable_signature_slice_is_canonical(signature))
}

fn sccp_tron_solid_block_header_shape_is_bounded(header: &SccpTronSolidBlockHeaderProofV1) -> bool {
    header.version == 1
        && !header.raw_data.is_empty()
        && header.raw_data.len() <= SCCP_TRON_MAX_RAW_HEADER_BYTES
        && !header.parent_raw_data.is_empty()
        && header.parent_raw_data.len() <= SCCP_TRON_MAX_RAW_HEADER_BYTES
        && h256_is_nonzero(&header.raw_data_hash)
        && h256_is_nonzero(&header.parent_raw_data_hash)
        && h256_is_nonzero(&header.block_id)
        && h256_is_nonzero(&header.tx_trie_root)
        && h256_is_nonzero(&header.account_state_root)
        && h256_is_nonzero(&header.parent_block_id)
        && header.timestamp_ms != 0
        && header.header_version != 0
        && sccp_tron_address21_is_nonzero(&header.witness_address)
        && tron_recoverable_signature_slice_is_canonical(&header.witness_signature)
        && tron_recoverable_signature_slice_is_canonical(&header.parent_witness_signature)
}

fn sccp_tron_signed_block_header_shape_is_bounded(
    header: &SccpTronSignedBlockHeaderProofV1,
) -> bool {
    header.version == 1
        && !header.raw_data.is_empty()
        && header.raw_data.len() <= SCCP_TRON_MAX_RAW_HEADER_BYTES
        && h256_is_nonzero(&header.raw_data_hash)
        && h256_is_nonzero(&header.block_id)
        && h256_is_nonzero(&header.tx_trie_root)
        && h256_is_nonzero(&header.account_state_root)
        && h256_is_nonzero(&header.parent_block_id)
        && header.timestamp_ms != 0
        && header.header_version != 0
        && sccp_tron_address21_is_nonzero(&header.witness_address)
        && tron_recoverable_signature_slice_is_canonical(&header.witness_signature)
}

fn sccp_tron_witness_schedule_transition_shape_is_bounded(
    transition: &SccpTronWitnessScheduleTransitionProofV1,
) -> bool {
    transition.version == 1
        && transition.source_domain == SCCP_DOMAIN_TRON
        && transition.from_witness_schedule_epoch.checked_add(1)
            == Some(transition.to_witness_schedule_epoch)
        && transition.transition_block_number != 0
        && h256_is_nonzero(&transition.transition_block_hash)
        && h256_is_nonzero(&transition.parent_witness_schedule_hash)
        && h256_is_nonzero(&transition.next_witness_schedule_hash)
        && h256_is_nonzero(&transition.next_witness_schedule_payload_hash)
        && h256_is_nonzero(&transition.transition_message_hash)
        && h256_is_nonzero(&transition.transition_seal_hash)
        && transition.seal_proof.solid_block_message_hash == transition.transition_message_hash
        && !transition.next_witness_schedule_payload.is_empty()
        && transition.next_witness_schedule_payload.len()
            <= SCCP_TRON_MAX_WITNESS_SCHEDULE_PAYLOAD_BYTES
        && sccp_tron_witness_seal_shape_is_bounded(&transition.seal_proof)
}

fn sccp_tron_transaction_source_proof_is_present(adapter: &SccpTronDposSourceProofV1) -> bool {
    adapter.transaction_index != 0
        || adapter.transaction_count != 0
        || !adapter.transaction_bytes.is_empty()
        || !adapter.transaction_merkle_branch.is_empty()
}

fn sccp_tron_transaction_source_proof_shape_is_bounded(
    adapter: &SccpTronDposSourceProofV1,
) -> bool {
    if !sccp_tron_transaction_source_proof_is_present(adapter) {
        return true;
    }
    adapter.transaction_count != 0
        && adapter.transaction_index < adapter.transaction_count
        && !adapter.transaction_bytes.is_empty()
        && adapter.transaction_bytes.len() <= SCCP_TRON_MAX_TRANSACTION_BYTES
        && adapter.transaction_merkle_branch.len() <= SCCP_TRON_MAX_TRANSACTION_MERKLE_BRANCH_NODES
        && adapter
            .transaction_merkle_branch
            .iter()
            .all(|sibling| sibling.len() == 32)
}

fn sccp_tron_source_adapter_shape_is_bounded(adapter: &SccpTronDposSourceProofV1) -> bool {
    let transaction_source_proof_present = sccp_tron_transaction_source_proof_is_present(adapter);
    adapter.version == 1
        && adapter.source_domain == SCCP_DOMAIN_TRON
        && adapter.solid_block_number != 0
        && h256_is_nonzero(&adapter.block_hash)
        && h256_is_nonzero(&adapter.witness_schedule_hash)
        && h256_is_nonzero(&adapter.witness_seal_hash)
        && h256_is_nonzero(&adapter.receipt_root)
        && h256_is_nonzero(&adapter.transaction_root)
        && h256_is_nonzero(&adapter.receipt_proof_hash)
        && adapter.receipt_root_branch.is_empty()
        && if transaction_source_proof_present {
            adapter.receipt_root_index == 0 && adapter.receipt_trie_proof_nodes.is_empty()
        } else {
            mpt_proof_nodes_are_bounded(&adapter.receipt_trie_proof_nodes)
        }
        && sccp_tron_transaction_source_proof_shape_is_bounded(adapter)
        && sccp_tron_solid_block_header_shape_is_bounded(&adapter.solid_block_header_proof)
        && adapter.solid_block_ancestor_headers.len() <= SCCP_TRON_MAX_SOLID_BLOCK_ANCESTOR_HEADERS
        && adapter
            .solid_block_ancestor_headers
            .iter()
            .all(sccp_tron_signed_block_header_shape_is_bounded)
        && adapter.solid_block_confirmation_headers.len()
            <= SCCP_TRON_MAX_SOLID_BLOCK_CONFIRMATION_HEADERS
        && adapter
            .solid_block_confirmation_headers
            .iter()
            .all(sccp_tron_signed_block_header_shape_is_bounded)
        && sccp_tron_witness_seal_shape_is_bounded(&adapter.witness_seal_proof)
        && adapter.witness_schedule_transition_proofs.len()
            <= SCCP_TRON_MAX_WITNESS_SCHEDULE_TRANSITIONS
        && adapter
            .witness_schedule_transition_proofs
            .iter()
            .all(sccp_tron_witness_schedule_transition_shape_is_bounded)
}

fn sccp_source_adapter_proof_shape_is_bounded(proof: &SccpSourceAdapterProofV1) -> bool {
    match proof {
        SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) => {
            sccp_eth_source_adapter_shape_is_bounded(adapter)
        }
        SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) => {
            sccp_bsc_source_adapter_shape_is_bounded(adapter)
        }
        SccpSourceAdapterProofV1::SolanaFinalizedTransaction(adapter) => {
            sccp_solana_source_adapter_shape_is_bounded(adapter)
        }
        SccpSourceAdapterProofV1::TonMasterchainShard(adapter) => {
            sccp_ton_source_adapter_shape_is_bounded(adapter)
        }
        SccpSourceAdapterProofV1::TronDposReceipt(adapter) => {
            sccp_tron_source_adapter_shape_is_bounded(adapter)
        }
        SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter) => {
            sccp_substrate_source_adapter_shape_is_bounded(adapter)
        }
    }
}

fn sccp_substrate_grandpa_justification_shape_is_bounded(
    proof: &SccpSubstrateGrandpaJustificationProofV1,
) -> bool {
    proof.authority_public_keys.len() <= SCCP_SUBSTRATE_MAX_AUTHORITIES
        && proof.authority_weights.len() <= SCCP_SUBSTRATE_MAX_AUTHORITIES
        && proof.signers_bitmap.len() <= SCCP_SUBSTRATE_MAX_AUTHORITIES.div_ceil(8)
        && proof.signatures.len() <= SCCP_SUBSTRATE_MAX_AUTHORITIES
        && proof
            .authority_public_keys
            .iter()
            .all(|public_key| public_key.len() == 32)
        && proof
            .signatures
            .iter()
            .all(|signature| signature.len() == 64)
}

fn sccp_substrate_source_adapter_shape_is_bounded(
    adapter: &SccpSubstrateGrandpaSourceProofV1,
) -> bool {
    sccp_substrate_grandpa_justification_shape_is_bounded(&adapter.grandpa_justification)
        && sccp_source_state_verification_proof_shape_is_bounded(
            &adapter.runtime_storage_verification_proof,
        )
        && adapter.authority_set_transition_proofs.len()
            <= SCCP_SUBSTRATE_MAX_AUTHORITY_SET_TRANSITIONS
        && adapter
            .authority_set_transition_proofs
            .iter()
            .all(|transition| {
                transition.next_authority_set_payload.len()
                    <= SCCP_SUBSTRATE_MAX_AUTHORITY_SET_PAYLOAD_BYTES
                    && sccp_substrate_grandpa_justification_shape_is_bounded(
                        &transition.grandpa_justification,
                    )
            })
}

fn sccp_ton_validator_signature_proof_shape_is_bounded(
    proof: &SccpTonMasterchainValidatorSignaturesProofV1,
) -> bool {
    proof.validator_public_keys.len() <= SCCP_TON_MAX_VALIDATORS
        && proof.validator_weights.len() <= SCCP_TON_MAX_VALIDATORS
        && proof.signatures.len() <= SCCP_TON_MAX_VALIDATORS
        && proof.signers_bitmap.len() <= SCCP_TON_MAX_VALIDATORS.div_ceil(8)
}

fn sccp_ton_source_adapter_shape_is_bounded(adapter: &SccpTonMasterchainSourceProofV1) -> bool {
    adapter.shard_state_proof_boc.len() <= SCCP_TON_MAX_BOC_BYTES
        && adapter.shard_state_dictionary_proof_boc.len() <= SCCP_TON_MAX_BOC_BYTES
        && adapter
            .masterchain_config_proof
            .config_dictionary_proof_boc
            .len()
            <= SCCP_TON_MAX_BOC_BYTES
        && h256_merkle_branch_siblings_are_bounded(&adapter.shard_state_inclusion_branch)
        && h256_merkle_branch_siblings_are_bounded(
            &adapter.masterchain_config_proof.config_inclusion_branch,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &adapter.shard_state_verification_proof,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &adapter.masterchain_config_verification_proof,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &adapter.validator_set_transition_verification_proof,
        )
        && sccp_source_state_verification_proof_shape_is_bounded(
            &adapter.shard_accounts_dictionary_verification_proof,
        )
        && adapter.validator_set_transition_proofs.len() <= SCCP_TON_MAX_VALIDATOR_SET_TRANSITIONS
        && sccp_ton_validator_signature_proof_shape_is_bounded(&adapter.validator_signature_proof)
        && adapter
            .validator_set_transition_proofs
            .iter()
            .all(|transition| {
                transition.next_validator_set_payload.len()
                    <= 5 + SCCP_TON_MAX_VALIDATORS * (32 + 8)
                    && sccp_ton_validator_signature_proof_shape_is_bounded(
                        &transition.validator_signature_proof,
                    )
            })
}

fn verify_sccp_mpt_inclusion(
    root_hash: H256,
    key: &[u8],
    proof_nodes: &[Vec<u8>],
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&root_hash) || !mpt_proof_nodes_are_bounded(proof_nodes) {
        return None;
    }

    let key_nibbles = mpt_nibbles_from_bytes(key);
    let mut cursor = 0usize;
    let mut proof_index = 0usize;
    let mut expected_ref = SccpMptNodeRef::Hash(root_hash);
    let mut inline_node = None::<Vec<u8>>;
    let mut steps = 0usize;
    loop {
        let node = if let Some(node) = inline_node.take() {
            node
        } else {
            let node = proof_nodes.get(proof_index)?;
            proof_index = proof_index.checked_add(1)?;
            node.clone()
        };
        steps = steps.checked_add(1)?;
        if steps
            > proof_nodes
                .len()
                .saturating_add(SCCP_TRON_MAX_MPT_PROOF_NODES)
        {
            return None;
        }

        match &expected_ref {
            SccpMptNodeRef::Hash(hash) => {
                if keccak256_bytes(&node).as_slice() != hash.as_slice() {
                    return None;
                }
            }
            SccpMptNodeRef::Inline(raw) => {
                if node.as_slice() != raw.as_slice() {
                    return None;
                }
            }
        }

        let items = rlp_list_items(&node)?;
        let next_ref = match items.len() {
            17 => {
                if cursor == key_nibbles.len() {
                    let value = rlp_item_bytes(items[16])?;
                    return (!value.is_empty() && proof_index == proof_nodes.len())
                        .then(|| value.to_vec());
                }
                let next_nibble = usize::from(*key_nibbles.get(cursor)?);
                cursor = cursor.checked_add(1)?;
                mpt_child_ref(items[next_nibble])?
            }
            2 => {
                let compact_path = rlp_item_bytes(items[0])?;
                let (is_leaf, partial_path) = mpt_decode_compact_path(compact_path)?;
                let remaining = key_nibbles.get(cursor..)?;
                if !remaining.starts_with(&partial_path) {
                    return None;
                }
                cursor = cursor.checked_add(partial_path.len())?;
                if is_leaf {
                    if cursor != key_nibbles.len() {
                        return None;
                    }
                    let value = rlp_item_bytes(items[1])?;
                    return (!value.is_empty() && proof_index == proof_nodes.len())
                        .then(|| value.to_vec());
                }
                mpt_child_ref(items[1])?
            }
            _ => return None,
        };
        expected_ref = next_ref;
        if let SccpMptNodeRef::Inline(raw) = &expected_ref {
            inline_node = Some(raw.clone());
        }
    }
}

pub fn canonical_sccp_evm_receipt_root_mpt_value(receipt_root: H256) -> Option<Vec<u8>> {
    let value = rlp_encode_list(&[
        rlp_encode_bytes(SCCP_EVM_RECEIPT_ROOT_VALUE_MARKER_V1)?,
        rlp_encode_bytes(&receipt_root)?,
    ])?;
    (!value.is_empty() && value.len() <= SCCP_EVM_MAX_RECEIPT_VALUE_BYTES).then_some(value)
}

fn sccp_evm_receipt_root_from_mpt_value(value: &[u8]) -> Option<H256> {
    if value.is_empty() || value.len() > SCCP_EVM_MAX_RECEIPT_VALUE_BYTES {
        return None;
    }

    let items = rlp_list_items(value)?;
    if items.len() != 2 {
        return None;
    }
    let marker = rlp_item_bytes(items[0])?;
    let receipt_root = rlp_item_bytes(items[1])?;
    if marker != SCCP_EVM_RECEIPT_ROOT_VALUE_MARKER_V1 {
        return None;
    }
    <[u8; 32]>::try_from(receipt_root).ok()
}

fn sccp_evm_source_event_topic_v1() -> H256 {
    keccak256_bytes(SCCP_EVM_SOURCE_EVENT_ABI_V1)
}

fn sccp_evm_receipt_payload_for_admitted_type(value: &[u8]) -> Option<&[u8]> {
    match value.first()? {
        // EIP-2718 makes typed receipt payloads type-specific. Admit only
        // mainnet types whose current specs use the canonical receipt tuple.
        0x01..=0x04 => Some(&value[1..]),
        0x00..=0x7f => None,
        _ => Some(value),
    }
}

fn sccp_evm_receipt_value_contains_source_event_digest(
    value: &[u8],
    source_event_digest: H256,
) -> bool {
    sccp_evm_receipt_value_contains_source_event(value, source_event_digest, None)
}

fn sccp_evm_receipt_value_contains_source_event(
    value: &[u8],
    source_event_digest: H256,
    expected_emitter_address: Option<[u8; 20]>,
) -> bool {
    if value.is_empty() || value.len() > SCCP_EVM_MAX_RECEIPT_VALUE_BYTES {
        return false;
    }

    let Some(receipt) = sccp_evm_receipt_payload_for_admitted_type(value) else {
        return false;
    };
    let Some(items) = rlp_list_items(receipt) else {
        return false;
    };
    if items.len() != 4 {
        return false;
    }
    if rlp_item_bytes(items[0]) != Some(&[1]) {
        return false;
    }
    if rlp_item_bytes(items[1])
        .is_none_or(|gas| gas.is_empty() || gas.len() > 8 || (gas.len() > 1 && gas[0] == 0))
    {
        return false;
    }
    if rlp_item_bytes(items[2]).is_none_or(|bloom| bloom.len() != 256) {
        return false;
    }
    let SccpRlpItem::List {
        payload: receipt_logs_payload,
        ..
    } = items[3]
    else {
        return false;
    };
    let Some(log_items) = rlp_items_from_list_payload(receipt_logs_payload) else {
        return false;
    };
    let mut matched = false;
    for log in log_items {
        let SccpRlpItem::List {
            payload: single_log_payload,
            ..
        } = log
        else {
            return false;
        };
        let Some(fields) = rlp_items_from_list_payload(single_log_payload) else {
            return false;
        };
        if fields.len() != 3 {
            return false;
        }
        let Some(address) =
            rlp_item_bytes(fields[0]).and_then(|address| <[u8; 20]>::try_from(address).ok())
        else {
            return false;
        };
        let SccpRlpItem::List {
            payload: topics_payload,
            ..
        } = fields[1]
        else {
            return false;
        };
        let Some(topics) = rlp_items_from_list_payload(topics_payload) else {
            return false;
        };
        if topics.len() > SCCP_EVM_MAX_LOG_TOPICS {
            return false;
        }
        let Some(data) = rlp_item_bytes(fields[2]) else {
            return false;
        };
        let mut topic_bytes = Vec::with_capacity(topics.len());
        for topic in topics {
            let Some(topic) = rlp_item_bytes(topic) else {
                return false;
            };
            if topic.len() != 32 {
                return false;
            }
            topic_bytes.push(topic);
        }
        let event_topic = sccp_evm_source_event_topic_v1();
        if topic_bytes.len() == 2
            && topic_bytes[0] == event_topic.as_slice()
            && topic_bytes[1] == source_event_digest.as_slice()
            && data.is_empty()
            && expected_emitter_address.is_none_or(|expected| expected == address)
        {
            if matched {
                return false;
            }
            matched = true;
        }
    }

    matched
}

fn verify_sccp_evm_receipt_mpt_value(
    receipt_trie_root: H256,
    receipt_root_index: u64,
    receipt_trie_proof_nodes: &[Vec<u8>],
    expected_value: H256,
) -> bool {
    let receipt_trie_key = rlp_encode_u64(receipt_root_index);
    verify_sccp_mpt_inclusion(
        receipt_trie_root,
        &receipt_trie_key,
        receipt_trie_proof_nodes,
    )
    .and_then(|value| sccp_evm_receipt_root_from_mpt_value(&value))
    .is_some_and(|receipt_root| receipt_root == expected_value)
}

fn verify_sccp_evm_receipt_mpt_event_value_with_emitter(
    receipt_trie_root: H256,
    receipt_root_index: u64,
    receipt_trie_proof_nodes: &[Vec<u8>],
    source_event_digest: H256,
    expected_emitter_address: Option<[u8; 20]>,
) -> bool {
    let receipt_trie_key = rlp_encode_u64(receipt_root_index);
    verify_sccp_mpt_inclusion(
        receipt_trie_root,
        &receipt_trie_key,
        receipt_trie_proof_nodes,
    )
    .is_some_and(|value| {
        sccp_evm_receipt_value_contains_source_event(
            &value,
            source_event_digest,
            expected_emitter_address,
        )
    })
}

fn verify_sccp_evm_receipt_mpt_source_value(
    receipt_trie_root: H256,
    receipt_root_index: u64,
    receipt_trie_proof_nodes: &[Vec<u8>],
    receipt_or_message_root: H256,
    source_event_digest: H256,
    material: &SccpSourceVerifierMaterialV1,
) -> bool {
    let expected_emitter_address = if !material.placeholder_material
        && sccp_source_bridge_emitter_binding_required(material.source_domain)
    {
        let Some(address) =
            sccp_source_bridge_emitter_address_as_array(&material.source_bridge_emitter_address)
        else {
            return false;
        };
        if !address20_is_nonzero(&address) {
            return false;
        }
        Some(address)
    } else {
        None
    };

    verify_sccp_evm_receipt_mpt_event_value_with_emitter(
        receipt_trie_root,
        receipt_root_index,
        receipt_trie_proof_nodes,
        source_event_digest,
        expected_emitter_address,
    ) || (material.placeholder_material
        && verify_sccp_evm_receipt_mpt_value(
            receipt_trie_root,
            receipt_root_index,
            receipt_trie_proof_nodes,
            receipt_or_message_root,
        ))
}

fn sccp_tron_receipt_root_from_mpt_value(value: &[u8]) -> Option<H256> {
    if value.is_empty() || value.len() > SCCP_TRON_MAX_RECEIPT_VALUE_BYTES {
        return None;
    }

    let items = rlp_list_items(value)?;
    if items.len() != 2 {
        return None;
    }
    let marker = rlp_item_bytes(items[0])?;
    let receipt_root = rlp_item_bytes(items[1])?;
    if marker != SCCP_TRON_RECEIPT_ROOT_VALUE_MARKER_V1 {
        return None;
    }
    let receipt_root = <[u8; 32]>::try_from(receipt_root).ok()?;
    h256_is_nonzero(&receipt_root).then_some(receipt_root)
}

fn read_protobuf_length_delimited_field<'a>(
    bytes: &'a [u8],
    cursor: &mut usize,
) -> Option<&'a [u8]> {
    let len = usize::try_from(read_protobuf_varint_at(bytes, cursor)?).ok()?;
    let end = (*cursor).checked_add(len)?;
    let value = bytes.get(*cursor..end)?;
    *cursor = end;
    Some(value)
}

fn sccp_tron_log_address_is_well_formed(address: &[u8]) -> bool {
    match address.len() {
        20 => address.iter().any(|byte| *byte != 0),
        21 => address[0] == 0x41 && address[1..].iter().any(|byte| *byte != 0),
        _ => false,
    }
}

fn sccp_tron_log_address_matches_expected(
    address: &[u8],
    expected_emitter_address: Option<[u8; 20]>,
) -> bool {
    if !sccp_tron_log_address_is_well_formed(address) {
        return false;
    }
    let Some(expected) = expected_emitter_address else {
        return true;
    };
    match address.len() {
        20 => address == expected.as_slice(),
        21 => address[0] == 0x41 && &address[1..] == expected.as_slice(),
        _ => false,
    }
}

fn sccp_tron_transaction_info_log_matches_source_event(
    log: &[u8],
    source_event_digest: H256,
    expected_emitter_address: Option<[u8; 20]>,
) -> Option<bool> {
    let mut cursor = 0usize;
    let mut address = None::<&[u8]>;
    let mut topics = Vec::<&[u8]>::new();
    let mut data = None::<&[u8]>;
    while cursor < log.len() {
        let key = read_protobuf_varint_at(log, &mut cursor)?;
        let field_number = key >> 3;
        let wire_type = u8::try_from(key & 0x07).ok()?;
        match (field_number, wire_type) {
            (1, 2) if address.is_none() => {
                address = Some(read_protobuf_length_delimited_field(log, &mut cursor)?);
            }
            (1, 2) => return None,
            (2, 2) => {
                if topics.len() >= SCCP_TRON_MAX_TRANSACTION_INFO_LOG_TOPICS {
                    return None;
                }
                let topic = read_protobuf_length_delimited_field(log, &mut cursor)?;
                if topic.len() != 32 {
                    return None;
                }
                topics.push(topic);
            }
            (3, 2) if data.is_none() => {
                data = Some(read_protobuf_length_delimited_field(log, &mut cursor)?);
            }
            (3, 2) => return None,
            (1 | 2 | 3, _) => return None,
            (_, _) => return None,
        }
    }

    let address = address?;
    if !sccp_tron_log_address_matches_expected(address, expected_emitter_address) {
        return None;
    }

    let event_topic = sccp_evm_source_event_topic_v1();
    Some(
        topics.len() == 2
            && topics[0] == event_topic.as_slice()
            && topics[1] == source_event_digest.as_slice()
            && data.unwrap_or_default().is_empty(),
    )
}

fn sccp_tron_transaction_info_value_contains_source_event_digest(
    value: &[u8],
    source_event_digest: H256,
) -> bool {
    sccp_tron_transaction_info_value_contains_source_event(value, source_event_digest, None)
}

fn sccp_tron_transaction_info_value_contains_source_event(
    value: &[u8],
    source_event_digest: H256,
    expected_emitter_address: Option<[u8; 20]>,
) -> bool {
    if value.is_empty() || value.len() > SCCP_TRON_MAX_RECEIPT_VALUE_BYTES {
        return false;
    }

    let mut cursor = 0usize;
    let mut log_count = 0usize;
    let mut matched = false;
    let mut result_seen = false;
    while cursor < value.len() {
        let Some(key) = read_protobuf_varint_at(value, &mut cursor) else {
            return false;
        };
        let field_number = key >> 3;
        let Some(wire_type) = u8::try_from(key & 0x07).ok() else {
            return false;
        };
        match (field_number, wire_type) {
            (8, 2) => {
                log_count = log_count.saturating_add(1);
                if log_count > SCCP_TRON_MAX_TRANSACTION_INFO_LOGS {
                    return false;
                }
                let Some(log) = read_protobuf_length_delimited_field(value, &mut cursor) else {
                    return false;
                };
                let Some(log_matches) = sccp_tron_transaction_info_log_matches_source_event(
                    log,
                    source_event_digest,
                    expected_emitter_address,
                ) else {
                    return false;
                };
                matched |= log_matches;
            }
            (9, 0) => {
                if result_seen {
                    return false;
                }
                result_seen = true;
                let Some(result) = read_protobuf_varint_at(value, &mut cursor) else {
                    return false;
                };
                if result != 0 {
                    return false;
                }
            }
            (_, wire_type) => {
                if skip_protobuf_field(value, &mut cursor, wire_type).is_none() {
                    return false;
                }
            }
        }
    }

    matched && result_seen
}

fn verify_sccp_tron_receipt_mpt_source_value(
    transaction_root: H256,
    receipt_root_index: u64,
    receipt_trie_proof_nodes: &[Vec<u8>],
    receipt_or_message_root: H256,
    source_event_digest: H256,
    material: &SccpSourceVerifierMaterialV1,
) -> bool {
    let receipt_trie_key = rlp_encode_u64(receipt_root_index);
    let Some(value) = verify_sccp_mpt_inclusion(
        transaction_root,
        &receipt_trie_key,
        receipt_trie_proof_nodes,
    ) else {
        return false;
    };
    let expected_emitter_address = if !material.placeholder_material
        && sccp_source_bridge_emitter_binding_required(material.source_domain)
    {
        let Some(address) =
            sccp_source_bridge_emitter_address_as_array(&material.source_bridge_emitter_address)
        else {
            return false;
        };
        if !address20_is_nonzero(&address) {
            return false;
        }
        Some(address)
    } else {
        None
    };

    sccp_tron_transaction_info_value_contains_source_event(
        &value,
        source_event_digest,
        expected_emitter_address,
    ) || (material.placeholder_material
        && sccp_tron_receipt_root_from_mpt_value(&value)
            .is_some_and(|receipt_root| receipt_root == receipt_or_message_root))
}

pub fn canonical_sccp_tron_source_message_call_data(
    source_domain: u32,
    target_domain: u32,
    source_event_digest: H256,
) -> Option<Vec<u8>> {
    if source_domain != SCCP_DOMAIN_TRON
        || target_domain != SCCP_DOMAIN_SORA
        || !h256_is_nonzero(&source_event_digest)
    {
        return None;
    }
    let selector_hash = keccak256_bytes(SCCP_TRON_SOURCE_MESSAGE_CALL_ABI_V1);
    let mut out = Vec::with_capacity(4 + 32 * 3);
    out.extend_from_slice(&selector_hash[..4]);
    out.extend_from_slice(&abi_word_u32(source_domain));
    out.extend_from_slice(&abi_word_u32(target_domain));
    out.extend_from_slice(&source_event_digest);
    Some(out)
}

fn sccp_tron_transaction_merkle_node(left: &H256, right: &H256) -> H256 {
    let mut bytes = Vec::with_capacity(64);
    bytes.extend_from_slice(left);
    bytes.extend_from_slice(right);
    sha256_bytes(&bytes)
}

fn sccp_tron_transaction_merkle_root_from_branch(
    transaction_hash: H256,
    transaction_index: u64,
    transaction_count: u64,
    transaction_merkle_branch: &[Vec<u8>],
) -> Option<H256> {
    if transaction_count == 0
        || transaction_index >= transaction_count
        || transaction_merkle_branch.len() > SCCP_TRON_MAX_TRANSACTION_MERKLE_BRANCH_NODES
        || !transaction_merkle_branch
            .iter()
            .all(|sibling| sibling.len() == 32)
    {
        return None;
    }

    let mut current = transaction_hash;
    let mut index = transaction_index;
    let mut count = transaction_count;
    let mut branch_cursor = 0usize;
    while count > 1 {
        if index & 1 == 0 {
            if index + 1 < count {
                let sibling: H256 = transaction_merkle_branch
                    .get(branch_cursor)?
                    .as_slice()
                    .try_into()
                    .ok()?;
                branch_cursor = branch_cursor.checked_add(1)?;
                current = sccp_tron_transaction_merkle_node(&current, &sibling);
            }
        } else {
            let sibling: H256 = transaction_merkle_branch
                .get(branch_cursor)?
                .as_slice()
                .try_into()
                .ok()?;
            branch_cursor = branch_cursor.checked_add(1)?;
            current = sccp_tron_transaction_merkle_node(&sibling, &current);
        }
        index >>= 1;
        count = count.checked_add(1)?.checked_div(2)?;
    }

    (branch_cursor == transaction_merkle_branch.len()).then_some(current)
}

fn canonical_sccp_tron_transaction_source_proof_bytes_internal(
    source_event_digest: H256,
    receipt_or_message_root: H256,
    transaction_root: H256,
    transaction_index: u64,
    transaction_count: u64,
    transaction_bytes: &[u8],
    transaction_merkle_branch: &[Vec<u8>],
    inclusion_branch: &[Vec<u8>],
    expected_contract_address: Option<[u8; 20]>,
    expected_owner_address: Option<[u8; 20]>,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&source_event_digest)
        || !h256_is_nonzero(&receipt_or_message_root)
        || !h256_is_nonzero(&transaction_root)
        || transaction_count == 0
        || transaction_index >= transaction_count
        || transaction_bytes.is_empty()
        || transaction_bytes.len() > SCCP_TRON_MAX_TRANSACTION_BYTES
        || transaction_merkle_branch.len() > SCCP_TRON_MAX_TRANSACTION_MERKLE_BRANCH_NODES
        || !transaction_merkle_branch
            .iter()
            .all(|sibling| sibling.len() == 32)
        || !h256_merkle_branch_is_nonempty_and_bounded(inclusion_branch)
    {
        return None;
    }
    if expected_contract_address.is_some_and(|address| !address20_is_nonzero(&address))
        || expected_owner_address.is_some_and(|address| !address20_is_nonzero(&address))
    {
        return None;
    }
    if !verify_sccp_tron_transaction_bytes_source_call(
        transaction_bytes,
        SCCP_DOMAIN_TRON,
        SCCP_DOMAIN_SORA,
        source_event_digest,
        expected_contract_address,
        expected_owner_address,
    ) {
        return None;
    }
    if sccp_tron_transaction_merkle_root_from_branch(
        sha256_bytes(transaction_bytes),
        transaction_index,
        transaction_count,
        transaction_merkle_branch,
    )? != transaction_root
    {
        return None;
    }

    let mut out = Vec::new();
    push_u8(&mut out, 1);
    out.extend_from_slice(&source_event_digest);
    out.extend_from_slice(&receipt_or_message_root);
    out.extend_from_slice(&transaction_root);
    push_u64(&mut out, transaction_index);
    push_u64(&mut out, transaction_count);
    push_vec(&mut out, transaction_bytes);
    push_u32(
        &mut out,
        u32::try_from(transaction_merkle_branch.len()).ok()?,
    );
    for sibling in transaction_merkle_branch {
        let sibling: H256 = sibling.as_slice().try_into().ok()?;
        out.extend_from_slice(&sibling);
    }
    push_h256_inclusion_branch(&mut out, inclusion_branch)?;
    Some(out)
}

pub fn canonical_sccp_tron_transaction_source_proof_bytes(
    source_event_digest: H256,
    receipt_or_message_root: H256,
    transaction_root: H256,
    transaction_index: u64,
    transaction_count: u64,
    transaction_bytes: &[u8],
    transaction_merkle_branch: &[Vec<u8>],
    inclusion_branch: &[Vec<u8>],
) -> Option<Vec<u8>> {
    canonical_sccp_tron_transaction_source_proof_bytes_internal(
        source_event_digest,
        receipt_or_message_root,
        transaction_root,
        transaction_index,
        transaction_count,
        transaction_bytes,
        transaction_merkle_branch,
        inclusion_branch,
        None,
        None,
    )
}

