fn sccp_tron_source_bridge_addresses_from_material(
    material: &SccpSourceVerifierMaterialV1,
) -> Option<([u8; 20], [u8; 20])> {
    if material.source_domain != SCCP_DOMAIN_TRON
        || material.placeholder_material
        || !sccp_source_bridge_emitter_binding_is_production_ready(material)
        || !sccp_source_bridge_config_hash_is_production_ready(material)
    {
        return None;
    }
    Some((
        sccp_source_bridge_emitter_address_as_array(&material.source_bridge_emitter_address)?,
        sccp_source_bridge_emitter_address_as_array(&material.source_bridge_owner_address)?,
    ))
}

fn sccp_tron_source_bridge_addresses_from_production_material(
    material: &SccpSourceVerifierMaterialV1,
) -> Option<([u8; 20], [u8; 20])> {
    if !sccp_source_verifier_material_is_production_ready(material) {
        return None;
    }
    sccp_tron_source_bridge_addresses_from_material(material)
}

