fn sccp_solana_message_root_from_branch(
    source_event_digest: H256,
    transaction_signature: &[u8],
    emitter_program_id: &[u8],
    inclusion_branch: &[Vec<u8>],
) -> Option<H256> {
    if !h256_is_nonzero(&source_event_digest)
        || !h256_merkle_branch_is_nonempty_and_bounded(inclusion_branch)
    {
        return None;
    }
    let leaf_hash = sccp_solana_transaction_status_leaf_hash(
        source_event_digest,
        transaction_signature,
        emitter_program_id,
    )?;
    sccp_source_message_root_from_branch(leaf_hash, 0, inclusion_branch)
}

fn sccp_source_message_inclusion_leaf_hash_for_adapter(
    source_event_digest: H256,
    adapter: &SccpSourceAdapterProofV1,
) -> Option<H256> {
    if !h256_is_nonzero(&source_event_digest) {
        return None;
    }
    match adapter {
        SccpSourceAdapterProofV1::SolanaFinalizedTransaction(adapter) => {
            sccp_solana_transaction_status_leaf_hash(
                source_event_digest,
                &adapter.transaction_signature,
                &adapter.emitter_program_id,
            )
        }
        SccpSourceAdapterProofV1::EthereumBeaconReceipt(_)
        | SccpSourceAdapterProofV1::BscValidatorSetReceipt(_)
        | SccpSourceAdapterProofV1::TonMasterchainShard(_)
        | SccpSourceAdapterProofV1::TronDposReceipt(_)
        | SccpSourceAdapterProofV1::SubstrateGrandpaEvent(_) => {
            Some(sccp_source_event_leaf_hash(source_event_digest))
        }
    }
}

fn sccp_solana_message_identity_shape_is_valid(
    transaction_signature: &[u8],
    emitter_program_id: &[u8],
) -> bool {
    transaction_signature.len() == SCCP_SOLANA_TRANSACTION_SIGNATURE_BYTES
        && emitter_program_id.len() == SCCP_SOLANA_PROGRAM_ID_BYTES
        && transaction_signature.iter().copied().any(|byte| byte != 0)
        && emitter_program_id.iter().copied().any(|byte| byte != 0)
}

