pub fn canonical_sccp_solana_vote_roster_bytes(
    validator_public_keys: &[Vec<u8>],
    validator_stakes: &[u64],
) -> Option<Vec<u8>> {
    if validator_public_keys.is_empty()
        || validator_public_keys.len() > SCCP_SOLANA_MAX_VALIDATORS
        || validator_public_keys.len() != validator_stakes.len()
    {
        return None;
    }
    let mut out = Vec::new();
    let mut seen_keys = Vec::<[u8; 32]>::new();
    push_u8(&mut out, 1);
    push_u32(
        &mut out,
        u32::try_from(validator_public_keys.len()).expect("Solana roster length fits u32"),
    );
    for (public_key, stake) in validator_public_keys.iter().zip(validator_stakes.iter()) {
        let public_key: [u8; 32] = public_key.as_slice().try_into().ok()?;
        if *stake == 0
            || !h256_is_nonzero(&public_key)
            || seen_keys.iter().any(|known_key| known_key == &public_key)
        {
            return None;
        }
        seen_keys.push(public_key);
        push_vec(&mut out, &public_key);
        push_u64(&mut out, *stake);
    }
    Some(out)
}

pub fn sccp_solana_vote_roster_hash(
    validator_public_keys: &[Vec<u8>],
    validator_stakes: &[u64],
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_SOLANA_VOTE_ROSTER_PREFIX_V1,
        &canonical_sccp_solana_vote_roster_bytes(validator_public_keys, validator_stakes)?,
    ))
}

