pub fn canonical_sccp_ton_validator_set_bytes(
    validator_public_keys: &[Vec<u8>],
    validator_weights: &[u64],
) -> Option<Vec<u8>> {
    if validator_public_keys.is_empty()
        || validator_public_keys.len() > SCCP_TON_MAX_VALIDATORS
        || validator_public_keys.len() != validator_weights.len()
    {
        return None;
    }

    let mut out = Vec::new();
    let mut seen_keys = Vec::with_capacity(validator_public_keys.len());
    push_u8(&mut out, 1);
    push_u32(
        &mut out,
        u32::try_from(validator_public_keys.len()).expect("TON validator count fits u32"),
    );
    for (public_key, weight) in validator_public_keys.iter().zip(validator_weights.iter()) {
        let public_key: [u8; 32] = public_key.as_slice().try_into().ok()?;
        if public_key.iter().all(|byte| *byte == 0)
            || *weight == 0
            || seen_keys.contains(&public_key)
        {
            return None;
        }
        seen_keys.push(public_key);
        out.extend_from_slice(&public_key);
        push_u64(&mut out, *weight);
    }
    Some(out)
}

pub fn sccp_ton_validator_set_hash(
    validator_public_keys: &[Vec<u8>],
    validator_weights: &[u64],
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_TON_VALIDATOR_SET_PREFIX_V1,
        &canonical_sccp_ton_validator_set_bytes(validator_public_keys, validator_weights)?,
    ))
}

pub fn decode_sccp_ton_validator_set_payload(payload: &[u8]) -> Option<(Vec<[u8; 32]>, Vec<u64>)> {
    let mut cursor = 0usize;
    if *payload.get(cursor)? != 1 {
        return None;
    }
    cursor = cursor.checked_add(1)?;
    let validator_count = usize::try_from(read_le_u32_at(payload, &mut cursor)?).ok()?;
    if validator_count == 0
        || validator_count > SCCP_TON_MAX_VALIDATORS
        || payload.len().checked_sub(cursor)? != validator_count.checked_mul(40)?
    {
        return None;
    }

    let mut validator_public_keys = Vec::<[u8; 32]>::with_capacity(validator_count);
    let mut validator_weights = Vec::<u64>::with_capacity(validator_count);
    for _ in 0..validator_count {
        let key_end = cursor.checked_add(32)?;
        let mut public_key = [0u8; 32];
        public_key.copy_from_slice(payload.get(cursor..key_end)?);
        cursor = key_end;
        if public_key.iter().all(|byte| *byte == 0) {
            return None;
        }
        if validator_public_keys
            .iter()
            .any(|known_key| known_key == &public_key)
        {
            return None;
        }
        let weight = read_le_u64_at(payload, &mut cursor)?;
        if weight == 0 {
            return None;
        }
        validator_public_keys.push(public_key);
        validator_weights.push(weight);
    }

    (cursor == payload.len()).then_some((validator_public_keys, validator_weights))
}

pub fn sccp_ton_validator_set_hash_from_payload(payload: &[u8]) -> Option<H256> {
    decode_sccp_ton_validator_set_payload(payload)?;
    Some(prefixed_blake2b(SCCP_TON_VALIDATOR_SET_PREFIX_V1, payload))
}

pub fn sccp_ton_validator_set_payload_hash(payload: &[u8]) -> H256 {
    prefixed_blake2b(SCCP_TON_VALIDATOR_SET_PAYLOAD_PREFIX_V1, payload)
}

