pub fn canonical_sccp_ton_masterchain_config_proof_bytes(
    proof: &SccpTonMasterchainConfigProofV1,
) -> Option<Vec<u8>> {
    if proof.version != 1
        || proof.source_domain != SCCP_DOMAIN_TON
        || proof.masterchain_seqno == 0
        || proof.config_leaf_index != SCCP_TON_CURRENT_VALIDATOR_SET_CONFIG_PARAM
        || !h256_is_nonzero(&proof.masterchain_block_hash)
        || !h256_is_nonzero(&proof.shard_state_root)
        || !h256_is_nonzero(&proof.config_root)
        || !h256_is_nonzero(&proof.validator_set_hash)
        || !h256_is_nonzero(&proof.validator_set_payload_hash)
        || !h256_is_nonzero(&proof.config_leaf_hash)
        || !h256_is_nonzero(&proof.config_value_hash)
        || proof.config_dictionary_proof_boc.is_empty()
        || !proof.config_inclusion_branch.is_empty()
    {
        return None;
    }
    let config_key = sccp_ton_current_validator_set_config_key();
    let proven_validator_set_payload =
        sccp_ton_config_validator_set_payload_from_proof_boc(&proof.config_dictionary_proof_boc)?;
    if sccp_ton_validator_set_payload_hash(&proven_validator_set_payload)
        != proof.validator_set_payload_hash
        || sccp_ton_validator_set_hash_from_payload(&proven_validator_set_payload)?
            != proof.validator_set_hash
        || proof.config_leaf_hash
            != sccp_ton_masterchain_config_leaf_hash(
                proof.source_domain,
                proof.masterchain_seqno,
                proof.masterchain_block_hash,
                proof.shard_state_root,
                proof.validator_set_hash,
                proof.validator_set_payload_hash,
            )
        || sccp_ton_hashmap_e_proof_root_hash(&proof.config_dictionary_proof_boc)?
            != proof.config_root
        || sccp_ton_hashmap_e_cell_ref_value_hash(
            &proof.config_dictionary_proof_boc,
            &config_key,
            SCCP_TON_CONFIG_PARAM_KEY_BITS,
        )? != proof.config_value_hash
    {
        return None;
    }
    if !h256_merkle_branch_siblings_are_bounded(&proof.config_inclusion_branch) {
        return None;
    }
    let mut out = Vec::new();
    push_ton_masterchain_config_proof(&mut out, proof);
    Some(out)
}

