pub fn canonical_sccp_ton_shard_proof_bytes_with_dictionary(
    source_event_digest: H256,
    masterchain_seqno: u64,
    masterchain_block_hash: H256,
    shard_workchain_id: i32,
    shard_shard: u64,
    shard_seqno: u64,
    shard_block_hash: H256,
    shard_file_hash: H256,
    shard_state_root: H256,
    transaction_root: H256,
    transaction_lt: u64,
    shard_state_proof_boc: &[u8],
    shard_state_dictionary_root: H256,
    shard_state_dictionary_key_bit_len: u16,
    shard_state_dictionary_key: &[u8],
    shard_state_dictionary_proof_boc: &[u8],
    shard_state_leaf_index: u64,
    shard_state_inclusion_branch: &[Vec<u8>],
    inclusion_branch: &[Vec<u8>],
) -> Option<Vec<u8>> {
    let has_dictionary_opening = h256_is_nonzero(&shard_state_dictionary_root)
        || shard_state_dictionary_key_bit_len != 0
        || !shard_state_dictionary_key.is_empty()
        || !shard_state_dictionary_proof_boc.is_empty();
    if !h256_is_nonzero(&source_event_digest)
        || transaction_lt == 0
        || has_dictionary_opening != !shard_state_proof_boc.is_empty()
    {
        return None;
    }
    let mut out = Vec::new();
    push_u8(&mut out, 1);
    out.extend_from_slice(&source_event_digest);
    push_u64(&mut out, masterchain_seqno);
    out.extend_from_slice(&masterchain_block_hash);
    push_i32(&mut out, shard_workchain_id);
    push_u64(&mut out, shard_shard);
    push_u64(&mut out, shard_seqno);
    out.extend_from_slice(&shard_block_hash);
    out.extend_from_slice(&shard_file_hash);
    out.extend_from_slice(&shard_state_root);
    out.extend_from_slice(&transaction_root);
    push_u64(&mut out, transaction_lt);
    if !shard_state_proof_boc.is_empty() {
        push_vec(&mut out, shard_state_proof_boc);
    }
    if has_dictionary_opening {
        if !h256_is_nonzero(&shard_state_dictionary_root)
            || shard_state_dictionary_proof_boc.is_empty()
            || !shard_state_inclusion_branch.is_empty()
            || !ton_hashmap_key_is_canonical(
                shard_state_dictionary_key,
                shard_state_dictionary_key_bit_len,
            )
        {
            return None;
        }
        out.extend_from_slice(&shard_state_dictionary_root);
        push_u16(&mut out, shard_state_dictionary_key_bit_len);
        push_vec(&mut out, shard_state_dictionary_key);
        push_vec(&mut out, shard_state_dictionary_proof_boc);
    }
    push_u64(&mut out, shard_state_leaf_index);
    push_h256_inclusion_branch(&mut out, shard_state_inclusion_branch)?;
    push_h256_inclusion_branch(&mut out, inclusion_branch)?;
    Some(out)
}

