pub fn canonical_sccp_tron_witness_seal_bytes(
    proof: &SccpTronDposWitnessSealProofV1,
) -> Option<Vec<u8>> {
    if !h256_is_nonzero(&proof.solid_block_message_hash)
        || proof
            .signatures
            .iter()
            .any(|signature| !tron_recoverable_signature_slice_is_canonical(signature))
    {
        return None;
    }
    let witness_schedule_hash =
        sccp_tron_witness_schedule_hash(&proof.witness_addresses, &proof.witness_weights)?;
    if !verify_sccp_tron_witness_seal_signatures(proof, witness_schedule_hash) {
        return None;
    }
    let mut out = Vec::new();
    push_tron_witness_seal_proof(&mut out, proof);
    out.extend_from_slice(&witness_schedule_hash);
    Some(out)
}

pub fn sccp_tron_witness_seal_hash(proof: &SccpTronDposWitnessSealProofV1) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_TRON_WITNESS_SEAL_PREFIX_V1,
        &canonical_sccp_tron_witness_seal_bytes(proof)?,
    ))
}

/// Build the canonical TRON witness-schedule transition message preimage.
pub fn canonical_sccp_tron_witness_schedule_transition_message_bytes(
    source_domain: u32,
    from_witness_schedule_epoch: u64,
    to_witness_schedule_epoch: u64,
    transition_block_number: u64,
    transition_block_hash: H256,
    parent_witness_schedule_hash: H256,
    next_witness_schedule_hash: H256,
    next_witness_schedule_payload_hash: H256,
) -> Option<Vec<u8>> {
    if source_domain != SCCP_DOMAIN_TRON
        || from_witness_schedule_epoch.checked_add(1)? != to_witness_schedule_epoch
        || transition_block_number == 0
        || !h256_is_nonzero(&transition_block_hash)
        || !h256_is_nonzero(&parent_witness_schedule_hash)
        || !h256_is_nonzero(&next_witness_schedule_hash)
        || !h256_is_nonzero(&next_witness_schedule_payload_hash)
    {
        return None;
    }
    let mut out = Vec::new();
    push_u8(&mut out, 1);
    push_u32(&mut out, source_domain);
    push_u64(&mut out, from_witness_schedule_epoch);
    push_u64(&mut out, to_witness_schedule_epoch);
    push_u64(&mut out, transition_block_number);
    out.extend_from_slice(&transition_block_hash);
    out.extend_from_slice(&parent_witness_schedule_hash);
    out.extend_from_slice(&next_witness_schedule_hash);
    out.extend_from_slice(&next_witness_schedule_payload_hash);
    Some(out)
}

/// Hash a canonical TRON witness-schedule transition message.
pub fn sccp_tron_witness_schedule_transition_message_hash(
    source_domain: u32,
    from_witness_schedule_epoch: u64,
    to_witness_schedule_epoch: u64,
    transition_block_number: u64,
    transition_block_hash: H256,
    parent_witness_schedule_hash: H256,
    next_witness_schedule_hash: H256,
    next_witness_schedule_payload_hash: H256,
) -> Option<H256> {
    Some(prefixed_keccak(
        SCCP_TRON_WITNESS_SCHEDULE_TRANSITION_MESSAGE_PREFIX_V1,
        &canonical_sccp_tron_witness_schedule_transition_message_bytes(
            source_domain,
            from_witness_schedule_epoch,
            to_witness_schedule_epoch,
            transition_block_number,
            transition_block_hash,
            parent_witness_schedule_hash,
            next_witness_schedule_hash,
            next_witness_schedule_payload_hash,
        )?,
    ))
}

/// Build the canonical TRON witness-schedule transition seal preimage.
pub fn canonical_sccp_tron_witness_schedule_transition_seal_bytes(
    proof: &SccpTronWitnessScheduleTransitionProofV1,
) -> Option<Vec<u8>> {
    if proof.version != 1
        || proof.next_witness_schedule_payload.is_empty()
        || proof.seal_proof.solid_block_message_hash != proof.transition_message_hash
        || proof
            .seal_proof
            .signatures
            .iter()
            .any(|signature| !tron_recoverable_signature_slice_is_canonical(signature))
    {
        return None;
    }
    let parent_witness_schedule_hash = sccp_tron_witness_schedule_hash(
        &proof.seal_proof.witness_addresses,
        &proof.seal_proof.witness_weights,
    )?;
    if parent_witness_schedule_hash != proof.parent_witness_schedule_hash
        || sccp_tron_witness_schedule_payload_hash(&proof.next_witness_schedule_payload)
            != Some(proof.next_witness_schedule_payload_hash)
        || sccp_tron_witness_schedule_hash_from_payload(&proof.next_witness_schedule_payload)?
            != proof.next_witness_schedule_hash
    {
        return None;
    }
    if sccp_tron_witness_schedule_transition_message_hash(
        proof.source_domain,
        proof.from_witness_schedule_epoch,
        proof.to_witness_schedule_epoch,
        proof.transition_block_number,
        proof.transition_block_hash,
        proof.parent_witness_schedule_hash,
        proof.next_witness_schedule_hash,
        proof.next_witness_schedule_payload_hash,
    )? != proof.transition_message_hash
    {
        return None;
    }
    if !verify_sccp_tron_witness_seal_signatures(&proof.seal_proof, parent_witness_schedule_hash) {
        return None;
    }
    let mut out = Vec::new();
    push_u8(&mut out, proof.version);
    push_u32(&mut out, proof.source_domain);
    push_u64(&mut out, proof.from_witness_schedule_epoch);
    push_u64(&mut out, proof.to_witness_schedule_epoch);
    push_u64(&mut out, proof.transition_block_number);
    out.extend_from_slice(&proof.transition_block_hash);
    out.extend_from_slice(&proof.parent_witness_schedule_hash);
    out.extend_from_slice(&proof.next_witness_schedule_hash);
    push_vec(&mut out, &proof.next_witness_schedule_payload);
    out.extend_from_slice(&proof.next_witness_schedule_payload_hash);
    out.extend_from_slice(&proof.transition_message_hash);
    out.extend_from_slice(&parent_witness_schedule_hash);
    push_tron_witness_seal_proof(&mut out, &proof.seal_proof);
    Some(out)
}

/// Hash a canonical TRON witness-schedule transition seal.
pub fn sccp_tron_witness_schedule_transition_seal_hash(
    proof: &SccpTronWitnessScheduleTransitionProofV1,
) -> Option<H256> {
    Some(prefixed_blake2b(
        SCCP_TRON_WITNESS_SCHEDULE_TRANSITION_SEAL_PREFIX_V1,
        &canonical_sccp_tron_witness_schedule_transition_seal_bytes(proof)?,
    ))
}

