    fn high_s_recoverable_signature(signature: &[u8]) -> Vec<u8> {
        let mut out = <[u8; 65]>::try_from(signature).expect("recoverable signature");
        let mut borrow = 0u16;
        for idx in (0..32).rev() {
            let minuend = u16::from(SECP256K1_SCALAR_ORDER_BE[idx]);
            let subtrahend = u16::from(out[32 + idx]) + borrow;
            if minuend >= subtrahend {
                out[32 + idx] = u8::try_from(minuend - subtrahend).expect("byte subtraction");
                borrow = 0;
            } else {
                out[32 + idx] = u8::try_from(minuend + 256 - subtrahend).expect("byte subtraction");
                borrow = 1;
            }
        }
        assert_eq!(borrow, 0);
        out[64] = match out[64] {
            27 => 28,
            28 => 27,
            recovery => recovery,
        };
        assert!(!secp256k1_recoverable_signature_has_low_s(&out));
        out.to_vec()
    }

    fn java_tron_recovery_id_signature(signature: &[u8]) -> Vec<u8> {
        let mut out = <[u8; 65]>::try_from(signature).expect("recoverable signature");
        out[64] = match out[64] {
            0..=3 => out[64],
            27..=30 => out[64] - 27,
            recovery => panic!("unexpected recovery id {recovery}"),
        };
        assert!(tron_recoverable_signature_is_canonical(&out));
        out.to_vec()
    }

    fn switch_tron_adapter_signatures_to_java_tron_recovery_ids(
        adapter: &mut SccpTronDposSourceProofV1,
    ) {
        adapter.solid_block_header_proof.witness_signature =
            java_tron_recovery_id_signature(&adapter.solid_block_header_proof.witness_signature);
        adapter.solid_block_header_proof.parent_witness_signature = java_tron_recovery_id_signature(
            &adapter.solid_block_header_proof.parent_witness_signature,
        );
        for ancestor in &mut adapter.solid_block_ancestor_headers {
            ancestor.witness_signature =
                java_tron_recovery_id_signature(&ancestor.witness_signature);
        }
        for confirmation in &mut adapter.solid_block_confirmation_headers {
            confirmation.witness_signature =
                java_tron_recovery_id_signature(&confirmation.witness_signature);
        }
        for signature in &mut adapter.witness_seal_proof.signatures {
            *signature = java_tron_recovery_id_signature(signature);
        }
        adapter.witness_seal_hash = sccp_tron_witness_seal_hash(&adapter.witness_seal_proof)
            .expect("TRON witness seal hash accepts java-tron recovery ids");
        for transition in &mut adapter.witness_schedule_transition_proofs {
            for signature in &mut transition.seal_proof.signatures {
                *signature = java_tron_recovery_id_signature(signature);
            }
            transition.transition_seal_hash =
                sccp_tron_witness_schedule_transition_seal_hash(transition)
                    .expect("TRON transition seal hash accepts java-tron recovery ids");
        }
    }

