    fn sample_bsc_validator_set_transition_proof(
        parent_signers: &[KeyPair; 4],
        from_validator_epoch: u64,
        to_validator_epoch: u64,
        transition_block_number: u64,
        parent_validator_set_hash: H256,
        next_validator_set_hash: H256,
        next_validator_set_payload: Vec<u8>,
    ) -> SccpBscValidatorSetTransitionProofV1 {
        let (transition_state_root, validator_set_metadata_proof) =
            sample_bsc_validator_set_metadata_proof(&next_validator_set_payload);
        let transition_header_rlp = sample_bsc_parlia_epoch_header_rlp_with_state_root(
            transition_block_number,
            &next_validator_set_payload,
            transition_state_root,
        );
        let transition_block_hash = keccak256_bytes(&transition_header_rlp);
        let next_validator_set_payload_hash =
            sccp_bsc_validator_set_payload_hash(&next_validator_set_payload);
        let validator_set_metadata_proof_hash = validator_set_metadata_proof.metadata_proof_hash;
        let transition_message_hash = sccp_bsc_validator_set_transition_message_hash(
            SCCP_DOMAIN_BSC,
            from_validator_epoch,
            to_validator_epoch,
            transition_block_number,
            transition_block_hash,
            parent_validator_set_hash,
            next_validator_set_hash,
            next_validator_set_payload_hash,
            validator_set_metadata_proof_hash,
        )
        .expect("BSC validator-set transition message hash");
        let signatures = parent_signers[..3]
            .iter()
            .map(|signer| {
                sccp_evm_sign_digest(signer, &transition_message_hash)
                    .expect("BSC validator-set transition signature")
                    .to_vec()
            })
            .collect::<Vec<_>>();
        let seal_proof = SccpBscValidatorSetSealProofV1 {
            version: 1,
            total_power: 4,
            signed_power: 3,
            commit_message_hash: transition_message_hash,
            validator_public_keys: sample_bsc_validator_public_keys(parent_signers),
            validator_powers: vec![1, 1, 1, 1],
            signers_bitmap: vec![0b0000_0111],
            signatures,
        };
        let mut proof = SccpBscValidatorSetTransitionProofV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_BSC,
            from_validator_epoch,
            to_validator_epoch,
            transition_block_number,
            transition_header_rlp,
            transition_block_hash,
            parent_validator_set_hash,
            next_validator_set_hash,
            next_validator_set_payload,
            next_validator_set_payload_hash,
            validator_set_metadata_proof,
            validator_set_metadata_proof_hash,
            transition_message_hash,
            transition_seal_hash: [0u8; 32],
            seal_proof,
        };
        proof.transition_seal_hash =
            sccp_bsc_validator_set_transition_seal_hash(&proof).expect("BSC transition seal hash");
        proof
    }

    fn resign_bsc_validator_set_transition_proof(
        proof: &mut SccpBscValidatorSetTransitionProofV1,
        parent_signers: &[KeyPair; 4],
    ) {
        proof.transition_message_hash = sccp_bsc_validator_set_transition_message_hash(
            proof.source_domain,
            proof.from_validator_epoch,
            proof.to_validator_epoch,
            proof.transition_block_number,
            proof.transition_block_hash,
            proof.parent_validator_set_hash,
            proof.next_validator_set_hash,
            proof.next_validator_set_payload_hash,
            proof.validator_set_metadata_proof_hash,
        )
        .expect("BSC transition message hash");
        proof.seal_proof.commit_message_hash = proof.transition_message_hash;
        proof.seal_proof.signatures = parent_signers[..3]
            .iter()
            .map(|signer| {
                sccp_evm_sign_digest(signer, &proof.transition_message_hash)
                    .expect("BSC transition signature")
                    .to_vec()
            })
            .collect();
        proof.transition_seal_hash =
            sccp_bsc_validator_set_transition_seal_hash(proof).expect("BSC transition seal hash");
    }

    fn sample_eth_rlp_string(value: &[u8]) -> Vec<u8> {
        if value.len() == 1 && value[0] < 0x80 {
            return vec![value[0]];
        }
        let mut out = Vec::new();
        if value.len() < 56 {
            out.push(0x80 + u8::try_from(value.len()).expect("short RLP string length fits u8"));
        } else {
            let len_bytes = sample_minimal_be_usize(value.len());
            out.push(0xb7 + u8::try_from(len_bytes.len()).expect("RLP length-of-length fits u8"));
            out.extend_from_slice(&len_bytes);
        }
        out.extend_from_slice(value);
        out
    }

    fn sample_minimal_be_usize(value: usize) -> Vec<u8> {
        let bytes = value.to_be_bytes();
        bytes
            .iter()
            .skip_while(|byte| **byte == 0)
            .copied()
            .collect::<Vec<_>>()
    }

    fn sample_eth_rlp_u64(value: u64) -> Vec<u8> {
        if value == 0 {
            return sample_eth_rlp_string(&[]);
        }
        let bytes = value.to_be_bytes();
        sample_eth_rlp_string(
            bytes
                .iter()
                .skip_while(|byte| **byte == 0)
                .copied()
                .collect::<Vec<_>>()
                .as_slice(),
        )
    }

    fn sample_eth_rlp_list(fields: &[Vec<u8>]) -> Vec<u8> {
        let payload = fields
            .iter()
            .flat_map(|field| field.iter().copied())
            .collect::<Vec<_>>();
        let mut out = Vec::new();
        if payload.len() < 56 {
            out.push(0xc0 + u8::try_from(payload.len()).expect("short RLP list length fits u8"));
        } else {
            let len_bytes = sample_minimal_be_usize(payload.len());
            out.push(0xf7 + u8::try_from(len_bytes.len()).expect("RLP length-of-length fits u8"));
            out.extend_from_slice(&len_bytes);
        }
        out.extend_from_slice(&payload);
        out
    }

    fn sample_mpt_compact_path(nibbles: &[u8], is_leaf: bool) -> Vec<u8> {
        assert!(nibbles.iter().all(|nibble| *nibble < 16));
        let mut prefixed = Vec::with_capacity(nibbles.len() + 2);
        let flag = if is_leaf { 2 } else { 0 };
        if nibbles.len() % 2 == 1 {
            prefixed.push(flag + 1);
            prefixed.extend_from_slice(nibbles);
        } else {
            prefixed.push(flag);
            prefixed.push(0);
            prefixed.extend_from_slice(nibbles);
        }
        prefixed
            .chunks(2)
            .map(|chunk| (chunk[0] << 4) | chunk[1])
            .collect()
    }

