    fn sample_tron_source_trigger_raw_data(
        contract_address: [u8; 20],
        call_data: &[u8],
    ) -> Vec<u8> {
        let mut trigger = Vec::new();
        let mut owner_address = vec![0x41];
        owner_address.extend_from_slice(&sample_tron_source_bridge_owner_address());
        let mut tron_contract_address = vec![0x41];
        tron_contract_address.extend_from_slice(&contract_address);
        push_protobuf_bytes(&mut trigger, 1, &owner_address);
        push_protobuf_bytes(&mut trigger, 2, &tron_contract_address);
        push_protobuf_bytes(&mut trigger, 4, call_data);

        let mut any = Vec::new();
        push_protobuf_bytes(&mut any, 1, SCCP_TRON_TRIGGER_SMART_CONTRACT_TYPE_URL_V1);
        push_protobuf_bytes(&mut any, 2, &trigger);

        let mut contract = Vec::new();
        push_protobuf_u64(&mut contract, 1, 31);
        push_protobuf_bytes(&mut contract, 2, &any);

        let mut raw_data = Vec::new();
        push_protobuf_bytes(&mut raw_data, 1, &[0x12, 0x34]);
        push_protobuf_u64(&mut raw_data, 3, 12_345);
        push_protobuf_bytes(&mut raw_data, 4, &[0x56; 8]);
        push_protobuf_u64(&mut raw_data, 8, 123_456_789);
        push_protobuf_bytes(&mut raw_data, 11, &contract);
        push_protobuf_u64(&mut raw_data, 14, 123_450_000);
        push_protobuf_u64(&mut raw_data, 18, 50_000_000);
        raw_data
    }

    fn sample_tron_source_trigger_transaction_from_raw_data(
        raw_data: Vec<u8>,
        contract_ret: u64,
        signature: &[u8],
    ) -> Vec<u8> {
        let mut result = Vec::new();
        push_protobuf_u64(&mut result, 2, 0);
        push_protobuf_u64(&mut result, 3, contract_ret);

        let mut transaction = Vec::new();
        push_protobuf_bytes(&mut transaction, 1, &raw_data);
        push_protobuf_bytes(&mut transaction, 2, signature);
        push_protobuf_bytes(&mut transaction, 5, &result);
        transaction
    }

