    fn sample_tron_transaction_signature(raw_data: &[u8]) -> Vec<u8> {
        let raw_data_hash = sha256_bytes(raw_data);
        let signer = sample_tron_transaction_signer();
        let signature =
            sccp_evm_sign_digest(&signer, &raw_data_hash).expect("TRON transaction signature");
        assert!(tron_recoverable_signature_is_canonical(&signature));
        assert!(verify_sccp_tron_transaction_signatures(
            raw_data_hash,
            &[signature.as_slice()],
            sample_tron_source_bridge_owner_address(),
        ));
        signature.to_vec()
    }

    fn sample_tron_transaction_raw_data(transaction: &[u8]) -> Vec<u8> {
        let mut cursor = 0usize;
        let mut raw_data = None::<Vec<u8>>;
        while cursor < transaction.len() {
            let key = read_protobuf_varint_at(transaction, &mut cursor)
                .expect("sample transaction protobuf key");
            let field_number = key >> 3;
            let wire_type = u8::try_from(key & 0x07).expect("sample wire type fits u8");
            match (field_number, wire_type) {
                (1, 2) if raw_data.is_none() => {
                    raw_data = Some(
                        read_protobuf_length_delimited_field(transaction, &mut cursor)
                            .expect("sample transaction raw_data")
                            .to_vec(),
                    );
                }
                (_, wire_type) => {
                    skip_protobuf_field(transaction, &mut cursor, wire_type)
                        .expect("sample transaction field");
                }
            }
        }
        raw_data.expect("sample transaction has raw_data")
    }

