    fn sample_mpt_proof_with_inline_leaf(
        key: &[u8],
        value: &[u8],
    ) -> (H256, Vec<Vec<u8>>, Vec<u8>) {
        let key_nibbles = mpt_nibbles_from_bytes(key);
        assert!(!key_nibbles.is_empty());
        let branch_nibble = usize::from(key_nibbles[0]);
        let compact_path = sample_mpt_compact_path(&key_nibbles[1..], true);
        let leaf_node = sample_eth_rlp_list(&[
            sample_eth_rlp_string(&compact_path),
            sample_eth_rlp_string(value),
        ]);
        assert!(leaf_node.len() < 32);

        let mut branch_fields = Vec::with_capacity(17);
        for nibble in 0..16 {
            if nibble == branch_nibble {
                branch_fields.push(leaf_node.clone());
            } else {
                branch_fields.push(sample_eth_rlp_string(&[]));
            }
        }
        branch_fields.push(sample_eth_rlp_string(&[]));
        let root_node = sample_eth_rlp_list(&branch_fields);
        let root = keccak256_bytes(&root_node);
        (root, vec![root_node], leaf_node)
    }

    #[derive(Clone)]
    struct SampleMptNode {
        raw: Vec<u8>,
        children: Vec<(u8, SampleMptNode)>,
        value: Option<Vec<u8>>,
    }

    fn sample_mpt_child_field(child: &SampleMptNode) -> Vec<u8> {
        if child.raw.len() < 32 {
            child.raw.clone()
        } else {
            sample_eth_rlp_string(&keccak256_bytes(&child.raw))
        }
    }

    fn sample_mpt_build_node(mut entries: Vec<(Vec<u8>, Vec<u8>)>, depth: usize) -> SampleMptNode {
        assert!(!entries.is_empty());
        entries.sort_by(|left, right| left.0.cmp(&right.0));
        if entries.len() == 1 {
            let (nibbles, value) = entries.pop().expect("one MPT entry");
            let compact_path = sample_mpt_compact_path(&nibbles[depth..], true);
            let raw = sample_eth_rlp_list(&[
                sample_eth_rlp_string(&compact_path),
                sample_eth_rlp_string(&value),
            ]);
            return SampleMptNode {
                raw,
                children: Vec::new(),
                value: Some(value),
            };
        }

        let mut common_prefix_len = 0usize;
        'outer: loop {
            let Some(first_nibble) = entries[0].0.get(depth + common_prefix_len).copied() else {
                break;
            };
            for (nibbles, _) in entries.iter().skip(1) {
                if nibbles.get(depth + common_prefix_len).copied() != Some(first_nibble) {
                    break 'outer;
                }
            }
            common_prefix_len += 1;
        }

        if common_prefix_len != 0 {
            let compact_path =
                sample_mpt_compact_path(&entries[0].0[depth..depth + common_prefix_len], false);
            let child = sample_mpt_build_node(entries, depth + common_prefix_len);
            let raw = sample_eth_rlp_list(&[
                sample_eth_rlp_string(&compact_path),
                sample_mpt_child_field(&child),
            ]);
            return SampleMptNode {
                raw,
                children: vec![(u8::MAX, child)],
                value: None,
            };
        }

        let mut branch_groups: Vec<Vec<(Vec<u8>, Vec<u8>)>> = vec![Vec::new(); 16];
        let mut branch_value = None::<Vec<u8>>;
        for (nibbles, value) in entries {
            if depth == nibbles.len() {
                branch_value = Some(value);
                continue;
            }
            let nibble = usize::from(nibbles[depth]);
            branch_groups[nibble].push((nibbles, value));
        }

        let mut children = Vec::<(u8, SampleMptNode)>::new();
        let mut fields = Vec::with_capacity(17);
        for (nibble, group) in branch_groups.into_iter().enumerate() {
            if group.is_empty() {
                fields.push(sample_eth_rlp_string(&[]));
            } else {
                let child = sample_mpt_build_node(group, depth + 1);
                fields.push(sample_mpt_child_field(&child));
                children.push((u8::try_from(nibble).expect("nibble fits u8"), child));
            }
        }
        fields.push(sample_eth_rlp_string(
            branch_value.as_deref().unwrap_or_default(),
        ));
        let raw = sample_eth_rlp_list(&fields);
        SampleMptNode {
            raw,
            children,
            value: branch_value,
        }
    }

    fn sample_mpt_path_proof_nodes(
        node: &SampleMptNode,
        key_nibbles: &[u8],
        depth: usize,
        include_current: bool,
        out: &mut Vec<Vec<u8>>,
    ) -> bool {
        if include_current {
            out.push(node.raw.clone());
        }
        if node.value.is_some() && node.children.is_empty() {
            return true;
        }
        if node.children.len() == 1 && node.children[0].0 == u8::MAX {
            let child = &node.children[0].1;
            let items = rlp_list_items(&node.raw).expect("sample extension node decodes");
            let partial = rlp_item_bytes(items[0])
                .and_then(mpt_decode_compact_path)
                .expect("sample extension path decodes")
                .1;
            let child_is_hashed = child.raw.len() >= 32;
            return sample_mpt_path_proof_nodes(
                child,
                key_nibbles,
                depth + partial.len(),
                child_is_hashed,
                out,
            );
        }
        let Some(next_nibble) = key_nibbles.get(depth).copied() else {
            return node.value.is_some();
        };
        let Some((_, child)) = node
            .children
            .iter()
            .find(|(nibble, _)| *nibble == next_nibble)
        else {
            return false;
        };
        sample_mpt_path_proof_nodes(child, key_nibbles, depth + 1, child.raw.len() >= 32, out)
    }

    fn sample_mpt_proofs_for_entries(
        entries: Vec<(Vec<u8>, Vec<u8>)>,
    ) -> (H256, Vec<(Vec<u8>, Vec<Vec<u8>>)>) {
        let nibble_entries = entries
            .iter()
            .map(|(key, value)| (mpt_nibbles_from_bytes(key), value.clone()))
            .collect::<Vec<_>>();
        let root_node = sample_mpt_build_node(nibble_entries, 0);
        let root = keccak256_bytes(&root_node.raw);
        let proofs = entries
            .into_iter()
            .map(|(key, _)| {
                let mut proof_nodes = Vec::new();
                let found = sample_mpt_path_proof_nodes(
                    &root_node,
                    &mpt_nibbles_from_bytes(&key),
                    0,
                    true,
                    &mut proof_nodes,
                );
                assert!(found, "sample MPT proof path exists");
                (key, proof_nodes)
            })
            .collect();
        (root, proofs)
    }

