    fn sample_bsc_validator_set_metadata_proof(
        next_validator_set_payload: &[u8],
    ) -> (H256, SccpBscValidatorSetMetadataProofV1) {
        let (validator_addresses, validator_powers) =
            decode_sccp_bsc_validator_set_payload(next_validator_set_payload)
                .expect("BSC validator payload decodes");
        assert!(validator_powers.iter().all(|power| *power == 1));

        let length_slot = sccp_bsc_validator_set_length_slot();
        let length_value = sample_evm_storage_value_from_word(evm_u256_from_u64(
            u64::try_from(validator_addresses.len()).expect("validator count fits u64"),
        ));
        let mut storage_entries = vec![(
            evm_storage_trie_key(length_slot).to_vec(),
            length_value.clone(),
        )];
        let mut storage_slots = Vec::with_capacity(validator_addresses.len());
        let mut storage_values = Vec::with_capacity(validator_addresses.len());
        for (idx, address) in validator_addresses.iter().enumerate() {
            let storage_slot = sccp_bsc_current_validator_consensus_address_slot(
                u32::try_from(idx).expect("validator index fits u32"),
            )
            .expect("BSC validator storage slot");
            let mut word = [0u8; 32];
            word[12..].copy_from_slice(address);
            let storage_value = sample_evm_storage_value_from_word(word);
            storage_entries.push((
                evm_storage_trie_key(storage_slot).to_vec(),
                storage_value.clone(),
            ));
            storage_slots.push(storage_slot);
            storage_values.push(storage_value);
        }
        let (storage_root, storage_proofs) = sample_mpt_proofs_for_entries(storage_entries);
        let length_key = evm_storage_trie_key(length_slot).to_vec();
        let (_, length_proof_nodes) = storage_proofs
            .iter()
            .find(|(key, _)| key == &length_key)
            .expect("length proof exists")
            .clone();

        let validator_storage_proofs = storage_slots
            .into_iter()
            .zip(storage_values)
            .enumerate()
            .map(|(idx, (storage_slot, storage_value))| {
                let storage_key = evm_storage_trie_key(storage_slot).to_vec();
                let (_, storage_proof_nodes) = storage_proofs
                    .iter()
                    .find(|(key, _)| key == &storage_key)
                    .expect("validator storage proof exists")
                    .clone();
                SccpBscValidatorStorageProofV1 {
                    version: 1,
                    validator_index: u32::try_from(idx).expect("validator index fits u32"),
                    storage_slot,
                    storage_value_hash: sccp_bsc_validator_set_storage_value_hash(&storage_value),
                    storage_value,
                    storage_proof_nodes,
                }
            })
            .collect::<Vec<_>>();

        let account_value = sample_bsc_validator_set_account_value(storage_root);
        let (state_root, account_proofs) = sample_mpt_proofs_for_entries(vec![(
            keccak256_bytes(&SCCP_BSC_VALIDATOR_SET_CONTRACT_ADDRESS).to_vec(),
            account_value,
        )]);
        let account_proof_nodes = account_proofs
            .into_iter()
            .next()
            .expect("account proof exists")
            .1;
        let next_validator_set_payload_hash =
            sccp_bsc_validator_set_payload_hash(next_validator_set_payload);
        let mut proof = SccpBscValidatorSetMetadataProofV1 {
            version: 1,
            validator_contract_address: SCCP_BSC_VALIDATOR_SET_CONTRACT_ADDRESS.to_vec(),
            account_proof_nodes,
            storage_root,
            validator_set_length_slot: length_slot,
            validator_set_length_value_hash: sccp_bsc_validator_set_storage_value_hash(
                &length_value,
            ),
            validator_set_length_value: length_value,
            validator_set_length_proof_nodes: length_proof_nodes,
            validator_storage_proofs,
            metadata_proof_hash: [0u8; 32],
        };
        proof.metadata_proof_hash = sccp_bsc_validator_set_metadata_proof_hash(
            state_root,
            next_validator_set_payload_hash,
            &proof,
        )
        .expect("BSC validator metadata proof hash");
        (state_root, proof)
    }

