    fn sample_eth_beacon_header_witness(
        beacon_slot: u64,
        execution_header_rlp: &[u8],
    ) -> (u64, H256, H256, H256, Vec<Vec<u8>>, H256) {
        let execution_payload_header_root =
            sccp_eth_execution_payload_header_root_from_rlp(execution_header_rlp)
                .expect("ETH execution payload header SSZ root");
        let execution_payload_branch = vec![
            vec![0x21; 32],
            vec![0x22; 32],
            vec![0x23; 32],
            vec![0x24; 32],
        ];
        let beacon_body_root = sccp_eth_beacon_body_root_from_execution_payload_branch(
            execution_payload_header_root,
            &execution_payload_branch,
        )
        .expect("ETH beacon body root from execution payload branch");
        let beacon_proposer_index = 17;
        let beacon_parent_root = [0x25; 32];
        let beacon_state_root = [0x26; 32];
        let beacon_finalized_root = sccp_eth_beacon_block_header_root(
            beacon_slot,
            beacon_proposer_index,
            beacon_parent_root,
            beacon_state_root,
            beacon_body_root,
        );
        (
            beacon_proposer_index,
            beacon_parent_root,
            beacon_state_root,
            beacon_body_root,
            execution_payload_branch,
            beacon_finalized_root,
        )
    }

