    fn sample_ton_masterchain_config_proof(
        source_domain: u32,
        masterchain_seqno: u64,
        masterchain_block_hash: H256,
        shard_state_root: H256,
        validator_set_hash: H256,
        validator_set_payload: &[u8],
    ) -> SccpTonMasterchainConfigProofV1 {
        let validator_set_payload_hash = sccp_ton_validator_set_payload_hash(validator_set_payload);
        let config_leaf_hash = sccp_ton_masterchain_config_leaf_hash(
            source_domain,
            masterchain_seqno,
            masterchain_block_hash,
            shard_state_root,
            validator_set_hash,
            validator_set_payload_hash,
        );
        let config_dictionary_proof_boc = test_ton_config_dictionary_boc(validator_set_payload);
        let config_root = sccp_ton_hashmap_e_proof_root_hash(&config_dictionary_proof_boc)
            .expect("TON config proof root");
        let config_key = sccp_ton_current_validator_set_config_key();
        let config_value_hash = sccp_ton_hashmap_e_cell_ref_value_hash(
            &config_dictionary_proof_boc,
            &config_key,
            SCCP_TON_CONFIG_PARAM_KEY_BITS,
        )
        .expect("TON config value hash");
        SccpTonMasterchainConfigProofV1 {
            version: 1,
            source_domain,
            masterchain_seqno,
            masterchain_block_hash,
            shard_state_root,
            config_root,
            validator_set_hash,
            validator_set_payload_hash,
            config_leaf_hash,
            config_leaf_index: SCCP_TON_CURRENT_VALIDATOR_SET_CONFIG_PARAM,
            config_value_hash,
            config_dictionary_proof_boc,
            config_inclusion_branch: Vec::new(),
        }
    }

    fn sample_ton_validator_set_transition_proof(
        parent_signers: &[KeyPair; 4],
        from_validator_set_seqno: u64,
        to_validator_set_seqno: u64,
        masterchain_seqno: u64,
        masterchain_block_hash: H256,
        parent_validator_set_hash: H256,
        next_validator_set_payload: Vec<u8>,
        next_validator_set_config_hash: H256,
    ) -> SccpTonValidatorSetTransitionProofV1 {
        let next_validator_set_hash =
            sccp_ton_validator_set_hash_from_payload(&next_validator_set_payload)
                .expect("TON next validator set hash");
        let next_validator_set_payload_hash =
            sccp_ton_validator_set_payload_hash(&next_validator_set_payload);
        let transition_message_hash = sccp_ton_validator_set_transition_message_hash(
            SCCP_DOMAIN_TON,
            from_validator_set_seqno,
            to_validator_set_seqno,
            masterchain_seqno,
            SCCP_TON_MASTERCHAIN_WORKCHAIN_ID,
            SCCP_TON_MASTERCHAIN_SHARD,
            masterchain_block_hash,
            [0xA5; 32],
            parent_validator_set_hash,
            next_validator_set_hash,
            next_validator_set_payload_hash,
            next_validator_set_config_hash,
        );
        let validator_signature_proof =
            sample_ton_validator_signature_proof_for(parent_signers, transition_message_hash);
        let mut proof = SccpTonValidatorSetTransitionProofV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_TON,
            from_validator_set_seqno,
            to_validator_set_seqno,
            masterchain_seqno,
            masterchain_workchain_id: SCCP_TON_MASTERCHAIN_WORKCHAIN_ID,
            masterchain_shard: SCCP_TON_MASTERCHAIN_SHARD,
            masterchain_block_hash,
            masterchain_file_hash: [0xA5; 32],
            parent_validator_set_hash,
            next_validator_set_hash,
            next_validator_set_payload,
            next_validator_set_payload_hash,
            next_validator_set_config_hash,
            transition_message_hash,
            transition_signature_hash: [0u8; 32],
            validator_signature_proof,
        };
        proof.transition_signature_hash =
            sccp_ton_validator_set_transition_signature_hash(&proof).unwrap_or([0u8; 32]);
        proof
    }

