    fn sample_tron_witness_schedule_transition_proof(
        parent_signers: &[KeyPair; 4],
        next_witness_schedule_hash: H256,
        next_witness_schedule_payload: Vec<u8>,
        from_witness_schedule_epoch: u64,
        to_witness_schedule_epoch: u64,
        transition_block_number: u64,
        transition_block_hash: H256,
    ) -> SccpTronWitnessScheduleTransitionProofV1 {
        let parent_witness_schedule_hash = sample_tron_witness_schedule_hash_for(parent_signers);
        let next_witness_schedule_payload_hash =
            sccp_tron_witness_schedule_payload_hash(&next_witness_schedule_payload)
                .expect("TRON next witness-schedule payload hash");
        let transition_message_hash = sccp_tron_witness_schedule_transition_message_hash(
            SCCP_DOMAIN_TRON,
            from_witness_schedule_epoch,
            to_witness_schedule_epoch,
            transition_block_number,
            transition_block_hash,
            parent_witness_schedule_hash,
            next_witness_schedule_hash,
            next_witness_schedule_payload_hash,
        )
        .expect("TRON witness-schedule transition message hash");
        let signatures = parent_signers[..3]
            .iter()
            .map(|signer| {
                sccp_evm_sign_digest(signer, &transition_message_hash)
                    .expect("TRON witness-schedule transition signature")
                    .to_vec()
            })
            .collect::<Vec<_>>();
        let mut proof = SccpTronWitnessScheduleTransitionProofV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_TRON,
            from_witness_schedule_epoch,
            to_witness_schedule_epoch,
            transition_block_number,
            transition_block_hash,
            parent_witness_schedule_hash,
            next_witness_schedule_hash,
            next_witness_schedule_payload,
            next_witness_schedule_payload_hash,
            transition_message_hash,
            transition_seal_hash: [0u8; 32],
            seal_proof: SccpTronDposWitnessSealProofV1 {
                version: 1,
                total_weight: 4,
                signed_weight: 3,
                solid_block_message_hash: transition_message_hash,
                witness_addresses: sample_tron_witness_addresses(parent_signers),
                witness_weights: vec![1, 1, 1, 1],
                signers_bitmap: vec![0b0000_0111],
                signatures,
            },
        };
        proof.transition_seal_hash = sccp_tron_witness_schedule_transition_seal_hash(&proof)
            .expect("TRON witness-schedule transition seal hash");
        proof
    }

