    fn sample_solana_validator_vote_account_data(
        finalized_slot: u64,
    ) -> Vec<SccpSolanaVoteAccountDataV1> {
        let tower_vote_slots = sample_solana_tower_vote_slots(finalized_slot);
        let rooted_slot = sample_solana_rooted_slot(finalized_slot);
        let vote_account_addresses = sample_solana_validator_vote_account_addresses();
        sample_solana_validator_public_keys()
            .into_iter()
            .enumerate()
            .map(|(index, authorized_voter)| SccpSolanaVoteAccountDataV1 {
                node_pubkey: vec![0x51 + index as u8; 32],
                authorized_voter,
                authorized_withdrawer: vec![0x61 + index as u8; 32],
                inflation_rewards_collector: vote_account_addresses[index].clone(),
                block_revenue_collector: vec![0x51 + index as u8; 32],
                inflation_rewards_commission_bps: u16::try_from(index * 100)
                    .expect("sample index fits u16"),
                block_revenue_commission_bps: SCCP_SOLANA_COMMISSION_BPS_MAX,
                pending_delegator_rewards: 0,
                bls_pubkey_compressed: Vec::new(),
                root_slot: rooted_slot,
                tower_vote_slots: tower_vote_slots.clone(),
            })
            .collect()
    }

    fn sample_solana_vote_state_account_raw_data(
        data: &SccpSolanaVoteAccountDataV1,
        epoch: u64,
    ) -> Vec<u8> {
        let mut raw = Vec::new();
        raw.extend_from_slice(&SCCP_SOLANA_VOTE_STATE_V3_DISCRIMINANT.to_le_bytes());
        raw.extend_from_slice(&data.node_pubkey);
        raw.extend_from_slice(&data.authorized_withdrawer);
        raw.push(
            u8::try_from(data.inflation_rewards_commission_bps / 100)
                .expect("sample legacy commission fits u8"),
        );
        raw.extend_from_slice(&SCCP_SOLANA_TOWER_VOTE_STACK_DEPTH.to_le_bytes());
        for (index, slot) in data.tower_vote_slots.iter().enumerate() {
            raw.push(0);
            raw.extend_from_slice(&slot.to_le_bytes());
            let confirmation =
                u32::try_from(data.tower_vote_slots.len() - index).expect("confirmation fits u32");
            raw.extend_from_slice(&confirmation.to_le_bytes());
        }
        raw.push(1);
        raw.extend_from_slice(&data.root_slot.to_le_bytes());
        raw.extend_from_slice(&1u64.to_le_bytes());
        raw.extend_from_slice(&epoch.to_le_bytes());
        raw.extend_from_slice(&data.authorized_voter);
        raw.resize(SCCP_SOLANA_VOTE_STATE_ACCOUNT_DATA_LEN, 0);
        raw
    }

    fn sample_solana_validator_vote_account_raw_data(finalized_slot: u64) -> Vec<Vec<u8>> {
        let epoch = sccp_solana_mainnet_epoch_for_slot(finalized_slot);
        sample_solana_validator_vote_account_data(finalized_slot)
            .iter()
            .map(|data| sample_solana_vote_state_account_raw_data(data, epoch))
            .collect()
    }

