    fn sample_solana_stake_state_v2_raw_data(data: &SccpSolanaStakeAccountDataV1) -> Vec<u8> {
        let mut raw = vec![0u8; SCCP_SOLANA_STAKE_STATE_V2_STAKE_ACCOUNT_DATA_LEN];
        raw[0..4].copy_from_slice(&SCCP_SOLANA_STAKE_STATE_V2_STAKE_DISCRIMINANT.to_le_bytes());
        raw[SCCP_SOLANA_STAKE_STATE_V2_STAKER_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_STAKER_OFFSET + 32)]
            .copy_from_slice(&data.staker);
        raw[SCCP_SOLANA_STAKE_STATE_V2_WITHDRAWER_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_WITHDRAWER_OFFSET + 32)]
            .copy_from_slice(&data.withdrawer);
        raw[SCCP_SOLANA_STAKE_STATE_V2_VOTER_PUBKEY_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_VOTER_PUBKEY_OFFSET + 32)]
            .copy_from_slice(&data.voter_pubkey);
        raw[SCCP_SOLANA_STAKE_STATE_V2_DELEGATED_STAKE_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_DELEGATED_STAKE_OFFSET + 8)]
            .copy_from_slice(&data.delegated_stake.to_le_bytes());
        raw[SCCP_SOLANA_STAKE_STATE_V2_ACTIVATION_EPOCH_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_ACTIVATION_EPOCH_OFFSET + 8)]
            .copy_from_slice(&data.activation_epoch.to_le_bytes());
        raw[SCCP_SOLANA_STAKE_STATE_V2_DEACTIVATION_EPOCH_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_DEACTIVATION_EPOCH_OFFSET + 8)]
            .copy_from_slice(&data.deactivation_epoch.to_le_bytes());
        raw[SCCP_SOLANA_STAKE_STATE_V2_WARMUP_COOLDOWN_RATE_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_WARMUP_COOLDOWN_RATE_OFFSET
                + SCCP_SOLANA_STAKE_STATE_V2_WARMUP_COOLDOWN_RATE_BYTES)]
            .copy_from_slice(&data.warmup_cooldown_rate_bytes);
        raw[SCCP_SOLANA_STAKE_STATE_V2_CREDITS_OBSERVED_OFFSET
            ..(SCCP_SOLANA_STAKE_STATE_V2_CREDITS_OBSERVED_OFFSET + 8)]
            .copy_from_slice(&data.credits_observed.to_le_bytes());
        raw[SCCP_SOLANA_STAKE_STATE_V2_FLAG_OFFSET] = data.stake_flags;
        raw
    }

