    fn test_ton_shard_state_proof_boc_with_accounts_and_shard_identity_and_metadata(
        dictionary_boc: &[u8],
        global_id: i32,
        workchain_id: i32,
        shard_pfx_bits: u8,
        shard_prefix: u64,
        seq_no: u32,
        gen_utime: u32,
        gen_lt: u64,
        min_ref_mc_seqno: u32,
    ) -> Vec<u8> {
        assert!(shard_pfx_bits <= 60);
        let dictionary = parse_ton_boc_complete_ordinary(dictionary_boc).expect("dictionary BoC");
        assert_eq!(dictionary.roots, vec![0]);

        let mut root_bits = Vec::new();
        test_push_uint_bits(&mut root_bits, 0x9023_afe2, 32);
        test_push_uint_bits(
            &mut root_bits,
            u128::from(u32::from_be_bytes(global_id.to_be_bytes())),
            32,
        );
        test_push_uint_bits(&mut root_bits, 0, 2);
        test_push_uint_bits(&mut root_bits, u128::from(shard_pfx_bits), 6);
        test_push_uint_bits(
            &mut root_bits,
            u128::from(u32::from_be_bytes(workchain_id.to_be_bytes())),
            32,
        );
        test_push_uint_bits(&mut root_bits, u128::from(shard_prefix), 64);
        test_push_uint_bits(&mut root_bits, u128::from(seq_no), 32);
        test_push_uint_bits(&mut root_bits, 1, 32);
        test_push_uint_bits(&mut root_bits, u128::from(gen_utime), 32);
        test_push_uint_bits(&mut root_bits, u128::from(gen_lt), 64);
        test_push_uint_bits(&mut root_bits, u128::from(min_ref_mc_seqno), 32);
        test_push_uint_bits(&mut root_bits, 0, 1);
        test_push_uint_bits(&mut root_bits, 0, 1);
        let (root_data, root_data_descriptor) = test_bits_to_ton_data(&root_bits);

        let dictionary_offset = 2usize;
        let trailing_ref_index = dictionary_offset + dictionary.cells.len();
        let mut cells = vec![
            TestTonRawCell {
                descriptor: 3,
                data_descriptor: root_data_descriptor,
                data: root_data,
                refs: vec![1, dictionary_offset, trailing_ref_index],
            },
            TestTonRawCell {
                descriptor: 0,
                data_descriptor: 0,
                data: Vec::new(),
                refs: Vec::new(),
            },
        ];
        for cell in dictionary.cells {
            cells.push(TestTonRawCell {
                descriptor: cell.descriptor,
                data_descriptor: cell.data_descriptor,
                data: cell.data,
                refs: cell
                    .refs
                    .into_iter()
                    .map(|ref_index| ref_index + dictionary_offset)
                    .collect(),
            });
        }
        cells.push(TestTonRawCell {
            descriptor: 0,
            data_descriptor: 0,
            data: Vec::new(),
            refs: Vec::new(),
        });
        test_encode_ton_boc_single_root_raw(&cells, 0)
    }

    fn test_ton_shard_state_proof_boc_with_accounts(dictionary_boc: &[u8]) -> Vec<u8> {
        test_ton_shard_state_proof_boc_with_accounts_and_shard_prefix(dictionary_boc, 0, 0)
    }

    fn test_ton_shard_accounts_dictionary_boc(
        key: &[u8; 32],
        last_transaction_hash: H256,
        last_transaction_lt: u64,
    ) -> Vec<u8> {
        let mut root_bits = Vec::new();
        test_push_uint_bits(&mut root_bits, 1, 1);
        let (root_data, root_data_descriptor) = test_bits_to_ton_data(&root_bits);

        let mut edge_bits = Vec::new();
        test_push_uint_bits(&mut edge_bits, 0, 1);
        for _ in 0..usize::from(SCCP_TON_SHARD_ACCOUNT_KEY_BITS) {
            test_push_uint_bits(&mut edge_bits, 1, 1);
        }
        test_push_uint_bits(&mut edge_bits, 0, 1);
        test_push_bytes_bits(&mut edge_bits, key);

        test_push_uint_bits(&mut edge_bits, 0, 5);
        test_push_uint_bits(&mut edge_bits, 0, 4);
        test_push_uint_bits(&mut edge_bits, 0, 1);

        test_push_bytes_bits(&mut edge_bits, &last_transaction_hash);
        test_push_uint_bits(&mut edge_bits, u128::from(last_transaction_lt), 64);
        let (edge_data, edge_data_descriptor) = test_bits_to_ton_data(&edge_bits);

        test_encode_ton_boc_single_root_raw(
            &[
                TestTonRawCell {
                    descriptor: 1,
                    data_descriptor: root_data_descriptor,
                    data: root_data,
                    refs: vec![1],
                },
                TestTonRawCell {
                    descriptor: 1,
                    data_descriptor: edge_data_descriptor,
                    data: edge_data,
                    refs: vec![2],
                },
                TestTonRawCell {
                    descriptor: 0,
                    data_descriptor: 0,
                    data: Vec::new(),
                    refs: Vec::new(),
                },
            ],
            0,
        )
    }

    fn test_ton_config_dictionary_boc(validator_set_payload: &[u8]) -> Vec<u8> {
        let (public_keys, weights) = decode_sccp_ton_validator_set_payload(validator_set_payload)
            .expect("canonical TON validator-set payload");
        let entries = public_keys
            .into_iter()
            .zip(weights)
            .enumerate()
            .map(|(index, (public_key, weight))| {
                (
                    u16::try_from(index).expect("TON test validator index fits u16"),
                    public_key,
                    weight,
                )
            })
            .collect::<Vec<_>>();

        let mut root_bits = Vec::new();
        test_push_uint_bits(&mut root_bits, 1, 1);
        let (root_data, root_data_descriptor) = test_bits_to_ton_data(&root_bits);

        let config_key = sccp_ton_current_validator_set_config_key();
        let mut edge_bits = Vec::new();
        test_push_uint_bits(&mut edge_bits, 0, 1);
        for _ in 0..usize::from(SCCP_TON_CONFIG_PARAM_KEY_BITS) {
            test_push_uint_bits(&mut edge_bits, 1, 1);
        }
        test_push_uint_bits(&mut edge_bits, 0, 1);
        test_push_bytes_bits(&mut edge_bits, &config_key);
        let (edge_data, edge_data_descriptor) = test_bits_to_ton_data(&edge_bits);

        let mut value_bits = Vec::new();
        test_push_uint_bits(
            &mut value_bits,
            SCCP_TON_VALIDATORS_EXT_CONSTRUCTOR as u128,
            8,
        );
        test_push_uint_bits(&mut value_bits, 1, 32);
        test_push_uint_bits(&mut value_bits, 2, 32);
        test_push_uint_bits(
            &mut value_bits,
            u128::try_from(entries.len()).expect("entry count fits u128"),
            16,
        );
        test_push_uint_bits(
            &mut value_bits,
            u128::try_from(entries.len()).expect("entry count fits u128"),
            16,
        );
        let total_weight = entries
            .iter()
            .fold(0u64, |sum, (_, _, weight)| sum + *weight);
        test_push_uint_bits(&mut value_bits, u128::from(total_weight), 64);
        test_push_uint_bits(&mut value_bits, 1, 1);
        let (value_data, value_data_descriptor) = test_bits_to_ton_data(&value_bits);

        let mut cells = vec![
            TestTonRawCell {
                descriptor: 1,
                data_descriptor: root_data_descriptor,
                data: root_data,
                refs: vec![1],
            },
            TestTonRawCell {
                descriptor: 1,
                data_descriptor: edge_data_descriptor,
                data: edge_data,
                refs: vec![2],
            },
            TestTonRawCell {
                descriptor: 1,
                data_descriptor: value_data_descriptor,
                data: value_data,
                refs: vec![3],
            },
        ];
        let list_root = test_push_ton_validator_hashmap_cell(&mut cells, &entries, 0);
        assert_eq!(list_root, 3);
        test_encode_ton_boc_single_root_raw(&cells, 0)
    }

