    #[test]
    fn groth16_bn254_public_signal_words_match_destination_verifier_formula() {
        let public_inputs = SccpMessageTransparentPublicInputsV1 {
            version: 1,
            message_id: [0x11; 32],
            payload_hash: [0x22; 32],
            target_domain: SCCP_DOMAIN_TRON,
            commitment_root: [0x33; 32],
            finality_height: 19,
            finality_block_hash: [0x44; 32],
        };
        let signals = sccp_groth16_bn254_public_signal_words(
            &public_inputs,
            SCCP_DOMAIN_SORA,
            [0x55; 32],
            [0x66; 32],
        );
        let expected = [
            "0ffdbc782e79d1dc508e08af01e87f16d93b6e58e4861a0b8155455e3ee7a683",
            "0c5398ea95021a790e276e3ece1592b32b85751dc77e50293c867a5f2e0131bb",
            "21aac4195d8db839756f61c0780675823e15456c92acf135c36e02367c8fd11f",
            "01c73f2f9156a52493a9beabeec73e62deed32fcef2e3e6fac86a79f0764f0bc",
            "0ca6bbc36d23183d027c8df09f06c39e64abbb0bb4d6a4c37369d2c36f41a888",
            "2b153d0fe1bc6e2a6d44e851523edb1511dac55443ca80c22cbe9cb7423886dc",
            "2697e4e42f34b673b4aa254c6a92de09304e84c1a667c7d266777775a231efb4",
            "16fbe0c1d659f142b3e7815b24df66da3cfd89cc42d051b04bc31aae6925c396",
            "1157cd422e2089145c9cf93794dd6a0a1c3b1a611c22a5fe999d0542f62535d8",
        ]
        .map(test_h256_from_hex);

        assert_eq!(signals, expected);
        assert!(
            signals
                .iter()
                .all(|signal| !h256_be_ge(signal, &SCCP_GROTH16_BN254_SCALAR_FIELD_MODULUS_BE))
        );

        let changed_destination = sccp_groth16_bn254_public_signal_words(
            &public_inputs,
            SCCP_DOMAIN_SORA,
            [0x55; 32],
            [0x67; 32],
        );
        assert_eq!(&signals[..8], &changed_destination[..8]);
        assert_ne!(signals[8], changed_destination[8]);

        let changed_statement = sccp_groth16_bn254_public_signal_words(
            &public_inputs,
            SCCP_DOMAIN_SORA,
            [0x56; 32],
            [0x66; 32],
        );
        assert_eq!(&signals[..7], &changed_statement[..7]);
        assert_ne!(signals[7], changed_statement[7]);
        assert_eq!(signals[8], changed_statement[8]);
    }

