    #[cfg(feature = "bls")]
    fn signed_nexus_finality_proof(commitment_root: H256) -> NexusBridgeFinalityProofV1 {
        let keypairs = [
            iroha_crypto::KeyPair::from_seed(vec![1; 32], Algorithm::BlsNormal),
            iroha_crypto::KeyPair::from_seed(vec![2; 32], Algorithm::BlsNormal),
            iroha_crypto::KeyPair::from_seed(vec![3; 32], Algorithm::BlsNormal),
        ];
        let chain_id = "00000000-0000-0000-0000-000000000753".to_owned();
        let mut commit_qc = NexusCommitQcV1 {
            version: 1,
            phase: NexusConsensusPhaseV1::Commit,
            height: 7,
            view: 2,
            epoch: 1,
            mode_tag: "iroha2-consensus::permissioned-sumeragi@v1".to_owned(),
            subject_block_hash: [7u8; 32],
            parent_state_root: [0xA1; 32],
            post_state_root: [0xA2; 32],
            chain_order_hash: [0xA3; 32],
            rechain_seq: 4,
            highest_qc: Some(NexusQcRefV1 {
                height: 6,
                view: 1,
                epoch: 1,
                subject_block_hash: [6u8; 32],
                phase: NexusConsensusPhaseV1::Prepare,
            }),
            validator_set_hash_version: 1,
            validator_public_keys: keypairs
                .iter()
                .map(|keypair| keypair.public_key().to_string())
                .collect(),
            validator_set_pops: keypairs
                .iter()
                .map(|keypair| {
                    iroha_crypto::bls_normal_pop_prove(keypair.private_key()).expect("BLS PoP")
                })
                .collect(),
            signers_bitmap: vec![0b0000_0111],
            bls_aggregate_signature: Vec::new(),
        };
        let message = nexus_commit_vote_preimage(&chain_id, &commit_qc);
        let signatures = keypairs
            .iter()
            .map(|keypair| iroha_crypto::Signature::new(keypair.private_key(), &message))
            .collect::<Vec<_>>();
        let signature_refs = signatures
            .iter()
            .map(|signature| signature.payload().as_ref())
            .collect::<Vec<_>>();
        commit_qc.bls_aggregate_signature =
            iroha_crypto::bls_normal_aggregate_signatures(&signature_refs)
                .expect("aggregate BLS signatures");
        NexusBridgeFinalityProofV1 {
            version: 1,
            chain_id,
            height: 7,
            block_hash: [7u8; 32],
            commitment_root,
            block_header_bytes: vec![0x42; 4],
            commit_qc,
        }
    }

    fn sample_source_chain_proof_envelope(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
    ) -> SccpSourceChainProofEnvelopeV1 {
        sample_source_chain_proof_envelope_with_material(payload, commitment, commitment_root, None)
    }

    fn sample_source_chain_proof_envelope_with_material(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
    ) -> SccpSourceChainProofEnvelopeV1 {
        sample_source_chain_proof_envelope_with_material_and_deployment(
            payload,
            commitment,
            commitment_root,
            source_material,
            None,
        )
    }

    fn sample_source_chain_proof_envelope_with_material_and_deployment(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
        source_deployment: Option<&SccpSourceAdapterEngineDeploymentV1>,
    ) -> SccpSourceChainProofEnvelopeV1 {
        let source_domain = sccp_message_source_domain(payload);
        let target_domain = sccp_message_target_domain(payload);
        assert_ne!(
            source_domain, SCCP_DOMAIN_SORA,
            "SORA-origin messages use the Nexus bridge finality proof format"
        );
        let source_chain = sccp_chain_key_for_domain(source_domain)
            .expect("source domain chain key")
            .to_owned();
        let source_proof_plan =
            sccp_source_proof_plan_for_domain(source_domain).expect("source proof plan");
        let finality_model =
            sccp_proof_finality_model_for_domain(source_domain).expect("source finality model");
        let message_id = commitment.message_id;
        let payload_hash = commitment.payload_hash;
        let source_event_digest =
            sccp_source_event_digest(source_domain, target_domain, message_id, payload_hash);
        let inclusion_branch = vec![vec![0xC3; 32]];
        let solana_transaction_signature = sample_solana_transaction_signature();
        let solana_emitter_program_id = sample_solana_emitter_program_id();
        let source_event_leaf_hash = if source_domain == SCCP_DOMAIN_SOL {
            sccp_solana_transaction_status_leaf_hash(
                source_event_digest,
                &solana_transaction_signature,
                &solana_emitter_program_id,
            )
            .expect("Solana transaction-status leaf hash")
        } else {
            sccp_source_event_leaf_hash(source_event_digest)
        };
        let receipt_or_message_root = if source_domain == SCCP_DOMAIN_SOL {
            sccp_solana_message_root_from_branch(
                source_event_digest,
                &solana_transaction_signature,
                &solana_emitter_program_id,
                &inclusion_branch,
            )
            .expect("Solana transaction status root")
        } else {
            sccp_source_message_root_from_branch(source_event_leaf_hash, 0, &inclusion_branch)
                .expect("source root")
        };
        let solana_message_proof_hash = sccp_solana_message_proof_hash(
            source_event_digest,
            receipt_or_message_root,
            &solana_transaction_signature,
            &solana_emitter_program_id,
            &inclusion_branch,
        )
        .expect("Solana source message proof hash");
        let finality_height = if source_domain == SCCP_DOMAIN_SOL {
            SCCP_SOLANA_MAINNET_SLOTS_PER_EPOCH + 10_000 + u64::from(source_domain)
        } else {
            10_000 + u64::from(source_domain)
        };
        let evm_receipt_root_index = 0;
        let evm_receipt_mpt_proof = matches!(source_domain, SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC)
            .then(|| {
                if source_material.is_some_and(|material| !material.placeholder_material) {
                    let message_emitter_address = source_material
                        .and_then(|material| {
                            sccp_source_bridge_emitter_address_as_array(
                                &material.source_bridge_emitter_address,
                            )
                        })
                        .filter(address20_is_nonzero)
                        .unwrap_or_else(|| sample_evm_message_emitter_address(source_domain));
                    sample_tron_receipt_mpt_proof_with_value(
                        evm_receipt_root_index,
                        &sample_evm_receipt_with_sccp_log(
                            message_emitter_address,
                            source_event_digest,
                        ),
                    )
                } else {
                    sample_evm_receipt_mpt_proof(evm_receipt_root_index, receipt_or_message_root)
                }
            });
        let evm_receipts_root = evm_receipt_mpt_proof
            .as_ref()
            .map(|(receipts_root, _)| *receipts_root);
        let eth_execution_header_rlp = (source_domain == SCCP_DOMAIN_ETH).then(|| {
            sample_eth_execution_header_rlp(
                finality_height,
                evm_receipts_root.expect("ETH receipts root from receipt MPT proof"),
            )
        });
        let tron_receipt_root_index = 0;
        let tron_transaction_source_proof = (source_domain == SCCP_DOMAIN_TRON)
            .then(|| {
                source_material
                    .filter(|material| !material.placeholder_material)
                    .map(|material| {
                        let message_emitter_address = sccp_source_bridge_emitter_address_as_array(
                            &material.source_bridge_emitter_address,
                        )
                        .filter(address20_is_nonzero)
                        .unwrap_or_else(sample_tron_message_emitter_address);
                        sample_tron_transaction_source_proof(
                            message_emitter_address,
                            source_domain,
                            target_domain,
                            source_event_digest,
                        )
                    })
            })
            .flatten();
        let tron_receipt_mpt_proof = (source_domain == SCCP_DOMAIN_TRON
            && tron_transaction_source_proof.is_none())
        .then(|| sample_tron_receipt_mpt_proof(tron_receipt_root_index, receipt_or_message_root));
        let tron_transaction_root = tron_transaction_source_proof
            .as_ref()
            .map(|(transaction_root, _, _, _, _)| *transaction_root)
            .or_else(|| {
                tron_receipt_mpt_proof
                    .as_ref()
                    .map(|(transaction_root, _)| *transaction_root)
            });
        let tron_solid_block_header_proof = tron_transaction_root.map(|transaction_root| {
            sample_tron_solid_block_header_proof(finality_height, transaction_root)
        });
        let finality_block_hash = if let Some(header_proof) = &tron_solid_block_header_proof {
            header_proof.block_id
        } else {
            eth_execution_header_rlp
                .as_ref()
                .map_or([0x71; 32], |header| keccak256_bytes(header))
        };
        let finalized_header_hash = sccp_source_finalized_header_hash(
            source_domain,
            finality_model,
            finality_height,
            finality_block_hash,
            receipt_or_message_root,
        );
        let mut adapter_proof = match source_domain {
            SCCP_DOMAIN_ETH => {
                let beacon_slot = finality_height.saturating_mul(32);
                let sync_committee_root = sample_eth_sync_committee_hash();
                let execution_header_rlp =
                    eth_execution_header_rlp.expect("ETH execution header RLP");
                let (
                    beacon_proposer_index,
                    beacon_parent_root,
                    beacon_state_root,
                    beacon_body_root,
                    execution_payload_branch,
                    beacon_finalized_root,
                ) = sample_eth_beacon_header_witness(beacon_slot, &execution_header_rlp);
                let execution_receipts_root =
                    evm_receipts_root.expect("ETH receipts root from receipt MPT proof");
                let (_, receipt_trie_proof_nodes) = evm_receipt_mpt_proof
                    .clone()
                    .expect("ETH receipt MPT proof");
                let receipt_trie_proof_hash = sccp_evm_receipt_proof_hash(
                    source_domain,
                    source_event_digest,
                    beacon_slot,
                    finality_height,
                    finality_block_hash,
                    execution_receipts_root,
                    beacon_finalized_root,
                    sync_committee_root,
                    evm_receipt_root_index,
                    &receipt_trie_proof_nodes,
                    &inclusion_branch,
                )
                .expect("EVM source receipt proof hash");
                let sync_committee_proof = sample_eth_sync_committee_proof(
                    source_domain,
                    beacon_slot,
                    finality_height,
                    finality_block_hash,
                    execution_receipts_root,
                    beacon_finalized_root,
                    sync_committee_root,
                    receipt_trie_proof_hash,
                );
                let sync_committee_signature_hash =
                    sccp_eth_sync_committee_aggregate_hash(&sync_committee_proof)
                        .expect("ETH sync committee aggregate hash");
                SccpSourceAdapterProofV1::EthereumBeaconReceipt(SccpEvmBeaconSourceProofV1 {
                    version: 1,
                    source_domain,
                    beacon_slot,
                    execution_block_number: finality_height,
                    execution_block_hash: finality_block_hash,
                    execution_header_rlp,
                    execution_receipts_root,
                    beacon_finalized_root,
                    beacon_proposer_index,
                    beacon_parent_root,
                    beacon_state_root,
                    beacon_body_root,
                    execution_payload_branch,
                    sync_committee_root,
                    sync_committee_signature_hash,
                    receipt_trie_proof_hash,
                    sync_committee_proof,
                    sync_committee_transition_proofs: Vec::new(),
                    receipt_root_index: evm_receipt_root_index,
                    receipt_trie_proof_nodes,
                })
            }
            SCCP_DOMAIN_BSC => {
                let validator_epoch = sccp_bsc_parlia_epoch_for_block(finality_height)
                    .expect("BSC finality block maps to Parlia epoch");
                let validator_set_hash = sample_bsc_validator_set_hash();
                let receipts_root =
                    evm_receipts_root.expect("BSC receipts root from receipt MPT proof");
                let (_, receipt_trie_proof_nodes) = evm_receipt_mpt_proof
                    .clone()
                    .expect("BSC receipt MPT proof");
                let seal_proof = sample_bsc_validator_set_seal_proof(
                    source_domain,
                    validator_epoch,
                    finality_height,
                    finality_block_hash,
                    receipts_root,
                    validator_set_hash,
                );
                let commit_seal_hash =
                    sccp_bsc_commit_seal_hash(&seal_proof).expect("BSC commit seal hash");
                let receipt_trie_proof_hash = sccp_bsc_receipt_proof_hash(
                    source_domain,
                    source_event_digest,
                    validator_epoch,
                    finality_height,
                    finality_block_hash,
                    receipts_root,
                    validator_set_hash,
                    commit_seal_hash,
                    evm_receipt_root_index,
                    &receipt_trie_proof_nodes,
                    &inclusion_branch,
                )
                .expect("BSC source receipt proof hash");
                SccpSourceAdapterProofV1::BscValidatorSetReceipt(SccpBscValidatorSetSourceProofV1 {
                    version: 1,
                    source_domain,
                    validator_epoch,
                    block_number: finality_height,
                    block_hash: finality_block_hash,
                    receipts_root,
                    validator_set_hash,
                    commit_seal_hash,
                    receipt_trie_proof_hash,
                    seal_proof,
                    validator_set_transition_proofs: Vec::new(),
                    receipt_root_index: evm_receipt_root_index,
                    receipt_trie_proof_nodes,
                })
            }
            SCCP_DOMAIN_SOL => {
                let solana_bank_hash =
                    sample_solana_bank_hash(finality_height, finality_block_hash);
                let finality_context = sample_solana_finality_context(
                    finality_height,
                    finality_block_hash,
                    solana_bank_hash,
                    receipt_or_message_root,
                );
                let finality_context_hash = sccp_solana_finality_context_hash(&finality_context);
                SccpSourceAdapterProofV1::SolanaFinalizedTransaction(
                    SccpSolanaFinalizedSourceProofV1 {
                        version: 1,
                        source_domain,
                        finalized_slot: finality_height,
                        blockhash: finality_block_hash,
                        bank_hash: solana_bank_hash,
                        transaction_status_root: receipt_or_message_root,
                        message_proof_hash: solana_message_proof_hash,
                        transaction_signature: solana_transaction_signature,
                        emitter_program_id: solana_emitter_program_id,
                        finality_context,
                        vote_proof: sample_solana_vote_proof(
                            source_domain,
                            finality_height,
                            finality_block_hash,
                            solana_bank_hash,
                            receipt_or_message_root,
                            solana_message_proof_hash,
                            finality_context_hash,
                        ),
                    },
                )
            }
            SCCP_DOMAIN_TON => {
                let shard_workchain_id = SCCP_TON_BASECHAIN_WORKCHAIN_ID;
                let shard_shard = SCCP_TON_BASECHAIN_FULL_SHARD;
                let shard_seqno = finality_height.saturating_sub(1).max(1);
                let shard_block_hash = [0xD1; 32];
                let shard_file_hash = [0xD3; 32];
                let shard_state_leaf_index = 0;
                let transaction_lt = finality_height.saturating_add(1);
                let mut shard_state_dictionary_key = [0u8; 32];
                shard_state_dictionary_key[0] = 0x11;
                let shard_state_dictionary_proof_boc = test_ton_shard_accounts_dictionary_boc(
                    &shard_state_dictionary_key,
                    receipt_or_message_root,
                    transaction_lt,
                );
                let shard_state_dictionary_root =
                    sccp_ton_hashmap_e_proof_root_hash(&shard_state_dictionary_proof_boc)
                        .expect("TON shard accounts root");
                let shard_state_proof_boc =
                    test_ton_shard_state_proof_boc_with_accounts_and_shard_identity_and_metadata(
                        &shard_state_dictionary_proof_boc,
                        SCCP_TON_MAINNET_GLOBAL_ID,
                        SCCP_TON_BASECHAIN_WORKCHAIN_ID,
                        0,
                        0,
                        u32::try_from(shard_seqno).expect("sample TON shard seqno fits u32"),
                        11,
                        transaction_lt,
                        u32::try_from(finality_height)
                            .expect("sample TON masterchain seqno fits u32"),
                    );
                let shard_state_root = sccp_ton_shard_state_proof_root_hash(&shard_state_proof_boc)
                    .expect("TON shard-state root from proof BoC");
                let shard_state_inclusion_branch = Vec::new();
                let validator_set_payload =
                    sample_ton_validator_set_payload_for(&sample_ton_validator_keypairs());
                let validator_set_hash =
                    sccp_ton_validator_set_hash_from_payload(&validator_set_payload)
                        .expect("TON validator set hash");
                let shard_proof_hash = sccp_ton_shard_proof_hash_with_dictionary(
                    source_event_digest,
                    finality_height,
                    finality_block_hash,
                    shard_workchain_id,
                    shard_shard,
                    shard_seqno,
                    shard_block_hash,
                    shard_file_hash,
                    shard_state_root,
                    receipt_or_message_root,
                    transaction_lt,
                    &shard_state_proof_boc,
                    shard_state_dictionary_root,
                    SCCP_TON_SHARD_ACCOUNT_KEY_BITS,
                    &shard_state_dictionary_key,
                    &shard_state_dictionary_proof_boc,
                    shard_state_leaf_index,
                    &shard_state_inclusion_branch,
                    &inclusion_branch,
                )
                .expect("TON source shard proof hash");
                let masterchain_config_proof = sample_ton_masterchain_config_proof(
                    source_domain,
                    finality_height,
                    finality_block_hash,
                    shard_state_root,
                    validator_set_hash,
                    &validator_set_payload,
                );
                let masterchain_config_root = masterchain_config_proof.config_root;
                let masterchain_config_proof_hash =
                    sccp_ton_masterchain_config_proof_hash(&masterchain_config_proof)
                        .expect("TON masterchain config proof hash");
                let validator_signature_proof = sample_ton_masterchain_validator_signatures_proof(
                    source_domain,
                    finality_height,
                    SCCP_TON_MASTERCHAIN_WORKCHAIN_ID,
                    SCCP_TON_MASTERCHAIN_SHARD,
                    finality_block_hash,
                    [0xA5; 32],
                    validator_set_hash,
                    masterchain_config_root,
                    masterchain_config_proof_hash,
                    shard_workchain_id,
                    shard_shard,
                    shard_seqno,
                    shard_block_hash,
                    shard_file_hash,
                    shard_state_root,
                    receipt_or_message_root,
                    shard_proof_hash,
                );
                let masterchain_signature_hash =
                    sccp_ton_masterchain_signatures_hash(&validator_signature_proof)
                        .expect("TON masterchain signature hash");
                SccpSourceAdapterProofV1::TonMasterchainShard(SccpTonMasterchainSourceProofV1 {
                    version: 1,
                    source_domain,
                    masterchain_seqno: finality_height,
                    masterchain_workchain_id: SCCP_TON_MASTERCHAIN_WORKCHAIN_ID,
                    masterchain_shard: SCCP_TON_MASTERCHAIN_SHARD,
                    masterchain_block_hash: finality_block_hash,
                    masterchain_file_hash: [0xA5; 32],
                    validator_set_hash,
                    masterchain_config_root,
                    masterchain_config_proof_hash,
                    shard_workchain_id,
                    shard_shard,
                    shard_seqno,
                    shard_block_hash,
                    shard_file_hash,
                    shard_state_root,
                    transaction_root: receipt_or_message_root,
                    transaction_lt,
                    shard_state_proof_boc,
                    shard_state_dictionary_root,
                    shard_state_dictionary_key_bit_len: SCCP_TON_SHARD_ACCOUNT_KEY_BITS,
                    shard_state_dictionary_key: shard_state_dictionary_key.to_vec(),
                    shard_state_dictionary_proof_boc,
                    shard_state_leaf_index,
                    shard_state_inclusion_branch,
                    shard_state_verification_proof: SccpSourceStateVerificationProofV1::default(),
                    masterchain_config_verification_proof:
                        SccpSourceStateVerificationProofV1::default(),
                    validator_set_transition_verification_proof:
                        SccpSourceStateVerificationProofV1::default(),
                    shard_accounts_dictionary_verification_proof:
                        SccpSourceStateVerificationProofV1::default(),
                    masterchain_signature_hash,
                    shard_proof_hash,
                    validator_signature_proof,
                    masterchain_config_proof,
                    validator_set_transition_proofs: Vec::new(),
                })
            }
            SCCP_DOMAIN_TRON => {
                let receipt_root_index = tron_receipt_root_index;
                let transaction_root =
                    tron_transaction_root.expect("TRON transaction root from source proof");
                let (
                    transaction_index,
                    transaction_count,
                    transaction_bytes,
                    transaction_merkle_branch,
                ) = tron_transaction_source_proof
                    .clone()
                    .map(|(_, index, count, bytes, branch)| (index, count, bytes, branch))
                    .unwrap_or((0, 0, Vec::new(), Vec::new()));
                let receipt_trie_proof_nodes = tron_receipt_mpt_proof
                    .clone()
                    .map(|(_, proof_nodes)| proof_nodes)
                    .unwrap_or_default();
                let solid_block_header_proof = tron_solid_block_header_proof
                    .clone()
                    .expect("TRON solid block-header proof");
                let witness_schedule_hash = sample_tron_witness_schedule_hash();
                let receipt_proof_hash = if tron_transaction_source_proof.is_some() {
                    sccp_tron_transaction_source_proof_hash(
                        source_event_digest,
                        receipt_or_message_root,
                        transaction_root,
                        transaction_index,
                        transaction_count,
                        &transaction_bytes,
                        &transaction_merkle_branch,
                        &inclusion_branch,
                    )
                    .expect("TRON transaction source proof hash")
                } else {
                    sccp_tron_receipt_state_proof_hash(
                        source_event_digest,
                        receipt_or_message_root,
                        transaction_root,
                        receipt_root_index,
                        &receipt_trie_proof_nodes,
                        &inclusion_branch,
                    )
                    .expect("TRON source receipt-state proof hash")
                };
                let witness_seal_proof = sample_tron_witness_seal_proof(
                    source_domain,
                    finality_height,
                    finality_block_hash,
                    witness_schedule_hash,
                    receipt_or_message_root,
                    transaction_root,
                    receipt_proof_hash,
                );
                let witness_seal_hash = sccp_tron_witness_seal_hash(&witness_seal_proof)
                    .expect("TRON witness seal hash");
                SccpSourceAdapterProofV1::TronDposReceipt(SccpTronDposSourceProofV1 {
                    version: 1,
                    source_domain,
                    solid_block_number: finality_height,
                    block_hash: finality_block_hash,
                    witness_schedule_hash,
                    witness_seal_hash,
                    receipt_root: receipt_or_message_root,
                    transaction_root,
                    solid_block_header_proof,
                    solid_block_ancestor_headers: sample_tron_solid_block_ancestor_headers(
                        finality_height,
                    ),
                    solid_block_confirmation_headers: sample_tron_solid_block_confirmation_headers(
                        finality_height,
                        finality_block_hash,
                    ),
                    receipt_root_index,
                    receipt_root_branch: Vec::new(),
                    receipt_trie_proof_nodes,
                    transaction_index,
                    transaction_count,
                    transaction_bytes,
                    transaction_merkle_branch,
                    receipt_proof_hash,
                    witness_seal_proof,
                    witness_schedule_transition_proofs: Vec::new(),
                })
            }
            SCCP_DOMAIN_SORA_KUSAMA | SCCP_DOMAIN_SORA_POLKADOT | SCCP_DOMAIN_SORA2 => {
                let grandpa_set_id = 42;
                let authority_set_hash = sample_substrate_authority_set_hash();
                let storage_proof_hash = sccp_substrate_storage_proof_hash(
                    source_domain,
                    source_event_digest,
                    0,
                    finality_height,
                    grandpa_set_id,
                    finality_block_hash,
                    authority_set_hash,
                    receipt_or_message_root,
                    &inclusion_branch,
                )
                .expect("Substrate source storage proof hash");
                let grandpa_justification = sample_substrate_grandpa_justification_proof(
                    source_domain,
                    finality_height,
                    grandpa_set_id,
                    finality_block_hash,
                    authority_set_hash,
                    receipt_or_message_root,
                    storage_proof_hash,
                );
                let grandpa_justification_hash =
                    sccp_substrate_grandpa_justification_hash(&grandpa_justification)
                        .expect("Substrate GRANDPA justification hash");
                SccpSourceAdapterProofV1::SubstrateGrandpaEvent(SccpSubstrateGrandpaSourceProofV1 {
                    version: 1,
                    source_domain,
                    finalized_block_number: finality_height,
                    grandpa_set_id,
                    block_hash: finality_block_hash,
                    authority_set_hash,
                    events_root: receipt_or_message_root,
                    grandpa_justification_hash,
                    storage_proof_hash,
                    runtime_storage_verification_proof: SccpSourceStateVerificationProofV1::default(
                    ),
                    grandpa_justification,
                    authority_set_transition_proofs: Vec::new(),
                })
            }
            _ => panic!("unsupported sample SCCP source domain {source_domain}"),
        };
        if let (Some(material), SccpSourceAdapterProofV1::SolanaFinalizedTransaction(adapter)) =
            (source_material, &mut adapter_proof)
            && sccp_source_state_verifier_is_production_ready(material)
        {
            adapter.vote_proof.accounts_lt_hash_proof =
                build_sccp_solana_accounts_lt_hash_verification_proof(adapter, material)
                    .expect("build Solana AccountsLtHash verification proof");
            if let Some(deployment) = source_deployment
                && sccp_solana_full_light_client_gate_hash_from_deployment_v1(material, deployment)
                    .is_some()
            {
                adapter.vote_proof.tower_replay_verification_proof =
                    build_sccp_solana_tower_replay_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build Solana Tower replay verification proof");
                adapter
                    .vote_proof
                    .full_accountsdb_lattice_verification_proof =
                    build_sccp_solana_full_accountsdb_lattice_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build Solana full AccountsDB lattice verification proof");
                adapter.vote_proof.bank_fork_choice_verification_proof =
                    build_sccp_solana_bank_fork_choice_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build Solana bank/fork-choice verification proof");
            }
        }
        if let (Some(material), SccpSourceAdapterProofV1::TonMasterchainShard(adapter)) =
            (source_material, &mut adapter_proof)
            && sccp_source_state_verifier_is_production_ready(material)
        {
            adapter.shard_state_verification_proof =
                build_sccp_ton_shard_state_verification_proof(adapter, material)
                    .expect("build TON shard-state verification proof");
            if let Some(deployment) = source_deployment
                && sccp_ton_full_light_client_gate_hash_from_deployment_v1(material, deployment)
                    .is_some()
            {
                adapter.masterchain_config_verification_proof =
                    build_sccp_ton_masterchain_config_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build TON masterchain config verification proof");
                adapter.validator_set_transition_verification_proof =
                    build_sccp_ton_validator_set_transition_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build TON validator-set transition verification proof");
                adapter.shard_accounts_dictionary_verification_proof =
                    build_sccp_ton_shard_accounts_dictionary_verification_proof(
                        adapter, material, deployment,
                    )
                    .expect("build TON shard-accounts dictionary verification proof");
            }
        }
        if let (Some(material), SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter)) =
            (source_material, &mut adapter_proof)
            && sccp_source_state_verifier_is_production_ready(material)
        {
            adapter.runtime_storage_verification_proof =
                build_sccp_substrate_runtime_storage_verification_proof(
                    adapter,
                    source_event_digest,
                    0,
                    &inclusion_branch,
                    material,
                )
                .expect("build Substrate runtime storage verification proof");
        }
        let adapter_transcript_hash = sccp_source_adapter_transcript_hash(
            source_domain,
            target_domain,
            source_proof_plan,
            finality_model,
            finality_height,
            finality_block_hash,
            receipt_or_message_root,
            source_event_digest,
            &adapter_proof,
        );
        let mut envelope = SccpSourceChainProofEnvelopeV1 {
            version: 1,
            source_domain,
            target_domain,
            source_chain: source_chain.clone(),
            source_proof_plan,
            finality_model,
            message_id,
            payload_hash,
            source_event_digest,
            commitment_root,
            finality_height,
            finality_block_hash,
            finalized_header_hash,
            receipt_or_message_root,
            consensus_proof: Vec::new(),
            message_inclusion_proof: Vec::new(),
            inclusion_branch,
        };
        let adapter_verification_proof =
            if let (Some(material), Some(deployment)) = (source_material, source_deployment) {
                build_sccp_source_adapter_verification_proof_with_material_and_deployment(
                    &envelope,
                    &adapter_proof,
                    adapter_transcript_hash,
                    material,
                    deployment,
                )
            } else if let Some(material) = source_material {
                build_sccp_source_adapter_verification_proof_with_material(
                    &envelope,
                    &adapter_proof,
                    adapter_transcript_hash,
                    material,
                )
            } else {
                build_sccp_source_adapter_verification_proof(
                    &envelope,
                    &adapter_proof,
                    adapter_transcript_hash,
                )
            }
            .expect("build source adapter verification proof");
        let verifier_evidence = if let (Some(material), Some(deployment)) =
            (source_material, source_deployment)
        {
            build_sccp_source_verifier_evidence_with_material_and_deployment(
                &envelope,
                &adapter_proof,
                adapter_transcript_hash,
                material,
                deployment,
            )
        } else if let Some(material) = source_material {
            build_sccp_source_verifier_evidence_with_material(
                &envelope,
                &adapter_proof,
                adapter_transcript_hash,
                material,
            )
        } else {
            build_sccp_source_verifier_evidence(&envelope, &adapter_proof, adapter_transcript_hash)
        }
        .expect("build source verifier evidence");
        let consensus_proof = to_bytes(&SccpSourceConsensusProofV1 {
            version: 1,
            source_domain,
            source_chain: source_chain.clone(),
            source_proof_plan,
            finality_model,
            finality_height,
            finality_block_hash,
            receipt_or_message_root,
            finalized_header_hash,
            adapter_proof,
            adapter_transcript_hash,
            verifier_evidence,
            adapter_verification_proof,
        })
        .expect("encode source consensus proof");
        let message_inclusion_proof = to_bytes(&SccpSourceMessageInclusionProofV1 {
            version: 1,
            source_domain,
            target_domain,
            message_id,
            payload_hash,
            source_event_digest,
            source_event_leaf_hash,
            receipt_or_message_root,
            leaf_index: 0,
        })
        .expect("encode source message inclusion proof");
        envelope.consensus_proof = consensus_proof;
        envelope.message_inclusion_proof = message_inclusion_proof;
        envelope
    }

    fn sample_source_chain_proof(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
    ) -> Vec<u8> {
        to_bytes(&sample_source_chain_proof_envelope(
            payload,
            commitment,
            commitment_root,
        ))
        .expect("encode source chain proof envelope")
    }

    fn sample_source_chain_proof_with_material(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
        source_material: &SccpSourceVerifierMaterialV1,
    ) -> Vec<u8> {
        to_bytes(&sample_source_chain_proof_envelope_with_material(
            payload,
            commitment,
            commitment_root,
            Some(source_material),
        ))
        .expect("encode source chain proof envelope")
    }

    fn sample_source_chain_proof_with_material_and_deployment(
        payload: &SccpPayloadV1,
        commitment: &SccpHubCommitmentV1,
        commitment_root: H256,
        source_material: &SccpSourceVerifierMaterialV1,
        source_deployment: &SccpSourceAdapterEngineDeploymentV1,
    ) -> Vec<u8> {
        to_bytes(
            &sample_source_chain_proof_envelope_with_material_and_deployment(
                payload,
                commitment,
                commitment_root,
                Some(source_material),
                Some(source_deployment),
            ),
        )
        .expect("encode deployment-bound source chain proof envelope")
    }

    fn sample_message_bundle(payload: SccpPayloadV1) -> NexusSccpMessageProofV1 {
        sample_message_bundle_with_source_material(payload, None)
    }

    fn sample_message_bundle_with_source_material(
        payload: SccpPayloadV1,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
    ) -> NexusSccpMessageProofV1 {
        sample_message_bundle_with_source_material_and_deployment(payload, source_material, None)
    }

    fn sample_message_bundle_with_source_material_and_deployment(
        payload: SccpPayloadV1,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
        source_deployment: Option<&SccpSourceAdapterEngineDeploymentV1>,
    ) -> NexusSccpMessageProofV1 {
        let commitment = SccpHubCommitmentV1 {
            version: 1,
            kind: sccp_message_kind(&payload),
            target_domain: sccp_message_target_domain(&payload),
            message_id: sccp_message_id(&payload),
            payload_hash: payload_hash(&canonical_sccp_payload_bytes(&payload)),
        };
        let commitment_root = commitment_leaf_hash(&commitment);
        let source_domain = sccp_message_source_domain(&payload);
        let target_domain = sccp_message_target_domain(&payload);
        let finality_proof = if source_domain == SCCP_DOMAIN_SORA
            || !is_supported_domain(source_domain)
            || !is_supported_domain(target_domain)
            || sccp_source_proof_plan_for_domain(source_domain).is_none()
        {
            sample_finality_proof(commitment_root)
        } else if let (Some(material), Some(deployment)) = (source_material, source_deployment) {
            sample_source_chain_proof_with_material_and_deployment(
                &payload,
                &commitment,
                commitment_root,
                material,
                deployment,
            )
        } else if let Some(material) = source_material {
            sample_source_chain_proof_with_material(
                &payload,
                &commitment,
                commitment_root,
                material,
            )
        } else {
            sample_source_chain_proof(&payload, &commitment, commitment_root)
        };
        NexusSccpMessageProofV1 {
            version: 1,
            commitment_root,
            commitment,
            merkle_proof: SccpMerkleProofV1 { steps: Vec::new() },
            payload,
            finality_proof,
        }
    }

    fn assert_rejects_message_payload(payload: SccpPayloadV1) {
        assert!(!verify_sccp_payload_structure(&payload), "{payload:?}");
        assert!(!verify_message_bundle_structure(&sample_message_bundle(
            payload
        )));
    }

    fn sample_burn_bundle(nonce: u64) -> NexusSccpBurnProofV1 {
        let payload = BurnPayloadV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_ETH,
            dest_domain: SCCP_DOMAIN_SORA,
            nonce,
            sora_asset_id: [0x11; 32],
            amount: 42,
            recipient: [0x22; 32],
        };
        let commitment = SccpHubCommitmentV1 {
            version: 1,
            kind: SccpHubMessageKind::Burn,
            target_domain: payload.dest_domain,
            message_id: burn_message_id(&payload),
            payload_hash: payload_hash(&canonical_burn_payload_bytes(&payload)),
        };
        let commitment_root = commitment_leaf_hash(&commitment);
        NexusSccpBurnProofV1 {
            version: 1,
            commitment_root,
            commitment,
            merkle_proof: SccpMerkleProofV1 { steps: Vec::new() },
            payload,
            finality_proof: sample_finality_proof(commitment_root),
        }
    }

    fn sample_account_bytes(domain: u32) -> Vec<u8> {
        match domain {
            SCCP_DOMAIN_SORA
            | SCCP_DOMAIN_SORA_KUSAMA
            | SCCP_DOMAIN_SORA_POLKADOT
            | SCCP_DOMAIN_SORA2 => format!(
                "account@{}",
                sccp_chain_key_for_domain(domain).expect("domain chain key")
            )
            .into_bytes(),
            SCCP_DOMAIN_ETH | SCCP_DOMAIN_BSC => {
                b"0x1111111111111111111111111111111111111111".to_vec()
            }
            SCCP_DOMAIN_SOL => b"11111111111111111111111111111111".to_vec(),
            SCCP_DOMAIN_TON => {
                b"0:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef".to_vec()
            }
            SCCP_DOMAIN_TRON => b"TJRabPrwbZy45sbavfcjinPJC18kjpRTv8".to_vec(),
            _ => panic!("unsupported sample SCCP domain {domain}"),
        }
    }

    fn sample_transfer_bundle(
        source_domain: u32,
        dest_domain: u32,
        nonce: u64,
    ) -> NexusSccpMessageProofV1 {
        sample_transfer_bundle_with_source_material(source_domain, dest_domain, nonce, None)
    }

    fn sample_transfer_bundle_with_source_material(
        source_domain: u32,
        dest_domain: u32,
        nonce: u64,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
    ) -> NexusSccpMessageProofV1 {
        sample_transfer_bundle_with_source_material_and_deployment(
            source_domain,
            dest_domain,
            nonce,
            source_material,
            None,
        )
    }

    fn sample_transfer_bundle_with_source_material_and_deployment(
        source_domain: u32,
        dest_domain: u32,
        nonce: u64,
        source_material: Option<&SccpSourceVerifierMaterialV1>,
        source_deployment: Option<&SccpSourceAdapterEngineDeploymentV1>,
    ) -> NexusSccpMessageProofV1 {
        assert_ne!(source_domain, dest_domain);
        let source_chain = sccp_chain_key_for_domain(source_domain).expect("source chain key");
        let dest_chain = sccp_chain_key_for_domain(dest_domain).expect("destination chain key");
        sample_message_bundle_with_source_material_and_deployment(
            SccpPayloadV1::Transfer(TransferPayloadV1 {
                version: 1,
                source_domain,
                dest_domain,
                nonce,
                asset_home_domain: if source_domain == SCCP_DOMAIN_SORA {
                    SCCP_DOMAIN_SORA
                } else {
                    source_domain
                },
                asset_id_codec: SCCP_CODEC_TEXT_UTF8,
                asset_id: format!("{source_chain}#{dest_chain}#asset").into_bytes(),
                amount: 100 + u128::from(nonce),
                sender_codec: sccp_counterparty_account_codec(source_domain)
                    .expect("source account codec"),
                sender: sample_account_bytes(source_domain),
                recipient_codec: sccp_counterparty_account_codec(dest_domain)
                    .expect("destination account codec"),
                recipient: sample_account_bytes(dest_domain),
                route_id_codec: SCCP_CODEC_TEXT_UTF8,
                route_id: format!("{source_chain}:{dest_chain}:asset").into_bytes(),
            }),
            source_material,
            source_deployment,
        )
    }

    /// Build a deployment-bound Ethereum mainnet -> SORA transfer bundle for executor tests.
    #[cfg(feature = "test-fixtures")]
    pub fn sample_eth_mainnet_to_sora_transfer_bundle_with_material_and_deployment(
        nonce: u64,
        source_material: &SccpSourceVerifierMaterialV1,
        source_deployment: &SccpSourceAdapterEngineDeploymentV1,
    ) -> NexusSccpMessageProofV1 {
        let bundle = sample_transfer_bundle_with_source_material_and_deployment(
            SCCP_DOMAIN_ETH,
            SCCP_DOMAIN_SORA,
            nonce,
            Some(source_material),
            Some(source_deployment),
        );
        let source_proof = decode_sccp_source_chain_proof_envelope(&bundle.finality_proof)
            .expect("decode ETH source-chain proof envelope");
        assert!(
            verify_sccp_eth_mainnet_source_chain_proof_envelope_production(
                &source_proof,
                source_material,
                source_deployment,
            )
        );
        assert!(
            verified_sccp_eth_mainnet_source_chain_proof_envelope_for_production(
                &bundle,
                source_material,
                source_deployment,
            )
            .is_some()
        );
        bundle
    }

    /// Build a local-admission transparent proof for an Ethereum mainnet -> SORA transfer.
    #[cfg(feature = "test-fixtures")]
    pub fn sample_eth_mainnet_to_sora_local_admission_transparent_proof_with_material_and_deployment(
        nonce: u64,
        source_material: &SccpSourceVerifierMaterialV1,
        source_deployment: &SccpSourceAdapterEngineDeploymentV1,
    ) -> NexusSccpMessageTransparentProofV1 {
        let bundle = sample_eth_mainnet_to_sora_transfer_bundle_with_material_and_deployment(
            nonce,
            source_material,
            source_deployment,
        );
        let artifact =
            build_nexus_sccp_message_transparent_proof_with_source_verifier_material_and_deployment_allow_unready(
                &bundle,
                source_material,
                source_deployment,
                true,
            )
            .expect("build ETH local-admission transparent proof");
        assert_eq!(artifact.public_inputs.target_domain, SCCP_DOMAIN_SORA);
        assert!(matches!(
            artifact.submission_package.platform_payload,
            SccpPlatformSubmissionPayloadV1::LocalAdmission(_)
        ));
        assert!(
            verify_nexus_sccp_message_transparent_proof_structure_with_source_verifier_material_and_deployment_allow_unready_manifest(
                &artifact,
                source_material,
                source_deployment,
            )
        );
        artifact
    }

    fn assert_source_chain_proof_binds_material_but_adapter_is_not_ready(
        bundle: &NexusSccpMessageProofV1,
        material: &SccpSourceVerifierMaterialV1,
    ) -> SccpSourceChainProofEnvelopeV1 {
        assert!(sccp_source_verifier_material_is_production_ready(material));
        let proof = decode_sccp_source_chain_proof_envelope(&bundle.finality_proof)
            .expect("decode source-chain proof envelope");
        assert!(
            verify_sccp_source_chain_proof_envelope_structure_with_material(&proof, material,),
            "source proof must bind production material for domain {}",
            proof.source_domain,
        );
        let readiness = sccp_source_adapter_engine_readiness_with_material_for_domain(
            proof.source_domain,
            material,
        )
        .expect("source adapter readiness with material");
        assert!(readiness.source_verifier_material_ready);
        assert!(!readiness.external_consensus_verifier_ready);
        assert!(!readiness.external_message_inclusion_verifier_ready);
        assert!(!readiness.source_trust_anchor_ready);
        assert!(!readiness.production_ready);
        assert!(
            !verify_sccp_source_chain_proof_envelope_production_with_material(&proof, material,)
        );
        assert!(
            verified_sccp_message_source_chain_proof_envelope_for_production_with_material(
                bundle, material,
            )
            .is_none(),
            "exact source material alone must not satisfy the source-adapter production gate"
        );
        proof
    }

