    #[test]
    fn solana_stake_history_hash_binds_effective_and_delegated_stake_window() {
        let validator_public_keys = vec![vec![0x11; 32], vec![0x22; 32]];
        let validator_effective_stakes = vec![1, 2];
        let validator_delegated_stakes = vec![1, 3];
        let activation_epochs = vec![0, 2];
        let deactivation_epochs = vec![u64::MAX, 9];
        let vote_account_addresses = vec![vec![0x33; 32], vec![0x44; 32]];
        let stake_account_addresses = vec![vec![0x55; 32], vec![0x66; 32]];
        let vote_account_hashes = vec![vec![0x77; 32], vec![0x88; 32]];
        let stake_account_hashes = vec![vec![0x99; 32], vec![0xaa; 32]];
        let stake_history_entries = vec![
            SccpSolanaStakeHistoryEntryV1 {
                epoch: 2,
                effective: 23,
                activating: 3,
                deactivating: 0,
            },
            SccpSolanaStakeHistoryEntryV1 {
                epoch: 3,
                effective: 3,
                activating: 1,
                deactivating: 0,
            },
        ];
        let canonical = canonical_sccp_solana_stake_history_bytes(
            3,
            &validator_public_keys,
            &validator_effective_stakes,
            &validator_delegated_stakes,
            &activation_epochs,
            &deactivation_epochs,
            &vote_account_addresses,
            &stake_account_addresses,
            &vote_account_hashes,
            &stake_account_hashes,
            &stake_history_entries,
        )
        .expect("Solana stake-history bytes");
        assert_eq!(canonical.len(), 249);
        let hash = sccp_solana_stake_history_hash(
            3,
            &validator_public_keys,
            &validator_effective_stakes,
            &validator_delegated_stakes,
            &activation_epochs,
            &deactivation_epochs,
            &vote_account_addresses,
            &stake_account_addresses,
            &vote_account_hashes,
            &stake_account_hashes,
            &stake_history_entries,
        )
        .expect("Solana stake-history hash");
        assert!(h256_is_nonzero(&hash));
        assert_eq!(
            hash,
            [
                0xd7, 0x59, 0x57, 0xee, 0xc3, 0xcf, 0x9f, 0x5b, 0x88, 0x07, 0x6c, 0x8d, 0xc1, 0x8e,
                0x81, 0xc5, 0xde, 0xbd, 0x62, 0x7a, 0xdf, 0xbe, 0xd7, 0xe0, 0x3e, 0x35, 0x44, 0x3b,
                0xcc, 0x4d, 0x14, 0xb6,
            ],
        );
        let mut extra_effective = stake_history_entries.clone();
        extra_effective[1].effective += 1;
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &validator_effective_stakes,
                &validator_delegated_stakes,
                &activation_epochs,
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &extra_effective,
            )
            .is_none()
        );
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &[1, 1],
                &validator_delegated_stakes,
                &activation_epochs,
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &stake_history_entries,
            )
            .is_none()
        );
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &validator_effective_stakes,
                &[0, 3],
                &activation_epochs,
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &stake_history_entries,
            )
            .is_none()
        );
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &validator_effective_stakes,
                &validator_delegated_stakes,
                &[3, 2],
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &stake_history_entries,
            )
            .is_none()
        );
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &validator_effective_stakes,
                &validator_delegated_stakes,
                &activation_epochs,
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &stake_history_entries[..1],
            )
            .is_none()
        );
        let mut unsorted = stake_history_entries.clone();
        unsorted.swap(0, 1);
        assert!(
            sccp_solana_stake_history_hash(
                3,
                &validator_public_keys,
                &validator_effective_stakes,
                &validator_delegated_stakes,
                &activation_epochs,
                &deactivation_epochs,
                &vote_account_addresses,
                &stake_account_addresses,
                &vote_account_hashes,
                &stake_account_hashes,
                &unsorted,
            )
            .is_none()
        );
    }

    #[test]
    fn solana_tower_lockout_hash_binds_slot_context() {
        let finalized_slot = 1_296_096;
        let rooted_slot = 1_296_065;
        let parent_slot = 1_296_095;
        let parent_bank_hash = [0x33; 32];
        let epoch = sccp_solana_mainnet_epoch_for_slot(finalized_slot);

        assert_eq!(epoch, 3);
        assert_eq!(
            canonical_sccp_solana_tower_lockout_bytes(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                parent_bank_hash,
            )
            .expect("Solana tower lockout bytes")
            .len(),
            73,
        );
        let hash = sccp_solana_tower_lockout_hash(
            epoch,
            finalized_slot,
            rooted_slot,
            parent_slot,
            parent_bank_hash,
        )
        .expect("Solana tower lockout hash");
        assert!(h256_is_nonzero(&hash));
        assert!(
            sccp_solana_tower_lockout_hash(
                epoch + 1,
                finalized_slot,
                rooted_slot,
                parent_slot,
                parent_bank_hash,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_lockout_hash(
                epoch,
                finalized_slot,
                finalized_slot - (SCCP_SOLANA_TOWER_VOTE_STACK_DEPTH - 1),
                parent_slot,
                parent_bank_hash,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_lockout_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot - 1,
                parent_bank_hash,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_lockout_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                finalized_slot,
                parent_bank_hash,
            )
            .is_none()
        );
    }

    #[test]
    fn solana_tower_replay_hash_binds_vote_stack_context() {
        let finalized_slot = 1_296_096;
        let rooted_slot = 1_296_065;
        let parent_slot = 1_296_095;
        let epoch = sccp_solana_mainnet_epoch_for_slot(finalized_slot);
        let bank_fork_hash = [0xA5; 32];
        let tower_vote_slots = ((rooted_slot + 1)..=finalized_slot).collect::<Vec<_>>();

        assert_eq!(epoch, 3);
        assert_eq!(
            canonical_sccp_solana_tower_replay_bytes(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                bank_fork_hash,
                &tower_vote_slots,
            )
            .expect("Solana Tower replay bytes")
            .len(),
            573,
        );
        let hash = sccp_solana_tower_replay_hash(
            epoch,
            finalized_slot,
            rooted_slot,
            parent_slot,
            bank_fork_hash,
            &tower_vote_slots,
        )
        .expect("Solana Tower replay hash");
        assert!(h256_is_nonzero(&hash));
        assert_ne!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                [0xA6; 32],
                &tower_vote_slots,
            ),
            Some(hash),
            "Tower replay transcripts must bind the finalized bank-fork hash",
        );
        assert!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                [0u8; 32],
                &tower_vote_slots,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_replay_hash(
                epoch + 1,
                finalized_slot,
                rooted_slot,
                parent_slot,
                bank_fork_hash,
                &tower_vote_slots,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot - 1,
                bank_fork_hash,
                &tower_vote_slots,
            )
            .is_none()
        );
        assert!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                bank_fork_hash,
                &tower_vote_slots[..tower_vote_slots.len() - 1],
            )
            .is_none()
        );
        let mut unsorted_vote_slots = tower_vote_slots.clone();
        unsorted_vote_slots.swap(0, 1);
        assert!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                bank_fork_hash,
                &unsorted_vote_slots,
            )
            .is_none()
        );
        let mut wrong_last_vote_slot = tower_vote_slots.clone();
        *wrong_last_vote_slot
            .last_mut()
            .expect("Solana Tower vote stack is non-empty") -= 1;
        assert!(
            sccp_solana_tower_replay_hash(
                epoch,
                finalized_slot,
                rooted_slot,
                parent_slot,
                bank_fork_hash,
                &wrong_last_vote_slot,
            )
            .is_none()
        );
    }

