    #[test]
    fn evm_source_adapter_binds_receipt_trie_proof_hash_to_inclusion_witness() {
        let bundle = sample_transfer_bundle(SCCP_DOMAIN_ETH, SCCP_DOMAIN_SORA, 701);
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &consensus.adapter_proof
        else {
            panic!("expected ETH adapter proof");
        };
        let expected = sccp_evm_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.beacon_slot,
            adapter.execution_block_number,
            adapter.execution_block_hash,
            adapter.execution_receipts_root,
            adapter.beacon_finalized_root,
            adapter.sync_committee_root,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("ETH receipt proof hash");
        assert_eq!(adapter.receipt_trie_proof_hash, expected);
        assert!(verify_sccp_evm_receipt_mpt_value(
            adapter.execution_receipts_root,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            valid.receipt_or_message_root,
        ));
        assert!(verify_sccp_source_adapter_proof_binding(
            &consensus.adapter_proof,
            &valid,
        ));

        let mut wrong_hash = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &mut wrong_hash else {
            panic!("expected ETH adapter proof");
        };
        adapter.receipt_trie_proof_hash[0] ^= 0x01;
        let eth_beacon_slot = adapter.beacon_slot;
        let eth_execution_block_number = adapter.execution_block_number;
        let eth_execution_block_hash = adapter.execution_block_hash;
        let eth_execution_receipts_root = adapter.execution_receipts_root;
        let eth_beacon_finalized_root = adapter.beacon_finalized_root;
        let eth_sync_committee_root = adapter.sync_committee_root;
        let eth_receipt_root_index = adapter.receipt_root_index;
        let eth_receipt_trie_proof_nodes = adapter.receipt_trie_proof_nodes.clone();
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_hash,
            &valid,
        ));

        let mut wrong_branch = valid.clone();
        wrong_branch.inclusion_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &consensus.adapter_proof,
            &wrong_branch,
        ));

        let mut wrong_header = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &mut wrong_header else {
            panic!("expected ETH adapter proof");
        };
        adapter.execution_header_rlp[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_header,
            &valid,
        ));

        let mut wrong_beacon_branch = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &mut wrong_beacon_branch
        else {
            panic!("expected ETH adapter proof");
        };
        adapter.execution_payload_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_beacon_branch,
            &valid,
        ));

        assert!(
            sccp_evm_receipt_proof_hash(
                valid.source_domain,
                valid.source_event_digest,
                eth_beacon_slot,
                eth_execution_block_number,
                eth_execution_block_hash,
                eth_execution_receipts_root,
                eth_beacon_finalized_root,
                eth_sync_committee_root,
                eth_receipt_root_index,
                &eth_receipt_trie_proof_nodes,
                &[vec![0xAA; 31]],
            )
            .is_none()
        );
        assert!(
            sccp_evm_receipt_proof_hash(
                valid.source_domain,
                [0; 32],
                eth_beacon_slot,
                eth_execution_block_number,
                eth_execution_block_hash,
                eth_execution_receipts_root,
                eth_beacon_finalized_root,
                eth_sync_committee_root,
                eth_receipt_root_index,
                &eth_receipt_trie_proof_nodes,
                &valid.inclusion_branch,
            )
            .is_none()
        );

        let mut wrong_receipt_trie_node = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &mut wrong_receipt_trie_node
        else {
            panic!("expected ETH adapter proof");
        };
        adapter.receipt_trie_proof_nodes[0][0] ^= 0x01;
        adapter.receipt_trie_proof_hash = sccp_evm_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.beacon_slot,
            adapter.execution_block_number,
            adapter.execution_block_hash,
            adapter.execution_receipts_root,
            adapter.beacon_finalized_root,
            adapter.sync_committee_root,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("ETH receipt proof hash");
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_receipt_trie_node,
            &valid,
        ));
    }

    #[test]
    fn eth_source_adapter_verifies_beacon_sync_committee_certificate() {
        let material = sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            SCCP_DOMAIN_ETH,
            sample_eth_sync_committee_hash(),
            [0xB2; 32],
            [0xC3; 32],
            [0xD4; 32],
            sample_evm_message_emitter_address(SCCP_DOMAIN_ETH),
            sample_evm_source_bridge_code_hash(SCCP_DOMAIN_ETH),
        )
        .expect("ETH mainnet source material");
        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_ETH,
            SCCP_DOMAIN_SORA,
            706,
            Some(&material),
        );
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &consensus.adapter_proof
        else {
            panic!("expected ETH adapter proof");
        };

        assert!(verify_sccp_eth_beacon_sync_committee_proof(
            adapter, &valid, &material,
        ));
        let typed_fallback_bundle = sample_transfer_bundle(SCCP_DOMAIN_ETH, SCCP_DOMAIN_SORA, 806);
        let typed_fallback_valid = source_chain_proof_from_bundle(&typed_fallback_bundle);
        let typed_fallback_consensus = source_consensus_proof_from_envelope(&typed_fallback_valid);
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(typed_fallback_adapter) =
            &typed_fallback_consensus.adapter_proof
        else {
            panic!("expected ETH adapter proof");
        };
        assert!(verify_sccp_evm_receipt_mpt_value(
            typed_fallback_adapter.execution_receipts_root,
            typed_fallback_adapter.receipt_root_index,
            &typed_fallback_adapter.receipt_trie_proof_nodes,
            typed_fallback_valid.receipt_or_message_root,
        ));
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            typed_fallback_adapter,
            &typed_fallback_valid,
            &material,
        ));
        assert_eq!(
            sccp_eth_sync_committee_hash(
                &adapter.sync_committee_proof.sync_committee_public_keys,
                &adapter.sync_committee_proof.sync_committee_weights,
                &adapter.sync_committee_proof.sync_committee_pops,
            ),
            Some(material.source_trust_anchor_hash),
        );
        assert_eq!(
            adapter.sync_committee_proof.sync_committee_message_hash,
            sccp_eth_sync_committee_message_hash(
                adapter.source_domain,
                adapter.beacon_slot,
                adapter.execution_block_number,
                adapter.execution_block_hash,
                adapter.execution_receipts_root,
                adapter.beacon_finalized_root,
                adapter.sync_committee_root,
                adapter.receipt_trie_proof_hash,
            ),
        );
        assert_eq!(
            sccp_eth_sync_committee_aggregate_hash(&adapter.sync_committee_proof),
            Some(adapter.sync_committee_signature_hash),
        );
        assert!(verify_sccp_eth_execution_header_receipts_root_binding(
            adapter
        ));
        assert!(verify_sccp_eth_beacon_execution_header_root_binding(
            adapter
        ));
        let execution_payload_header_root =
            sccp_eth_execution_payload_header_root_from_rlp(&adapter.execution_header_rlp)
                .expect("ETH execution payload header SSZ root");
        assert_eq!(
            sccp_eth_beacon_body_root_from_execution_payload_branch(
                execution_payload_header_root,
                &adapter.execution_payload_branch,
            ),
            Some(adapter.beacon_body_root),
        );
        assert_eq!(
            sccp_eth_beacon_block_header_root(
                adapter.beacon_slot,
                adapter.beacon_proposer_index,
                adapter.beacon_parent_root,
                adapter.beacon_state_root,
                adapter.beacon_body_root,
            ),
            adapter.beacon_finalized_root,
        );

        let mut wrong_execution_branch = adapter.clone();
        wrong_execution_branch.execution_payload_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_execution_branch,
            &valid,
            &material,
        ));

        let mut wrong_beacon_header = adapter.clone();
        wrong_beacon_header.beacon_parent_root[0] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_beacon_header,
            &valid,
            &material,
        ));

        let mut wrong_signature = adapter.clone();
        wrong_signature.sync_committee_proof.aggregate_signature[0] ^= 0x01;
        wrong_signature.sync_committee_signature_hash =
            sccp_eth_sync_committee_aggregate_hash(&wrong_signature.sync_committee_proof)
                .expect("ETH sync committee aggregate hash");
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_signature,
            &valid,
            &material,
        ));

        let mut insufficient_weight = adapter.clone();
        insufficient_weight.sync_committee_proof.signers_bitmap = vec![0b0000_0011];
        insufficient_weight.sync_committee_proof.signed_weight = 2;
        let signers = sample_eth_sync_committee_keypairs();
        let signatures = signers[..2]
            .iter()
            .map(|signer| {
                iroha_crypto::Signature::new(
                    signer.private_key(),
                    &insufficient_weight
                        .sync_committee_proof
                        .sync_committee_message_hash,
                )
            })
            .collect::<Vec<_>>();
        let signature_refs = signatures
            .iter()
            .map(|signature| signature.payload().as_ref())
            .collect::<Vec<_>>();
        insufficient_weight.sync_committee_proof.aggregate_signature =
            iroha_crypto::bls_normal_aggregate_signatures(&signature_refs)
                .expect("ETH aggregate sync committee signature");
        assert!(
            sccp_eth_sync_committee_aggregate_hash(&insufficient_weight.sync_committee_proof)
                .is_none()
        );
        insufficient_weight.sync_committee_signature_hash = [0u8; 32];
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &insufficient_weight,
            &valid,
            &material,
        ));

        let mut wrong_anchor = material.clone();
        wrong_anchor.source_trust_anchor_hash[0] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            adapter,
            &valid,
            &wrong_anchor,
        ));

        let mut wrong_header = adapter.clone();
        wrong_header.execution_header_rlp[0] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_header,
            &valid,
            &material,
        ));

        let mut wrong_message = adapter.clone();
        wrong_message
            .sync_committee_proof
            .sync_committee_message_hash[0] ^= 0x01;
        wrong_message.sync_committee_signature_hash =
            sccp_eth_sync_committee_aggregate_hash(&wrong_message.sync_committee_proof)
                .expect("ETH sync committee aggregate hash");
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_message,
            &valid,
            &material,
        ));

        let mut wrong_signature_hash = adapter.clone();
        wrong_signature_hash.sync_committee_signature_hash[0] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_signature_hash,
            &valid,
            &material,
        ));
    }

    #[test]
    fn eth_source_adapter_verifies_sync_committee_transition_chain() {
        let parent_signers = sample_eth_sync_committee_keypairs();
        let active_signers = sample_eth_next_sync_committee_keypairs();
        let parent_sync_committee_hash = sample_eth_sync_committee_hash_for(&parent_signers);
        let active_sync_committee_hash = sample_eth_sync_committee_hash_for(&active_signers);
        let active_sync_committee_payload = sample_eth_sync_committee_payload_for(&active_signers);
        let material = sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            SCCP_DOMAIN_ETH,
            parent_sync_committee_hash,
            [0xB2; 32],
            [0xC3; 32],
            [0xD4; 32],
            sample_evm_message_emitter_address(SCCP_DOMAIN_ETH),
            sample_evm_source_bridge_code_hash(SCCP_DOMAIN_ETH),
        )
        .expect("ETH mainnet source material anchored to parent sync committee");

        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_ETH,
            SCCP_DOMAIN_SORA,
            710,
            Some(&material),
        );
        let mut valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(mut adapter) = consensus.adapter_proof
        else {
            panic!("expected ETH adapter proof");
        };

        adapter.sync_committee_root = active_sync_committee_hash;
        adapter.receipt_trie_proof_hash = sccp_evm_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.beacon_slot,
            adapter.execution_block_number,
            adapter.execution_block_hash,
            adapter.execution_receipts_root,
            adapter.beacon_finalized_root,
            adapter.sync_committee_root,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("active ETH receipt proof hash");
        let active_message_hash = sccp_eth_sync_committee_message_hash(
            adapter.source_domain,
            adapter.beacon_slot,
            adapter.execution_block_number,
            adapter.execution_block_hash,
            adapter.execution_receipts_root,
            adapter.beacon_finalized_root,
            adapter.sync_committee_root,
            adapter.receipt_trie_proof_hash,
        );
        adapter.sync_committee_proof =
            sample_eth_sync_committee_signature_proof_for(&active_signers, active_message_hash);
        adapter.sync_committee_signature_hash =
            sccp_eth_sync_committee_aggregate_hash(&adapter.sync_committee_proof)
                .expect("active ETH sync committee aggregate hash");
        let active_sync_period =
            sccp_eth_mainnet_sync_committee_period_for_slot(adapter.beacon_slot);
        assert!(
            active_sync_period > 0,
            "fixture beacon slot must allow a parent sync-committee transition"
        );
        let parent_sync_period = active_sync_period - 1;
        let parent_period_transition_slot = parent_sync_period
            .saturating_mul(SCCP_ETH_MAINNET_SLOTS_PER_SYNC_COMMITTEE_PERIOD)
            + SCCP_ETH_MAINNET_SLOTS_PER_EPOCH;
        assert_eq!(
            sccp_eth_mainnet_sync_committee_period_for_slot(parent_period_transition_slot),
            parent_sync_period
        );
        adapter.sync_committee_transition_proofs =
            vec![sample_eth_sync_committee_transition_proof(
                &parent_signers,
                parent_sync_period,
                active_sync_period,
                parent_period_transition_slot,
                adapter.beacon_finalized_root,
                parent_sync_committee_hash,
                active_sync_committee_payload.clone(),
                [0xBE; 32],
            )];
        assert_eq!(
            adapter.sync_committee_transition_proofs[0].next_sync_committee_hash,
            active_sync_committee_hash
        );
        assert_eq!(
            adapter.sync_committee_transition_proofs[0].next_sync_committee_payload_hash,
            sccp_eth_sync_committee_payload_hash(&active_sync_committee_payload)
        );
        replace_source_adapter_proof_with_material(
            &mut valid,
            SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter.clone()),
            &material,
        );

        assert!(
            verify_sccp_source_chain_proof_envelope_structure_with_material(&valid, &material,)
        );
        assert!(verify_sccp_eth_beacon_sync_committee_proof(
            &adapter, &valid, &material,
        ));

        let mut tampered_payload = adapter.clone();
        tampered_payload.sync_committee_transition_proofs[0].next_sync_committee_payload[1] ^= 0x01;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &tampered_payload,
            &valid,
            &material,
        ));

        let mut wrong_next_payload = adapter.clone();
        let parent_payload = sample_eth_sync_committee_payload_for(&parent_signers);
        wrong_next_payload.sync_committee_transition_proofs[0].next_sync_committee_payload =
            parent_payload.clone();
        wrong_next_payload.sync_committee_transition_proofs[0].next_sync_committee_payload_hash =
            sccp_eth_sync_committee_payload_hash(&parent_payload);
        let wrong_next_message_hash = sccp_eth_sync_committee_transition_message_hash(
            SCCP_DOMAIN_ETH,
            wrong_next_payload.sync_committee_transition_proofs[0].from_sync_period,
            wrong_next_payload.sync_committee_transition_proofs[0].to_sync_period,
            wrong_next_payload.sync_committee_transition_proofs[0].transition_slot,
            wrong_next_payload.sync_committee_transition_proofs[0].finalized_beacon_root,
            wrong_next_payload.sync_committee_transition_proofs[0].parent_sync_committee_hash,
            wrong_next_payload.sync_committee_transition_proofs[0].next_sync_committee_hash,
            wrong_next_payload.sync_committee_transition_proofs[0].next_sync_committee_payload_hash,
            wrong_next_payload.sync_committee_transition_proofs[0].next_sync_committee_branch_hash,
        );
        wrong_next_payload.sync_committee_transition_proofs[0].transition_message_hash =
            wrong_next_message_hash;
        wrong_next_payload.sync_committee_transition_proofs[0].sync_committee_proof =
            sample_eth_sync_committee_signature_proof_for(&parent_signers, wrong_next_message_hash);
        wrong_next_payload.sync_committee_transition_proofs[0].transition_signature_hash =
            sccp_eth_sync_committee_transition_signature_hash(
                &wrong_next_payload.sync_committee_transition_proofs[0],
            )
            .expect("ETH sync committee transition signature hash");
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_next_payload,
            &valid,
            &material,
        ));

        let mut missing_transition = adapter.clone();
        missing_transition.sync_committee_transition_proofs.clear();
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &missing_transition,
            &valid,
            &material,
        ));

        let mut skipped_period = adapter.clone();
        skipped_period.sync_committee_transition_proofs[0].to_sync_period += 1;
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &skipped_period,
            &valid,
            &material,
        ));

        let mut wrong_transition_slot_period = adapter.clone();
        wrong_transition_slot_period.sync_committee_transition_proofs =
            vec![sample_eth_sync_committee_transition_proof(
                &parent_signers,
                parent_sync_period,
                active_sync_period,
                adapter.beacon_slot,
                adapter.beacon_finalized_root,
                parent_sync_committee_hash,
                active_sync_committee_payload,
                [0xBE; 32],
            )];
        assert_eq!(
            sccp_eth_mainnet_sync_committee_period_for_slot(
                wrong_transition_slot_period.sync_committee_transition_proofs[0].transition_slot
            ),
            active_sync_period
        );
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_transition_slot_period,
            &valid,
            &material,
        ));

        let mut wrong_parent = adapter.clone();
        wrong_parent.sync_committee_transition_proofs[0].parent_sync_committee_hash[0] ^= 0x01;
        wrong_parent.sync_committee_transition_proofs[0].transition_signature_hash =
            sccp_eth_sync_committee_transition_signature_hash(
                &wrong_parent.sync_committee_transition_proofs[0],
            )
            .expect("ETH sync committee transition signature hash");
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_parent,
            &valid,
            &material,
        ));

        let mut wrong_transition_signature = adapter;
        wrong_transition_signature.sync_committee_transition_proofs[0]
            .sync_committee_proof
            .aggregate_signature[0] ^= 0x01;
        wrong_transition_signature.sync_committee_transition_proofs[0].transition_signature_hash =
            sccp_eth_sync_committee_transition_signature_hash(
                &wrong_transition_signature.sync_committee_transition_proofs[0],
            )
            .expect("ETH sync committee transition signature hash");
        assert!(!verify_sccp_eth_beacon_sync_committee_proof(
            &wrong_transition_signature,
            &valid,
            &material,
        ));
    }

    #[test]
    fn eth_sync_committee_transition_transcript_matches_sdk_fixture() {
        let parent_public_keys = vec![vec![0x11; 48], vec![0x22; 48]];
        let parent_weights = vec![1, 2];
        let parent_pops = vec![vec![0xaa; 96], vec![0xbb; 96]];
        let parent_sync_committee_hash =
            sccp_eth_sync_committee_hash(&parent_public_keys, &parent_weights, &parent_pops)
                .expect("ETH parent sync-committee hash");
        assert_eq!(
            parent_sync_committee_hash,
            test_h256_from_hex(
                "0xa95be780d50a9f42f4b1871e29798dbee0352d08027f0c4c6f4fc6466b4bd536"
            )
        );

        let next_public_keys = vec![vec![0x33; 48], vec![0x44; 48]];
        let next_weights = vec![3, 4];
        let next_pops = vec![vec![0xcc; 96], vec![0xdd; 96]];
        let next_sync_committee_payload = canonical_sccp_eth_sync_committee_payload_bytes(
            &next_public_keys,
            &next_weights,
            &next_pops,
        )
        .expect("ETH next sync-committee payload");
        assert_eq!(
            encode_lower_hex(&next_sync_committee_payload),
            "",
        );
        let next_sync_committee_hash =
            sccp_eth_sync_committee_hash_from_payload(&next_sync_committee_payload)
                .expect("ETH next sync-committee hash");
        let next_sync_committee_payload_hash =
            sccp_eth_sync_committee_payload_hash(&next_sync_committee_payload);
        assert_eq!(
            next_sync_committee_hash,
            test_h256_from_hex(
                "0xb3343685e8ab63a2d66bccebb6c03a149a53330389473b4a495598065c17b445"
            )
        );
        assert_eq!(
            next_sync_committee_payload_hash,
            test_h256_from_hex(
                "0xfdba6ad2ff9acca564b1042eec01c2d6356d5e2ade5e653c9d47360e55d53e17"
            )
        );

        let transition_message_hash = sccp_eth_sync_committee_transition_message_hash(
            SCCP_DOMAIN_ETH,
            7,
            8,
            19,
            [0xaa; 32],
            parent_sync_committee_hash,
            next_sync_committee_hash,
            next_sync_committee_payload_hash,
            [0xbe; 32],
        );
        assert_eq!(
            canonical_sccp_eth_sync_committee_transition_message_bytes(
                SCCP_DOMAIN_ETH,
                7,
                8,
                19,
                [0xaa; 32],
                parent_sync_committee_hash,
                next_sync_committee_hash,
                next_sync_committee_payload_hash,
                [0xbe; 32],
            )
            .len(),
            189
        );
        assert_eq!(
            transition_message_hash,
            test_h256_from_hex(
                "0xc5cbfaf915a63e59bc142277814f13fab1e8012a0bd56db7033b18bc02637bec"
            )
        );

        let mut proof = SccpEthSyncCommitteeTransitionProofV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_ETH,
            from_sync_period: 7,
            to_sync_period: 8,
            transition_slot: 19,
            finalized_beacon_root: [0xaa; 32],
            parent_sync_committee_hash,
            next_sync_committee_hash,
            next_sync_committee_payload,
            next_sync_committee_payload_hash,
            next_sync_committee_branch_hash: [0xbe; 32],
            transition_message_hash,
            transition_signature_hash: [0u8; 32],
            sync_committee_proof: SccpEthBeaconSyncCommitteeProofV1 {
                version: 1,
                total_weight: 3,
                signed_weight: 3,
                sync_committee_message_hash: transition_message_hash,
                sync_committee_public_keys: parent_public_keys,
                sync_committee_weights: parent_weights,
                sync_committee_pops: parent_pops,
                signers_bitmap: vec![0x03],
                aggregate_signature: vec![0xee; 96],
            },
        };
        proof.transition_signature_hash = sccp_eth_sync_committee_transition_signature_hash(&proof)
            .expect("ETH transition signature hash");
        assert_eq!(
            canonical_sccp_eth_sync_committee_transition_signature_bytes(&proof)
                .expect("ETH transition signature bytes")
                .len(),
            1068
        );
        assert_eq!(
            proof.transition_signature_hash,
            test_h256_from_hex(
                "0x2d03886e7ea307f7b5a77af00075b32536cbf016d0d8554bec2b1e424252f858"
            )
        );

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.sync_committee_public_keys[0] = vec![0; 48];
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.sync_committee_pops[0] = vec![0; 96];
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.signers_bitmap = vec![0x00];
        invalid.sync_committee_proof.signed_weight = 0;
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.signers_bitmap = vec![0x04];
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.signers_bitmap = vec![0x01];
        invalid.sync_committee_proof.signed_weight = 2;
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.signers_bitmap = vec![0x01];
        invalid.sync_committee_proof.signed_weight = 1;
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.total_weight = 4;
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());

        let mut invalid = proof.clone();
        invalid.sync_committee_proof.aggregate_signature = vec![0; 96];
        assert!(canonical_sccp_eth_sync_committee_transition_signature_bytes(&invalid).is_none());
    }

    #[test]
    fn bsc_source_adapter_binds_receipt_trie_proof_hash_to_inclusion_witness() {
        let bundle = sample_transfer_bundle(SCCP_DOMAIN_BSC, SCCP_DOMAIN_SORA, 702);
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };
        let expected = sccp_bsc_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
            adapter.commit_seal_hash,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("BSC receipt proof hash");
        assert_eq!(adapter.receipt_trie_proof_hash, expected);
        assert!(verify_sccp_evm_receipt_mpt_value(
            adapter.receipts_root,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            valid.receipt_or_message_root,
        ));
        assert!(verify_sccp_source_adapter_proof_binding(
            &consensus.adapter_proof,
            &valid,
        ));

        let mut wrong_hash = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &mut wrong_hash else {
            panic!("expected BSC adapter proof");
        };
        adapter.receipt_trie_proof_hash[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_hash,
            &valid,
        ));

        let mut wrong_commit_seal = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &mut wrong_commit_seal
        else {
            panic!("expected BSC adapter proof");
        };
        adapter.commit_seal_hash[0] ^= 0x01;
        let bsc_validator_epoch = adapter.validator_epoch;
        let bsc_block_number = adapter.block_number;
        let bsc_block_hash = adapter.block_hash;
        let bsc_receipts_root = adapter.receipts_root;
        let bsc_validator_set_hash = adapter.validator_set_hash;
        let bsc_commit_seal_hash = adapter.commit_seal_hash;
        let bsc_receipt_root_index = adapter.receipt_root_index;
        let bsc_receipt_trie_proof_nodes = adapter.receipt_trie_proof_nodes.clone();
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_commit_seal,
            &valid,
        ));
        assert!(
            sccp_bsc_receipt_proof_hash(
                valid.source_domain,
                valid.source_event_digest,
                bsc_validator_epoch,
                bsc_block_number,
                bsc_block_hash,
                bsc_receipts_root,
                bsc_validator_set_hash,
                bsc_commit_seal_hash,
                bsc_receipt_root_index,
                &bsc_receipt_trie_proof_nodes,
                &[vec![0xAA; 31]],
            )
            .is_none()
        );
        assert!(
            sccp_bsc_receipt_proof_hash(
                valid.source_domain,
                [0; 32],
                bsc_validator_epoch,
                bsc_block_number,
                bsc_block_hash,
                bsc_receipts_root,
                bsc_validator_set_hash,
                bsc_commit_seal_hash,
                bsc_receipt_root_index,
                &bsc_receipt_trie_proof_nodes,
                &valid.inclusion_branch,
            )
            .is_none()
        );

        let mut wrong_receipt_trie_node = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) =
            &mut wrong_receipt_trie_node
        else {
            panic!("expected BSC adapter proof");
        };
        adapter.receipt_trie_proof_nodes[0][0] ^= 0x01;
        adapter.receipt_trie_proof_hash = sccp_bsc_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
            adapter.commit_seal_hash,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("BSC receipt proof hash");
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_receipt_trie_node,
            &valid,
        ));

        let mut wrong_validator_epoch = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &mut wrong_validator_epoch
        else {
            panic!("expected BSC adapter proof");
        };
        adapter.validator_epoch += 1;
        adapter.receipt_trie_proof_hash = sccp_bsc_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
            adapter.commit_seal_hash,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("BSC receipt proof hash");
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_validator_epoch,
            &valid,
        ));
    }

    #[test]
    fn bsc_source_adapter_verifies_validator_set_seal_certificate() {
        let material = sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            SCCP_DOMAIN_BSC,
            sample_bsc_validator_set_hash(),
            [0xB2; 32],
            [0xC3; 32],
            [0xD4; 32],
            sample_evm_message_emitter_address(SCCP_DOMAIN_BSC),
            sample_evm_source_bridge_code_hash(SCCP_DOMAIN_BSC),
        )
        .expect("BSC mainnet source material");
        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_BSC,
            SCCP_DOMAIN_SORA,
            706,
            Some(&material),
        );
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };
        assert!(verify_sccp_bsc_validator_set_seal_proof(
            adapter, &valid, &material,
        ));
        let typed_fallback_bundle = sample_transfer_bundle(SCCP_DOMAIN_BSC, SCCP_DOMAIN_SORA, 807);
        let typed_fallback_valid = source_chain_proof_from_bundle(&typed_fallback_bundle);
        let typed_fallback_consensus = source_consensus_proof_from_envelope(&typed_fallback_valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(typed_fallback_adapter) =
            &typed_fallback_consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };
        assert!(verify_sccp_evm_receipt_mpt_value(
            typed_fallback_adapter.receipts_root,
            typed_fallback_adapter.receipt_root_index,
            &typed_fallback_adapter.receipt_trie_proof_nodes,
            typed_fallback_valid.receipt_or_message_root,
        ));
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            typed_fallback_adapter,
            &typed_fallback_valid,
            &material,
        ));
        assert_eq!(
            sccp_bsc_validator_set_hash(
                &adapter.seal_proof.validator_public_keys,
                &adapter.seal_proof.validator_powers,
            ),
            Some(material.source_trust_anchor_hash),
        );
        assert_eq!(
            sccp_bsc_commit_seal_hash(&adapter.seal_proof),
            Some(adapter.commit_seal_hash),
        );

        let mut wrong_signature = adapter.clone();
        wrong_signature.seal_proof.signatures[0][0] ^= 0x01;
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_signature,
            &valid,
            &material,
        ));

        let mut insufficient_power = adapter.clone();
        insufficient_power.seal_proof.signers_bitmap = vec![0b0000_0011];
        insufficient_power.seal_proof.signatures.truncate(2);
        insufficient_power.seal_proof.signed_power = 2;
        assert!(
            sccp_bsc_commit_seal_hash(&insufficient_power.seal_proof).is_none(),
            "BSC commit seal hash must reject sub-quorum seals"
        );
        insufficient_power.commit_seal_hash = [0u8; 32];
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &insufficient_power,
            &valid,
            &material,
        ));

        let mut wrong_anchor = material.clone();
        wrong_anchor.source_trust_anchor_hash[0] ^= 0x01;
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            adapter,
            &valid,
            &wrong_anchor,
        ));

        let mut wrong_commit_message = adapter.clone();
        wrong_commit_message.seal_proof.commit_message_hash[0] ^= 0x01;
        assert!(
            sccp_bsc_commit_seal_hash(&wrong_commit_message.seal_proof).is_none(),
            "BSC commit seal hash must reject signatures over a stale message"
        );
        wrong_commit_message.commit_seal_hash = [0u8; 32];
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_commit_message,
            &valid,
            &material,
        ));

        let mut wrong_epoch_window = adapter.clone();
        wrong_epoch_window.validator_epoch += 1;
        wrong_epoch_window.seal_proof = sample_bsc_validator_set_seal_proof_for(
            &sample_bsc_validator_keypairs(),
            wrong_epoch_window.source_domain,
            wrong_epoch_window.validator_epoch,
            wrong_epoch_window.block_number,
            wrong_epoch_window.block_hash,
            wrong_epoch_window.receipts_root,
            wrong_epoch_window.validator_set_hash,
        );
        wrong_epoch_window.commit_seal_hash =
            sccp_bsc_commit_seal_hash(&wrong_epoch_window.seal_proof)
                .expect("BSC commit seal hash");
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_epoch_window,
            &valid,
            &material,
        ));
    }

    #[test]
    fn bsc_parlia_header_payload_extraction_matches_transition_payload() {
        let active_signers = sample_bsc_next_validator_keypairs();
        let validator_set_payload = sample_bsc_validator_set_payload_for(&active_signers);
        let pre_luban_extra = sample_bsc_parlia_extra_from_payload(&validator_set_payload, false);
        assert!(
            bsc_parlia_validator_set_payload_candidates_from_extra(&pre_luban_extra)
                .iter()
                .any(|candidate| candidate == &validator_set_payload)
        );

        let post_luban_header =
            sample_bsc_parlia_epoch_header_rlp(18_000_000, &validator_set_payload);
        assert_eq!(
            sccp_bsc_validator_set_payload_from_header_rlp(&post_luban_header),
            Some(validator_set_payload.clone())
        );
        assert!(sccp_bsc_validator_set_payload_from_header_rlp(&[0x80]).is_none());
    }

    #[test]
    fn bsc_source_adapter_verifies_validator_set_transition_chain() {
        let parent_signers = sample_bsc_validator_keypairs();
        let active_signers = sample_bsc_next_validator_keypairs();
        let parent_validator_set_hash = sample_bsc_validator_set_hash_for(&parent_signers);
        let active_validator_set_hash = sample_bsc_validator_set_hash_for(&active_signers);
        let active_validator_set_payload = sample_bsc_validator_set_payload_for(&active_signers);
        assert_eq!(
            sccp_bsc_validator_set_hash_from_payload(&active_validator_set_payload),
            Some(active_validator_set_hash)
        );
        let material = sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            SCCP_DOMAIN_BSC,
            parent_validator_set_hash,
            [0xB2; 32],
            [0xC3; 32],
            [0xD4; 32],
            sample_evm_message_emitter_address(SCCP_DOMAIN_BSC),
            sample_evm_source_bridge_code_hash(SCCP_DOMAIN_BSC),
        )
        .expect("BSC mainnet source material anchored to parent validator set");

        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_BSC,
            SCCP_DOMAIN_SORA,
            709,
            Some(&material),
        );
        let mut valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(mut adapter) = consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };

        adapter.validator_set_hash = active_validator_set_hash;
        adapter.seal_proof = sample_bsc_validator_set_seal_proof_for(
            &active_signers,
            adapter.source_domain,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
        );
        adapter.commit_seal_hash =
            sccp_bsc_commit_seal_hash(&adapter.seal_proof).expect("active BSC commit seal hash");
        adapter.receipt_trie_proof_hash = sccp_bsc_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
            adapter.commit_seal_hash,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("active BSC receipt proof hash");
        let active_transition_block = sccp_bsc_parlia_epoch_start_block(adapter.validator_epoch)
            .expect("active BSC epoch start block");
        adapter.validator_set_transition_proofs = vec![sample_bsc_validator_set_transition_proof(
            &parent_signers,
            adapter.validator_epoch - 1,
            adapter.validator_epoch,
            active_transition_block,
            parent_validator_set_hash,
            active_validator_set_hash,
            active_validator_set_payload.clone(),
        )];
        assert_eq!(
            sccp_bsc_validator_set_payload_hash(&active_validator_set_payload),
            adapter.validator_set_transition_proofs[0].next_validator_set_payload_hash
        );
        assert_eq!(
            sccp_bsc_validator_set_payload_from_header_rlp(
                &adapter.validator_set_transition_proofs[0].transition_header_rlp,
            ),
            Some(active_validator_set_payload.clone())
        );
        replace_source_adapter_proof_with_material(
            &mut valid,
            SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter.clone()),
            &material,
        );

        assert!(
            verify_sccp_source_chain_proof_envelope_structure_with_material(&valid, &material,)
        );
        assert!(verify_sccp_bsc_validator_set_seal_proof(
            &adapter, &valid, &material,
        ));

        let mut missing_transition = adapter.clone();
        missing_transition.validator_set_transition_proofs.clear();
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &missing_transition,
            &valid,
            &material,
        ));

        let mut wrong_parent = adapter.clone();
        wrong_parent.validator_set_transition_proofs[0].parent_validator_set_hash[0] ^= 0x01;
        assert!(
            sccp_bsc_validator_set_transition_seal_hash(
                &wrong_parent.validator_set_transition_proofs[0],
            )
            .is_none(),
            "BSC transition seal hash must reject stale message hashes"
        );
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_parent,
            &valid,
            &material,
        ));

        let mut wrong_payload_hash = adapter.clone();
        wrong_payload_hash.validator_set_transition_proofs[0].next_validator_set_payload[0] ^= 0x01;
        wrong_payload_hash.validator_set_transition_proofs[0].transition_seal_hash =
            sccp_bsc_validator_set_transition_seal_hash(
                &wrong_payload_hash.validator_set_transition_proofs[0],
            )
            .expect("BSC transition seal hash");
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_payload_hash,
            &valid,
            &material,
        ));

        let mut missing_metadata = adapter.clone();
        missing_metadata.validator_set_transition_proofs[0].validator_set_metadata_proof =
            SccpBscValidatorSetMetadataProofV1::default();
        missing_metadata.validator_set_transition_proofs[0].validator_set_metadata_proof_hash =
            [0u8; 32];
        assert!(
            sccp_bsc_validator_set_transition_seal_hash(
                &missing_metadata.validator_set_transition_proofs[0],
            )
            .is_none(),
            "BSC transition seal hash must reject missing metadata hash"
        );
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &missing_metadata,
            &valid,
            &material,
        ));

        let mut wrong_contract = adapter.clone();
        wrong_contract.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .validator_contract_address[19] = 0x01;
        let wrong_contract_state_root = sccp_bsc_validator_set_transition_header_state_root(
            &wrong_contract.validator_set_transition_proofs[0],
        )
        .expect("BSC transition state root");
        wrong_contract.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .metadata_proof_hash = sccp_bsc_validator_set_metadata_proof_hash(
            wrong_contract_state_root,
            wrong_contract.validator_set_transition_proofs[0].next_validator_set_payload_hash,
            &wrong_contract.validator_set_transition_proofs[0].validator_set_metadata_proof,
        )
        .expect("BSC metadata proof hash");
        wrong_contract.validator_set_transition_proofs[0].validator_set_metadata_proof_hash =
            wrong_contract.validator_set_transition_proofs[0]
                .validator_set_metadata_proof
                .metadata_proof_hash;
        resign_bsc_validator_set_transition_proof(
            &mut wrong_contract.validator_set_transition_proofs[0],
            &parent_signers,
        );
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_contract,
            &valid,
            &material,
        ));

        let mut wrong_storage_value = adapter.clone();
        wrong_storage_value.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .validator_storage_proofs[0]
            .storage_value[0] ^= 0x01;
        let tampered_value = wrong_storage_value.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .validator_storage_proofs[0]
            .storage_value
            .clone();
        wrong_storage_value.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .validator_storage_proofs[0]
            .storage_value_hash = sccp_bsc_validator_set_storage_value_hash(&tampered_value);
        let wrong_storage_state_root = sccp_bsc_validator_set_transition_header_state_root(
            &wrong_storage_value.validator_set_transition_proofs[0],
        )
        .expect("BSC transition state root");
        wrong_storage_value.validator_set_transition_proofs[0]
            .validator_set_metadata_proof
            .metadata_proof_hash = sccp_bsc_validator_set_metadata_proof_hash(
            wrong_storage_state_root,
            wrong_storage_value.validator_set_transition_proofs[0].next_validator_set_payload_hash,
            &wrong_storage_value.validator_set_transition_proofs[0].validator_set_metadata_proof,
        )
        .expect("BSC metadata proof hash");
        wrong_storage_value.validator_set_transition_proofs[0].validator_set_metadata_proof_hash =
            wrong_storage_value.validator_set_transition_proofs[0]
                .validator_set_metadata_proof
                .metadata_proof_hash;
        resign_bsc_validator_set_transition_proof(
            &mut wrong_storage_value.validator_set_transition_proofs[0],
            &parent_signers,
        );
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_storage_value,
            &valid,
            &material,
        ));

        let mut wrong_header_payload = adapter.clone();
        wrong_header_payload.validator_set_transition_proofs[0].transition_header_rlp =
            sample_bsc_parlia_epoch_header_rlp(
                wrong_header_payload.validator_set_transition_proofs[0].transition_block_number,
                &sample_bsc_validator_set_payload_for(&parent_signers),
            );
        wrong_header_payload.validator_set_transition_proofs[0].transition_block_hash =
            keccak256_bytes(
                &wrong_header_payload.validator_set_transition_proofs[0].transition_header_rlp,
            );
        wrong_header_payload.validator_set_transition_proofs[0].transition_message_hash =
            sccp_bsc_validator_set_transition_message_hash(
                wrong_header_payload.validator_set_transition_proofs[0].source_domain,
                wrong_header_payload.validator_set_transition_proofs[0].from_validator_epoch,
                wrong_header_payload.validator_set_transition_proofs[0].to_validator_epoch,
                wrong_header_payload.validator_set_transition_proofs[0].transition_block_number,
                wrong_header_payload.validator_set_transition_proofs[0].transition_block_hash,
                wrong_header_payload.validator_set_transition_proofs[0].parent_validator_set_hash,
                wrong_header_payload.validator_set_transition_proofs[0].next_validator_set_hash,
                wrong_header_payload.validator_set_transition_proofs[0]
                    .next_validator_set_payload_hash,
                wrong_header_payload.validator_set_transition_proofs[0]
                    .validator_set_metadata_proof_hash,
            )
            .expect("BSC transition message hash");
        wrong_header_payload.validator_set_transition_proofs[0]
            .seal_proof
            .commit_message_hash =
            wrong_header_payload.validator_set_transition_proofs[0].transition_message_hash;
        wrong_header_payload.validator_set_transition_proofs[0]
            .seal_proof
            .signatures = parent_signers[..3]
            .iter()
            .map(|signer| {
                sccp_evm_sign_digest(
                    signer,
                    &wrong_header_payload.validator_set_transition_proofs[0]
                        .transition_message_hash,
                )
                .expect("BSC transition signature")
                .to_vec()
            })
            .collect::<Vec<_>>();
        wrong_header_payload.validator_set_transition_proofs[0].transition_seal_hash =
            sccp_bsc_validator_set_transition_seal_hash(
                &wrong_header_payload.validator_set_transition_proofs[0],
            )
            .expect("BSC transition seal hash");
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_header_payload,
            &valid,
            &material,
        ));

        let wrong_next_payload = sample_bsc_validator_set_payload_for(&parent_signers);
        let mut wrong_next_set = adapter.clone();
        let wrong_next_transition = wrong_next_set.validator_set_transition_proofs[0].clone();
        wrong_next_set.validator_set_transition_proofs[0] =
            sample_bsc_validator_set_transition_proof(
                &parent_signers,
                wrong_next_transition.from_validator_epoch,
                wrong_next_transition.to_validator_epoch,
                wrong_next_transition.transition_block_number,
                parent_validator_set_hash,
                active_validator_set_hash,
                wrong_next_payload,
            );
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_next_set,
            &valid,
            &material,
        ));

        let mut wrong_transition_signature = adapter;
        wrong_transition_signature.validator_set_transition_proofs[0]
            .seal_proof
            .signatures[0][0] ^= 0x01;
        wrong_transition_signature.validator_set_transition_proofs[0].transition_seal_hash =
            sccp_bsc_validator_set_transition_seal_hash(
                &wrong_transition_signature.validator_set_transition_proofs[0],
            )
            .expect("BSC transition seal hash");
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_transition_signature,
            &valid,
            &material,
        ));
    }

    #[test]
    fn bsc_validator_set_transition_chain_requires_increasing_transition_blocks() {
        let parent_signers = sample_bsc_validator_keypairs();
        let middle_signers = sample_bsc_next_validator_keypairs();
        let active_signers = sample_bsc_third_validator_keypairs();
        let parent_validator_set_hash = sample_bsc_validator_set_hash_for(&parent_signers);
        let middle_validator_set_payload = sample_bsc_validator_set_payload_for(&middle_signers);
        let middle_validator_set_hash =
            sccp_bsc_validator_set_hash_from_payload(&middle_validator_set_payload)
                .expect("middle BSC validator-set hash");
        let active_validator_set_payload = sample_bsc_validator_set_payload_for(&active_signers);
        let active_validator_set_hash =
            sccp_bsc_validator_set_hash_from_payload(&active_validator_set_payload)
                .expect("active BSC validator-set hash");
        let material = sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            SCCP_DOMAIN_BSC,
            parent_validator_set_hash,
            [0xB2; 32],
            [0xC3; 32],
            [0xD4; 32],
            sample_evm_message_emitter_address(SCCP_DOMAIN_BSC),
            sample_evm_source_bridge_code_hash(SCCP_DOMAIN_BSC),
        )
        .expect("BSC mainnet source material anchored to parent validator set");

        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_BSC,
            SCCP_DOMAIN_SORA,
            712,
            Some(&material),
        );
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(mut adapter) = consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };

        adapter.validator_set_hash = active_validator_set_hash;
        adapter.seal_proof = sample_bsc_validator_set_seal_proof_for(
            &active_signers,
            adapter.source_domain,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
        );
        adapter.commit_seal_hash =
            sccp_bsc_commit_seal_hash(&adapter.seal_proof).expect("active BSC commit seal hash");
        adapter.receipt_trie_proof_hash = sccp_bsc_receipt_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            adapter.validator_epoch,
            adapter.block_number,
            adapter.block_hash,
            adapter.receipts_root,
            adapter.validator_set_hash,
            adapter.commit_seal_hash,
            adapter.receipt_root_index,
            &adapter.receipt_trie_proof_nodes,
            &valid.inclusion_branch,
        )
        .expect("active BSC receipt proof hash");
        let middle_transition_block =
            sccp_bsc_parlia_epoch_start_block(adapter.validator_epoch - 1)
                .expect("middle BSC epoch start block");
        let active_transition_block = sccp_bsc_parlia_epoch_start_block(adapter.validator_epoch)
            .expect("active BSC epoch start block");

        adapter.validator_set_transition_proofs = vec![
            sample_bsc_validator_set_transition_proof(
                &parent_signers,
                adapter.validator_epoch - 2,
                adapter.validator_epoch - 1,
                middle_transition_block,
                parent_validator_set_hash,
                middle_validator_set_hash,
                middle_validator_set_payload.clone(),
            ),
            sample_bsc_validator_set_transition_proof(
                &middle_signers,
                adapter.validator_epoch - 1,
                adapter.validator_epoch,
                active_transition_block,
                middle_validator_set_hash,
                active_validator_set_hash,
                active_validator_set_payload.clone(),
            ),
        ];
        assert!(verify_sccp_bsc_validator_set_seal_proof(
            &adapter, &valid, &material,
        ));

        let mut skipped_epoch = adapter.clone();
        skipped_epoch.validator_set_transition_proofs =
            vec![sample_bsc_validator_set_transition_proof(
                &parent_signers,
                adapter.validator_epoch - 1,
                adapter.validator_epoch,
                active_transition_block,
                parent_validator_set_hash,
                active_validator_set_hash,
                active_validator_set_payload.clone(),
            )];
        skipped_epoch.validator_set_transition_proofs[0].from_validator_epoch =
            adapter.validator_epoch - 2;
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &skipped_epoch,
            &valid,
            &material,
        ));

        let mut wrong_epoch_block = adapter.clone();
        wrong_epoch_block.validator_set_transition_proofs =
            vec![sample_bsc_validator_set_transition_proof(
                &parent_signers,
                adapter.validator_epoch - 1,
                adapter.validator_epoch,
                active_transition_block,
                parent_validator_set_hash,
                active_validator_set_hash,
                active_validator_set_payload.clone(),
            )];
        wrong_epoch_block.validator_set_transition_proofs[0].transition_block_number += 1;
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &wrong_epoch_block,
            &valid,
            &material,
        ));
        assert!(
            sccp_bsc_validator_set_transition_message_hash(
                SCCP_DOMAIN_BSC,
                adapter.validator_epoch - 1,
                adapter.validator_epoch,
                active_transition_block + 1,
                [0xAA; 32],
                parent_validator_set_hash,
                active_validator_set_hash,
                sccp_bsc_validator_set_payload_hash(&active_validator_set_payload),
                [0xBB; 32],
            )
            .is_none(),
            "BSC transition messages must use the Parlia epoch-start block"
        );

        let mut non_monotonic = adapter.clone();
        non_monotonic.validator_set_transition_proofs = vec![
            sample_bsc_validator_set_transition_proof(
                &parent_signers,
                adapter.validator_epoch - 2,
                adapter.validator_epoch - 1,
                middle_transition_block,
                parent_validator_set_hash,
                middle_validator_set_hash,
                middle_validator_set_payload,
            ),
            sample_bsc_validator_set_transition_proof(
                &middle_signers,
                adapter.validator_epoch - 1,
                adapter.validator_epoch,
                active_transition_block,
                middle_validator_set_hash,
                active_validator_set_hash,
                active_validator_set_payload,
            ),
        ];
        non_monotonic.validator_set_transition_proofs[1].transition_block_number =
            middle_transition_block;
        assert!(!verify_sccp_bsc_validator_set_seal_proof(
            &non_monotonic,
            &valid,
            &material,
        ));
    }

    #[test]
    fn evm_bsc_and_substrate_source_adapters_bind_proof_hashes_to_inclusion_witnesses() {
        let eth_bundle = sample_transfer_bundle(SCCP_DOMAIN_ETH, SCCP_DOMAIN_SORA, 705);
        let eth_valid = source_chain_proof_from_bundle(&eth_bundle);
        let eth_consensus = source_consensus_proof_from_envelope(&eth_valid);
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(eth_adapter) =
            &eth_consensus.adapter_proof
        else {
            panic!("expected EVM adapter proof");
        };
        let eth_expected = sccp_evm_receipt_proof_hash(
            eth_valid.source_domain,
            eth_valid.source_event_digest,
            eth_adapter.beacon_slot,
            eth_adapter.execution_block_number,
            eth_adapter.execution_block_hash,
            eth_adapter.execution_receipts_root,
            eth_adapter.beacon_finalized_root,
            eth_adapter.sync_committee_root,
            eth_adapter.receipt_root_index,
            &eth_adapter.receipt_trie_proof_nodes,
            &eth_valid.inclusion_branch,
        )
        .expect("EVM receipt proof hash");
        assert_eq!(eth_adapter.receipt_trie_proof_hash, eth_expected);
        assert!(verify_sccp_source_adapter_proof_binding(
            &eth_consensus.adapter_proof,
            &eth_valid,
        ));

        let mut eth_wrong_hash = eth_consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::EthereumBeaconReceipt(adapter) = &mut eth_wrong_hash else {
            panic!("expected EVM adapter proof");
        };
        adapter.receipt_trie_proof_hash[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &eth_wrong_hash,
            &eth_valid,
        ));
        let mut eth_wrong_branch = eth_valid.clone();
        eth_wrong_branch.inclusion_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &eth_consensus.adapter_proof,
            &eth_wrong_branch,
        ));
        assert!(
            sccp_evm_receipt_proof_hash(
                eth_valid.source_domain,
                eth_valid.source_event_digest,
                eth_adapter.beacon_slot,
                eth_adapter.execution_block_number,
                eth_adapter.execution_block_hash,
                eth_adapter.execution_receipts_root,
                eth_adapter.beacon_finalized_root,
                eth_adapter.sync_committee_root,
                eth_adapter.receipt_root_index,
                &eth_adapter.receipt_trie_proof_nodes,
                &[vec![0xAA; 31]],
            )
            .is_none()
        );

        let bsc_bundle = sample_transfer_bundle(SCCP_DOMAIN_BSC, SCCP_DOMAIN_SORA, 706);
        let bsc_valid = source_chain_proof_from_bundle(&bsc_bundle);
        let bsc_consensus = source_consensus_proof_from_envelope(&bsc_valid);
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(bsc_adapter) =
            &bsc_consensus.adapter_proof
        else {
            panic!("expected BSC adapter proof");
        };
        let bsc_expected = sccp_bsc_receipt_proof_hash(
            bsc_valid.source_domain,
            bsc_valid.source_event_digest,
            bsc_adapter.validator_epoch,
            bsc_adapter.block_number,
            bsc_adapter.block_hash,
            bsc_adapter.receipts_root,
            bsc_adapter.validator_set_hash,
            bsc_adapter.commit_seal_hash,
            bsc_adapter.receipt_root_index,
            &bsc_adapter.receipt_trie_proof_nodes,
            &bsc_valid.inclusion_branch,
        )
        .expect("BSC receipt proof hash");
        assert_eq!(bsc_adapter.receipt_trie_proof_hash, bsc_expected);
        assert!(verify_sccp_source_adapter_proof_binding(
            &bsc_consensus.adapter_proof,
            &bsc_valid,
        ));

        let mut bsc_wrong_hash = bsc_consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::BscValidatorSetReceipt(adapter) = &mut bsc_wrong_hash else {
            panic!("expected BSC adapter proof");
        };
        adapter.receipt_trie_proof_hash[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &bsc_wrong_hash,
            &bsc_valid,
        ));
        let mut bsc_wrong_branch = bsc_valid.clone();
        bsc_wrong_branch.inclusion_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &bsc_consensus.adapter_proof,
            &bsc_wrong_branch,
        ));
        assert!(
            sccp_bsc_receipt_proof_hash(
                bsc_valid.source_domain,
                bsc_valid.source_event_digest,
                bsc_adapter.validator_epoch,
                bsc_adapter.block_number,
                bsc_adapter.block_hash,
                bsc_adapter.receipts_root,
                bsc_adapter.validator_set_hash,
                bsc_adapter.commit_seal_hash,
                bsc_adapter.receipt_root_index,
                &bsc_adapter.receipt_trie_proof_nodes,
                &[vec![0xAA; 31]],
            )
            .is_none()
        );

        let substrate_bundle =
            sample_transfer_bundle(SCCP_DOMAIN_SORA_KUSAMA, SCCP_DOMAIN_SORA, 707);
        let substrate_valid = source_chain_proof_from_bundle(&substrate_bundle);
        let substrate_consensus = source_consensus_proof_from_envelope(&substrate_valid);
        let SccpSourceAdapterProofV1::SubstrateGrandpaEvent(substrate_adapter) =
            &substrate_consensus.adapter_proof
        else {
            panic!("expected Substrate adapter proof");
        };
        let substrate_inclusion = source_inclusion_proof_from_envelope(&substrate_valid);
        let substrate_expected = sccp_substrate_storage_proof_hash(
            substrate_valid.source_domain,
            substrate_valid.source_event_digest,
            substrate_inclusion.leaf_index,
            substrate_adapter.finalized_block_number,
            substrate_adapter.grandpa_set_id,
            substrate_adapter.block_hash,
            substrate_adapter.authority_set_hash,
            substrate_adapter.events_root,
            &substrate_valid.inclusion_branch,
        )
        .expect("Substrate storage proof hash");
        assert_eq!(substrate_adapter.storage_proof_hash, substrate_expected);
        assert_eq!(
            sccp_substrate_grandpa_justification_hash(&substrate_adapter.grandpa_justification,),
            Some(substrate_adapter.grandpa_justification_hash),
        );
        assert!(verify_sccp_source_adapter_proof_binding(
            &substrate_consensus.adapter_proof,
            &substrate_valid,
        ));

        let mut substrate_wrong_hash = substrate_consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter) = &mut substrate_wrong_hash
        else {
            panic!("expected Substrate adapter proof");
        };
        adapter.storage_proof_hash[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &substrate_wrong_hash,
            &substrate_valid,
        ));
        let mut substrate_wrong_branch = substrate_valid.clone();
        substrate_wrong_branch.inclusion_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &substrate_consensus.adapter_proof,
            &substrate_wrong_branch,
        ));
        let mut substrate_wrong_leaf_index = substrate_valid.clone();
        let mut wrong_leaf_inclusion =
            source_inclusion_proof_from_envelope(&substrate_wrong_leaf_index);
        wrong_leaf_inclusion.leaf_index = 1;
        replace_source_inclusion_proof(&mut substrate_wrong_leaf_index, &wrong_leaf_inclusion);
        assert!(!verify_sccp_source_adapter_proof_binding(
            &substrate_consensus.adapter_proof,
            &substrate_wrong_leaf_index,
        ));
        assert!(
            sccp_substrate_storage_proof_hash(
                substrate_valid.source_domain,
                substrate_valid.source_event_digest,
                substrate_inclusion.leaf_index,
                substrate_adapter.finalized_block_number,
                substrate_adapter.grandpa_set_id,
                substrate_adapter.block_hash,
                substrate_adapter.authority_set_hash,
                substrate_adapter.events_root,
                &[vec![0xAA; 31]],
            )
            .is_none()
        );
        assert!(
            sccp_substrate_storage_proof_hash(
                substrate_valid.source_domain,
                [0; 32],
                substrate_inclusion.leaf_index,
                substrate_adapter.finalized_block_number,
                substrate_adapter.grandpa_set_id,
                substrate_adapter.block_hash,
                substrate_adapter.authority_set_hash,
                substrate_adapter.events_root,
                &substrate_valid.inclusion_branch,
            )
            .is_none()
        );
    }

    #[test]
    fn substrate_source_adapter_verifies_grandpa_justification_certificate() {
        let material =
            sccp_substrate_family_runtime_source_verifier_material_with_hashes_and_runtime_storage_v1(
            SCCP_DOMAIN_SORA_KUSAMA,
            sample_substrate_authority_set_hash(),
            [0xB2; 32],
            [0xC3; 32],
            [0xE5; 32],
            [0xD4; 32],
        )
        .expect("Substrate runtime source material");
        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_SORA_KUSAMA,
            SCCP_DOMAIN_SORA,
            708,
            Some(&material),
        );
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter) = &consensus.adapter_proof
        else {
            panic!("expected Substrate adapter proof");
        };

        assert!(verify_sccp_substrate_grandpa_justification_proof(
            adapter, &valid, &material,
        ));
        assert!(verify_sccp_substrate_runtime_storage_verification_proof(
            adapter, &valid, &material,
        ));
        assert_eq!(
            adapter.runtime_storage_verification_proof.circuit_id,
            SCCP_SUBSTRATE_RUNTIME_STORAGE_OPEN_VERIFY_CIRCUIT_ID_V1,
        );
        let template_material =
            sccp_substrate_family_runtime_source_verifier_material_v1(SCCP_DOMAIN_SORA_KUSAMA)
                .expect("Substrate runtime source material template");
        assert!(
            build_sccp_substrate_runtime_storage_verification_proof(
                adapter,
                valid.source_event_digest,
                source_inclusion_proof_from_envelope(&valid).leaf_index,
                &valid.inclusion_branch,
                &template_material,
            )
            .is_none(),
            "UI/runtime storage proof requests must reject template Substrate verifier material",
        );
        let mut missing_runtime_storage_proof = adapter.clone();
        missing_runtime_storage_proof.runtime_storage_verification_proof =
            SccpSourceStateVerificationProofV1::default();
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &missing_runtime_storage_proof,
            &valid,
            &material,
        ));
        let mut all_zero_runtime_storage_proof = adapter.clone();
        let runtime_storage_proof_len =
            adapter.runtime_storage_verification_proof.proof_bytes.len();
        all_zero_runtime_storage_proof
            .runtime_storage_verification_proof
            .proof_bytes = vec![0; runtime_storage_proof_len];
        assert!(
            !verify_sccp_substrate_runtime_storage_verification_proof(
                &all_zero_runtime_storage_proof,
                &valid,
                &material,
            ),
            "Substrate runtime-storage verifier must reject all-zero source-state proof capsules"
        );
        assert!(
            !verify_sccp_substrate_grandpa_justification_proof(
                &all_zero_runtime_storage_proof,
                &valid,
                &material,
            ),
            "Substrate production source proofs must not bind all-zero runtime-storage proof capsules"
        );
        assert!(
            !sccp_source_adapter_proof_shape_is_bounded(
                &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(all_zero_runtime_storage_proof),
            ),
            "Substrate source-adapter preflight must reject all-zero runtime-storage proof capsules"
        );
        let mut tampered_runtime_storage_proof = adapter.clone();
        tampered_runtime_storage_proof
            .runtime_storage_verification_proof
            .proof_bytes[0] ^= 0x01;
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &tampered_runtime_storage_proof,
            &valid,
            &material,
        ));
        assert_eq!(
            sccp_substrate_authority_set_hash(
                &adapter.grandpa_justification.authority_public_keys,
                &adapter.grandpa_justification.authority_weights,
            ),
            Some(material.source_trust_anchor_hash),
        );
        assert_eq!(
            adapter.grandpa_justification.precommit_message_hash,
            sccp_substrate_grandpa_precommit_hash(
                adapter.source_domain,
                adapter.finalized_block_number,
                adapter.grandpa_set_id,
                adapter.block_hash,
                adapter.authority_set_hash,
                adapter.events_root,
                adapter.storage_proof_hash,
            ),
        );
        assert_eq!(
            sccp_substrate_grandpa_justification_hash(&adapter.grandpa_justification),
            Some(adapter.grandpa_justification_hash),
        );

        let mut wrong_signature = adapter.clone();
        wrong_signature.grandpa_justification.signatures[0][0] ^= 0x01;
        wrong_signature.grandpa_justification_hash =
            sccp_substrate_grandpa_justification_hash(&wrong_signature.grandpa_justification)
                .expect("Substrate GRANDPA justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_signature,
            &valid,
            &material,
        ));

        let mut insufficient_weight = adapter.clone();
        insufficient_weight.grandpa_justification.signers_bitmap = vec![0b0000_0011];
        insufficient_weight
            .grandpa_justification
            .signatures
            .truncate(2);
        insufficient_weight.grandpa_justification.signed_weight = 2;
        insufficient_weight.grandpa_justification_hash =
            sccp_substrate_grandpa_justification_hash(&insufficient_weight.grandpa_justification)
                .expect("Substrate GRANDPA justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &insufficient_weight,
            &valid,
            &material,
        ));

        let mut wrong_anchor = material.clone();
        wrong_anchor.source_trust_anchor_hash[0] ^= 0x01;
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            adapter,
            &valid,
            &wrong_anchor,
        ));

        let mut wrong_precommit = adapter.clone();
        wrong_precommit.grandpa_justification.precommit_message_hash[0] ^= 0x01;
        wrong_precommit.grandpa_justification_hash =
            sccp_substrate_grandpa_justification_hash(&wrong_precommit.grandpa_justification)
                .expect("Substrate GRANDPA justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_precommit,
            &valid,
            &material,
        ));

        let mut wrong_justification_hash = adapter.clone();
        wrong_justification_hash.grandpa_justification_hash[0] ^= 0x01;
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_justification_hash,
            &valid,
            &material,
        ));
    }

    #[test]
    fn substrate_source_adapter_verifies_authority_set_transition_chain() {
        let parent_signers = sample_substrate_authority_keypairs();
        let active_signers = sample_substrate_next_authority_keypairs();
        let parent_authority_set_hash = sample_substrate_authority_set_hash_for(&parent_signers);
        let active_authority_set_payload =
            sample_substrate_authority_set_payload_for(&active_signers);
        let active_authority_set_hash =
            sccp_substrate_authority_set_hash_from_payload(&active_authority_set_payload)
                .expect("active Substrate authority set hash");
        let material =
            sccp_substrate_family_runtime_source_verifier_material_with_hashes_and_runtime_storage_v1(
            SCCP_DOMAIN_SORA_KUSAMA,
            parent_authority_set_hash,
            [0xB2; 32],
            [0xC3; 32],
            [0xE5; 32],
            [0xD4; 32],
        )
        .expect("Substrate source material anchored to parent authority set");

        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_SORA_KUSAMA,
            SCCP_DOMAIN_SORA,
            711,
            Some(&material),
        );
        let mut valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::SubstrateGrandpaEvent(mut adapter) = consensus.adapter_proof
        else {
            panic!("expected Substrate adapter proof");
        };

        adapter.authority_set_hash = active_authority_set_hash;
        adapter.storage_proof_hash = sccp_substrate_storage_proof_hash(
            valid.source_domain,
            valid.source_event_digest,
            source_inclusion_proof_from_envelope(&valid).leaf_index,
            adapter.finalized_block_number,
            adapter.grandpa_set_id,
            adapter.block_hash,
            adapter.authority_set_hash,
            adapter.events_root,
            &valid.inclusion_branch,
        )
        .expect("active Substrate storage proof hash");
        adapter.grandpa_justification = sample_substrate_grandpa_justification_proof_for(
            &active_signers,
            adapter.source_domain,
            adapter.finalized_block_number,
            adapter.grandpa_set_id,
            adapter.block_hash,
            adapter.authority_set_hash,
            adapter.events_root,
            adapter.storage_proof_hash,
        );
        adapter.grandpa_justification_hash =
            sccp_substrate_grandpa_justification_hash(&adapter.grandpa_justification)
                .expect("active Substrate GRANDPA justification hash");
        adapter.authority_set_transition_proofs =
            vec![sample_substrate_authority_set_transition_proof(
                adapter.source_domain,
                &parent_signers,
                adapter.grandpa_set_id - 1,
                adapter.grandpa_set_id,
                adapter.finalized_block_number - 1,
                [0xDB; 32],
                parent_authority_set_hash,
                active_authority_set_hash,
                active_authority_set_payload.clone(),
            )];
        adapter.runtime_storage_verification_proof =
            build_sccp_substrate_runtime_storage_verification_proof(
                &adapter,
                valid.source_event_digest,
                source_inclusion_proof_from_envelope(&valid).leaf_index,
                &valid.inclusion_branch,
                &material,
            )
            .expect("active Substrate runtime storage verification proof");
        assert_eq!(
            sccp_substrate_authority_set_payload_hash(&active_authority_set_payload),
            adapter.authority_set_transition_proofs[0].next_authority_set_payload_hash
        );
        replace_source_adapter_proof_with_material(
            &mut valid,
            SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter.clone()),
            &material,
        );

        assert!(
            verify_sccp_source_chain_proof_envelope_structure_with_material(&valid, &material,)
        );
        assert!(verify_sccp_substrate_grandpa_justification_proof(
            &adapter, &valid, &material,
        ));

        let mut missing_transition = adapter.clone();
        missing_transition.authority_set_transition_proofs.clear();
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &missing_transition,
            &valid,
            &material,
        ));

        let mut wrong_parent = adapter.clone();
        wrong_parent.authority_set_transition_proofs[0].parent_authority_set_hash[0] ^= 0x01;
        wrong_parent.authority_set_transition_proofs[0].transition_justification_hash =
            sccp_substrate_authority_set_transition_justification_hash(
                &wrong_parent.authority_set_transition_proofs[0],
            )
            .expect("Substrate transition justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_parent,
            &valid,
            &material,
        ));

        let mut wrong_payload_hash = adapter.clone();
        wrong_payload_hash.authority_set_transition_proofs[0].next_authority_set_payload[0] ^= 0x01;
        wrong_payload_hash.authority_set_transition_proofs[0].transition_justification_hash =
            sccp_substrate_authority_set_transition_justification_hash(
                &wrong_payload_hash.authority_set_transition_proofs[0],
            )
            .expect("Substrate transition justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_payload_hash,
            &valid,
            &material,
        ));

        let wrong_next_payload = sample_substrate_authority_set_payload_for(&parent_signers);
        let mut wrong_next_payload_proof = adapter.clone();
        let wrong_next_transition =
            wrong_next_payload_proof.authority_set_transition_proofs[0].clone();
        wrong_next_payload_proof.authority_set_transition_proofs[0] =
            sample_substrate_authority_set_transition_proof(
                adapter.source_domain,
                &parent_signers,
                wrong_next_transition.from_grandpa_set_id,
                wrong_next_transition.to_grandpa_set_id,
                wrong_next_transition.transition_block_number,
                wrong_next_transition.transition_block_hash,
                parent_authority_set_hash,
                active_authority_set_hash,
                wrong_next_payload,
            );
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_next_payload_proof,
            &valid,
            &material,
        ));

        let mut wrong_next_set = adapter.clone();
        wrong_next_set.authority_set_transition_proofs[0].next_authority_set_hash[0] ^= 0x01;
        wrong_next_set.authority_set_transition_proofs[0].transition_message_hash =
            sccp_substrate_authority_set_transition_message_hash(
                wrong_next_set.authority_set_transition_proofs[0].source_domain,
                wrong_next_set.authority_set_transition_proofs[0].from_grandpa_set_id,
                wrong_next_set.authority_set_transition_proofs[0].to_grandpa_set_id,
                wrong_next_set.authority_set_transition_proofs[0].transition_block_number,
                wrong_next_set.authority_set_transition_proofs[0].transition_block_hash,
                wrong_next_set.authority_set_transition_proofs[0].parent_authority_set_hash,
                wrong_next_set.authority_set_transition_proofs[0].next_authority_set_hash,
                wrong_next_set.authority_set_transition_proofs[0].next_authority_set_payload_hash,
            );
        wrong_next_set.authority_set_transition_proofs[0].transition_justification_hash =
            sccp_substrate_authority_set_transition_justification_hash(
                &wrong_next_set.authority_set_transition_proofs[0],
            )
            .expect("Substrate transition justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_next_set,
            &valid,
            &material,
        ));

        let mut wrong_transition_signature = adapter;
        wrong_transition_signature.authority_set_transition_proofs[0]
            .grandpa_justification
            .signatures[0][0] ^= 0x01;
        wrong_transition_signature.authority_set_transition_proofs[0]
            .transition_justification_hash =
            sccp_substrate_authority_set_transition_justification_hash(
                &wrong_transition_signature.authority_set_transition_proofs[0],
            )
            .expect("Substrate transition justification hash");
        assert!(!verify_sccp_substrate_grandpa_justification_proof(
            &wrong_transition_signature,
            &valid,
            &material,
        ));
    }

    #[test]
    fn substrate_source_adapter_preflight_rejects_oversized_shapes() {
        let bundle = sample_transfer_bundle(SCCP_DOMAIN_SORA_KUSAMA, SCCP_DOMAIN_SORA, 707);
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter) = consensus.adapter_proof
        else {
            panic!("expected Substrate adapter proof");
        };
        assert!(sccp_source_adapter_proof_shape_is_bounded(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter.clone()),
        ));
        assert!(verify_sccp_source_adapter_proof_binding(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(adapter.clone()),
            &valid,
        ));

        let mut too_many_authorities = adapter.clone();
        too_many_authorities
            .grandpa_justification
            .authority_public_keys = vec![vec![0x11; 32]; SCCP_SUBSTRATE_MAX_AUTHORITIES + 1];
        too_many_authorities.grandpa_justification.authority_weights =
            vec![1; SCCP_SUBSTRATE_MAX_AUTHORITIES + 1];
        too_many_authorities.grandpa_justification.signers_bitmap =
            vec![0xFF; (SCCP_SUBSTRATE_MAX_AUTHORITIES + 1).div_ceil(8)];
        assert!(!sccp_source_adapter_proof_shape_is_bounded(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(too_many_authorities.clone()),
        ));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(too_many_authorities),
            &valid,
        ));

        let mut oversized_signers_bitmap = adapter.clone();
        oversized_signers_bitmap
            .grandpa_justification
            .signers_bitmap = vec![0xFF; SCCP_SUBSTRATE_MAX_AUTHORITIES.div_ceil(8) + 1];
        assert!(!sccp_source_adapter_proof_shape_is_bounded(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(oversized_signers_bitmap),
        ));

        let mut too_many_transitions = adapter.clone();
        too_many_transitions.authority_set_transition_proofs = vec![
            SccpSubstrateAuthoritySetTransitionProofV1::default();
            SCCP_SUBSTRATE_MAX_AUTHORITY_SET_TRANSITIONS + 1
        ];
        assert!(!sccp_source_adapter_proof_shape_is_bounded(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(too_many_transitions),
        ));

        let mut oversized_transition_payload = adapter;
        let transition = SccpSubstrateAuthoritySetTransitionProofV1 {
            next_authority_set_payload: vec![
                0xAA;
                SCCP_SUBSTRATE_MAX_AUTHORITY_SET_PAYLOAD_BYTES + 1
            ],
            ..SccpSubstrateAuthoritySetTransitionProofV1::default()
        };
        oversized_transition_payload.authority_set_transition_proofs = vec![transition];
        assert!(!sccp_source_adapter_proof_shape_is_bounded(
            &SccpSourceAdapterProofV1::SubstrateGrandpaEvent(oversized_transition_payload),
        ));

        let oversized_public_keys = vec![vec![0x22; 32]; SCCP_SUBSTRATE_MAX_AUTHORITIES + 1];
        let oversized_weights = vec![1; SCCP_SUBSTRATE_MAX_AUTHORITIES + 1];
        let oversized_payload = canonical_sccp_substrate_authority_set_bytes(
            &oversized_public_keys,
            &oversized_weights,
        );
        assert!(oversized_payload.is_none());
    }

    #[test]
    fn substrate_authority_set_transition_transcript_matches_sdk_fixture() {
        let parent_authority_public_keys = vec![vec![0x11; 32], vec![0x22; 32], vec![0x33; 32]];
        let parent_authority_weights = vec![5, 7, 11];
        let parent_authority_set_payload = canonical_sccp_substrate_authority_set_bytes(
            &parent_authority_public_keys,
            &parent_authority_weights,
        )
        .expect("Substrate parent authority-set payload");
        assert_eq!(
            encode_lower_hex(&parent_authority_set_payload),
            "0103000000111111111111111111111111111111111111111111111111111111111111111105000000000000002222222222222222222222222222222222222222222222222222222222222222070000000000000033333333333333333333333333333333333333333333333333333333333333330b00000000000000",
        );
        let parent_authority_set_hash =
            sccp_substrate_authority_set_hash_from_payload(&parent_authority_set_payload)
                .expect("Substrate parent authority-set hash");
        assert_eq!(
            parent_authority_set_hash,
            test_h256_from_hex(
                "0xb2efd5d86304ea728a8a9ed4013aab8f3e10c0cf862e859c9cade55e660934ef"
            )
        );

        let next_authority_public_keys = vec![vec![0xaa; 32], vec![0xbb; 32], vec![0xcc; 32]];
        let next_authority_weights = vec![13, 17, 19];
        let next_authority_set_payload = canonical_sccp_substrate_authority_set_bytes(
            &next_authority_public_keys,
            &next_authority_weights,
        )
        .expect("Substrate next authority-set payload");
        assert_eq!(
            encode_lower_hex(&next_authority_set_payload),
            "0103000000aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa0d00000000000000bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb1100000000000000cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc1300000000000000",
        );
        let next_authority_set_hash =
            sccp_substrate_authority_set_hash_from_payload(&next_authority_set_payload)
                .expect("Substrate next authority-set hash");
        let next_authority_set_payload_hash =
            sccp_substrate_authority_set_payload_hash(&next_authority_set_payload);
        assert_eq!(
            next_authority_set_hash,
            test_h256_from_hex(
                "0x07cdbba0d61fdd4324b571dd793965e52acbf7f4c163af328e26c92c047501b3"
            )
        );
        assert_eq!(
            next_authority_set_payload_hash,
            test_h256_from_hex(
                "0x12ce972498ba5cd8a760aee0429fdc30d8b6447890e1bf77d8dde46f86b40d85"
            )
        );

        let transition_message_hash = sccp_substrate_authority_set_transition_message_hash(
            SCCP_DOMAIN_SORA_KUSAMA,
            41,
            42,
            9001,
            [0x44; 32],
            parent_authority_set_hash,
            next_authority_set_hash,
            next_authority_set_payload_hash,
        );
        assert_eq!(
            canonical_sccp_substrate_authority_set_transition_message_bytes(
                SCCP_DOMAIN_SORA_KUSAMA,
                41,
                42,
                9001,
                [0x44; 32],
                parent_authority_set_hash,
                next_authority_set_hash,
                next_authority_set_payload_hash,
            )
            .len(),
            157
        );
        assert_eq!(
            transition_message_hash,
            test_h256_from_hex(
                "0x60589333bf798bf592b2642d0fbac39b4e9305576cd2ebe9dd1f448a97a0596b"
            )
        );

        let mut proof = SccpSubstrateAuthoritySetTransitionProofV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_SORA_KUSAMA,
            from_grandpa_set_id: 41,
            to_grandpa_set_id: 42,
            transition_block_number: 9001,
            transition_block_hash: [0x44; 32],
            parent_authority_set_hash,
            next_authority_set_hash,
            next_authority_set_payload,
            next_authority_set_payload_hash,
            transition_message_hash,
            transition_justification_hash: [0u8; 32],
            grandpa_justification: SccpSubstrateGrandpaJustificationProofV1 {
                version: 1,
                total_weight: 23,
                signed_weight: 12,
                precommit_message_hash: transition_message_hash,
                authority_public_keys: parent_authority_public_keys,
                authority_weights: parent_authority_weights,
                signers_bitmap: vec![0x03],
                signatures: vec![vec![0x77; 64], vec![0x88; 64]],
            },
        };
        proof.transition_justification_hash =
            sccp_substrate_authority_set_transition_justification_hash(&proof)
                .expect("Substrate authority-set transition justification hash");
        assert_eq!(
            canonical_sccp_substrate_authority_set_transition_justification_bytes(&proof)
                .expect("Substrate transition justification bytes")
                .len(),
            684
        );
        assert_eq!(
            proof.transition_justification_hash,
            test_h256_from_hex(
                "0x20b1996d21f10ffacc430735eeea2ad9c64a32bebd85c5186c4435b77480dd36"
            )
        );
    }

    #[test]
    fn substrate_authority_set_rejects_zero_public_keys() {
        let zero_authority_keys = vec![vec![0u8; 32]];
        let authority_weights = vec![1];
        assert!(
            canonical_sccp_substrate_authority_set_bytes(&zero_authority_keys, &authority_weights)
                .is_none()
        );

        let mut raw_payload = Vec::new();
        raw_payload.push(1);
        raw_payload.extend_from_slice(&1u32.to_le_bytes());
        raw_payload.extend_from_slice(&[0u8; 32]);
        raw_payload.extend_from_slice(&1u64.to_le_bytes());
        assert!(decode_sccp_substrate_authority_set_payload(&raw_payload).is_none());
        assert!(sccp_substrate_authority_set_hash_from_payload(&raw_payload).is_none());

        let proof = SccpSubstrateGrandpaJustificationProofV1 {
            version: 1,
            total_weight: 1,
            signed_weight: 1,
            precommit_message_hash: [0x44; 32],
            authority_public_keys: zero_authority_keys,
            authority_weights,
            signers_bitmap: vec![0x01],
            signatures: vec![vec![0x55; 64]],
        };
        assert!(canonical_sccp_substrate_grandpa_justification_bytes(&proof).is_none());
    }

    #[test]
    fn ton_source_adapter_binds_shard_proof_hash_to_inclusion_witness() {
        let bundle = sample_transfer_bundle(SCCP_DOMAIN_TON, SCCP_DOMAIN_SORA, 703);
        let valid = source_chain_proof_from_bundle(&bundle);
        let consensus = source_consensus_proof_from_envelope(&valid);
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &consensus.adapter_proof
        else {
            panic!("expected TON adapter proof");
        };
        let expected = sccp_ton_shard_proof_hash_with_dictionary(
            valid.source_event_digest,
            adapter.masterchain_seqno,
            adapter.masterchain_block_hash,
            adapter.shard_workchain_id,
            adapter.shard_shard,
            adapter.shard_seqno,
            adapter.shard_block_hash,
            adapter.shard_file_hash,
            adapter.shard_state_root,
            adapter.transaction_root,
            adapter.transaction_lt,
            &adapter.shard_state_proof_boc,
            adapter.shard_state_dictionary_root,
            adapter.shard_state_dictionary_key_bit_len,
            &adapter.shard_state_dictionary_key,
            &adapter.shard_state_dictionary_proof_boc,
            adapter.shard_state_leaf_index,
            &adapter.shard_state_inclusion_branch,
            &valid.inclusion_branch,
        )
        .expect("TON shard proof hash");
        assert_eq!(adapter.shard_proof_hash, expected);
        let valid_shard_workchain_id = adapter.shard_workchain_id;
        let valid_shard_shard = adapter.shard_shard;
        let valid_shard_seqno = adapter.shard_seqno;
        let valid_shard_file_hash = adapter.shard_file_hash;
        let valid_transaction_lt = adapter.transaction_lt;
        assert!(verify_sccp_ton_shard_state_opening(adapter));
        assert!(verify_sccp_source_adapter_proof_binding(
            &consensus.adapter_proof,
            &valid,
        ));
        assert!(verify_sccp_ton_masterchain_config_proof(adapter));
        assert_eq!(
            sccp_ton_masterchain_config_proof_hash(&adapter.masterchain_config_proof),
            Some(adapter.masterchain_config_proof_hash)
        );
        assert_eq!(
            adapter.masterchain_config_proof.config_leaf_hash,
            sccp_ton_masterchain_config_leaf_hash(
                adapter.source_domain,
                adapter.masterchain_seqno,
                adapter.masterchain_block_hash,
                adapter.shard_state_root,
                adapter.validator_set_hash,
                adapter.masterchain_config_proof.validator_set_payload_hash,
            )
        );
        let material = sample_ready_source_verifier_material(SCCP_DOMAIN_TON);
        assert!(verify_sccp_ton_masterchain_validator_signatures_proof(
            adapter, &valid, &material,
        ));
        assert_eq!(
            sccp_ton_validator_set_hash(
                &adapter.validator_signature_proof.validator_public_keys,
                &adapter.validator_signature_proof.validator_weights,
            ),
            Some(material.source_trust_anchor_hash),
        );

        let mut wrong_hash = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut wrong_hash else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_proof_hash[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_hash,
            &valid,
        ));

        let mut wrong_branch = valid.clone();
        wrong_branch.inclusion_branch[0][0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &consensus.adapter_proof,
            &wrong_branch,
        ));

        let mut wrong_shard_block = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut wrong_shard_block else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_block_hash[0] ^= 0x01;
        let wrong_shard_block_hash: H256 = adapter.shard_block_hash;
        let wrong_shard_state_root_hash: H256 = adapter.shard_state_root;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_shard_block,
            &valid,
        ));

        let mut wrong_shard_state_adapter = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut wrong_shard_state_adapter
        else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_state_root[0] ^= 0x01;
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_shard_state_adapter,
            &valid,
        ));

        let mut wrong_shard_state_dictionary_proof = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) =
            &mut wrong_shard_state_dictionary_proof
        else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_state_dictionary_proof_boc[12] ^= 0x01;
        assert!(!verify_sccp_ton_shard_state_opening(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_shard_state_dictionary_proof,
            &valid,
        ));

        let mut wrong_config_dictionary_proof = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) =
            &mut wrong_config_dictionary_proof
        else {
            panic!("expected TON adapter proof");
        };
        adapter.masterchain_config_proof.config_dictionary_proof_boc[12] ^= 0x01;
        assert!(!verify_sccp_ton_masterchain_config_proof(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_config_dictionary_proof,
            &valid,
        ));

        let mut wrong_config_value_hash = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut wrong_config_value_hash
        else {
            panic!("expected TON adapter proof");
        };
        adapter.masterchain_config_proof.config_value_hash[0] ^= 0x01;
        assert!(
            sccp_ton_masterchain_config_proof_hash(&adapter.masterchain_config_proof).is_none()
        );
        assert!(!verify_sccp_ton_masterchain_config_proof(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_config_value_hash,
            &valid,
        ));

        let mut wrong_config_index = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut wrong_config_index else {
            panic!("expected TON adapter proof");
        };
        adapter.masterchain_config_proof.config_leaf_index = 0;
        assert_ne!(
            adapter.masterchain_config_proof.config_leaf_index,
            SCCP_TON_CURRENT_VALIDATOR_SET_CONFIG_PARAM
        );
        assert!(!verify_sccp_ton_masterchain_config_proof(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_config_index,
            &valid,
        ));

        let mut oversized_shard_state_branch = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) =
            &mut oversized_shard_state_branch
        else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_state_inclusion_branch =
            vec![vec![0x12; 32]; SCCP_MAX_SOURCE_MERKLE_BRANCH_NODES + 1];
        assert!(!sccp_ton_source_adapter_shape_is_bounded(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &oversized_shard_state_branch,
            &valid,
        ));

        let mut oversized_config_branch = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) = &mut oversized_config_branch
        else {
            panic!("expected TON adapter proof");
        };
        adapter.masterchain_config_proof.config_inclusion_branch =
            vec![vec![0x34; 32]; SCCP_MAX_SOURCE_MERKLE_BRANCH_NODES + 1];
        assert!(!sccp_ton_source_adapter_shape_is_bounded(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &oversized_config_branch,
            &valid,
        ));

        let mut oversized_source_state_label = consensus.adapter_proof.clone();
        let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) =
            &mut oversized_source_state_label
        else {
            panic!("expected TON adapter proof");
        };
        adapter.shard_state_verification_proof.circuit_id =
            "x".repeat(SCCP_SOURCE_STATE_MAX_PROOF_LABEL_BYTES + 1);
        assert!(!sccp_ton_source_adapter_shape_is_bounded(adapter));
        assert!(!verify_sccp_source_adapter_proof_binding(
            &oversized_source_state_label,
            &valid,
        ));

        let mut wrong_config_payload_hash = consensus.adapter_proof.clone();
        {
            let SccpSourceAdapterProofV1::TonMasterchainShard(adapter) =
                &mut wrong_config_payload_hash
            else {
                panic!("expected TON adapter proof");
            };
            adapter.masterchain_config_proof.validator_set_payload_hash[0] ^= 0x01;
            adapter.masterchain_config_proof.config_leaf_hash =
                sccp_ton_masterchain_config_leaf_hash(
                    adapter.source_domain,
                    adapter.masterchain_seqno,
                    adapter.masterchain_block_hash,
                    adapter.shard_state_root,
                    adapter.validator_set_hash,
                    adapter.masterchain_config_proof.validator_set_payload_hash,
                );
            assert!(
                sccp_ton_masterchain_config_proof_hash(&adapter.masterchain_config_proof).is_none()
            );
            assert!(!verify_sccp_ton_masterchain_config_proof(adapter));
        }
        assert!(!verify_sccp_source_adapter_proof_binding(
            &wrong_config_payload_hash,
            &valid,
        ));

        assert!(
            sccp_ton_shard_proof_hash(
                valid.source_event_digest,
                valid.finality_height,
                valid.finality_block_hash,
                valid_shard_workchain_id,
                valid_shard_shard,
                valid_shard_seqno,
                wrong_shard_block_hash,
                valid_shard_file_hash,
                wrong_shard_state_root_hash,
                valid.receipt_or_message_root,
                valid_transaction_lt,
                0,
                &[vec![0xAA; 32]],
                &[vec![0xAA; 31]],
            )
            .is_none()
        );
    }

