    #[test]
    fn tron_solid_block_header_transcript_matches_sdk_fixture() {
        let block_number = 12_345;
        let timestamp_ms = 1_700_000_012_345;
        let tx_trie_root = [0xDD; 32];
        let account_state_root = [0xEE; 32];
        let parent_block_number = block_number - 1;
        let parent_timestamp_ms = timestamp_ms - 1;
        let parent_tx_trie_root = [0xCC; 32];
        let parent_account_state_root = [0xAA; 32];
        let grandparent_block_id = [0xBB; 32];
        let witness_address = {
            let mut address = vec![0x41];
            address.extend_from_slice(&[0x11; 20]);
            address
        };
        let parent_raw_data = canonical_sccp_tron_raw_block_header_bytes(
            parent_block_number,
            parent_tx_trie_root,
            parent_account_state_root,
            grandparent_block_id,
            &witness_address,
            1,
            parent_timestamp_ms,
        )
        .expect("TRON parent raw block-header bytes");
        let parent_raw_data_hash = sha256_bytes(&parent_raw_data);
        let parent_block_id =
            sccp_tron_block_id_from_raw_data_hash(parent_block_number, parent_raw_data_hash);
        let raw_data = canonical_sccp_tron_raw_block_header_bytes(
            block_number,
            tx_trie_root,
            account_state_root,
            parent_block_id,
            &witness_address,
            1,
            timestamp_ms,
        )
        .expect("TRON raw block-header bytes");
        assert_eq!(
            encode_lower_hex(&raw_data),
            "08b9b096ffbc311220dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd1a200000000000003038701e5a1cd89912e6118f8aa18222c8b90867fedcca84c4d438b9604a1541111111111111111111111111111111111111111150015a20eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
        );

        let raw_data_hash = sha256_bytes(&raw_data);
        let block_id = sccp_tron_block_id_from_raw_data_hash(block_number, raw_data_hash);
        let proof = SccpTronSolidBlockHeaderProofV1 {
            version: 1,
            raw_data,
            witness_signature: vec![0xAA; 65],
            parent_raw_data,
            parent_witness_signature: vec![0xBB; 65],
            raw_data_hash,
            parent_raw_data_hash,
            block_id,
            tx_trie_root,
            account_state_root,
            parent_block_id,
            witness_address,
            timestamp_ms,
            header_version: 1,
        };
        assert_eq!(
            raw_data_hash,
            test_h256_from_hex(
                "0x614a09275b6d0fffb6bc08fb34f737c093d9dd2adefccb04344715e2619c8286",
            ),
        );
        assert_eq!(
            parent_raw_data_hash,
            test_h256_from_hex(
                "0x5647d462e78851c6701e5a1cd89912e6118f8aa18222c8b90867fedcca84c4d4",
            ),
        );
        assert_eq!(
            block_id,
            test_h256_from_hex(
                "0x0000000000003039b6bc08fb34f737c093d9dd2adefccb04344715e2619c8286",
            ),
        );
        assert_eq!(
            parent_block_id,
            test_h256_from_hex(
                "0x0000000000003038701e5a1cd89912e6118f8aa18222c8b90867fedcca84c4d4",
            ),
        );
        assert!(canonical_sccp_tron_solid_block_header_proof_bytes(&proof).is_none());
        assert!(sccp_tron_solid_block_header_proof_hash(&proof).is_none());

        let signed_proof = sample_tron_solid_block_header_proof(block_number, tx_trie_root);
        assert_eq!(
            canonical_sccp_tron_solid_block_header_proof_bytes(&signed_proof)
                .expect("signed TRON solid-block header proof bytes")
                .len(),
            650,
        );
        assert!(h256_is_nonzero(
            &sccp_tron_solid_block_header_proof_hash(&signed_proof)
                .expect("signed TRON solid-block header proof hash")
        ));
        let mut oversized_raw_data = signed_proof;
        oversized_raw_data.raw_data = vec![0xAA; SCCP_TRON_MAX_RAW_HEADER_BYTES + 1];
        assert!(canonical_sccp_tron_solid_block_header_proof_bytes(&oversized_raw_data).is_none());
    }

