    #[test]
    #[allow(clippy::too_many_lines)]
    fn transparent_fastpq_open_verify_summary_reports_binding_metadata() {
        let bundle = sample_message_bundle(SccpPayloadV1::Transfer(TransferPayloadV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_SORA,
            dest_domain: SCCP_DOMAIN_TON,
            nonce: 26,
            asset_home_domain: SCCP_DOMAIN_SORA,
            asset_id_codec: SCCP_CODEC_TEXT_UTF8,
            asset_id: b"xor#open-verify-summary".to_vec(),
            amount: 123,
            sender_codec: SCCP_CODEC_TEXT_UTF8,
            sender: b"nexus:summary".to_vec(),
            recipient_codec: SCCP_CODEC_TON_RAW,
            recipient: b"0:abcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcd"
                .to_vec(),
            route_id_codec: SCCP_CODEC_TEXT_UTF8,
            route_id: b"nexus:ton:summary".to_vec(),
        }));
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_TON).expect("ton manifest");
        let public_inputs =
            sccp_message_transparent_public_inputs(&bundle).expect("message public inputs");
        let proof_bytes =
            build_sccp_message_transparent_fastpq_proof_bytes(&bundle, &manifest).expect("proof");
        let summary = summarize_sccp_message_transparent_open_verify_proof(&proof_bytes)
            .expect("proof summary");

        assert_eq!(summary.version, 1);
        assert_eq!(summary.backend, "stark");
        assert_eq!(
            summary.circuit_id,
            SCCP_TRANSPARENT_OPEN_VERIFY_CIRCUIT_ID_V1
        );
        assert_eq!(
            summary.vk_hash,
            sccp_message_transparent_fastpq_verifier_commitment(&manifest)
                .expect("verifier commitment")
        );
        assert_eq!(
            summary.public_inputs_schema_hash,
            prefixed_blake2b(
                SCCP_TRANSPARENT_OPEN_VERIFY_SCHEMA_HASH_PREFIX_V1,
                &sccp_message_transparent_open_verify_schema_descriptor(&manifest),
            )
        );
        assert_eq!(
            summary.public_inputs_schema_len_bytes as usize,
            sccp_message_transparent_open_verify_schema_descriptor(&manifest).len()
        );
        assert_eq!(summary.public_input_column_count, 6);
        assert_eq!(summary.public_input_word_count, 6);
        assert_eq!(
            summary.backend_proof_len_bytes as usize,
            build_sccp_message_transparent_fastpq_raw_proof_bytes(
                &build_sccp_message_transparent_fastpq_batch(&bundle, &manifest)
                    .expect("fastpq batch"),
            )
            .expect("raw proof")
            .len()
        );
        assert_eq!(summary.aux_len_bytes, 0);
        let inner =
            build_sccp_message_transparent_inner_proof(&bundle, &manifest).expect("inner proof");
        let ton_payload = build_sccp_ton_internal_message_submission_payload(
            &manifest,
            &proof_bytes,
            &public_inputs,
            &bundle,
            inner.statement_hash,
            &manifest.destination_binding,
        )
        .expect("ton payload");
        assert_eq!(
            summarize_sccp_message_transparent_open_verify_proof_from_artifact(
                &NexusSccpMessageTransparentProofV1 {
                    version: 1,
                    local_domain: manifest.local_domain,
                    counterparty_domain: manifest.counterparty_domain,
                    security_model: manifest.security_model,
                    anchor_governance: manifest.anchor_governance,
                    destination_binding: manifest.destination_binding.clone(),
                    proof_family: manifest.proof_family.clone(),
                    verifier_backend: manifest.verifier_backend.clone(),
                    message_backend: manifest.message_backend.clone(),
                    registry_backend: manifest.registry_backend.clone(),
                    manifest_seed: manifest.manifest_seed.clone(),
                    finality_model: manifest.finality_model,
                    verifier_target: manifest.verifier_target,
                    public_inputs: public_inputs.clone(),
                    proof_bytes: proof_bytes.clone(),
                    submission_package: SccpCounterpartySubmissionPackageV1 {
                        version: 1,
                        proof_family: manifest.proof_family.clone(),
                        verifier_backend: manifest.verifier_backend.clone(),
                        envelope_encoding: "ton_message_body_boc_v1".to_owned(),
                        submission_kind: manifest.submission_template.submission_kind.clone(),
                        verifier_entrypoint: manifest
                            .submission_template
                            .verifier_entrypoint
                            .clone(),
                        platform_payload: SccpPlatformSubmissionPayloadV1::TonInternalMessage(
                            ton_payload,
                        ),
                        arguments: Vec::new(),
                        envelope_bytes: vec![0xCC],
                    },
                    bundle: bundle.clone(),
                }
            ),
            Some(summary.clone())
        );
        assert_eq!(
            build_sccp_message_transparent_open_verify_summary_from_bundle(&bundle),
            Some(summary)
        );
    }

    #[test]
    fn ton_internal_message_submission_rejects_mismatched_context() {
        let bundle = sample_message_bundle(SccpPayloadV1::Transfer(TransferPayloadV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_SORA,
            dest_domain: SCCP_DOMAIN_TON,
            nonce: 27,
            asset_home_domain: SCCP_DOMAIN_SORA,
            asset_id_codec: SCCP_CODEC_TEXT_UTF8,
            asset_id: b"xor#ton-context".to_vec(),
            amount: 321,
            sender_codec: SCCP_CODEC_TEXT_UTF8,
            sender: b"nexus:ton-context".to_vec(),
            recipient_codec: SCCP_CODEC_TON_RAW,
            recipient: b"0:abcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcd"
                .to_vec(),
            route_id_codec: SCCP_CODEC_TEXT_UTF8,
            route_id: b"nexus:ton:context".to_vec(),
        }));
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_TON).expect("ton manifest");
        let public_inputs =
            sccp_message_transparent_public_inputs(&bundle).expect("message public inputs");
        let proof_bytes =
            build_sccp_message_transparent_fastpq_proof_bytes(&bundle, &manifest).expect("proof");
        let inner =
            build_sccp_message_transparent_inner_proof(&bundle, &manifest).expect("inner proof");

        assert!(
            build_sccp_ton_internal_message_submission_payload(
                &manifest,
                &proof_bytes,
                &public_inputs,
                &bundle,
                inner.statement_hash,
                &manifest.destination_binding,
            )
            .is_some(),
            "valid TON context must still package"
        );

        let mut wrong_target_inputs = public_inputs.clone();
        wrong_target_inputs.target_domain = SCCP_DOMAIN_SORA;
        assert!(
            build_sccp_ton_internal_message_submission_payload(
                &manifest,
                &proof_bytes,
                &wrong_target_inputs,
                &bundle,
                inner.statement_hash,
                &manifest.destination_binding,
            )
            .is_none(),
            "TON package must not accept local-domain public inputs"
        );

        let mut wrong_backend = manifest.clone();
        wrong_backend.verifier_backend.key = "debug-ton-contract".to_owned();
        assert!(
            build_sccp_ton_internal_message_submission_payload(
                &wrong_backend,
                &proof_bytes,
                &public_inputs,
                &bundle,
                inner.statement_hash,
                &wrong_backend.destination_binding,
            )
            .is_none(),
            "TON package must stay locked to ton-contract-v1"
        );

        let mut wrong_binding = manifest.destination_binding.clone();
        wrong_binding.binding_hash = [0x99; 32];
        assert!(
            build_sccp_ton_internal_message_submission_payload(
                &manifest,
                &proof_bytes,
                &public_inputs,
                &bundle,
                inner.statement_hash,
                &wrong_binding,
            )
            .is_none(),
            "TON package must use the manifest destination binding"
        );

        let bundle_bytes = canonical_nexus_sccp_message_bundle_bytes(&bundle);
        assert!(
            build_sccp_ton_message_body_boc(
                &manifest,
                &manifest.destination_binding,
                &public_inputs,
                &proof_bytes,
                &bundle_bytes,
                [0; 32],
            )
            .is_none(),
            "TON message body must bind a non-zero statement hash"
        );
        assert!(
            build_sccp_ton_message_body_boc(
                &manifest,
                &manifest.destination_binding,
                &public_inputs,
                &proof_bytes,
                &[],
                inner.statement_hash,
            )
            .is_none(),
            "TON message body must include the canonical SCCP bundle bytes"
        );
        assert!(
            build_sccp_ton_message_body_boc(
                &manifest,
                &manifest.destination_binding,
                &public_inputs,
                &proof_bytes,
                &[0, 0],
                inner.statement_hash,
            )
            .is_none(),
            "TON message body must reject all-zero bundle bytes"
        );
        let oversized_bundle_bytes = vec![0xAA; SCCP_NATIVE_RECURSIVE_MAX_PROOF_BYTES + 1];
        assert!(
            build_sccp_ton_message_body_boc(
                &manifest,
                &manifest.destination_binding,
                &public_inputs,
                &proof_bytes,
                &oversized_bundle_bytes,
                inner.statement_hash,
            )
            .is_none(),
            "TON message body must keep bundle bytes inside the native recursive payload corridor"
        );
    }

    #[test]
    fn ton_proof_request_hash_matches_cross_sdk_vector() {
        let public_inputs = SccpMessageTransparentPublicInputsV1 {
            version: 1,
            message_id: [0x11; 32],
            payload_hash: [0x22; 32],
            target_domain: SCCP_DOMAIN_TON,
            commitment_root: [0x33; 32],
            finality_height: 123_456_789,
            finality_block_hash: [0x44; 32],
        };
        let deployment_binding = SccpSourceAdapterDeploymentBindingV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_TON,
            target_domain: SCCP_DOMAIN_SORA,
            source_adapter_deployment_hash: [0xAA; 32],
            source_adapter_deployment_receipt_hash: [0xBB; 32],
        };
        let request = build_sccp_ton_proof_request(
            &public_inputs,
            &[1, 2, 3, 4, 5, 6, 7, 8, 9],
            Some(&[0x51, 0x52, 0x53]),
            [0x55; 32],
            [0x66; 32],
            [0x42; 32],
            &deployment_binding,
        )
        .expect("canonical TON proof request");

        assert_eq!(
            request.public_inputs_bytes,
            decode_hex_bytes(
                "0x011111111111111111111111111111111111111111111111111111111111111111222222222222222222222222222222222222222222222222222222222222222204000000333333333333333333333333333333333333333333333333333333333333333315cd5b07000000004444444444444444444444444444444444444444444444444444444444444444",
            )
            .expect("cross-SDK TON public-input byte vector")
        );
        assert_eq!(
            request.source_adapter_deployment_binding_hash,
            decode_fixed_hex_bytes::<32>(
                "0x7d35b186e3d49aed31693e33d33355fa8fa9032160c929f2c7fe260094f6ccdf",
            )
            .expect("cross-SDK TON deployment binding hash vector")
        );
        assert_eq!(
            request.request_hash,
            decode_fixed_hex_bytes::<32>(
                "0xb3a61f09923efd639a0263de6b45eec6ddd5de679bfaab1b6ec1c591fd1b1d1b",
            )
            .expect("cross-SDK TON request hash vector")
        );

        let proof_result = wrap_sccp_ton_proof_result(&[0x91, 0x92, 0x93, 0x94, 0x95], &request)
            .expect("wrapped TON proof result");
        assert_eq!(
            proof_result.envelope_hash,
            decode_fixed_hex_bytes::<32>(
                "0xa2bc6697b237fd4b2dd3f60f187a184793104a99372dcdf60c7ec585ef32f5ab",
            )
            .expect("cross-SDK TON envelope hash vector")
        );
    }

    #[test]
    fn ton_proof_result_submission_requires_canonical_ui_result() {
        let bundle = sample_message_bundle(SccpPayloadV1::Transfer(TransferPayloadV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_SORA,
            dest_domain: SCCP_DOMAIN_TON,
            nonce: 28,
            asset_home_domain: SCCP_DOMAIN_SORA,
            asset_id_codec: SCCP_CODEC_TEXT_UTF8,
            asset_id: b"xor#ton-proof-result".to_vec(),
            amount: 654,
            sender_codec: SCCP_CODEC_TEXT_UTF8,
            sender: b"nexus:ton-proof-result".to_vec(),
            recipient_codec: SCCP_CODEC_TON_RAW,
            recipient: b"0:abcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcd"
                .to_vec(),
            route_id_codec: SCCP_CODEC_TEXT_UTF8,
            route_id: b"nexus:ton:proof-result".to_vec(),
        }));
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_TON).expect("ton manifest");
        let public_inputs =
            sccp_message_transparent_public_inputs(&bundle).expect("message public inputs");
        let bundle_bytes = canonical_nexus_sccp_message_bundle_bytes(&bundle);
        let inner =
            build_sccp_message_transparent_inner_proof(&bundle, &manifest).expect("inner proof");
        let deployment_binding = SccpSourceAdapterDeploymentBindingV1 {
            version: 1,
            source_domain: SCCP_DOMAIN_TON,
            target_domain: SCCP_DOMAIN_SORA,
            source_adapter_deployment_hash: [0xAA; 32],
            source_adapter_deployment_receipt_hash: [0xBB; 32],
        };
        let source_proof_bytes = [0x51, 0x52, 0x53];
        let source_state_verifier_hash = [0x42; 32];
        let request = build_sccp_ton_proof_request(
            &public_inputs,
            &bundle_bytes,
            Some(&source_proof_bytes),
            inner.statement_hash,
            manifest.destination_binding.binding_hash,
            source_state_verifier_hash,
            &deployment_binding,
        )
        .expect("canonical TON proof request");

        assert_eq!(request.backend, SCCP_TON_CONTRACT_PROOF_BACKEND_V1);
        assert_eq!(request.source_domain, SCCP_DOMAIN_TON);
        assert_eq!(request.target_domain, SCCP_DOMAIN_TON);
        assert_eq!(request.public_inputs.target_domain, SCCP_DOMAIN_TON);
        assert_eq!(
            request.source_adapter_deployment_binding_hash,
            sccp_source_adapter_deployment_binding_hash(&deployment_binding)
                .expect("deployment binding hash")
        );
        assert_eq!(
            request.source_adapter_deployment_binding_hash,
            decode_fixed_hex_bytes::<32>(
                "0x7d35b186e3d49aed31693e33d33355fa8fa9032160c929f2c7fe260094f6ccdf",
            )
            .expect("cross-SDK TON deployment binding hash vector"),
            "Rust must keep TON source-adapter deployment binding bytes in parity with JS/Python/mobile SDKs"
        );

        let recursive_proof_bytes = vec![0x91; 128];
        let proof_result = wrap_sccp_ton_proof_result(&recursive_proof_bytes, &request)
            .expect("wrapped TON proof result");
        let raw_boc = build_sccp_ton_message_body_boc(
            &manifest,
            &manifest.destination_binding,
            &public_inputs,
            &recursive_proof_bytes,
            &bundle_bytes,
            inner.statement_hash,
        )
        .expect("raw TON body");
        let typed_payload = build_sccp_ton_internal_message_submission_payload_from_proof_result(
            &manifest,
            &manifest.destination_binding,
            &proof_result,
        )
        .expect("typed TON submission payload");
        assert_eq!(typed_payload.message_body_boc, raw_boc);
        assert_eq!(typed_payload.proof_bytes, recursive_proof_bytes);
        assert_eq!(typed_payload.bundle_bytes, bundle_bytes);
        assert_eq!(
            typed_payload.destination_binding_hash,
            manifest.destination_binding.binding_hash
        );

        let oversized_message_body_proof =
            vec![0xAB; SCCP_TON_MAX_BOC_CELLS * SCCP_TON_MAX_CELL_DATA_BYTES];
        let oversized_proof_result =
            wrap_sccp_ton_proof_result(&oversized_message_body_proof, &request)
                .expect("oversized TON message-body proof can still be wrapped");
        assert!(
            build_sccp_ton_message_body_boc_from_proof_result(
                &manifest,
                &manifest.destination_binding,
                &oversized_proof_result,
            )
            .is_none(),
            "TON message-body BOC construction must enforce the bounded cell cap"
        );

        let mut tampered_envelope = proof_result.clone();
        tampered_envelope.envelope_hash = [0; 32];
        assert!(
            build_sccp_ton_message_body_boc_from_proof_result(
                &manifest,
                &manifest.destination_binding,
                &tampered_envelope,
            )
            .is_none(),
            "TON submission must reject proof results whose envelope hash drifts"
        );

        let mut tampered_destination = proof_result.clone();
        tampered_destination.destination_binding_hash = [0xCC; 32];
        assert!(
            build_sccp_ton_internal_message_submission_payload_from_proof_result(
                &manifest,
                &manifest.destination_binding,
                &tampered_destination,
            )
            .is_none(),
            "TON submission must reject proof results for another destination binding"
        );

        let mut wrong_route_request = request.clone();
        wrong_route_request
            .source_adapter_deployment_binding
            .target_domain = SCCP_DOMAIN_TON;
        assert!(
            wrap_sccp_ton_proof_result(&recursive_proof_bytes, &wrong_route_request).is_none(),
            "TON proof results must bind the governed TON -> SORA source adapter deployment"
        );

        assert!(
            build_sccp_ton_proof_request(
                &public_inputs,
                &bundle_bytes,
                Some(&[0, 0, 0]),
                inner.statement_hash,
                manifest.destination_binding.binding_hash,
                source_state_verifier_hash,
                &deployment_binding,
            )
            .is_none(),
            "TON proof requests must reject all-zero source proof bytes"
        );
        let oversized_source_proof_bytes = vec![0xAA; SCCP_SOURCE_STATE_MAX_PROOF_BYTES + 1];
        assert!(
            build_sccp_ton_proof_request(
                &public_inputs,
                &bundle_bytes,
                Some(&oversized_source_proof_bytes),
                inner.statement_hash,
                manifest.destination_binding.binding_hash,
                source_state_verifier_hash,
                &deployment_binding,
            )
            .is_none(),
            "TON proof requests must keep source proof bytes inside the source-state proof corridor"
        );
        assert!(
            build_sccp_ton_proof_request(
                &public_inputs,
                &[0, 0],
                Some(&source_proof_bytes),
                inner.statement_hash,
                manifest.destination_binding.binding_hash,
                source_state_verifier_hash,
                &deployment_binding,
            )
            .is_none(),
            "TON proof requests must reject all-zero bundle bytes before UI proving"
        );
        let oversized_bundle_bytes = vec![0xAA; SCCP_NATIVE_RECURSIVE_MAX_PROOF_BYTES + 1];
        assert!(
            build_sccp_ton_proof_request(
                &public_inputs,
                &oversized_bundle_bytes,
                Some(&source_proof_bytes),
                inner.statement_hash,
                manifest.destination_binding.binding_hash,
                source_state_verifier_hash,
                &deployment_binding,
            )
            .is_none(),
            "TON proof requests must keep bundle bytes inside the native recursive payload corridor"
        );
        assert!(
            build_sccp_ton_proof_request(
                &public_inputs,
                &bundle_bytes,
                Some(&source_proof_bytes),
                inner.statement_hash,
                manifest.destination_binding.binding_hash,
                sccp_ton_template_source_state_verifier_hash_v1(),
                &deployment_binding,
            )
            .is_none(),
            "TON proof requests must not package template source-state verifier material"
        );
    }

    #[test]
    fn transparent_fastpq_open_verify_summary_allows_metadata_only_envelopes() {
        let open = StarkFriOpenProofV1 {
            version: 1,
            public_inputs: vec![vec![[0x55; 32]]],
            envelope_bytes: vec![0xAA, 0xBB, 0xCC],
        };
        let open_proof_bytes = norito::to_bytes(&open).expect("encode open proof");
        let proof_bytes = norito::to_bytes(&OpenVerifyEnvelope {
            backend: BackendTag::Stark,
            circuit_id: SCCP_TRANSPARENT_OPEN_VERIFY_CIRCUIT_ID_V1.to_owned(),
            vk_hash: [0x66; 32],
            public_inputs: vec![0x77, 0x88, 0x99],
            proof_bytes: open_proof_bytes.clone(),
            aux: vec![0xDE, 0xAD],
        })
        .expect("encode envelope");

        let summary = summarize_sccp_message_transparent_open_verify_proof(&proof_bytes)
            .expect("proof summary");

        assert_eq!(summary.backend, "stark");
        assert_eq!(
            summary.circuit_id,
            SCCP_TRANSPARENT_OPEN_VERIFY_CIRCUIT_ID_V1
        );
        assert_eq!(summary.vk_hash, [0x66; 32]);
        assert_eq!(
            summary.public_inputs_schema_hash,
            prefixed_blake2b(
                SCCP_TRANSPARENT_OPEN_VERIFY_SCHEMA_HASH_PREFIX_V1,
                &[0x77, 0x88, 0x99]
            )
        );
        assert_eq!(summary.public_inputs_schema_len_bytes, 3);
        assert_eq!(summary.public_input_column_count, 1);
        assert_eq!(summary.public_input_word_count, 1);
        assert_eq!(
            summary.open_proof_len_bytes as usize,
            open_proof_bytes.len()
        );
        assert_eq!(summary.backend_proof_len_bytes, 3);
        assert_eq!(summary.aux_len_bytes, 2);
    }

    #[test]
    fn transparent_fastpq_open_verify_summary_rejects_bad_envelope_shapes() {
        let open = StarkFriOpenProofV1 {
            version: 1,
            public_inputs: vec![vec![[0x55; 32]]],
            envelope_bytes: vec![0xAA, 0xBB, 0xCC],
        };
        let mut env = OpenVerifyEnvelope {
            backend: BackendTag::Stark,
            circuit_id: SCCP_TRANSPARENT_OPEN_VERIFY_CIRCUIT_ID_V1.to_owned(),
            vk_hash: [0x66; 32],
            public_inputs: vec![0x77, 0x88, 0x99],
            proof_bytes: norito::to_bytes(&open).expect("encode open proof"),
            aux: Vec::new(),
        };

        let mut wrong_backend = env.clone();
        wrong_backend.backend = BackendTag::Groth16;
        assert!(
            summarize_sccp_message_transparent_open_verify_proof(
                &norito::to_bytes(&wrong_backend).expect("encode wrong backend envelope"),
            )
            .is_none()
        );

        let mut malformed_open = env.clone();
        malformed_open.proof_bytes = vec![0x01, 0x02];
        assert!(
            summarize_sccp_message_transparent_open_verify_proof(
                &norito::to_bytes(&malformed_open).expect("encode malformed open envelope"),
            )
            .is_none()
        );

        let mut non_v1_open = open;
        non_v1_open.version = 2;
        env.proof_bytes = norito::to_bytes(&non_v1_open).expect("encode non-v1 open proof");
        assert!(
            summarize_sccp_message_transparent_open_verify_proof(
                &norito::to_bytes(&env).expect("encode non-v1 open envelope"),
            )
            .is_none()
        );
    }

    #[test]
    fn proof_manifests_mark_current_counterparty_lanes_non_production() {
        for domain in SCCP_CORE_REMOTE_DOMAINS {
            let manifest = sccp_proof_manifest_for_domain(domain).expect("manifest");
            assert!(!manifest.production_ready);
            assert_eq!(
                manifest.disabled_reason.as_deref(),
                sccp_lane_disabled_reason_for_domain(domain)
            );
            assert_eq!(manifest.destination_rollout.domain, domain);
            assert_eq!(
                manifest.destination_rollout.chain,
                sccp_chain_key_for_domain(domain).expect("chain key")
            );
            assert!(!manifest.destination_rollout.immutable_verifier_ready);
            assert!(!manifest.destination_rollout.anchors_ready);
            assert!(!manifest.destination_rollout.blockers.is_empty());
            assert!(!sccp_destination_rollout_is_production_ready(
                domain,
                &manifest.destination_rollout
            ));
        }
    }

    #[test]
    fn production_policy_uses_ethereum_mainnet_lane_launch() {
        assert_eq!(
            SccpLaunchModeV1::default(),
            SccpLaunchModeV1::EthereumMainnetLane
        );
        let policy = sccp_production_policy_v1();
        assert_eq!(policy.launch_mode, SccpLaunchModeV1::EthereumMainnetLane);
        assert_eq!(
            policy.proof_submitter_policy,
            SccpProofSubmitterPolicyV1::Permissionless
        );
        assert_eq!(
            policy.route_activation_policy,
            SccpRouteActivationPolicyV1::GovernanceAllowlist
        );
        assert!(!policy.per_message_human_approval_required);
        assert!(!sccp_all_lanes_launch_ready_v1());
        assert!(!sccp_lane_production_ready_for_domain(SCCP_DOMAIN_ETH));
    }

    #[test]
    fn production_readiness_lists_source_destination_and_route_blockers() {
        let readiness =
            sccp_lane_production_readiness_for_domain(SCCP_DOMAIN_ETH).expect("eth readiness");

        assert_eq!(
            readiness.source_proof_plan,
            SccpSourceProofPlanV1::EthereumBeaconReceiptProof
        );
        assert_eq!(
            readiness.destination_verifier_plan,
            SccpDestinationVerifierPlanV1::EvmGroth16Bn254Adapter
        );
        assert_eq!(
            readiness.verifier_backend.key,
            SCCP_EVM_GROTH16_BN254_PROOF_BACKEND_V1
        );
        assert!(readiness.permissionless_submission);
        assert!(!readiness.source_adapter_ready);
        assert!(
            readiness
                .source_adapter_engine
                .adapter_statement_binding_ready
        );
        assert!(
            readiness
                .source_adapter_engine
                .source_verifier_material
                .placeholder_material
        );
        assert!(
            !readiness
                .source_adapter_engine
                .source_verifier_material_ready
        );
        assert!(!sccp_source_verifier_material_is_production_ready(
            &readiness.source_adapter_engine.source_verifier_material
        ));
        assert!(readiness.source_adapter_engine.adapter_open_verify_ready);
        assert!(readiness.source_adapter_engine.finality_model_ready);
        assert!(
            !readiness
                .source_adapter_engine
                .external_consensus_verifier_ready
        );
        assert!(
            !readiness
                .source_adapter_engine
                .external_message_inclusion_verifier_ready
        );
        assert!(!readiness.source_adapter_engine.source_trust_anchor_ready);
        assert!(!readiness.source_adapter_engine.production_ready);
        assert!(!readiness.immutable_verifier_ready);
        assert!(!readiness.anchors_ready);
        assert!(!readiness.routes_allowlisted);
        assert_eq!(readiness.route_allowlist.domain, SCCP_DOMAIN_ETH);
        assert_eq!(
            readiness.route_allowlist.chain,
            sccp_chain_key_for_domain(SCCP_DOMAIN_ETH).expect("eth chain key")
        );
        assert_eq!(
            readiness.route_allowlist.activation_policy,
            SccpRouteActivationPolicyV1::GovernanceAllowlist
        );
        assert!(readiness.route_allowlist.route_allowlist_id.is_none());
        assert!(readiness.route_allowlist.route_allowlist_hash.is_none());
        assert!(!readiness.route_allowlist.routes_allowlisted);
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &readiness.route_allowlist
        ));
        assert!(!readiness.production_ready);
        assert!(
            readiness
                .blockers
                .iter()
                .any(|blocker| blocker.contains("route allowlist is not anchored"))
        );
        assert!(
            readiness
                .blockers
                .iter()
                .any(|blocker| blocker.contains("governance has not activated"))
        );
        assert!(
            readiness
                .blockers
                .iter()
                .any(|blocker| blocker.contains("destination verifier rollout material"))
        );
        assert!(
            readiness
                .blockers
                .iter()
                .any(|blocker| blocker.contains("Ethereum recursive source-adapter verifier"))
        );
        assert!(
            readiness
                .blockers
                .iter()
                .all(|blocker| !blocker.contains("all-lanes-at-once"))
        );
    }

    #[test]
    fn ton_readiness_blocker_reflects_remaining_deployment_evidence() {
        let readiness =
            sccp_lane_production_readiness_for_domain(SCCP_DOMAIN_TON).expect("ton readiness");

        assert!(!readiness.source_adapter_ready);
        assert!(!readiness.production_ready);
        assert!(
            readiness.blockers.iter().any(|blocker| {
                blocker.contains("TON governed full-light-client verifier deployment")
            }),
            "TON readiness must report the remaining governed deployment/canary blocker: {:?}",
            readiness.blockers
        );
        assert!(
            readiness
                .blockers
                .iter()
                .all(|blocker| !blocker.contains("shard-state proof evaluation")),
            "TON readiness must not report shard-state proof evaluation as missing after the verifier path is implemented: {:?}",
            readiness.blockers
        );
    }

    #[test]
    fn route_allowlist_production_gate_rejects_incomplete_or_replayed_material() {
        let blocked = sccp_route_allowlist_for_domain(SCCP_DOMAIN_ETH).expect("eth allowlist");
        assert_eq!(blocked.domain, SCCP_DOMAIN_ETH);
        assert_eq!(
            blocked.chain,
            sccp_chain_key_for_domain(SCCP_DOMAIN_ETH).expect("eth chain key")
        );
        assert_eq!(
            blocked.activation_policy,
            SccpRouteActivationPolicyV1::GovernanceAllowlist
        );
        assert!(blocked.route_allowlist_id.is_none());
        assert!(blocked.route_allowlist_hash.is_none());
        assert!(!blocked.routes_allowlisted);
        assert!(!blocked.blockers.is_empty());
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &blocked
        ));

        let exact_hash = format!("0x{}", "66".repeat(32));
        let profiled = sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_ETH, exact_hash.clone())
            .expect("exact route allowlist");
        assert_eq!(
            profiled.route_allowlist_id.as_deref(),
            Some(SCCP_ETH_MAINNET_ROUTE_ALLOWLIST_ID_V1)
        );
        assert_eq!(
            profiled.route_allowlist_hash.as_deref(),
            Some(exact_hash.as_str())
        );
        assert!(profiled.routes_allowlisted);
        assert!(profiled.blockers.is_empty());
        assert!(sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &profiled
        ));

        let mut eth_with_tron_canary = profiled.clone();
        eth_with_tron_canary.tron_route_canary_call_data_sha256 =
            Some(format!("0x{}", "91".repeat(32)));
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &eth_with_tron_canary
        ));

        let mut tron_with_evm_canary =
            sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_TRON, format!("0x{}", "77".repeat(32)))
                .expect("TRON route allowlist");
        tron_with_evm_canary.evm_route_canary_transaction_hash =
            Some(format!("0x{}", "92".repeat(32)));
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_TRON,
            &tron_with_evm_canary
        ));

        let mut ton_with_tron_canary =
            sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_TON, format!("0x{}", "78".repeat(32)))
                .expect("TON route allowlist");
        ton_with_tron_canary.tron_route_canary_payload_hash =
            Some(format!("0x{}", "93".repeat(32)));
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_TON,
            &ton_with_tron_canary
        ));

        let mut sol_with_ton_canary =
            sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_SOL, format!("0x{}", "79".repeat(32)))
                .expect("Solana route allowlist");
        sol_with_ton_canary.ton_route_canary_last_transaction_hash =
            Some(format!("0x{}", "94".repeat(32)));
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_SOL,
            &sol_with_ton_canary
        ));

        let mut generic = blocked.clone();
        generic.route_allowlist_id = Some("sccp:eth:route-allowlist:generic:v1".to_owned());
        generic.route_allowlist_hash = Some(exact_hash.clone());
        generic.routes_allowlisted = true;
        generic.blockers.clear();
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &generic
        ));

        let mut wrong_domain = profiled.clone();
        wrong_domain.domain = SCCP_DOMAIN_BSC;
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &wrong_domain
        ));

        let mut wrong_chain = profiled.clone();
        wrong_chain.chain = sccp_chain_key_for_domain(SCCP_DOMAIN_BSC)
            .expect("bsc chain key")
            .to_owned();
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &wrong_chain
        ));

        let mut missing_id = profiled.clone();
        missing_id.route_allowlist_id = None;
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &missing_id
        ));

        let mut missing_hash = profiled.clone();
        missing_hash.route_allowlist_hash = None;
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &missing_hash
        ));

        let mut zero_hash = profiled.clone();
        zero_hash.route_allowlist_hash = Some(format!("0x{}", "00".repeat(32)));
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &zero_hash
        ));
        assert!(
            sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_ETH, format!("0x{}", "00".repeat(32)))
                .is_none()
        );

        let mut malformed_hash = profiled.clone();
        malformed_hash.route_allowlist_hash = Some("0x1234".to_owned());
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &malformed_hash
        ));
        assert!(sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_ETH, "0x1234".to_owned()).is_none());

        let mut blocked_profile = profiled.clone();
        blocked_profile
            .blockers
            .push("governance has not activated this SCCP route profile".to_owned());
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &blocked_profile
        ));

        let mut inactive_profile = profiled.clone();
        inactive_profile.routes_allowlisted = false;
        assert!(!sccp_route_allowlist_is_production_ready(
            SCCP_DOMAIN_ETH,
            &inactive_profile
        ));

        assert!(sccp_route_allowlist_for_domain(SCCP_DOMAIN_SORA).is_none());
        assert!(sccp_profiled_route_allowlist_v1(SCCP_DOMAIN_SORA, exact_hash).is_none());

        let vector_hash = sccp_route_allowlist_hash_for_lane_evidence_v1(
            SCCP_DOMAIN_ETH,
            [0x11; 32],
            [0x22; 32],
            [0x33; 32],
        )
        .expect("route allowlist vector hash");
        assert_eq!(
            vector_hash,
            decode_fixed_hex_bytes::<32>(
                "5cbb92b2e55d2cad382b687ec60703217fd13be788f38a8e92d459e5fe82aca5",
            )
            .expect("route allowlist vector")
        );
        assert!(
            sccp_route_allowlist_hash_for_lane_evidence_v1(
                SCCP_DOMAIN_ETH,
                [0x00; 32],
                [0x22; 32],
                [0x33; 32],
            )
            .is_none()
        );
        assert!(
            sccp_route_allowlist_hash_for_lane_evidence_v1(
                SCCP_DOMAIN_ETH,
                [0x11; 32],
                [0x11; 32],
                [0x33; 32],
            )
            .is_none()
        );
        assert!(
            sccp_route_allowlist_hash_for_lane_evidence_v1(
                SCCP_DOMAIN_ETH,
                [0x11; 32],
                [0x22; 32],
                [0x11; 32],
            )
            .is_none()
        );
    }

    fn route_allowlist_with_test_canary(
        allowlist: SccpRouteAllowlistReadinessV1,
        destination_rollout: &SccpDestinationRolloutV1,
        route_canary_evidence_hash: H256,
    ) -> SccpRouteAllowlistReadinessV1 {
        let destination_binding_hash = decode_fixed_hex_bytes::<32>(
            destination_rollout
                .destination_binding_hash
                .as_deref()
                .expect("destination binding hash"),
        )
        .expect("decode destination binding hash");
        sccp_route_allowlist_with_canary_evidence_v1(
            allowlist,
            route_canary_evidence_hash,
            destination_binding_hash,
        )
        .expect("route canary evidence")
    }

    #[test]
    fn route_allowlist_lane_canary_builder_rejects_source_record_hash_replay() {
        let source_material =
            sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
                SCCP_DOMAIN_ETH,
                [0x11; 32],
                [0x12; 32],
                [0x13; 32],
                [0x14; 32],
                sample_evm_message_emitter_address(SCCP_DOMAIN_ETH),
                sample_evm_source_bridge_code_hash(SCCP_DOMAIN_ETH),
            )
            .expect("ETH source material");
        let source_deployment =
            sccp_source_adapter_engine_deployment_from_material_v1(&source_material, [0x15; 32])
                .expect("ETH source deployment");
        let destination_rollout = sccp_evm_mainnet_destination_rollout_with_binding_v1(
            SCCP_DOMAIN_ETH,
            "0x1111111111111111111111111111111111111111".to_owned(),
            format!("0x{}", "22".repeat(32)),
            format!("0x{}", "23".repeat(32)),
            encode_0x_lower_hex(&sccp_eth_mainnet_network_id_word_v1()),
            format!("0x{}", "25".repeat(20)),
        )
        .expect("ETH destination rollout");
        let route_allowlist = sccp_profiled_route_allowlist_for_lane_evidence_v1(
            SCCP_DOMAIN_ETH,
            &source_material,
            &source_deployment,
            &destination_rollout,
        )
        .expect("evidence-bound ETH route allowlist");
        let destination_binding_hash = decode_fixed_hex_bytes::<32>(
            destination_rollout
                .destination_binding_hash
                .as_deref()
                .expect("destination binding hash"),
        )
        .expect("decode destination binding hash");
        let source_material_hash = sccp_source_verifier_material_hash(&source_material);
        let source_deployment_hash = sccp_source_adapter_engine_deployment_hash(&source_deployment);

        for replayed_hash in [source_material_hash, source_deployment_hash] {
            assert!(
                sccp_route_allowlist_with_lane_canary_evidence_v1(
                    route_allowlist.clone(),
                    replayed_hash,
                    destination_binding_hash,
                    source_material_hash,
                    source_deployment_hash,
                )
                .is_none(),
                "lane-aware canary builder must reject source record hash replay"
            );
        }

        let generic_allowlist = sccp_route_allowlist_with_lane_canary_evidence_v1(
            route_allowlist.clone(),
            [0xe1; 32],
            destination_binding_hash,
            source_material_hash,
            source_deployment_hash,
        )
        .expect("generic non-replayed canary evidence");
        assert!(
            !sccp_route_allowlist_canary_evidence_is_bound(
                SCCP_DOMAIN_ETH,
                &generic_allowlist,
                &destination_rollout,
                &decode_fixed_hex_bytes::<32>(
                    generic_allowlist
                        .route_allowlist_hash
                        .as_deref()
                        .expect("route allowlist hash")
                )
                .expect("decode route allowlist hash"),
                &destination_binding_hash,
                &source_material_hash,
                &source_deployment_hash,
            ),
            "EVM route canary evidence must include MessageProofAccepted metadata"
        );

        let route_canary_hash = sccp_evm_route_canary_evidence_hash_v1(
            SCCP_DOMAIN_ETH,
            decode_fixed_hex_bytes::<32>(
                route_allowlist
                    .route_allowlist_hash
                    .as_deref()
                    .expect("route allowlist hash"),
            )
            .expect("decode route allowlist hash"),
            destination_binding_hash,
            &destination_rollout,
            [0xea; 32],
            3,
            18_765_432,
            [0xe8; 32],
            [0xe9; 32],
            [0xeb; 32],
            [0xdd; 32],
            [0xdc; 32],
            SCCP_DOMAIN_ETH,
            [0xf1; 32],
            [0xee; 32],
            [0xed; 32],
            [0xec; 32],
            1,
            SCCP_DOMAIN_SORA,
            true,
        )
        .expect("EVM route canary hash");
        let route_canary_bytes = canonical_sccp_evm_route_canary_evidence_bytes_v1(
            SCCP_DOMAIN_ETH,
            decode_fixed_hex_bytes::<32>(
                route_allowlist
                    .route_allowlist_hash
                    .as_deref()
                    .expect("route allowlist hash"),
            )
            .expect("decode route allowlist hash"),
            destination_binding_hash,
            &destination_rollout,
            [0xea; 32],
            3,
            18_765_432,
            [0xe8; 32],
            [0xe9; 32],
            [0xeb; 32],
            [0xdd; 32],
            [0xdc; 32],
            SCCP_DOMAIN_ETH,
            [0xf1; 32],
            [0xee; 32],
            [0xed; 32],
            [0xec; 32],
            1,
            SCCP_DOMAIN_SORA,
            true,
        )
        .expect("EVM route canary bytes");
        assert_eq!(
            route_canary_bytes[0], 3,
            "EVM canary transcript must use the v3 receipt-block-bound layout"
        );
        assert_eq!(
            &route_canary_bytes[89..97],
            &18_765_432u64.to_le_bytes(),
            "EVM canary transcript must bind the receipt block number"
        );
        assert_eq!(
            &route_canary_bytes[97..129],
            &[0xe8; 32],
            "EVM canary transcript must bind the receipt block hash"
        );
        assert_eq!(
            &route_canary_bytes[129..161],
            &[0xe9; 32],
            "EVM canary transcript must bind the block receiptsRoot"
        );
        assert_eq!(
            &route_canary_bytes[225..229],
            &SCCP_DOMAIN_SORA.to_le_bytes(),
            "EVM canary transcript must bind the SORA proof source-domain word"
        );
        assert_eq!(
            &route_canary_bytes[229..233],
            &SCCP_DOMAIN_ETH.to_le_bytes(),
            "EVM canary transcript must bind the target EVM-family lane"
        );
        assert_eq!(
            &route_canary_bytes[297..329],
            &[0xed; 32],
            "EVM canary transcript must bind the finality height public input"
        );
        assert_eq!(
            &route_canary_bytes[329..361],
            &[0xec; 32],
            "EVM canary transcript must bind the finality block hash public input"
        );
        assert_eq!(
            &route_canary_bytes[393..397],
            &1u32.to_le_bytes(),
            "EVM canary transcript must bind Groth16 proof ABI version"
        );
        assert_eq!(
            &route_canary_bytes[397..401],
            &SCCP_DOMAIN_SORA.to_le_bytes(),
            "EVM canary transcript must bind the SORA proof source-domain word"
        );
        assert_eq!(
            *route_canary_bytes.last().expect("used-message proof flag"),
            1,
            "EVM canary transcript must bind the consumed-message flag"
        );
        assert!(h256_is_nonzero(&route_canary_hash));
        assert_ne!(route_canary_hash, source_material_hash);
        assert_ne!(route_canary_hash, source_deployment_hash);
        assert!(
            sccp_evm_route_canary_evidence_hash_v1(
                SCCP_DOMAIN_ETH,
                decode_fixed_hex_bytes::<32>(
                    route_allowlist
                        .route_allowlist_hash
                        .as_deref()
                        .expect("route allowlist hash"),
                )
                .expect("decode route allowlist hash"),
                destination_binding_hash,
                &destination_rollout,
                [0xea; 32],
                3,
                18_765_432,
                [0xe8; 32],
                [0xe9; 32],
                [0xeb; 32],
                [0xdd; 32],
                [0xdc; 32],
                SCCP_DOMAIN_ETH,
                [0xf1; 32],
                [0xee; 32],
                [0xea; 32],
                [0xec; 32],
                1,
                SCCP_DOMAIN_SORA,
                true,
            )
            .is_none(),
            "EVM canary transcript roles must reject transaction/finality replay"
        );
        let assert_rejected_canary = |target_domain: u32,
                                      proof_version: u32,
                                      proof_source_domain: u32,
                                      used_message_proof| {
            assert!(
                sccp_evm_route_canary_evidence_hash_v1(
                    SCCP_DOMAIN_ETH,
                    decode_fixed_hex_bytes::<32>(
                        route_allowlist
                            .route_allowlist_hash
                            .as_deref()
                            .expect("route allowlist hash"),
                    )
                    .expect("decode route allowlist hash"),
                    destination_binding_hash,
                    &destination_rollout,
                    [0xea; 32],
                    3,
                    18_765_432,
                    [0xe8; 32],
                    [0xe9; 32],
                    [0xeb; 32],
                    [0xdd; 32],
                    [0xdc; 32],
                    target_domain,
                    [0xf1; 32],
                    [0xee; 32],
                    [0xed; 32],
                    [0xec; 32],
                    proof_version,
                    proof_source_domain,
                    used_message_proof,
                )
                .is_none(),
                "EVM canary hash must reject wrong target/proof metadata"
            );
            assert!(
                sccp_evm_route_allowlist_with_lane_canary_evidence_v1(
                    route_allowlist.clone(),
                    &destination_rollout,
                    destination_binding_hash,
                    source_material_hash,
                    source_deployment_hash,
                    [0xea; 32],
                    3,
                    18_765_432,
                    [0xe8; 32],
                    [0xe9; 32],
                    [0xeb; 32],
                    [0xdd; 32],
                    [0xdc; 32],
                    target_domain,
                    [0xf1; 32],
                    [0xee; 32],
                    [0xed; 32],
                    [0xec; 32],
                    proof_version,
                    proof_source_domain,
                    used_message_proof,
                )
                .is_none(),
                "EVM canary allowlist builder must reject wrong target/proof metadata"
            );
        };
        assert_rejected_canary(SCCP_DOMAIN_BSC, 1, SCCP_DOMAIN_SORA, true);
        assert_rejected_canary(SCCP_DOMAIN_ETH, 2, SCCP_DOMAIN_SORA, true);
        assert_rejected_canary(SCCP_DOMAIN_ETH, 1, SCCP_DOMAIN_ETH, true);
        assert_rejected_canary(SCCP_DOMAIN_ETH, 1, SCCP_DOMAIN_SORA, false);
        let allowlist = sccp_evm_route_allowlist_with_lane_canary_evidence_v1(
            route_allowlist,
            &destination_rollout,
            destination_binding_hash,
            source_material_hash,
            source_deployment_hash,
            [0xea; 32],
            3,
            18_765_432,
            [0xe8; 32],
            [0xe9; 32],
            [0xeb; 32],
            [0xdd; 32],
            [0xdc; 32],
            SCCP_DOMAIN_ETH,
            [0xf1; 32],
            [0xee; 32],
            [0xed; 32],
            [0xec; 32],
            1,
            SCCP_DOMAIN_SORA,
            true,
        )
        .expect("EVM transaction-bound canary evidence");
        assert_eq!(
            allowlist.route_canary_evidence_hash.as_deref(),
            Some(encode_0x_lower_hex(&route_canary_hash).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_transaction_hash.as_deref(),
            Some(encode_0x_lower_hex(&[0xea; 32]).as_str())
        );
        assert_eq!(allowlist.evm_route_canary_log_index, Some(3));
        assert_eq!(
            allowlist.evm_route_canary_receipt_block_number,
            Some(18_765_432)
        );
        assert_eq!(
            allowlist.evm_route_canary_receipt_block_hash.as_deref(),
            Some(encode_0x_lower_hex(&[0xe8; 32]).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_block_receipts_root.as_deref(),
            Some(encode_0x_lower_hex(&[0xe9; 32]).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_call_data_sha256.as_deref(),
            Some(encode_0x_lower_hex(&[0xeb; 32]).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_payload_hash.as_deref(),
            Some(encode_0x_lower_hex(&[0xdc; 32]).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_target_domain,
            Some(SCCP_DOMAIN_ETH)
        );
        assert_eq!(
            allowlist.evm_route_canary_finality_height.as_deref(),
            Some(encode_0x_lower_hex(&[0xed; 32]).as_str())
        );
        assert_eq!(
            allowlist.evm_route_canary_finality_block_hash.as_deref(),
            Some(encode_0x_lower_hex(&[0xec; 32]).as_str())
        );
        assert_eq!(allowlist.evm_route_canary_proof_version, Some(1));
        assert_eq!(
            allowlist.evm_route_canary_proof_source_domain,
            Some(SCCP_DOMAIN_SORA)
        );
        assert_eq!(allowlist.evm_route_canary_used_message_proof, Some(true));
        assert!(sccp_route_allowlist_canary_evidence_is_bound(
            SCCP_DOMAIN_ETH,
            &allowlist,
            &destination_rollout,
            &decode_fixed_hex_bytes::<32>(
                allowlist
                    .route_allowlist_hash
                    .as_deref()
                    .expect("route allowlist hash")
            )
            .expect("decode route allowlist hash"),
            &destination_binding_hash,
            &source_material_hash,
            &source_deployment_hash,
        ));
        let mut mismatched_route_hash = decode_fixed_hex_bytes::<32>(
            allowlist
                .route_allowlist_hash
                .as_deref()
                .expect("route allowlist hash"),
        )
        .expect("decode route allowlist hash");
        mismatched_route_hash[0] ^= 0x01;
        assert!(
            !sccp_route_allowlist_canary_evidence_is_bound(
                SCCP_DOMAIN_ETH,
                &allowlist,
                &destination_rollout,
                &mismatched_route_hash,
                &destination_binding_hash,
                &source_material_hash,
                &source_deployment_hash,
            ),
            "EVM route canary evidence must reject changed source/deployment-bound route hashes"
        );
    }

