    #[test]
    fn evm_source_material_and_deployment_hashes_match_helper_vectors() {
        let vectors = [
            (
                SCCP_DOMAIN_ETH,
                "4d1e9d15bc59c0a2157aa967eb033f5778c805aea4707785a31ef6b60f694d77",
                "feb62925410b1376a2cd3704c3822e335da96c3dcc283b041a559d7b08ab1cc4",
            ),
            (
                SCCP_DOMAIN_BSC,
                "1630e4d75e2676cc443e07b0477303240ae4cff13bdf9fe61725b4a9a4ee959a",
                "7d47ade779a5bddb3a5f283600af677db8605b75a00516a4328f3823ff28fb2d",
            ),
        ];

        for (domain, expected_material_hash, expected_deployment_hash) in vectors {
            let material =
                sccp_evm_family_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
                    domain, [0x44; 32], [0x55; 32], [0x66; 32], [0x88; 32], [0x11; 20], [0x77; 32],
                )
                .expect("EVM-family source verifier material");
            let deployment =
                sccp_source_adapter_engine_deployment_from_material_v1(&material, [0xaa; 32])
                    .expect("EVM-family source adapter deployment");
            assert_eq!(
                sccp_source_verifier_material_hash(&material),
                decode_fixed_hex_bytes::<32>(expected_material_hash)
                    .expect("EVM-family source verifier material vector")
            );
            assert_eq!(
                sccp_source_adapter_engine_deployment_hash(&deployment),
                decode_fixed_hex_bytes::<32>(expected_deployment_hash)
                    .expect("EVM-family source adapter deployment vector")
            );
        }
    }

    #[test]
    fn tron_source_material_and_deployment_hash_match_helper_vectors() {
        let source_bridge_config_hash = decode_fixed_hex_bytes::<32>(
            "e986dd67bfa2307b4e00cf46bde41a88003a55c5b7fea311fa106614b2252f9d",
        )
        .expect("TRON source bridge config vector");
        let expected_material_hash = decode_fixed_hex_bytes::<32>(
            "68c20262e44676bd5f3c4ec428f063373147a1ca14c5885648a9c651b3bcd8d8",
        )
        .expect("TRON source verifier material vector");
        let expected_deployment_hash = decode_fixed_hex_bytes::<32>(
            "94dbe28a2fb16e043b83639b6dea8ec62f53679599ef1dd220fd13c71c7bdcb8",
        )
        .expect("TRON source adapter deployment vector");

        let material = sccp_tron_mainnet_source_verifier_material_with_hashes_and_emitter_v1(
            [0x44; 32],
            [0x55; 32],
            [0x66; 32],
            [0x11; 20],
            [0x77; 32],
            [0x33; 32],
            [0x22; 20],
            source_bridge_config_hash,
            [0x88; 32],
        )
        .expect("TRON source verifier material");
        let deployment =
            sccp_source_adapter_engine_deployment_from_material_v1(&material, [0xaa; 32])
                .expect("TRON source adapter deployment");

        assert_eq!(
            sccp_source_verifier_material_hash(&material),
            expected_material_hash
        );
        assert_eq!(
            sccp_source_adapter_engine_deployment_hash(&deployment),
            expected_deployment_hash
        );
        let gate_hash = sccp_tron_dpos_source_gate_hash_from_deployment_v1(&material, &deployment)
            .expect("TRON DPoS source gate hash");
        assert_eq!(
            gate_hash,
            decode_fixed_hex_bytes::<32>(
                "776e8ebaf68ce872b0596330e4eb0c26bc6151ea23cb45dcd46316bb1f12bd28",
            )
            .expect("TRON DPoS source gate vector")
        );
        let mut wrong_target_deployment = deployment.clone();
        wrong_target_deployment.target_domain = SCCP_DOMAIN_ETH;
        assert_eq!(
            sccp_tron_dpos_source_gate_hash_from_deployment_v1(&material, &wrong_target_deployment),
            None
        );
    }

