    #[test]
    fn configured_source_material_does_not_bypass_disabled_manifest_gate() {
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_SOL).expect("sol manifest");
        let material = sample_ready_source_verifier_material(SCCP_DOMAIN_SOL);
        let bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_SOL,
            SCCP_DOMAIN_SORA,
            702,
            Some(&material),
        );
        assert!(
            !sccp_source_verifier_material_is_production_ready(&material),
            "generic SOL source material must stay fail-closed until it matches the deployed mainnet profile"
        );
        assert!(!manifest.production_ready);
        assert!(
            build_nexus_sccp_message_transparent_proof_with_source_verifier_material_allow_unready(
                &bundle, &material, true,
            )
            .is_some(),
            "diagnostic builders may still render explicit-material fixtures when allow_unready is set"
        );

        assert!(
            build_sccp_counterparty_submission_package_with_source_verifier_material(
                &bundle,
                &manifest,
                &[0xAA],
                &material,
            )
            .is_none()
        );
        assert!(
            build_nexus_sccp_message_transparent_proof_with_source_verifier_material(
                &bundle, &material,
            )
            .is_none()
        );

        let mainnet_material =
            sccp_solana_mainnet_source_verifier_material_with_hashes_and_accounts_db_v1(
                sample_solana_vote_roster_hash(),
                [0xB2; 32],
                [0xC3; 32],
                [0xE5; 32],
                [0xD4; 32],
            )
            .expect("Solana mainnet deployed material");
        assert!(sccp_source_verifier_material_is_production_ready(
            &mainnet_material
        ));
        let mainnet_bundle = sample_transfer_bundle_with_source_material(
            SCCP_DOMAIN_SOL,
            SCCP_DOMAIN_SORA,
            704,
            Some(&mainnet_material),
        );
        assert_source_chain_proof_binds_material_but_adapter_is_not_ready(
            &mainnet_bundle,
            &mainnet_material,
        );
        assert!(
            build_sccp_counterparty_submission_package_with_source_verifier_material(
                &mainnet_bundle,
                &manifest,
                &[0xAA],
                &mainnet_material,
            )
            .is_none(),
            "ready source material alone must not bypass the disabled destination manifest"
        );
        assert!(
            build_sccp_counterparty_submission_package_with_source_verifier_material_allow_unready(
                &mainnet_bundle,
                &manifest,
                &[0xAA],
                &mainnet_material,
                true,
            )
            .is_some(),
            "bridge admission can rebuild a source-material package while the outbound destination manifest is still disabled"
        );

        let proof =
            build_nexus_sccp_message_transparent_proof_with_source_verifier_material_allow_unready(
                &mainnet_bundle,
                &mainnet_material,
                true,
            )
            .expect("diagnostic source-material proof");
        assert!(
            !verify_nexus_sccp_message_transparent_proof_structure_with_source_verifier_material(
                &proof,
                &mainnet_material,
            ),
            "normal verifier path must keep the disabled destination manifest gate closed"
        );
        assert!(
            verify_nexus_sccp_message_transparent_proof_structure_with_source_verifier_material_allow_unready(
                &proof,
                &mainnet_material,
                true,
            ),
            "diagnostic verifier permits the disabled destination manifest after source material is supplied"
        );
        assert!(
            !verify_nexus_sccp_message_transparent_proof_structure_with_source_verifier_material_allow_unready_manifest(
                &proof,
                &mainnet_material,
            ),
            "production admission must not treat material-only source proofs as deployment-ready"
        );
    }

