    #[test]
    fn evm_destination_binding_uses_lowercase_hex_key_and_expected_hash() {
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_ETH).expect("eth manifest");
        let network_id = core::array::from_fn(|idx| u8::try_from(idx).expect("index fits in u8"));
        let verifier_address = core::array::from_fn(|idx| {
            let idx = u8::try_from(idx).expect("index fits in u8");
            0x80u8.saturating_add(idx)
        });
        let bridge_address = core::array::from_fn(|idx| {
            let idx = u8::try_from(idx).expect("index fits in u8");
            0xA0u8.saturating_add(idx)
        });
        let verifier_code_hash = [0x44; 32];
        let verifier_key_hash = [0x55; 32];

        let binding = build_sccp_evm_destination_binding(
            &manifest,
            network_id,
            verifier_address,
            bridge_address,
            verifier_code_hash,
            verifier_key_hash,
        )
        .expect("production EVM destination binding");
        let verifier_backend_hash = keccak256_bytes(manifest.verifier_backend.key.as_bytes());
        let proof_family_hash = keccak256_bytes(manifest.proof_family.as_bytes());

        assert_eq!(
            binding.key,
            format!(
                "evm:{}:{}:{}:0x{}:0x{}:0x{}:0x{}",
                manifest.local_domain,
                manifest.counterparty_domain,
                encode_lower_hex(&network_id),
                encode_lower_hex(&verifier_address),
                encode_lower_hex(&bridge_address),
                encode_lower_hex(&verifier_code_hash),
                encode_lower_hex(&verifier_key_hash)
            )
        );
        assert_eq!(
            binding.binding_hash,
            sccp_evm_destination_binding_hash(
                network_id,
                manifest.local_domain,
                manifest.counterparty_domain,
                verifier_backend_hash,
                proof_family_hash,
                verifier_address,
                bridge_address,
                verifier_code_hash,
                verifier_key_hash
            )
        );
    }

    #[test]
    fn evm_destination_binding_rejects_cross_lane_and_contract_replay_by_hash() {
        let eth = sccp_proof_manifest_for_domain(SCCP_DOMAIN_ETH).expect("eth manifest");
        let bsc = sccp_proof_manifest_for_domain(SCCP_DOMAIN_BSC).expect("bsc manifest");
        let network_id = [0x11; 32];
        let verifier_address = [0x22; 20];
        let bridge_address = [0x33; 20];
        let eth_binding =
            sample_evm_destination_binding(&eth, network_id, verifier_address, bridge_address);
        assert!(
            sccp_evm_destination_binding_matches_deployment_material(&eth, &eth_binding),
            "canonical EVM deployment binding must round-trip through the parser"
        );

        let mut forged_key = eth_binding.clone();
        forged_key.key.push_str(":spoof");
        assert!(
            !sccp_evm_destination_binding_matches_deployment_material(&eth, &forged_key),
            "EVM binding keys must be parsed and recomputed, not trusted"
        );

        let mut forged_hash = eth_binding.clone();
        forged_hash.binding_hash[0] ^= 0x01;
        assert!(
            !sccp_evm_destination_binding_matches_deployment_material(&eth, &forged_hash),
            "EVM binding hashes must match the recomputed deployment tuple"
        );

        let bsc_binding =
            sample_evm_destination_binding(&bsc, network_id, verifier_address, bridge_address);
        assert!(
            !sccp_evm_destination_binding_matches_deployment_material(&bsc, &eth_binding),
            "EVM bindings must not replay across governed lanes"
        );
        assert_ne!(eth_binding.key, bsc_binding.key);
        assert_ne!(eth_binding.binding_hash, bsc_binding.binding_hash);

        let changed_verifier =
            sample_evm_destination_binding(&eth, network_id, [0x44; 20], bridge_address);
        assert_ne!(eth_binding.binding_hash, changed_verifier.binding_hash);

        let changed_bridge =
            sample_evm_destination_binding(&eth, network_id, verifier_address, [0x55; 20]);
        assert_ne!(eth_binding.binding_hash, changed_bridge.binding_hash);

        let changed_code_hash = build_sccp_evm_destination_binding(
            &eth,
            network_id,
            verifier_address,
            bridge_address,
            [0x66; 32],
            [0x55; 32],
        )
        .expect("changed verifier code hash binding");
        assert_ne!(eth_binding.binding_hash, changed_code_hash.binding_hash);

        let changed_key_hash = build_sccp_evm_destination_binding(
            &eth,
            network_id,
            verifier_address,
            bridge_address,
            [0x44; 32],
            [0x77; 32],
        )
        .expect("changed verifier key hash binding");
        assert_ne!(eth_binding.binding_hash, changed_key_hash.binding_hash);

        let mut forked_manifest = eth.clone();
        forked_manifest.proof_family.push_str("-fork");
        assert!(
            build_sccp_evm_destination_binding(
                &forked_manifest,
                network_id,
                verifier_address,
                bridge_address,
                [0x44; 32],
                [0x55; 32],
            )
            .is_none(),
            "EVM destination bindings must use the canonical production proof family"
        );

        let mut backend_fork = eth;
        backend_fork.verifier_backend.key.push_str("-fork");
        assert!(
            build_sccp_evm_destination_binding(
                &backend_fork,
                network_id,
                verifier_address,
                bridge_address,
                [0x44; 32],
                [0x55; 32],
            )
            .is_none(),
            "EVM destination bindings must use a canonical verifier backend"
        );
    }

    #[test]
    fn evm_destination_binding_requires_deployed_verifier_hashes() {
        let production = sccp_proof_manifest_for_domain(SCCP_DOMAIN_ETH).expect("eth manifest");
        let reference = sample_reference_evm_attestation_manifest();

        assert!(
            build_sccp_evm_destination_binding(
                &production,
                [0x11; 32],
                [0x22; 20],
                [0x33; 20],
                [0; 32],
                [0x55; 32],
            )
            .is_none(),
            "verifier code hash is mandatory"
        );
        assert!(
            build_sccp_evm_destination_binding(
                &production,
                [0x11; 32],
                [0x22; 20],
                [0x33; 20],
                [0x44; 32],
                [0; 32],
            )
            .is_none(),
            "production Groth16 verifier key hash is mandatory"
        );
        assert!(
            build_sccp_evm_destination_binding(
                &reference, [0x11; 32], [0x22; 20], [0x33; 20], [0x44; 32], [0; 32],
            )
            .is_none(),
            "reference verifier cannot be exposed as a deployable EVM destination binding"
        );
        assert!(
            build_sccp_evm_destination_binding(
                &reference, [0x11; 32], [0x22; 20], [0x33; 20], [0x44; 32], [0x55; 32],
            )
            .is_none(),
            "reference verifier cannot be exposed as a deployable EVM destination binding"
        );
        let mut wrong_target = production.clone();
        wrong_target.verifier_target = SccpProofVerifierTargetV1::TronContract;
        assert!(
            build_sccp_evm_destination_binding(
                &wrong_target,
                [0x11; 32],
                [0x22; 20],
                [0x33; 20],
                [0x44; 32],
                [0x55; 32],
            )
            .is_none(),
            "EVM destination bindings must target EVM contracts"
        );
    }

    #[test]
    fn tron_destination_binding_requires_contract_code_and_key_material() {
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_TRON).expect("tron manifest");
        let binding = build_sccp_tron_destination_binding(
            &manifest,
            [0x71; 32],
            "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
            [0x72; 32],
            [0x73; 32],
        )
        .expect("TRON destination binding");
        assert!(binding.key.contains("TJRabPrwbZy45sbavfcjinPJC18kjpRTv8"));
        assert!(binding.key.contains(&"72".repeat(32)));
        assert!(binding.key.contains(&"73".repeat(32)));
        assert_ne!(
            binding.binding_hash,
            manifest.destination_binding.binding_hash
        );
        let script_vector_binding = build_sccp_tron_destination_binding(
            &manifest,
            [0x33; 32],
            "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
            [0xBB; 32],
            [0xCC; 32],
        )
        .expect("TRON destination binding vector");
        assert_eq!(
            encode_lower_hex(&script_vector_binding.binding_hash),
            "17c953ad5b8c9a2b6f7102aca993fa7c427d018505cf4f58fac35ea454caba7f"
        );

        let changed_contract = build_sccp_tron_destination_binding(
            &manifest,
            [0x71; 32],
            "TLa2f6VPqDgRE67v1736s7bJ8Ray5wYjU7",
            [0x72; 32],
            [0x73; 32],
        )
        .expect("changed TRON destination binding");
        assert_ne!(binding.binding_hash, changed_contract.binding_hash);
        let changed_network = build_sccp_tron_destination_binding(
            &manifest,
            [0x70; 32],
            "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
            [0x72; 32],
            [0x73; 32],
        )
        .expect("changed TRON network binding");
        assert_ne!(binding.binding_hash, changed_network.binding_hash);
        let changed_key_hash = build_sccp_tron_destination_binding(
            &manifest,
            [0x71; 32],
            "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
            [0x72; 32],
            [0x74; 32],
        )
        .expect("changed TRON verifier-key binding");
        assert_ne!(binding.binding_hash, changed_key_hash.binding_hash);
        let mut forged_key = binding.clone();
        forged_key.key.push_str(":spoof");
        assert!(
            !sccp_tron_destination_binding_matches_deployment_material(&manifest, &forged_key),
            "TRON binding keys must be parsed and recomputed, not trusted"
        );
        assert!(
            build_sccp_tron_destination_binding(
                &manifest,
                [0x71; 32],
                "not-a-tron-address",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "malformed TRON verifier address must fail closed"
        );
        assert!(
            build_sccp_tron_destination_binding(
                &manifest,
                [0x71; 32],
                " TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "padded TRON verifier address must fail closed"
        );
        assert!(
            build_sccp_tron_destination_binding(
                &manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON verifier code hash is mandatory"
        );
        assert!(
            build_sccp_tron_destination_binding(
                &manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0; 32],
            )
            .is_none(),
            "TRON Groth16 verifier key hash is mandatory"
        );

        let mut wrong_source_manifest = manifest.clone();
        wrong_source_manifest.local_domain = SCCP_DOMAIN_ETH;
        assert!(
            build_sccp_tron_destination_binding(
                &wrong_source_manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON destination bindings must source from SORA"
        );

        let mut wrong_target_manifest = manifest.clone();
        wrong_target_manifest.counterparty_domain = SCCP_DOMAIN_TON;
        assert!(
            build_sccp_tron_destination_binding(
                &wrong_target_manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON destination bindings must target the TRON domain"
        );

        let mut wrong_target_kind_manifest = manifest.clone();
        wrong_target_kind_manifest.verifier_target = SccpProofVerifierTargetV1::EvmContract;
        assert!(
            build_sccp_tron_destination_binding(
                &wrong_target_kind_manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON destination bindings must target TRON contracts"
        );

        let mut backend_fork_manifest = manifest.clone();
        backend_fork_manifest.verifier_backend.key.push_str("-fork");
        assert!(
            build_sccp_tron_destination_binding(
                &backend_fork_manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON destination bindings must use the canonical verifier backend"
        );

        let mut wrong_family_manifest = manifest.clone();
        wrong_family_manifest.proof_family = "debug-proof-family".to_owned();
        assert!(
            build_sccp_tron_destination_binding(
                &wrong_family_manifest,
                [0x71; 32],
                "TJRabPrwbZy45sbavfcjinPJC18kjpRTv8",
                [0x72; 32],
                [0x73; 32],
            )
            .is_none(),
            "TRON destination bindings must use the production proof family"
        );
    }

    #[test]
    fn reference_evm_submission_package_builder_accepts_explicit_deployment_binding_when_unready_allowed()
     {
        let bundle = sample_evm_transfer_bundle(58);
        let manifest = sample_reference_evm_attestation_manifest();
        let signer = sample_secp256k1_signer();
        let native_proof_bytes = vec![0xAA, 0xBB, 0xCC];
        let deployment_binding =
            sample_evm_destination_binding(&manifest, [0x11; 32], [0x33; 20], [0x22; 20]);
        let submission_package =
            build_sccp_counterparty_submission_package_with_destination_binding_and_signer_allow_unready(
                &bundle,
                &manifest,
                &native_proof_bytes,
                &deployment_binding,
                &signer,
                true,
            )
            .expect("explicit EVM deployment binding builds a submission package");
        let public_inputs =
            sccp_message_transparent_public_inputs(&bundle).expect("message public inputs");
        let proof = NexusSccpMessageTransparentProofV1 {
            version: 1,
            local_domain: manifest.local_domain,
            counterparty_domain: manifest.counterparty_domain,
            security_model: manifest.security_model,
            anchor_governance: manifest.anchor_governance,
            destination_binding: manifest.destination_binding.clone(),
            proof_family: manifest.proof_family.clone(),
            verifier_backend: manifest.verifier_backend.clone(),
            message_backend: manifest.message_backend.clone(),
            registry_backend: manifest.registry_backend.clone(),
            manifest_seed: manifest.manifest_seed.clone(),
            finality_model: manifest.finality_model,
            verifier_target: manifest.verifier_target,
            public_inputs,
            proof_bytes: native_proof_bytes,
            submission_package,
            bundle,
        };

        let payload = evm_payload_from_proof(&proof);
        assert_eq!(payload.destination_binding, deployment_binding);
        assert_eq!(proof.destination_binding, manifest.destination_binding);
        assert!(verify_sccp_evm_submission_package(&manifest, &proof));
    }

