    #[test]
    fn solana_submission_package_binds_statement_and_destination() {
        let bundle = sample_transfer_bundle(SCCP_DOMAIN_SORA, SCCP_DOMAIN_SOL, 61);
        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_SOL).expect("sol manifest");
        let proof = build_nexus_sccp_message_transparent_proof_allow_unready(&bundle, true)
            .expect("Solana proof artifact");
        let inner =
            build_sccp_message_transparent_inner_proof(&bundle, &manifest).expect("inner proof");

        assert!(verify_nexus_sccp_message_transparent_proof_structure_allow_unready(&proof, true,));
        assert_eq!(proof.submission_package.arguments.len(), 6);
        assert_eq!(proof.submission_package.arguments[3].key, "statement_hash");
        assert_eq!(
            proof.submission_package.arguments[3].bytes,
            inner.statement_hash.to_vec()
        );
        assert_eq!(
            proof.submission_package.arguments[4].key,
            "destination_binding_hash"
        );
        assert_eq!(
            proof.submission_package.arguments[4].bytes,
            manifest.destination_binding.binding_hash.to_vec()
        );
        assert_eq!(
            proof.submission_package.arguments[5].key,
            "proof_context_hash"
        );
        assert_eq!(
            proof.submission_package.arguments[5].bytes,
            sccp_solana_proof_context_hash(
                inner.statement_hash,
                manifest.destination_binding.binding_hash
            )
            .to_vec()
        );

        let SccpPlatformSubmissionPayloadV1::SolanaProgramInstruction(payload) =
            &proof.submission_package.platform_payload
        else {
            panic!("expected Solana program instruction payload");
        };
        assert_eq!(payload.proof_bytes, proof.proof_bytes);
        assert_eq!(
            payload.public_inputs_bytes,
            canonical_sccp_message_transparent_public_inputs_bytes(&proof.public_inputs)
        );
        assert_eq!(
            payload.bundle_bytes,
            canonical_nexus_sccp_message_bundle_bytes(&bundle)
        );
        assert_eq!(payload.destination_binding, manifest.destination_binding);
        assert_eq!(
            payload.destination_binding_hash,
            manifest.destination_binding.binding_hash
        );
        assert_eq!(payload.statement_hash, inner.statement_hash);
        assert_eq!(
            payload.proof_context_hash,
            sccp_solana_proof_context_hash(
                inner.statement_hash,
                manifest.destination_binding.binding_hash
            )
        );

        let mut wrong_statement = proof.clone();
        let SccpPlatformSubmissionPayloadV1::SolanaProgramInstruction(payload) =
            &mut wrong_statement.submission_package.platform_payload
        else {
            panic!("expected Solana program instruction payload");
        };
        payload.statement_hash[0] ^= 0x01;
        assert!(
            !verify_nexus_sccp_message_transparent_proof_structure_allow_unready(
                &wrong_statement,
                true,
            )
        );

        let mut wrong_binding = proof.clone();
        let SccpPlatformSubmissionPayloadV1::SolanaProgramInstruction(payload) =
            &mut wrong_binding.submission_package.platform_payload
        else {
            panic!("expected Solana program instruction payload");
        };
        payload.destination_binding_hash[0] ^= 0x01;
        assert!(
            !verify_nexus_sccp_message_transparent_proof_structure_allow_unready(
                &wrong_binding,
                true,
            )
        );

        let mut wrong_context = proof;
        let SccpPlatformSubmissionPayloadV1::SolanaProgramInstruction(payload) =
            &mut wrong_context.submission_package.platform_payload
        else {
            panic!("expected Solana program instruction payload");
        };
        payload.proof_context_hash[0] ^= 0x01;
        assert!(
            !verify_nexus_sccp_message_transparent_proof_structure_allow_unready(
                &wrong_context,
                true,
            )
        );
    }

    #[test]
    fn solana_submission_package_rejects_oversized_bundle_bytes() {
        let SccpPayloadV1::Transfer(mut payload) =
            sample_transfer_bundle(SCCP_DOMAIN_SORA, SCCP_DOMAIN_SOL, 65).payload
        else {
            panic!("expected transfer payload");
        };
        payload.asset_id = vec![b'a'; SCCP_NATIVE_RECURSIVE_MAX_PROOF_BYTES + 1];
        let bundle = sample_message_bundle(SccpPayloadV1::Transfer(payload));
        assert!(verify_message_bundle_structure(&bundle));
        assert!(
            canonical_nexus_sccp_message_bundle_bytes(&bundle).len()
                > SCCP_NATIVE_RECURSIVE_MAX_PROOF_BYTES,
            "test fixture must exceed the native recursive payload corridor",
        );

        let manifest = sccp_proof_manifest_for_domain(SCCP_DOMAIN_SOL).expect("sol manifest");
        assert!(
            build_sccp_counterparty_submission_package_allow_unready(
                &bundle,
                &manifest,
                &[0xAA, 0xBB],
                true,
            )
            .is_none(),
            "Solana verifier-program bundle bytes must use the native recursive payload corridor",
        );
    }

